const clamp01 = (n: number) => Math.min(1, Math.max(0, n));

const formatTime = (s: number) => `${s.toFixed(1)}s`;

export default function AIAgentLanes({
  task = "Where should our 30-person team meet for a May offsite?",
  lanes = DEMO_LANES,
  answer = DEMO_ANSWER,
  className,
}: AIAgentLanesProps) {
  const reduceMotion = useReducedMotion();
  const total = Math.max(...lanes.flatMap((l) => l.steps.map((s) => s.end)));
  const [now, setNow] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [selected, setSelected] = useState(lanes[0]?.id ?? "");
  const [hover, setHover] = useState<{ lane: number; step: number } | null>(
    null
  );
  const nowRef = useRef(0);
  nowRef.current = now;

  // Start once on mount; reduced motion shows the finished run.
  useEffect(() => {
    if (reduceMotion) {
      setNow(total);
      return;
    }
    const id = setTimeout(() => setPlaying(true), 500);
    return () => clearTimeout(id);
  }, [reduceMotion, total]);

  useEffect(() => {
    if (!playing) {
      return;
    }
    let frame = 0;
    let last = performance.now();
    const tick = (t: number) => {
      const next = Math.min(total, nowRef.current + (t - last) / 1000);
      last = t;
      setNow(next);
      if (next >= total) {
        setPlaying(false);
        return;
      }
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [playing, total]);

  const done = now >= total;
  const lead = lanes[0];
  const subs = lanes.slice(1);
  const running = subs.filter(
    (l) => now >= (l.steps[0]?.start ?? 0) && now < laneEnd(l)
  ).length;
  const x = (t: number) => `${(t / total) * 100}%`;
  const hoverStep = hover ? lanes[hover.lane]?.steps[hover.step] : undefined;

  const toggle = () => {
    if (done) {
      setNow(0);
      setPlaying(true);
      return;
    }
    setPlaying((p) => !p);
  };

  return (
    <div
      className={cn(
        "w-full max-w-2xl rounded-2xl bg-white ring-1 ring-black/[0.08] dark:bg-zinc-900 dark:ring-white/10",
        className
      )}
    >
      <header className="flex items-start justify-between gap-4 border-black/[0.06] border-b px-4 py-3 dark:border-white/[0.08]">
        <div className="min-w-0">
          <p className="text-[11px] text-zinc-500 dark:text-zinc-400">
            {statusLine(done, running, now, total)}
          </p>
          <h3 className="mt-0.5 font-medium text-sm text-zinc-900 leading-snug dark:text-zinc-100">
            {task}
          </h3>
        </div>
        <button
          aria-label={playButtonLabel(done, playing)}
          className="flex size-8 shrink-0 items-center justify-center rounded-lg text-zinc-600 ring-1 ring-black/10 transition-colors duration-150 hover:bg-zinc-100 hover:text-zinc-900 focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-zinc-900/30 dark:text-zinc-300 dark:ring-white/15 dark:hover:bg-white/[0.07] dark:hover:text-white"
          onClick={toggle}
          type="button"
        >
          <PlayIcon done={done} playing={playing} />
        </button>
      </header>

      <div className="px-4 pt-4">
        <div className="flex">
          <ul className="w-[84px] shrink-0 sm:w-28">
            {lanes.map((lane, i) => (
              <li key={lane.id} style={{ height: LANE_H }}>
                <LaneLabel
                  active={selected === lane.id}
                  finished={i > 0 && now >= laneEnd(lane)}
                  lane={lane}
                  lead={i === 0}
                  onSelect={() => setSelected(lane.id)}
                  started={now >= (lane.steps[0]?.start ?? 0)}
                />
              </li>
            ))}
          </ul>

          <div className="relative min-w-0 flex-1">
            <Connectors lead={lead} now={now} subs={subs} total={total} />
            {lanes.map((lane, li) => (
              <div
                className="relative border-black/[0.05] border-b border-dashed last:border-b-0 dark:border-white/[0.06]"
                key={lane.id}
                style={{ height: LANE_H }}
              >
                {lane.steps.map((step, si) => (
                  <StepBar
                    key={`${step.label}-${step.start}`}
                    left={x(step.start)}
                    now={now}
                    onHover={(on) =>
                      setHover(on ? { lane: li, step: si } : null)
                    }
                    onSelect={() => setSelected(lane.id)}
                    step={step}
                    width={x(step.end - step.start)}
                  />
                ))}
              </div>
            ))}
            <div
              aria-hidden="true"
              className="pointer-events-none absolute inset-y-0 w-px bg-zinc-900/70 dark:bg-white/70"
              style={{ left: x(now) }}
            />
            <AnimatePresence>
              {/* A bar scrubbed out of existence never fires pointerleave. */}
              {hoverStep && hover && now > hoverStep.start && (
                <StepTip
                  key={`${hover.lane}-${hover.step}`}
                  now={now}
                  step={hoverStep}
                  top={hover.lane * LANE_H}
                  total={total}
                />
              )}
            </AnimatePresence>
          </div>
        </div>

        <div className="flex items-center">
          <span className="w-[84px] shrink-0 sm:w-28" />
          <Scrubber
            now={now}
            onScrub={(t) => {
              setPlaying(false);
              setNow(t);
            }}
            total={total}
          />
        </div>
      </div>

      <Transcript
        answer={answer}
        lane={lanes.find((l) => l.id === selected) ?? lead}
        lead={selected === lead.id}
        now={now}
      />
    </div>
  );
}

const laneEnd = (lane: AgentLane) => lane.steps.at(-1)?.end ?? 0;

const statusLine = (
  done: boolean,
  running: number,
  now: number,
  total: number
) => {
  if (done) {
    return `Done in ${formatTime(total)}`;
  }
  if (running > 0) {
    return `${running} ${running === 1 ? "agent" : "agents"} working · ${formatTime(now)}`;
  }
  return now === 0 ? "Ready" : `Lead agent · ${formatTime(now)}`;
};

const playButtonLabel = (done: boolean, playing: boolean) => {
  if (done) {
    return "Replay run";
  }
  return playing ? "Pause" : "Play";
};

function PlayIcon({ done, playing }: { done: boolean; playing: boolean }) {
  if (done) {
    return <RotateCcw className="size-3.5" />;
  }
  return playing ? (
    <Pause className="size-3.5" />
  ) : (
    <Play className="size-3.5" />
  );
}

function LaneLabel({
  lane,
  lead,
  active,
  started,
  finished,
  onSelect,
}: {
  lane: AgentLane;
  lead: boolean;
  active: boolean;
  started: boolean;
  finished: boolean;
  onSelect: () => void;
}) {
  return (
    <button
      aria-pressed={active}
      className={cn(
        "-ml-1.5 flex h-7 max-w-full items-center gap-1.5 rounded-md px-1.5 text-left text-[12px] transition-colors duration-150 focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-zinc-900/30 dark:focus-visible:ring-white/30",
        active
          ? "bg-zinc-100 font-medium text-zinc-900 dark:bg-white/[0.08] dark:text-zinc-100"
          : "text-zinc-500 hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-zinc-100",
        !started && "opacity-50"
      )}
      onClick={onSelect}
      type="button"
    >
      <span className="relative flex size-3.5 shrink-0 items-center justify-center">
        <AnimatePresence initial={false} mode="popLayout">
          {finished ? (
            <motion.span
              animate={{ opacity: 1, scale: 1 }}
              className="flex size-3.5 items-center justify-center rounded-full bg-teal-600 text-white dark:bg-teal-500"
              initial={{ opacity: 0, scale: 0.5 }}
              key="done"
              transition={{ duration: 0.25, ease: EASE_OUT }}
            >
              <Check className="size-2.5" strokeWidth={3} />
            </motion.span>
          ) : (
            <motion.span
              className={cn(
                "size-2 rounded-full",
                lead
                  ? "bg-zinc-900 dark:bg-zinc-100"
                  : "ring-[1.5px] ring-zinc-400 ring-inset dark:ring-zinc-500"
              )}
              exit={{ opacity: 0 }}
              key="dot"
            />
          )}
        </AnimatePresence>
      </span>
      <span className="truncate">{lane.name}</span>
    </button>
  );
}

function StepBar({
  step,
  now,
  left,
  width,
  onHover,
  onSelect,
}: {
  step: AgentStep;
  now: number;
  left: string;
  width: string;
  onHover: (on: boolean) => void;
  onSelect: () => void;
}) {
  const progress = clamp01((now - step.start) / (step.end - step.start));
  if (progress <= 0) {
    return null;
  }
  const style: CSSProperties = { left, width };
  return (
    <button
      aria-label={`${TOOL_NAME[step.tool]}: ${step.label}`}
      className="absolute top-1/2 h-4 -translate-y-1/2 rounded-[4px] px-px outline-hidden focus-visible:ring-2 focus-visible:ring-zinc-900/40 dark:focus-visible:ring-white/40"
      onBlur={() => onHover(false)}
      onClick={onSelect}
      onFocus={() => onHover(true)}
      onPointerEnter={() => onHover(true)}
      onPointerLeave={() => onHover(false)}
      style={style}
      type="button"
    >
      <span
        className={cn(
          "block h-full origin-left rounded-[3px]",
          TOOL_STYLE[step.tool]
        )}
        style={{ width: `${progress * 100}%` }}
      />
    </button>
  );
}

function StepTip({
  step,
  now,
  top,
  total,
}: {
  step: AgentStep;
  now: number;
  top: number;
  total: number;
}) {
  const mid = (step.start + step.end) / 2 / total;
  const finished = now >= step.end;
  const anchor: CSSProperties =
    mid > 0.6
      ? { right: `${(1 - step.end / total) * 100}%` }
      : { left: `${(step.start / total) * 100}%` };
  return (
    <motion.div
      animate={{ opacity: 1, y: 0 }}
      className="pointer-events-none absolute z-20 w-56 -translate-y-full rounded-lg bg-zinc-900 px-3 py-2 text-[12px] text-zinc-300 shadow-lg dark:bg-zinc-800 dark:ring-1 dark:ring-white/10"
      exit={{ opacity: 0, transition: { duration: 0.08 } }}
      initial={{ opacity: 0, y: 3 }}
      style={{ ...anchor, top: top + 4 }}
      transition={{ duration: 0.14, ease: EASE_OUT }}
    >
      <p className="flex items-center justify-between gap-2 text-[11px] text-zinc-400">
        <span>{TOOL_NAME[step.tool]}</span>
        <span className="font-mono tabular-nums">
          {formatTime(Math.min(now, step.end) - step.start)}
        </span>
      </p>
      <p className="mt-0.5 font-medium text-white">{step.label}</p>
      {step.result && (
        <p className="mt-1 text-zinc-400">
          {finished ? step.result : "Waiting for results…"}
        </p>
      )}
    </motion.div>
  );
}

/** Lines from the lead out to each sub-agent, and back when they report. */
function Connectors({
  lead,
  subs,
  now,
  total,
}: {
  lead: AgentLane;
  subs: AgentLane[];
  now: number;
  total: number;
}) {
  const ref = useRef<SVGSVGElement>(null);
  const [width, setWidth] = useState(0);

  useEffect(() => {
    const el = ref.current;
    if (!el) {
      return;
    }
    // clientWidth on an <svg> reads 0 in some engines; the observed box does not.
    const observer = new ResizeObserver(([entry]) =>
      setWidth(entry.contentRect.width)
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const fork = lead.steps[0]?.end ?? 0;
  const join = lead.steps.at(-1)?.start ?? total;
  const xAt = (t: number) => (t / total) * width;
  const yAt = (lane: number) => lane * LANE_H + LANE_H / 2;
  const reach = (from: number, to: number) =>
    clamp01((now - from) / (to - from));
  const top = yAt(0);
  const fx = xAt(fork);
  const jx = xAt(join);

  return (
    <svg
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 h-full w-full overflow-visible"
      ref={ref}
    >
      {width > 0 && (
        <>
          {/* The lead waits on its sub-agents between handing off and writing. */}
          <line
            className="stroke-zinc-300 dark:stroke-zinc-600"
            strokeDasharray="2 3"
            x1={fx}
            x2={xAt(Math.min(Math.max(now, fork), join))}
            y1={top}
            y2={top}
          />
          {subs.map((lane, i) => {
            const y = yAt(i + 1);
            const sx = xAt(lane.steps[0]?.start ?? fork);
            const ex = xAt(laneEnd(lane));
            const out = `M ${fx} ${top} C ${fx + 6} ${top} ${fx + 2} ${y} ${sx} ${y}`;
            const back = `M ${ex} ${y} C ${jx - 18} ${y} ${jx - 12} ${top} ${jx} ${top}`;
            return (
              <g
                className="fill-none stroke-zinc-400 dark:stroke-zinc-500"
                key={lane.id}
              >
                <path
                  d={out}
                  pathLength={1}
                  strokeDasharray="1 1"
                  strokeDashoffset={1 - reach(fork, fork + 0.2)}
                />
                <path
                  d={back}
                  pathLength={1}
                  strokeDasharray="1 1"
                  strokeDashoffset={1 - reach(join - 0.35, join)}
                />
              </g>
            );
          })}
        </>
      )}
    </svg>
  );
}

function Scrubber({
  now,
  total,
  onScrub,
}: {
  now: number;
  total: number;
  onScrub: (t: number) => void;
}) {
  const ticks = Array.from(
    { length: Math.floor(total / TICK) + 1 },
    (_, i) => i * TICK
  );
  return (
    <div className="relative min-w-0 flex-1 pt-1 pb-3">
      <div className="relative h-4 text-[10px] text-zinc-400 tabular-nums dark:text-zinc-500">
        {ticks.map((t) => (
          <span
            className="absolute -translate-x-1/2 font-mono first:translate-x-0"
            key={t}
            style={{ left: `${(t / total) * 100}%` }}
          >
            {t}s
          </span>
        ))}
      </div>
      <input
        aria-label="Run time"
        aria-valuetext={formatTime(now)}
        className="peer absolute inset-x-0 -top-1 h-6 w-full cursor-ew-resize opacity-0"
        max={total}
        min={0}
        onChange={(e) => onScrub(Number(e.target.value))}
        step={0.1}
        type="range"
        value={now}
      />
      {/* The range input is invisible, so its focus ring lives on the knob. */}
      <span
        aria-hidden="true"
        className="pointer-events-none absolute -top-[3px] h-[7px] w-[7px] -translate-x-1/2 rounded-full bg-zinc-900 peer-focus-visible:ring-2 peer-focus-visible:ring-zinc-900/30 peer-focus-visible:ring-offset-2 peer-focus-visible:ring-offset-white dark:bg-white dark:peer-focus-visible:ring-white/40 dark:peer-focus-visible:ring-offset-zinc-900"
        style={{ left: `${(now / total) * 100}%` }}
      />
    </div>
  );
}

function Legend() {
  return (
    <ul className="hidden shrink-0 items-center gap-3 text-[10px] text-zinc-500 sm:flex dark:text-zinc-400">
      {(["search", "read", "think", "write"] as const).map((tool) => (
        <li className="flex items-center gap-1" key={tool}>
          <span className={cn("h-2 w-3 rounded-[2px]", TOOL_STYLE[tool])} />
          {TOOL_NAME[tool]}
        </li>
      ))}
    </ul>
  );
}

function Transcript({
  lane,
  lead,
  now,
  answer,
}: {
  lane: AgentLane;
  lead: boolean;
  now: number;
  answer: string;
}) {
  const steps = lane.steps.filter((s) => now >= s.start);
  const writing = lead ? lane.steps.at(-1) : undefined;
  const written =
    writing && now >= writing.start
      ? answer.slice(
          0,
          Math.round(
            answer.length *
              clamp01((now - writing.start) / (writing.end - writing.start))
          )
        )
      : "";

  return (
    <div className="min-h-[148px] border-black/[0.06] border-t px-4 py-3 dark:border-white/[0.08]">
      <div className="mb-2 flex items-center justify-between gap-3">
        <p className="text-[11px] text-zinc-500 dark:text-zinc-400">
          {lane.name}
          {lane.summary && now >= laneEnd(lane) && (
            <span className="text-zinc-900 dark:text-zinc-100">
              {" "}
              · {lane.summary}
            </span>
          )}
        </p>
        <Legend />
      </div>
      {written ? (
        <p className="text-[13px] text-zinc-800 leading-relaxed dark:text-zinc-200">
          {written}
          {now < (writing?.end ?? 0) && (
            <span className="ml-0.5 inline-block h-3 w-1.5 translate-y-[2px] rounded-[2px] bg-zinc-800 dark:bg-zinc-200" />
          )}
        </p>
      ) : (
        <ol className="space-y-1.5">
          {steps.length === 0 && (
            <li className="text-[12px] text-zinc-400 dark:text-zinc-500">
              Not started yet
            </li>
          )}
          {steps.map((step) => {
            const finished = now >= step.end;
            return (
              <li
                className="flex items-baseline gap-2 text-[12px]"
                key={`${step.label}-${step.start}`}
              >
                <span
                  className={cn(
                    "mt-px size-1.5 shrink-0 translate-y-[-1px] rounded-full",
                    finished
                      ? "bg-zinc-300 dark:bg-zinc-600"
                      : "animate-pulse bg-teal-600 motion-reduce:animate-none dark:bg-teal-400"
                  )}
                />
                <span className="w-14 shrink-0 text-zinc-400 dark:text-zinc-500">
                  {TOOL_NAME[step.tool]}
                </span>
                <span className="min-w-0 text-zinc-700 dark:text-zinc-300">
                  {step.label}
                  {finished && step.result && (
                    <span className="text-zinc-400 dark:text-zinc-500">
                      {" "}
                      → {step.result}
                    </span>
                  )}
                </span>
              </li>
            );
          })}
        </ol>
      )}
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: AI Autocomplete
 * @version: 1.0.0
 * @date: 2026-10-16
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import {
  type ChangeEvent,
  type KeyboardEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

export interface AIAutocompleteProps {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /**
   * Returns how the text could go on, or null for no suggestion. Called once
   * typing pauses, only while the caret is at the end. Demo completer when
   * omitted.
   */
  suggest?: (text: string) => string | null | Promise<string | null>;
  /** How long typing has to pause before asking for a suggestion, in ms. */
  delay?: number;
  placeholder?: string;
  /** Accessible name for the text box. */
  label?: string;
  className?: string;
}

const WORD = /^\s*\S+\s?/;
const WORDS = /\s*\S+\s*/g;

/** The next word of a suggestion, with the space around it. */
function nextWord(ghost: string) {
  return ghost.match(WORD)?.[0] ?? ghost;
}

/**
 * A text box that offers how your sentence could end, in grey after the
 * caret. Tab takes all of it, → takes one word, Esc waves it off, and
 * typing the same letters keeps it instead of asking again.
 */
export function AIAutocomplete({
  value: valueProp,
  defaultValue = "",
  onValueChange,
  suggest = demoSuggest,
  delay = 400,
  placeholder = "Start writing…",
  label = "Message",
  className,
}: AIAutocompleteProps) {
  const [ownValue, setOwnValue] = useState(defaultValue);
  const value = valueProp ?? ownValue;
  const [ghost, setGhost] = useState("");
  // Bumped for each new suggestion so its words fade in once, not on every
  // keystroke that types through them.
  const [batch, setBatch] = useState(0);
  const [atEnd, setAtEnd] = useState(true);
  // Announced once per suggestion, not again as typing eats into it.
  const [spoken, setSpoken] = useState("");
  const areaRef = useRef<HTMLTextAreaElement>(null);
  const request = useRef(0);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const setValue = useCallback(
    (next: string) => {
      setOwnValue(next);
      onValueChange?.(next);
    },
    [onValueChange]
  );

  const ask = useCallback(
    (text: string) => {
      if (timer.current) {
        clearTimeout(timer.current);
      }
      const id = ++request.current;
      timer.current = setTimeout(async () => {
        if (!text.trim()) {
          return;
        }
        let result: string | null;
        try {
          result = await suggest(text);
        } catch {
          // A failed suggestion just means no suggestion.
          return;
        }
        // A reply to text that has since changed is thrown away.
        if (id === request.current && result) {
          setGhost(result);
          setBatch((b) => b + 1);
          setSpoken(`Suggestion: ${result}. Press Tab to accept.`);
        }
      }, delay);
    },
    [suggest, delay]
  );

  useEffect(
    () => () => {
      if (timer.current) {
        clearTimeout(timer.current);
      }
    },
    []
  );

  // The first suggestion for the starting text, once it's on screen.
  const asked = useRef(false);
  useEffect(() => {
    if (!asked.current) {
      asked.current = true;
      ask(value);
    }
  }, [ask, value]);

  const caretAtEnd = () => {
    const area = areaRef.current;
    return (
      !!area &&
      area.selectionStart === area.selectionEnd &&
      area.selectionEnd === area.value.length
    );
  };

  const onChange = (event: ChangeEvent<HTMLTextAreaElement>) => {
    const next = event.target.value;
    const added = next.startsWith(value) ? next.slice(value.length) : null;
    setValue(next);
    const end = caretAtEnd();
    setAtEnd(end);
    // Typing what the suggestion says eats into it rather than replacing it.
    if (end && added && ghost.startsWith(added)) {
      const rest = ghost.slice(added.length);
      setGhost(rest);
      if (!rest) {
        ask(next);
      }
      return;
    }
    request.current++;
    setGhost("");
    if (end) {
      ask(next);
    }
  };

  const accept = (part: string) => {
    const next = value + part;
    setValue(next);
    setGhost((g) => g.slice(part.length));
    requestAnimationFrame(() => {
      const area = areaRef.current;
      if (area) {
        area.focus();
        area.setSelectionRange(next.length, next.length);
      }
    });
    if (part.length >= ghost.length) {
      ask(next);
    }
  };

  const showGhost = ghost.length > 0 && atEnd;

  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (!showGhost) {
      return;
    }
    const plain = !(event.metaKey || event.ctrlKey || event.altKey);
    if (event.key === "Tab" && plain && !event.shiftKey) {
      event.preventDefault();
      accept(ghost);
    } else if (event.key === "ArrowRight" && plain && caretAtEnd()) {
      event.preventDefault();
      accept(nextWord(ghost));
    } else if (event.key === "Escape") {
      event.preventDefault();
      request.current++;
      setGhost("");
    }
  };

  // Moving the caret off the end hides the suggestion; back at the end, it
  // returns. Clicks and arrow keys both land here.
  const onSelect = () => setAtEnd(caretAtEnd());

  const words = ghost.match(WORDS) ?? [];

  return (
    <div className={cn("w-full", className)}>
      <div className="relative">
        {/* The mirror: the same text, laid out identically under the text
          box, with the suggestion after it. It also sets the height, so
          the box grows with the suggestion and never scrolls. */}
        <div
          aria-hidden="true"
          className="pointer-events-none min-h-32 whitespace-pre-wrap break-words px-4 py-3 text-[15px] leading-6"
        >
          <span className="text-transparent">{value || "​"}</span>
          {value.endsWith("\n") && "​"}
          {showGhost && (
            <span className="text-zinc-400 dark:text-zinc-500" key={batch}>
              {words.map((word, i) => {
                const last = i === words.length - 1;
                return (
                  <span
                    // The Tab hint stays on the line of the last word.
                    className={cn(
                      "ai-autocomplete-word",
                      last && "whitespace-nowrap"
                    )}
                    // biome-ignore lint/suspicious/noArrayIndexKey: words of one suggestion, in order
                    key={i}
                    style={{ animationDelay: `${Math.min(i, 12) * 28}ms` }}
                  >
                    {last ? word.trimEnd() : word}
                    {last && (
                      <kbd className="ml-1.5 inline-flex h-5 translate-y-[-1px] items-center rounded border border-zinc-200 px-1 align-middle font-sans text-[10px] text-zinc-400 dark:border-zinc-800 dark:text-zinc-500">
                        Tab
                      </kbd>
                    )}
                  </span>
                );
              })}
            </span>
          )}
        </div>
        <textarea
          aria-label={label}
          className="absolute inset-0 h-full w-full resize-none overflow-hidden bg-transparent px-4 py-3 text-[15px] text-zinc-900 leading-6 caret-zinc-900 outline-none placeholder:text-zinc-400 dark:text-zinc-100 dark:caret-zinc-100 dark:placeholder:text-zinc-500"
          onChange={onChange}
          onFocus={onSelect}
          onKeyDown={onKeyDown}
          onSelect={onSelect}
          placeholder={placeholder}
          ref={areaRef}
          spellCheck={false}
          value={value}
        />
      </div>
      <p aria-live="polite" className="sr-only">
        {showGhost ? spoken : ""}
      </p>
      <style>{`
        .ai-autocomplete-word {
          animation: ai-autocomplete-in 180ms cubic-bezier(0.23, 1, 0.32, 1) both;
        }
        @keyframes ai-autocomplete-in {
          from { opacity: 0; filter: blur(2px); }
        }
        @media (prefers-reduced-motion: reduce) {
          .ai-autocomplete-word { animation-duration: 1ms; }
        }
      `}</style>
      <AcceptBar
        onAccept={() => accept(ghost)}
        onWord={() => accept(nextWord(ghost))}
        visible={showGhost}
      />
    </div>
  );
}

/** Tap targets for touch screens, which have no Tab key. */
function AcceptBar({
  visible,
  onAccept,
  onWord,
}: {
  visible: boolean;
  onAccept: () => void;
  onWord: () => void;
}) {
  const keep = (event: { preventDefault: () => void }) =>
    // Keep focus (and the caret) in the text box.
    event.preventDefault();
  return (
    <div
      className={cn(
        "flex items-center gap-1 px-3 pb-3 text-xs text-zinc-500 transition-opacity duration-150 dark:text-zinc-400",
        !visible && "pointer-events-none opacity-0"
      )}
    >
      <button
        className="flex items-center gap-1.5 rounded-md px-1.5 py-1 transition-colors duration-150 hover:bg-zinc-100 hover:text-zinc-900 dark:hover:bg-zinc-900 dark:hover:text-zinc-100"
        onClick={onAccept}
        onMouseDown={keep}
        tabIndex={-1}
        type="button"
      >
        <kbd className="rounded border border-zinc-200 px-1 font-sans text-[10px] dark:border-zinc-800">
          Tab
        </kbd>
        Accept
      </button>
      <button
        className="flex items-center gap-1.5 rounded-md px-1.5 py-1 transition-colors duration-150 hover:bg-zinc-100 hover:text-zinc-900 dark:hover:bg-zinc-900 dark:hover:text-zinc-100"
        onClick={onWord}
        onMouseDown={keep}
        tabIndex={-1}
        type="button"
      >
        <kbd className="rounded border border-zinc-200 px-1 font-sans text-[10px] dark:border-zinc-800">
          →
        </kbd>
        Word
      </button>
      <span className="ml-1 hidden sm:inline">
        <kbd className="rounded border border-zinc-200 px-1 font-sans text-[10px] dark:border-zinc-800">
          Esc
        </kbd>{" "}
        Dismiss
      </span>
    </div>
  );
}

// The reply the demo completer knows, sentence by sentence. A real app
// would call a model here; this one finds where you are in the script.
const SCRIPT = [
  "Hi Maya,\n\n",
  "Thanks for the update on the launch timeline. ",
  "Thursday works for me, so let's move the review to 3pm and keep the rest of the plan as it is. ",
  "I'll share the updated deck with the team before then. ",
  "Let me know if anything changes on your side.\n\n",
  "Best,\nSam",
];
const FULL = SCRIPT.join("");
const TRAILING_SPACE = /\s+$/;

function demoSuggest(text: string): Promise<string | null> {
  return new Promise((resolve) => {
    setTimeout(
      () => {
        // Match the end of what's written against the script, loosely.
        const tail = text.slice(-24).toLowerCase();
        const at = FULL.toLowerCase().lastIndexOf(tail);
        if (!tail.trim() || at < 0) {
          resolve(null);
          return;
        }
        const from = at + tail.length;
        // Offer up to the end of the current sentence.
        let end = from;
        let sum = 0;
        for (const part of SCRIPT) {
          sum += part.length;
          if (sum > from) {
            end = sum;
            break;
          }
        }
        const rest = FULL.slice(from, end).replace(TRAILING_SPACE, (s) =>
          s.includes("\n") ? s : " "
        );
        resolve(rest.trim() ? rest : null);
      },
      180 + Math.random() * 220
    );
  });
}

