    ],
  },
  {
    path: "app/checkout/form.test.ts",
    hunks: [
      {
        start: 31,
        lines: [
          {
            type: "context",
            text: '  it("rejects an empty postcode", () => {',
          },
          {
            type: "remove",
            text: '    expect(errorFor("")).toBe("Required");',
          },
          {
            type: "add",
            text: '    expect(errorFor("")).toBe("Enter a valid postcode");',
          },
          { type: "add", text: "  });" },
