/** Plain-language fixes for any text the demo has no hand-written take for. */
const RULES: Record<Action, [RegExp, string][]> = {
  grammar: [
    [/\bthen before\b/g, "than before"],
    [/\bmore then\b/g, "more than"],
    [/\bwho's account\b/g, "whose account"],
