              exit={{
                opacity: 0,
                filter: "blur(2px)",
                transition: { duration: 0.1 },
              }}
              initial={{ opacity: 0, filter: "blur(2px)" }}
              onClick={() => onSelect(null)}
              transition={{ duration: 0.18, ease: EASE_OUT }}
              type="button"
            >
              <X aria-hidden="true" className="size-3.5" />
            </motion.button>
          )}
        </AnimatePresence>
      </span>
    </motion.div>
  );
}

