    group: "Work",
    saved: "Jul 28",
  },
  {
    id: "tone",
    text: "Wants short, direct answers",
    group: "Work",
    saved: "Jul 28",
  },
];

const DEMO_REPLIES: Record<string, MemoryChange> = {
