/**
 * Runs steps a keystroke apart, with a pause after `pauseAfter` so the
 * number has time to slide away before expiry is typed.
 */
function playSteps(
  steps: (() => void)[],
  timer: RefObject<ReturnType<typeof setTimeout> | undefined>,
  pauseAfter: number
) {
  const run = (i: number) => {
    if (i >= steps.length) {
      return;
    }
    steps[i]();
    timer.current = setTimeout(() => run(i + 1), i === pauseAfter ? 260 : 45);
  };
  run(0);
}

/** What typing into the expiry field leaves, as up to four digits. */
function nextExpiry(previous: string, raw: string, inputType: string) {
  let digits = raw.replace(NOT_DIGIT, "").slice(0, 4);
  // Deleting the " / " takes the month digit with it.
  if (
    inputType === "deleteContentBackward" &&
    previous.length === 2 &&
    digits.length === 2
  ) {
    digits = digits.slice(0, 1);
  }
  if (digits.length === 1 && Number(digits) > 1) {
    digits = `0${digits}`;
  }
  return digits;
}

/** Backspace in an empty field, or ← at its start, goes to the field before. */
function stepsBack(event: KeyboardEvent<HTMLInputElement>, value: string) {
  const input = event.currentTarget;
  const atStart = input.selectionStart === 0 && input.selectionEnd === 0;
  return (
    (event.key === "Backspace" && value.length === 0) ||
    (event.key === "ArrowLeft" && atStart)
  );
}

/** Ghost digits show what's still to type, in the brand's grouping. */
function ghostsFor(spec: BrandSpec, typedLength: number) {
  let typed = typedLength;
  return spec.groups.map((size) => {
    const used = Math.min(size, typed);
    typed -= used;
    return "0".repeat(size - used);
  });
}

/** The drawn copy of the number, under a clear input, so groups can fade and slide. */
function NumberMirror({
  spec,
  groups,
  typedLength,
  collapsed,
  hideGhost,
  shift,
  slide,
  fade,
  groupRefs,
}: {
  spec: BrandSpec;
  groups: string[];
  typedLength: number;
  collapsed: boolean;
  hideGhost: boolean;
  shift: number;
  slide: Slide;
  fade: Fade;
  groupRefs: RefObject<(HTMLSpanElement | null)[]>;
}) {
  const ghost = ghostsFor(spec, typedLength);
  return (
    <motion.div
      animate={{ transform: `translateX(${-shift}px)` }}
      aria-hidden="true"
      className="pointer-events-none absolute inset-y-0 left-0 flex items-center whitespace-pre text-[15px] text-zinc-900 tabular-nums tracking-wide dark:text-zinc-100"
      initial={false}
      transition={slide}
    >
      {spec.groups.map((size, i) => {
        const typed = groups[i] ?? "";
        const isLast = i === spec.groups.length - 1;
        return (
          <motion.span
            animate={{ opacity: collapsed && !isLast ? 0 : 1 }}
            initial={false}
            key={`${spec.brand}-${size}-${i.toString()}`}
            ref={(el) => {
              groupRefs.current[i] = el;
            }}
            transition={fade}
          >
            {typed}
            <span
              className={cn(
                "text-zinc-300 transition-opacity duration-150 dark:text-zinc-700",
                hideGhost && "opacity-0"
              )}
            >
              {ghost[i]}
            </span>
            {isLast ? "" : " "}
          </motion.span>
        );
      })}
    </motion.div>
  );
}

function Hint({
  id,
  error,
  onCvc,
  spec,
  fade,
}: {
  id: string;
  error: string | null;
  onCvc: boolean;
  spec: BrandSpec;
  fade: Fade;
}) {
  let key = "secure";
  let body: ReactNode = (
    <>
      <Lock aria-hidden className="size-3" />
      Encrypted end to end
    </>
  );
  if (error) {
    key = error;
    body = error;
  } else if (onCvc) {
    key = "cvc";
    body = `${spec.cvc} digits, ${spec.brand === "amex" ? "on the front" : "on the back"} of your card`;
  }
  return (
    <div className="relative mt-2 h-4 text-xs" id={id}>
      <AnimatePresence initial={false} mode="popLayout">
        <motion.p
          animate={{ opacity: 1, y: 0 }}
          className={cn(
            "flex items-center gap-1.5",
            error
              ? "text-red-600 dark:text-red-400"
              : "text-zinc-500 dark:text-zinc-400"
          )}
          exit={{ opacity: 0, y: -4 }}
          initial={{ opacity: 0, y: 4 }}
          key={key}
          transition={fade}
        >
          {body}
        </motion.p>
      </AnimatePresence>
    </div>
  );
}

const PAY_TONES = {
  off: "bg-zinc-100 text-zinc-400 dark:bg-zinc-900 dark:text-zinc-600",
  ready:
    "bg-zinc-900 text-white hover:bg-zinc-800 dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-white",
  paid: "bg-emerald-600 text-white dark:bg-emerald-500 dark:text-emerald-950",
};

function PayButton({
  ready,
  status,
  money,
  fade,
  onPay,
}: {
  ready: boolean;
  status: "idle" | "paying" | "paid";
  money: string;
  fade: Fade;
  onPay: () => void;
}) {
  let payTone = ready ? PAY_TONES.ready : PAY_TONES.off;
  if (status === "paid") {
    payTone = PAY_TONES.paid;
  }
  let announcement = "";
  if (status === "paying") {
    announcement = "Processing payment";
  } else if (status === "paid") {
    announcement = `Paid ${money}`;
  }
  return (
    <>
      <span aria-live="polite" className="sr-only">
        {announcement}
      </span>
      <button
        aria-disabled={!ready}
        className={cn(
          "mt-4 flex h-11 w-full items-center justify-center gap-2 rounded-xl font-medium text-sm outline-none",
          "transition-colors duration-200 ease-out focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 dark:focus-visible:ring-offset-zinc-950",
          payTone
        )}
        onClick={onPay}
        type="button"
      >
        <AnimatePresence initial={false} mode="popLayout">
          <motion.span
            animate={{ opacity: 1, y: 0 }}
            className="inline-flex items-center gap-2"
            exit={{ opacity: 0, y: -8 }}
            initial={{ opacity: 0, y: 8 }}
            key={status}
            transition={fade}
          >
            {status === "idle" && `Pay ${money}`}
            {status === "paying" && (
              <>
                <span className="size-3.5 animate-spin rounded-full border-2 border-current border-r-transparent" />
                Processing
              </>
            )}
            {status === "paid" && (
              <>
                <Check aria-hidden className="size-4" strokeWidth={2.5} />
                Paid {money}
              </>
            )}
          </motion.span>
        </AnimatePresence>
      </button>
    </>
  );
}

/**
 * A one-row card input for checkout. The number groups the way the brand
 * prints it, and once it checks out it slides away to its last four digits,
 * making room for expiry and security code in the same row.
 */
export default function CardField({
  amount = 48,
  currency = "$",
  onPay,
  testMode = true,
  className,
}: CardFieldProps) {
  const [number, setNumber] = useState("");
  const [expiry, setExpiry] = useState("");
  const [cvc, setCvc] = useState("");
  const [editingNumber, setEditingNumber] = useState(true);
  const [focus, setFocus] = useState<"number" | "expiry" | "cvc" | null>(null);
  const [numberError, setNumberError] = useState(false);
  const [status, setStatus] = useState<"idle" | "paying" | "paid">("idle");
  const reduceMotion = Boolean(useReducedMotion());
  const shakeX = useMotionValue(0);

  const numberRef = useRef<HTMLInputElement>(null);
  const expiryRef = useRef<HTMLInputElement>(null);
  const cvcRef = useRef<HTMLInputElement>(null);
  const groupRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const caretRef = useRef<number | null>(null);
  const fillTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const resetTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const [shift, setShift] = useState(0);
  const id = useId();
  const numberId = `${id}-number`;
  const hintId = `${id}-hint`;

  const spec = specFor(number);
  const full = lengthOf(spec);
  const numberDone = number.length === full && luhn(number);
  const collapsed = numberDone && !editingNumber;
  const groups = groupsOf(number, spec);
  const expiryError = expiryProblem(expiry);
  const expiryDone = expiry.length === 4 && !expiryError;
  const cvcDone = cvc.length === spec.cvc;
  const ready = numberDone && expiryDone && cvcDone;

  const error = numberError
    ? "That card number doesn't look right"
    : expiryError;

  useEffect(
    () => () => {
      clearTimeout(fillTimer.current);
      clearTimeout(resetTimer.current);
    },
    []
  );

  // Keep the caret next to the digit it was after, across the spaces that
  // formatting adds and removes.
  useLayoutEffect(() => {
    const input = numberRef.current;
    if (caretRef.current === null || !input) {
      return;
    }
    // Setting a selection on a field that isn't focused can pull focus to it.
    if (document.activeElement !== input) {
      caretRef.current = null;
      return;
    }
    const want = caretRef.current;
    caretRef.current = null;
    let seen = 0;
    let at = 0;
    const value = input.value;
    while (at < value.length && seen < want) {
      if (value[at] !== " ") {
        seen += 1;
      }
      at += 1;
    }
    input.setSelectionRange(at, at);
  });

  // How far to slide the number so only its last group shows.
  useLayoutEffect(() => {
    if (!collapsed) {
      setShift(0);
      return;
    }
    const last = groupRefs.current[groups.length - 1];
    setShift(last ? last.offsetLeft : 0);
  }, [collapsed, groups.length]);

  const collapse = () => {
    setEditingNumber(false);
    requestAnimationFrame(() => expiryRef.current?.focus());
  };

  // Editing after a payment keeps the new input: the pending reset would
  // otherwise wipe it.
  const touch = () => {
    clearTimeout(resetTimer.current);
    setStatus((current) => (current === "paying" ? current : "idle"));
  };

  const writeNumber = (digits: string, caretDigits: number | null) => {
    const nextSpec = specFor(digits);
    const clipped = digits.slice(0, lengthOf(nextSpec));
    caretRef.current = caretDigits;
    setNumber(clipped);
    // A code typed for Amex is one digit too long for the other brands.
    setCvc((current) => current.slice(0, nextSpec.cvc));
    touch();
    const complete = clipped.length === lengthOf(nextSpec);
    const bad = complete && !luhn(clipped);
    setNumberError(bad);
    if (bad && !reduceMotion) {
      animate(shakeX, [0, -8, 7, -4, 2, 0], {
        duration: 0.36,
        ease: "easeOut",
      });
    } else if (complete && !bad) {
      collapse();
    }
  };

  const onNumber = (event: ChangeEvent<HTMLInputElement>) => {
    const raw = event.target.value;
    const caret = event.target.selectionStart ?? raw.length;
    const before = raw.slice(0, caret).replace(NOT_DIGIT, "").length;
    writeNumber(raw.replace(NOT_DIGIT, ""), before);
  };

  const onExpiry = (event: ChangeEvent<HTMLInputElement>) => {
    const digits = nextExpiry(
      expiry,
      event.target.value,
      (event.nativeEvent as InputEvent).inputType
    );
    setExpiry(digits);
    touch();
    if (digits.length === 4 && !expiryProblem(digits)) {
      cvcRef.current?.focus();
    }
  };

  const onCvc = (event: ChangeEvent<HTMLInputElement>) => {
    setCvc(event.target.value.replace(NOT_DIGIT, "").slice(0, spec.cvc));
    touch();
  };

  const editNumber = () => {
    setEditingNumber(true);
    requestAnimationFrame(() => {
      const input = numberRef.current;
      if (input) {
        input.focus();
        input.setSelectionRange(input.value.length, input.value.length);
      }
    });
  };

  const onExpiryKey = (event: KeyboardEvent<HTMLInputElement>) => {
    if (stepsBack(event, expiry)) {
      event.preventDefault();
      editNumber();
    }
  };

  const onCvcKey = (event: KeyboardEvent<HTMLInputElement>) => {
    if (stepsBack(event, cvc)) {
      event.preventDefault();
      const target = expiryRef.current;
      target?.focus();
      target?.setSelectionRange(target.value.length, target.value.length);
    }
    if (event.key === "Enter" && ready) {
      pay();
    }
  };

  const onNumberBlur = () => {
    setFocus(null);
    if (numberDone) {
      setEditingNumber(false);
    }
  };

  // Types the test card in like a person would, so you see the brand land
  // and the number slide away.
  const fillTestCard = () => {
    clearTimeout(fillTimer.current);
    setExpiry("");
    setCvc("");
    setEditingNumber(true);
    numberRef.current?.focus();
    const year = String((new Date().getFullYear() + 3) % 100).padStart(2, "0");
    const steps = [
      ...[...TEST_CARD].map(
        (_, i) => () => writeNumber(TEST_CARD.slice(0, i + 1), i + 1)
      ),
      () => setExpiry("1"),
      () => setExpiry("12"),
      () => setExpiry(`12${year[0]}`),
      () => {
        setExpiry(`12${year}`);
        cvcRef.current?.focus();
      },
      () => setCvc("1"),
      () => setCvc("12"),
      () => setCvc("123"),
    ];
    playSteps(steps, fillTimer, TEST_CARD.length - 1);
  };

  const pay = async () => {
    if (!ready || status !== "idle") {
      return;
    }
    setStatus("paying");
    const details = {
      brand: spec.brand,
      last4: number.slice(-4),
      expiry: `${expiry.slice(0, 2)}/${expiry.slice(2)}`,
    };
    try {
      await (onPay?.(details) ??
        new Promise((resolve) => setTimeout(resolve, 1100)));
    } catch {
      // A declined charge leaves the card as typed, ready to try again.
      setStatus("idle");
      return;
    }
    setStatus("paid");
    clearTimeout(resetTimer.current);
    resetTimer.current = setTimeout(() => {
      setNumber("");
      setExpiry("");
      setCvc("");
      setEditingNumber(true);
      setStatus("idle");
    }, 2400);
  };

  const slide = reduceMotion
    ? { duration: 0 }
    : { type: "spring" as const, duration: 0.45, bounce: 0 };
  const fade = { duration: reduceMotion ? 0 : 0.2, ease: EASE_OUT };
  const money = `${currency}${amount.toLocaleString("en-US", { minimumFractionDigits: 2 })}`;

  return (
    <div
      className={cn(
        "w-full max-w-sm rounded-3xl border border-zinc-200 bg-white p-5 dark:border-zinc-800 dark:bg-zinc-950",
        className
      )}
    >
      <div className="flex items-baseline justify-between">
        <label
          className="font-medium text-sm text-zinc-900 dark:text-zinc-100"
          htmlFor={numberId}
        >
          Card
        </label>
        {testMode && (
          <button
            className="rounded text-xs text-zinc-500 underline decoration-zinc-300 underline-offset-2 outline-none transition-colors duration-150 hover:text-zinc-900 focus-visible:ring-2 focus-visible:ring-zinc-400 dark:text-zinc-400 dark:decoration-zinc-700 dark:hover:text-zinc-100"
            onClick={fillTestCard}
            type="button"
          >
            Use test card
          </button>
        )}
      </div>

      <motion.div
        className={cn(
          "mt-2 flex h-12 items-center gap-3 rounded-xl border bg-white px-3 transition-[border-color,box-shadow] duration-150 dark:bg-zinc-950",
          rowTone(Boolean(error), focus !== null)
        )}
        style={{ x: shakeX }}
      >
        <BrandSlot back={focus === "cvc"} brand={spec.brand} fade={fade} />

        {/* The number. A clear input over a drawn copy, so the groups can
            fade and slide while the caret stays native. */}
        <div className="relative h-full min-w-0 flex-1 overflow-hidden">
          <NumberMirror
            collapsed={collapsed}
            fade={fade}
            groupRefs={groupRefs}
            groups={groups}
            hideGhost={collapsed || (number.length === 0 && focus !== "number")}
            shift={shift}
            slide={slide}
            spec={spec}
            typedLength={number.length}
          />
          {number.length === 0 && focus !== "number" && (
            <span className="pointer-events-none absolute inset-y-0 left-0 flex items-center text-[15px] text-zinc-400 dark:text-zinc-500">
              Card number
            </span>
          )}
          <input
            aria-describedby={hintId}
            aria-invalid={numberError}
            autoComplete="cc-number"
            className={cn(
              "absolute inset-0 h-full w-full bg-transparent text-[15px] text-transparent tabular-nums tracking-wide caret-zinc-900 outline-none dark:caret-zinc-100",
              collapsed && "pointer-events-none"
            )}
            id={numberId}
            inputMode="numeric"
            onBlur={onNumberBlur}
            onChange={onNumber}
            onFocus={() => {
              setFocus("number");
              setEditingNumber(true);
            }}
            onKeyDown={(event) => {
              // Tab from a finished number lands in expiry, not past the row.
              if (event.key === "Tab" && !event.shiftKey && numberDone) {
                event.preventDefault();
                collapse();
              }
            }}
            ref={numberRef}
            spellCheck={false}
            tabIndex={collapsed ? -1 : 0}
            value={groups.join(" ")}
          />
          {collapsed && (
            <button
              aria-label={`Edit card number ending ${number.slice(-4)}`}
              className="absolute inset-0 cursor-text rounded-md outline-none focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-inset"
              onClick={editNumber}
              type="button"
            />
          )}
        </div>

        <AnimatePresence initial={false}>
          {collapsed && (
            <motion.div
              animate={{ opacity: 1, x: 0 }}
              className="flex shrink-0 items-center gap-3"
              exit={{
                opacity: 0,
                x: 12,
                transition: { duration: reduceMotion ? 0 : 0.12 },
              }}
              initial={{ opacity: 0, x: 16 }}
              key="rest"
              transition={{ ...slide, opacity: fade }}
            >
              <input
                aria-invalid={Boolean(expiryError)}
                aria-label="Expiry, month and year"
                autoComplete="cc-exp"
                className={cn(
                  "h-10 w-[4.6rem] bg-transparent text-[15px] tabular-nums outline-none placeholder:text-zinc-400 dark:placeholder:text-zinc-500",
                  expiryError
                    ? "text-red-600 dark:text-red-400"
                    : "text-zinc-900 dark:text-zinc-100"
                )}
                inputMode="numeric"
                onBlur={() => setFocus(null)}
                onChange={onExpiry}
                onFocus={() => setFocus("expiry")}
                onKeyDown={onExpiryKey}
                placeholder="MM / YY"
                ref={expiryRef}
                value={formatExpiry(expiry)}
              />
              <input
                aria-label="Security code"
                autoComplete="cc-csc"
                className="h-10 w-[2.6rem] bg-transparent text-[15px] text-zinc-900 tabular-nums outline-none placeholder:text-zinc-400 dark:text-zinc-100 dark:placeholder:text-zinc-500"
                inputMode="numeric"
                onBlur={() => setFocus(null)}
                onChange={onCvc}
                onFocus={() => setFocus("cvc")}
                onKeyDown={onCvcKey}
                placeholder={spec.cvc === 4 ? "CVV" : "CVC"}
                ref={cvcRef}
                value={cvc}
              />
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>

      <Hint
        error={error}
        fade={fade}
        id={hintId}
        onCvc={focus === "cvc"}
        spec={spec}
      />

      <PayButton
        fade={fade}
        money={money}
        onPay={pay}
        ready={ready}
        status={status}
      />
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Flick Card
 * @version: 2.0.0
 * @date: 2026-10-14
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import {
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
  type Ref,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

// Degrees of turn per px of drag.
const DEG_PER_PX = 0.6;
// Spring that lands the card on a face, in degrees and seconds.
const STIFFNESS = 170;
const DAMPING = 20;
// How far ahead (in seconds of release velocity) the landing face is picked.
const PROJECTION = 0.22;
// A release faster than this (deg/s) always turns at least one face.
const FLICK_SPEED = 450;
// Never spin more than this many half turns from one flick.
const MAX_HALF_TURNS = 6;
// Movement below this (px) is a click, not a drag.
const DRAG_SLOP = 4;
// How far the card lifts toward the viewer at 90°, in px.
const LIFT = 36;
// Hover pre-tilt toward the pointer, in degrees.
const TILT = 6;
// Card thickness: stacked slices between the two faces.
const THICKNESS = 6;
const SLICES = 7;
const SLICE_DEPTHS = Array.from(
  { length: SLICES },
  (_, i) => -THICKNESS / 2 + (THICKNESS * (i + 0.5)) / SLICES
);
const SUBSTEP = 1 / 240;
// Release velocity is read from the last this-many ms of the drag.
const VELOCITY_WINDOW = 80;

const INTERACTIVE = "button, a, input, select, textarea, [data-no-flip]";

type Axis = "x" | "y";

export interface CardFlipProps {
  /** Front face. Defaults to an event ticket. */
  front?: ReactNode;
  /** Back face. Defaults to the ticket's entry code and seat. */
  back?: ReactNode;
  /** Controlled side: true shows the back. */
  flipped?: boolean;
  /** Starting side when uncontrolled. */
  defaultFlipped?: boolean;
  /** Called when a drag, click or key turns the card to the other side. */
  onFlippedChange?: (flipped: boolean) => void;
  /** "y" spins left and right like a coin, "x" tumbles top over bottom. */
  axis?: Axis;
  /** Accessible name of the card. */
  label?: string;
  className?: string;
  /** Classes for both faces, such as background, border and radius. */
  faceClassName?: string;
}

const mod2 = (n: number) => ((n % 2) + 2) % 2;
const sideOf = (angle: number) => mod2(Math.round(angle / 180)) === 1;
const nearestFace = (angle: number) => Math.round(angle / 180) * 180;

interface Sim {
  angle: number;
  velocity: number;
  target: number;
  raf: number;
  last: number;
  reduceMotion: boolean;
  pointerId: number | null;
  startX: number;
  startY: number;
  startAngle: number;
  dragging: boolean;
  samples: { t: number; a: number }[];
}

function cardTransform(axis: Axis, angle: number, lift: number) {
  const rotate = axis === "y" ? "rotateY" : "rotateX";
  return `translateZ(${lift.toFixed(2)}px) ${rotate}(${angle.toFixed(2)}deg)`;
}

// A flat band of light sweeps across whichever face is showing, and the face
// dims as it turns away from the light.
function paintLight(
  axis: Axis,
  sin: number,
  bands: (HTMLDivElement | null)[],
  shades: (HTMLDivElement | null)[]
) {
  const turn = Math.abs(sin);
  const shift = `${(sin * 140).toFixed(1)}%`;
  const transform =
    axis === "y"
      ? `translateX(${shift}) rotate(18deg)`
      : `translateY(${shift}) rotate(72deg)`;
  for (const band of bands) {
    if (band) {
      band.style.opacity = (turn * 0.12).toFixed(3);
      band.style.transform = transform;
    }
  }
  for (const shade of shades) {
    if (shade) {
      shade.style.opacity = (turn * 0.14).toFixed(3);
    }
  }
}

function releaseVelocity(samples: Sim["samples"], now: number) {
  const last = samples.at(-1);
  if (!last || now - last.t > VELOCITY_WINDOW) {
    return 0;
  }
  const first = samples.find((p) => last.t - p.t <= VELOCITY_WINDOW);
  if (!first || last.t <= first.t) {
    return 0;
  }
  return ((last.a - first.a) / (last.t - first.t)) * 1000;
}

export default function CardFlip({
  front,
  back,
  flipped,
  defaultFlipped = false,
  onFlippedChange,
  axis = "y",
  label = "Event ticket",
  className,
  faceClassName,
}: CardFlipProps) {
  const isControlled = flipped !== undefined;
  const [internalFlipped, setInternalFlipped] = useState(defaultFlipped);
  const isFlipped = isControlled ? flipped : internalFlipped;
  // Which face is turned toward the viewer right now (changes at 90°).
  const [backVisible, setBackVisible] = useState(isFlipped);
  // Bumped when a controlled card asks to turn; see the effect below.
  const [request, setRequest] = useState(0);
  const hintId = useId();

  const rootRef = useRef<HTMLDivElement>(null);
  const tiltRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  const shadowRef = useRef<HTMLDivElement>(null);
  const frontBandRef = useRef<HTMLDivElement>(null);
  const backBandRef = useRef<HTMLDivElement>(null);
  const frontShadeRef = useRef<HTMLDivElement>(null);
  const backShadeRef = useRef<HTMLDivElement>(null);

  // Styles React writes once; the spring owns them after that.
  const [initial] = useState(() => {
    const angle = isFlipped ? 180 : 0;
    return {
      angle,
      card: { transform: cardTransform(axis, angle, 0) },
      front: { transform: `translateZ(${THICKNESS / 2}px)` },
    };
  });

  const sim = useRef<Sim>({
    angle: initial.angle,
    velocity: 0,
    target: initial.angle,
    raf: 0,
    last: 0,
    reduceMotion: false,
    pointerId: null,
    startX: 0,
    startY: 0,
    startAngle: 0,
    dragging: false,
    samples: [],
  });

  // Latest props for the imperative handlers.
  const latest = useRef({ axis, isFlipped, isControlled, onFlippedChange });
  latest.current = { axis, isFlipped, isControlled, onFlippedChange };
  const backVisibleRef = useRef(backVisible);

  const render = useCallback(() => {
    const s = sim.current;
    const ax = latest.current.axis;
    const rad = (s.angle * Math.PI) / 180;
    const sin = Math.sin(rad);
    const turn = Math.abs(sin);
    const facing = Math.abs(Math.cos(rad));

    if (cardRef.current) {
      cardRef.current.style.transform = cardTransform(ax, s.angle, turn * LIFT);
    }
    if (shadowRef.current) {
      const narrow = (0.16 + 0.84 * facing).toFixed(3);
      const soft = (1 - turn * 0.12).toFixed(3);
      shadowRef.current.style.transform =
        ax === "y" ? `scale(${narrow}, ${soft})` : `scale(${soft}, ${narrow})`;
      shadowRef.current.style.opacity = (1 - turn * 0.45).toFixed(3);
    }
    paintLight(
      ax,
      sin,
      [frontBandRef.current, backBandRef.current],
      [frontShadeRef.current, backShadeRef.current]
    );

    const showsBack = sideOf(s.angle);
    if (showsBack !== backVisibleRef.current) {
      backVisibleRef.current = showsBack;
      setBackVisible(showsBack);
    }
  }, []);

  const step = useCallback(
    (now: number) => {
      const s = sim.current;
      const dt = Math.min(0.05, (now - s.last) / 1000);
      s.last = now;
      const n = Math.max(1, Math.ceil(dt / SUBSTEP));
      const h = dt / n;
      for (let i = 0; i < n; i++) {
        const force = -STIFFNESS * (s.angle - s.target) - DAMPING * s.velocity;
        s.velocity += force * h;
        s.angle += s.velocity * h;
      }
      if (Math.abs(s.angle - s.target) < 0.05 && Math.abs(s.velocity) < 0.5) {
        // Settled: park on 0 or 180 so the numbers never grow, then sleep.
        s.target = sideOf(s.target) ? 180 : 0;
        s.angle = s.target;
        s.velocity = 0;
        s.raf = 0;
        render();
        return;
      }
      render();
      s.raf = requestAnimationFrame(step);
    },
    [render]
  );

  const settle = useCallback(() => {
    const s = sim.current;
    if (s.reduceMotion) {
      // Reduced motion: no spin, land on the face at once.
      cancelAnimationFrame(s.raf);
      s.raf = 0;
      s.target = sideOf(s.target) ? 180 : 0;
      s.angle = s.target;
      s.velocity = 0;
      render();
      return;
    }
    if (!s.raf) {
      s.last = performance.now();
      s.raf = requestAnimationFrame(step);
    }
  }, [render, step]);

  // Point the spring at a face and report a side change.
  const aim = useCallback(
    (target: number) => {
      sim.current.target = target;
      const next = sideOf(target);
      const p = latest.current;
      if (next !== p.isFlipped) {
        if (p.isControlled) {
          setRequest((n) => n + 1);
        } else {
          setInternalFlipped(next);
        }
        p.onFlippedChange?.(next);
      }
      settle();
    },
    [settle]
  );

  const flipBy = useCallback(
    (direction: number) => {
      aim(nearestFace(sim.current.target) + 180 * direction);
    },
    [aim]
  );

  useEffect(() => {
    const s = sim.current;
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    s.reduceMotion = query.matches;
    const onChange = () => {
      s.reduceMotion = query.matches;
    };
    query.addEventListener("change", onChange);
    return () => {
      query.removeEventListener("change", onChange);
      cancelAnimationFrame(s.raf);
      s.raf = 0;
    };
  }, []);

  // Controlled: follow the prop when it disagrees with where the card lands.
  // `request` re-runs this after every turn the card asks for, so a parent
  // that ignores onFlippedChange sends the card back to its side.
  useEffect(() => {
    if (flipped === undefined || request < 0) {
      return;
    }
    const s = sim.current;
    if (s.dragging || sideOf(s.target) === flipped) {
      return;
    }
    // The nearest face on the asked-for side, so a refused turn swings back
    // the way it came.
    const face = nearestFace(s.angle);
    if (sideOf(face) === flipped) {
      s.target = face;
    } else {
      s.target = face + (s.angle < face ? -180 : 180);
    }
    settle();
  }, [flipped, request, settle]);

  // A new axis redraws the spring-owned transforms in place.
  useEffect(() => {
    latest.current.axis = axis;
    render();
  }, [axis, render]);

  const setTilt = (x: number, y: number) => {
    if (tiltRef.current) {
      tiltRef.current.style.transform = `rotateX(${(-y * TILT).toFixed(2)}deg) rotateY(${(x * TILT).toFixed(2)}deg)`;
    }
  };

  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    const s = sim.current;
    // One pointer at a time: a second finger does not steal the drag.
    if (
      s.pointerId !== null ||
      e.button !== 0 ||
      (e.target as Element).closest(INTERACTIVE)
    ) {
      return;
    }
    s.pointerId = e.pointerId;
    s.startX = e.clientX;
    s.startY = e.clientY;
    s.startAngle = s.angle;
    s.dragging = false;
    s.samples = [{ t: e.timeStamp, a: s.angle }];
    e.currentTarget.setPointerCapture(e.pointerId);
  };

  const hoverTilt = (e: PointerEvent<HTMLDivElement>) => {
    // The tilt follows the cursor: it's movement, so reduced motion skips it.
    if (
      e.pointerType !== "mouse" ||
      sim.current.reduceMotion ||
      !rootRef.current
    ) {
      return;
    }
    const r = rootRef.current.getBoundingClientRect();
    setTilt(
      ((e.clientX - r.left) / r.width) * 2 - 1,
      ((e.clientY - r.top) / r.height) * 2 - 1
    );
  };

  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    const s = sim.current;
    if (s.pointerId !== e.pointerId) {
      hoverTilt(e);
      return;
    }
    const dx = e.clientX - s.startX;
    const dy = e.clientY - s.startY;
    if (!s.dragging) {
      if (Math.hypot(dx, dy) < DRAG_SLOP) {
        return;
      }
      s.dragging = true;
      cancelAnimationFrame(s.raf);
      s.raf = 0;
      s.velocity = 0;
      setTilt(0, 0);
    }
    // One to one: the card stays under the finger.
    s.angle = s.startAngle + (axis === "y" ? dx : -dy) * DEG_PER_PX;
    s.samples.push({ t: e.timeStamp, a: s.angle });
    if (s.samples.length > 8) {
      s.samples.shift();
    }
    render();
  };

  const release = (e: PointerEvent<HTMLDivElement>, cancelled: boolean) => {
    const s = sim.current;
    if (s.pointerId !== e.pointerId) {
      return;
    }
    s.pointerId = null;
    if (!s.dragging) {
      if (!cancelled) {
        // A click pushes the half you pressed away from you.
        const r = e.currentTarget.getBoundingClientRect();
        const pushed =
          axis === "y"
            ? e.clientX > r.left + r.width / 2
            : e.clientY < r.top + r.height / 2;
        flipBy(pushed ? 1 : -1);
      }
      return;
    }
    s.dragging = false;

    const velocity = cancelled ? 0 : releaseVelocity(s.samples, e.timeStamp);
    const from = nearestFace(s.startAngle);
    let target = nearestFace(s.angle + velocity * PROJECTION);
    if (Math.abs(velocity) > FLICK_SPEED && target === from) {
      target = from + 180 * Math.sign(velocity);
    }
    const limit = MAX_HALF_TURNS * 180;
    target = Math.max(from - limit, Math.min(from + limit, target));
    s.velocity = velocity;
    aim(target);
  };

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.target !== e.currentTarget) {
      return;
    }
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      flipBy(1);
    }
  };

  const face = cn(
    "absolute inset-0 overflow-hidden rounded-2xl [backface-visibility:hidden]",
    "border border-zinc-200 bg-white text-zinc-900",
    "dark:border-zinc-800 dark:bg-zinc-900 dark:text-zinc-50",
    faceClassName
  );

  return (
    // biome-ignore lint/a11y/useSemanticElements: a labelled card whose faces hold their own content, not a plain button
    // biome-ignore lint/a11y/noNoninteractiveElementInteractions: drag, click and Enter or Space all turn the card
    <div
      aria-describedby={hintId}
      aria-label={label}
      aria-roledescription="flip card"
      className={cn(
        "group/flick relative aspect-[7/10] w-[260px] select-none rounded-2xl outline-hidden [perspective:1100px]",
        "focus-visible:ring-2 focus-visible:ring-orange-500 focus-visible:ring-offset-4 focus-visible:ring-offset-white dark:focus-visible:ring-offset-zinc-950",
        axis === "y" ? "touch-pan-y" : "touch-pan-x",
        className
      )}
      onKeyDown={onKeyDown}
      onLostPointerCapture={(e) => release(e, true)}
      onPointerCancel={(e) => release(e, true)}
      onPointerDown={onPointerDown}
      onPointerLeave={() => {
        if (sim.current.pointerId === null) {
          setTilt(0, 0);
        }
      }}
      onPointerMove={onPointerMove}
      onPointerUp={(e) => release(e, false)}
      ref={rootRef}
      role="group"
      // biome-ignore lint/a11y/noNoninteractiveTabindex: Enter and Space flip the card while it has focus
      tabIndex={0}
    >
      {/* Floor shadow: narrows and fades as the card turns edge-on. */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-[8%] -bottom-7 h-6 rounded-[50%] bg-zinc-900/25 blur-md dark:bg-black/70"
        ref={shadowRef}
      />

      <div
        className="relative h-full w-full transition-transform duration-500 ease-[cubic-bezier(0.23,1,0.32,1)] [transform-style:preserve-3d] motion-reduce:transition-none"
        ref={tiltRef}
      >
        <div
          className="relative h-full w-full cursor-grab rounded-2xl [transform-style:preserve-3d] group-active/flick:cursor-grabbing"
          ref={cardRef}
          style={initial.card}
        >
          {/* The edge: thin slices stacked between the two faces. */}
          {SLICE_DEPTHS.map((z) => (
            <div
              aria-hidden="true"
              className="absolute inset-0 rounded-2xl bg-zinc-300 dark:bg-zinc-700"
              key={z}
              style={{ transform: `translateZ(${z.toFixed(3)}px)` }}
            />
          ))}

          <div
            aria-hidden={backVisible || undefined}
            className={face}
            inert={backVisible}
            style={initial.front}
          >
            {front ?? <TicketFront />}
            <LightBand bandRef={frontBandRef} shadeRef={frontShadeRef} />
          </div>

          <div
            aria-hidden={!backVisible || undefined}
            className={face}
            inert={!backVisible}
            style={{
              transform: `${axis === "y" ? "rotateY" : "rotateX"}(180deg) translateZ(${THICKNESS / 2}px)`,
            }}
          >
            {back ?? <TicketBack />}
            <LightBand bandRef={backBandRef} shadeRef={backShadeRef} />
          </div>
        </div>
      </div>

      <span className="sr-only" id={hintId}>
        Showing the {isFlipped ? "back" : "front"}. Press Enter or Space, or
        drag, to turn it over.
      </span>
    </div>
  );
}

function LightBand({
  bandRef,
  shadeRef,
}: {
  bandRef: Ref<HTMLDivElement>;
  shadeRef: Ref<HTMLDivElement>;
