import {
  Cherry,
  Croissant,
  type LucideIcon,
  Milk,
  Minus,
  Plus,
  Trash2,
} from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type MouseEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

const EASE_OUT = [0.23, 1, 0.32, 1] as const;
/** Pill widths: "Add +" at rest, "− n +" once something is in the cart. */
const WIDTH_CLOSED = 80;
const WIDTH_OPEN = 108;
/** Press and hold + or −: wait, then repeat faster and faster. */
const HOLD_DELAY = 380;
const REPEAT_FIRST = 150;
const REPEAT_FASTEST = 55;
/** How long "Limit n per order" stays up. */
const LIMIT_FOR = 1600;

export interface AddToCartButtonProps {
  /** Controlled quantity. Leave out to let the button keep its own. */
  quantity?: number;
  defaultQuantity?: number;
  /** Most of this item one order can hold. */
  max?: number;
  /** Item name, used in the button labels for screen readers. */
  name?: string;
  label?: string;
  onQuantityChange?: (quantity: number) => void;
  className?: string;
}

/**
 * "Add +" that opens into a "− n +" stepper in place. The + never moves, so a
 * second tap lands where the first did. At one, − turns into a bin; holding
 * + or − repeats, and a hold on − stops at one rather than emptying the line.
 */
export function AddToCartButton({
  quantity,
  defaultQuantity = 0,
  max = 9,
  name = "item",
  label = "Add",
  onQuantityChange,
  className,
}: AddToCartButtonProps) {
  const [ownQuantity, setOwnQuantity] = useState(defaultQuantity);
  const value = quantity ?? ownQuantity;
  const [direction, setDirection] = useState(1);
  const [limitHits, setLimitHits] = useState(0);
  const [showLimit, setShowLimit] = useState(false);
  const reduceMotion = Boolean(useReducedMotion());

  const valueRef = useRef(value);
  valueRef.current = value;
  const holdRef = useRef<ReturnType<typeof setTimeout>>(undefined);
  // A touch press waiting to turn out a tap, a hold, or the start of a scroll.
  const touchRef = useRef<number | null>(null);
  const limitRef = useRef<ReturnType<typeof setTimeout>>(undefined);
  const addRef = useRef<HTMLButtonElement>(null);
  const plusRef = useRef<HTMLButtonElement>(null);
  const focusNext = useRef<"add" | "plus" | null>(null);

  const open = value > 0;

  const commit = useCallback(
    (next: number) => {
      const clamped = Math.min(max, Math.max(0, next));
      if (clamped === valueRef.current) {
        return;
      }
      setDirection(clamped > valueRef.current ? 1 : -1);
      valueRef.current = clamped;
      if (quantity === undefined) {
        setOwnQuantity(clamped);
      }
      onQuantityChange?.(clamped);
    },
    [max, quantity, onQuantityChange]
  );

  const hitLimit = useCallback(() => {
    setLimitHits((hits) => hits + 1);
    setShowLimit(true);
    clearTimeout(limitRef.current);
    limitRef.current = setTimeout(() => setShowLimit(false), LIMIT_FOR);
  }, []);

  /** One step; returns false when the step can't happen. */
  const step = useCallback(
    (delta: number) => {
      if (delta > 0 && valueRef.current >= max) {
        hitLimit();
        return false;
      }
      if (delta < 0 && valueRef.current === 1) {
        // The last one out: hand focus back to "Add" if it was on −.
        focusNext.current = "add";
      }
      commit(valueRef.current + delta);
      return true;
    },
    [commit, hitLimit, max]
  );

  const stopHold = useCallback(() => {
    clearTimeout(holdRef.current);
    touchRef.current = null;
  }, []);

  // A touch that was neither cancelled by a scroll nor held long enough to
  // repeat counts as one tap when the finger lifts.
  const endPress = () => {
    const delta = touchRef.current;
    stopHold();
    if (delta !== null) {
      step(delta);
    }
  };

  const startHold = (delta: number) => (event: PointerEvent) => {
    if (event.button !== 0) {
      return;
    }
    event.currentTarget.setPointerCapture(event.pointerId);
    stopHold();
    let interval = REPEAT_FIRST;
    const tick = () => {
      // A hold on − stops at one: emptying the line takes its own tap.
      if (delta < 0 && valueRef.current <= 1) {
        return;
      }
      if (!step(delta)) {
        return;
      }
      interval = Math.max(REPEAT_FASTEST, interval * 0.82);
      holdRef.current = setTimeout(tick, interval);
    };
    // In a list, a finger landing on + may be starting a scroll, so touch
    // waits for the lift (or the hold) instead of stepping on contact.
    if (event.pointerType === "touch") {
      touchRef.current = delta;
      holdRef.current = setTimeout(() => {
        touchRef.current = null;
        if (step(delta)) {
          holdRef.current = setTimeout(tick, REPEAT_FIRST);
        }
      }, HOLD_DELAY);
      return;
    }
    if (!step(delta)) {
      return;
    }
    holdRef.current = setTimeout(tick, HOLD_DELAY);
  };

  // Mouse presses step on pointerdown, touch on release; Enter and Space
  // arrive as a click.
  const keyStep = (delta: number) => (event: MouseEvent) => {
    if (event.detail === 0) {
      step(delta);
    }
  };

  const add = () => {
    focusNext.current = "plus";
    setDirection(1);
    commit(1);
  };

  useEffect(() => {
    if (focusNext.current === "plus" && value > 0) {
      plusRef.current?.focus();
    }
    if (focusNext.current === "add" && value === 0) {
      // After the press settles, or the browser drops focus on the removed −.
      requestAnimationFrame(() => addRef.current?.focus());
    }
    focusNext.current = null;
    if (value === 0) {
      clearTimeout(holdRef.current);
    }
  }, [value]);

  useEffect(
    () => () => {
      clearTimeout(holdRef.current);
      clearTimeout(limitRef.current);
    },
    []
  );

  const atMax = value >= max;
  const fade = reduceMotion
    ? { duration: 0 }
    : { duration: 0.2, ease: EASE_OUT };

  return (
    <div className={cn("relative inline-flex", className)}>
      <AnimatePresence>
        {showLimit && (
          <motion.span
            animate={{ opacity: 1, y: 0 }}
            className="pointer-events-none absolute right-0 bottom-full mb-2 whitespace-nowrap rounded-md bg-zinc-900 px-2 py-1 font-medium text-[11px] text-white dark:bg-zinc-100 dark:text-zinc-900"
            exit={{ opacity: 0, y: 2 }}
            initial={{ opacity: 0, y: 4 }}
            role="status"
            transition={fade}
          >
            Limit {max} per order
          </motion.span>
        )}
      </AnimatePresence>

      <motion.div
        animate={{ width: open ? WIDTH_OPEN : WIDTH_CLOSED }}
        className={cn(
          "relative h-9 overflow-hidden rounded-full ring-1 transition-colors duration-200 motion-reduce:transition-none",
          open
            ? "bg-zinc-900 text-white ring-zinc-900 dark:bg-zinc-100 dark:text-zinc-900 dark:ring-zinc-100"
            : "bg-white text-zinc-900 shadow-xs ring-zinc-200 hover:bg-zinc-50 dark:bg-zinc-900 dark:text-zinc-100 dark:ring-zinc-800 dark:hover:bg-zinc-800/70"
        )}
        initial={false}
        transition={{ ...fade, duration: reduceMotion ? 0 : 0.32 }}
      >
        <AnimatePresence initial={false}>
          {!open && (
            <motion.span
              animate={{ opacity: 1, x: 0, filter: "blur(0px)" }}
              aria-hidden
              className="pointer-events-none absolute inset-y-0 left-3.5 z-10 flex items-center font-medium text-sm"
              exit={{ opacity: 0, x: -6, filter: "blur(2px)" }}
              initial={{ opacity: 0, x: -6, filter: "blur(2px)" }}
              key="label"
              transition={fade}
            >
              {label}
            </motion.span>
          )}
        </AnimatePresence>

        {open ? (
          <fieldset className="contents">
            <legend className="sr-only">{`Quantity of ${name}`}</legend>
            <motion.button
              animate={{ opacity: 1, x: 0 }}
              aria-label={value === 1 ? `Remove ${name}` : `One less ${name}`}
              className="absolute inset-y-0 left-0 flex w-9 items-center justify-center rounded-full outline-none transition-colors duration-150 hover:bg-white/10 focus-visible:ring-2 focus-visible:ring-white/50 focus-visible:ring-inset active:bg-white/20 dark:active:bg-black/10 dark:focus-visible:ring-black/30 dark:hover:bg-black/5"
              initial={{ opacity: 0, x: 16 }}
              onClick={keyStep(-1)}
              onLostPointerCapture={stopHold}
              onPointerCancel={stopHold}
              onPointerDown={startHold(-1)}
              onPointerUp={endPress}
              transition={fade}
              type="button"
            >
              <MinusGlyph bin={value === 1} reduceMotion={reduceMotion} />
            </motion.button>

            <motion.output
              animate={{ opacity: 1, x: 0 }}
              aria-live="polite"
              className="absolute inset-y-0 right-9 left-9 flex items-center justify-center overflow-hidden font-semibold text-sm tabular-nums"
              initial={{ opacity: 0, x: 12 }}
              transition={fade}
            >
              <span className="sr-only">{`${value} ${name} in cart`}</span>
              <motion.span
                animate={
                  limitHits > 0 && !reduceMotion
                    ? { x: [0, -3, 3, -2, 2, 0] }
                    : undefined
                }
                aria-hidden
                className="flex"
                key={limitHits}
                transition={{ duration: 0.3, ease: "easeOut" }}
              >
                <RollingText
                  direction={direction}
                  reduceMotion={reduceMotion}
                  text={String(value)}
                />
              </motion.span>
            </motion.output>

            <button
              aria-disabled={atMax}
              aria-label={`One more ${name}`}
              className={cn(
                "absolute inset-y-0 right-0 flex w-9 items-center justify-center rounded-full outline-none transition-colors duration-150 focus-visible:ring-2 focus-visible:ring-white/50 focus-visible:ring-inset dark:focus-visible:ring-black/30",
                atMax
                  ? "text-white/40 dark:text-zinc-900/35"
                  : "hover:bg-white/10 active:bg-white/20 dark:active:bg-black/10 dark:hover:bg-black/5"
              )}
              onClick={keyStep(1)}
              onLostPointerCapture={stopHold}
              onPointerCancel={stopHold}
              onPointerDown={startHold(1)}
              onPointerUp={endPress}
              ref={plusRef}
              type="button"
            >
              <Plus aria-hidden className="size-4" />
            </button>
          </fieldset>
        ) : (
          <button
            aria-label={`${label} ${name} to cart`}
            className="absolute inset-0 flex items-center justify-end rounded-full outline-none focus-visible:ring-2 focus-visible:ring-zinc-900/20 focus-visible:ring-inset dark:focus-visible:ring-white/25"
            onClick={add}
            ref={addRef}
            type="button"
          >
            <span className="flex w-9 items-center justify-center">
              <Plus aria-hidden className="size-4" />
            </span>
          </button>
        )}
      </motion.div>
    </div>
  );
}

/** − at two or more; a bin at one, since the next tap empties the line. */
function MinusGlyph({
  bin,
  reduceMotion,
}: {
  bin: boolean;
  reduceMotion: boolean;
}) {
  return (
    <AnimatePresence initial={false} mode="popLayout">
      <motion.span
        animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
        className="flex"
        exit={{ opacity: 0, scale: 0.6, filter: "blur(2px)" }}
        initial={{ opacity: 0, scale: 0.6, filter: "blur(2px)" }}
        key={bin ? "bin" : "minus"}
        transition={reduceMotion ? { duration: 0 } : { duration: 0.16 }}
      >
        {bin ? (
          <Trash2 aria-hidden className="size-3.5" />
        ) : (
          <Minus aria-hidden className="size-4" />
        )}
      </motion.span>
    </AnimatePresence>
  );
}

/** Each character rolls on its own, keyed by its place from the right. */
function RollingText({
  text,
  direction,
  reduceMotion,
}: {
  text: string;
  direction: number;
  reduceMotion: boolean;
}) {
  const places = text.split("").map((char, index) => ({
    char,
    place: text.length - index,
  }));
  return (
    <span className="inline-flex overflow-hidden tabular-nums">
      {places.map(({ char, place }) => (
        <span className="relative inline-block" key={place}>
          <AnimatePresence custom={direction} initial={false} mode="popLayout">
            <motion.span
              animate={{ y: 0, opacity: 1 }}
              className="inline-block"
              custom={direction}
              exit={reduceMotion ? { opacity: 0 } : "out"}
              initial={reduceMotion ? { opacity: 0 } : "in"}
              key={char}
              transition={
                reduceMotion
                  ? { duration: 0 }
                  : { duration: 0.24, ease: EASE_OUT }
              }
              variants={{
                in: (dir: number) => ({ y: dir * 12, opacity: 0 }),
                out: (dir: number) => ({ y: dir * -12, opacity: 0 }),
              }}
            >
              {char}
            </motion.span>
          </AnimatePresence>
        </span>
      ))}
    </span>
  );
}

export interface CartItem {
  id: string;
  name: string;
  /** Pack size or weight, shown under the name. */
  detail: string;
  price: number;
  icon: LucideIcon;
  /** Tailwind classes for the icon tile. */
  tint: string;
  max?: number;
}

export interface CartButtonProps {
  items?: CartItem[];
  /** Starting quantities, by item id. */
  defaultQuantities?: Record<string, number>;
  currency?: string;
  onCheckout?: (quantities: Record<string, number>) => void;
  className?: string;
}

const DEFAULT_ITEMS: CartItem[] = [
  {
    id: "oat-milk",
    name: "Oat milk",
    detail: "1 L · Barista",
    price: 3.2,
    icon: Milk,
    tint: "bg-sky-50 text-sky-600 dark:bg-sky-500/10 dark:text-sky-300",
    max: 6,
  },
  {
    id: "croissant",
    name: "Butter croissant",
    detail: "Baked this morning",
    price: 2.6,
    icon: Croissant,
    tint: "bg-orange-50 text-orange-600 dark:bg-orange-500/10 dark:text-orange-300",
    max: 8,
  },
  {
    id: "cherries",
    name: "Cherries",
    detail: "500 g punnet",
    price: 5.8,
    icon: Cherry,
    tint: "bg-rose-50 text-rose-600 dark:bg-rose-500/10 dark:text-rose-300",
    max: 3,
  },
];

const money = (value: number, currency: string) =>
  `${currency}${value.toFixed(2)}`;

export default function CartButton({
  items = DEFAULT_ITEMS,
  defaultQuantities = { croissant: 2 },
  currency = "$",
  onCheckout,
  className,
}: CartButtonProps) {
  const [quantities, setQuantities] = useState(defaultQuantities);
  const reduceMotion = Boolean(useReducedMotion());

  const count = items.reduce(
    (sum, item) => sum + (quantities[item.id] ?? 0),
    0
  );
  const total = items.reduce(
    (sum, item) => sum + (quantities[item.id] ?? 0) * item.price,
    0
  );

  let summary = "Your cart is empty";
  if (count > 0) {
    summary = `Subtotal · ${count} ${count === 1 ? "item" : "items"}`;
  }

  const lastTotal = useRef(total);
  const direction = total >= lastTotal.current ? 1 : -1;
  useEffect(() => {
    lastTotal.current = total;
  }, [total]);

  return (
    <div
      className={cn(
        "w-full max-w-sm rounded-2xl bg-white ring-1 ring-zinc-200 dark:bg-zinc-950 dark:ring-zinc-800",
        className
      )}
    >
      <ul className="divide-y divide-zinc-100 px-4 dark:divide-zinc-900">
        {items.map((item) => {
          const Icon = item.icon;
          return (
            <li className="flex items-center gap-3 py-3" key={item.id}>
              <span
                className={cn(
                  "flex size-11 shrink-0 items-center justify-center rounded-xl",
                  item.tint
                )}
              >
                <Icon aria-hidden className="size-5" strokeWidth={1.75} />
              </span>
              <span className="min-w-0 flex-1">
                <span className="block truncate font-medium text-sm text-zinc-900 dark:text-zinc-100">
                  {item.name}
                </span>
                <span className="block truncate text-xs text-zinc-500 dark:text-zinc-400">
                  <span className="text-zinc-700 tabular-nums dark:text-zinc-300">
                    {money(item.price, currency)}
                  </span>
                  {` · ${item.detail}`}
                </span>
              </span>
              <AddToCartButton
                max={item.max}
                name={item.name}
                onQuantityChange={(next) =>
                  setQuantities((current) => ({ ...current, [item.id]: next }))
                }
                quantity={quantities[item.id] ?? 0}
              />
            </li>
          );
        })}
      </ul>

      <div className="flex items-center justify-between gap-3 border-zinc-100 border-t px-4 py-3.5 dark:border-zinc-900">
        <div className="min-w-0">
          <p className="text-xs text-zinc-500 dark:text-zinc-400">{summary}</p>
          <p className="font-semibold text-base text-zinc-900 dark:text-zinc-100">
            <RollingText
              direction={direction}
              reduceMotion={reduceMotion}
              text={money(total, currency)}
            />
          </p>
        </div>
        <button
          className={cn(
            "h-9 rounded-full px-4 font-medium text-sm transition-colors duration-150",
            count === 0
              ? "cursor-not-allowed bg-zinc-100 text-zinc-400 dark:bg-zinc-900 dark:text-zinc-600"
              : "bg-zinc-900 text-white hover:bg-zinc-800 active:bg-zinc-700 dark:bg-zinc-100 dark:text-zinc-900 dark:active:bg-zinc-300 dark:hover:bg-zinc-200"
          )}
          disabled={count === 0}
          onClick={() => onCheckout?.(quantities)}
          type="button"
        >
          Checkout
        </button>
      </div>
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Caustics Background
 * @version: 1.0.0
 * @date: 2026-10-22
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import { type ReactNode, useEffect, useRef } from "react";
import { cn } from "@/lib/utils";

export interface CausticsBackgroundProps {
  /** The headline. It floats on the water and casts a shadow on the floor. */
  title?: string;
  /**
   * Content under the headline. Give an element `data-shadow="box"` and it
   * casts a shadow too.
   */
  children?: ReactNode;
  /** Set false for water you can't touch. */
  interactive?: boolean;
  className?: string;
}

// Ripples alive at once. A new one replaces the oldest.
const RIPPLES = 12;
// How far apart the caustic cells are, in px.
const CELL = 150;
// Where the floor shadow lands, from the thing that casts it, in px.
const SHADOW_X = 16;
const SHADOW_Y = 30;
const SHADOW_BLUR = 7;
// Moving the pointer faster than this (px/ms) leaves a wake.
const WAKE_SPEED = 0.25;
const WAKE_EVERY = 70;

const VERTEX = `#version 300 es
in vec2 aPos;
out vec2 vUv;
void main() {
  vUv = aPos * 0.5 + 0.5;
  gl_Position = vec4(aPos, 0.0, 1.0);
}`;

const FRAGMENT = `#version 300 es
precision highp float;
in vec2 vUv;
out vec4 o;
uniform vec2 uRes;
uniform float uTime;
uniform vec4 uRipples[${RIPPLES}];
uniform sampler2D uMask;
uniform vec3 uWater;
uniform vec3 uLight;
uniform vec2 uShadow;

const float TAU = 6.28318530718;

vec2 hash(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(p) * 43758.5453);
}

// The bright web of light on a pool floor: the edges between drifting
// cells, where the waves focus the sun.
float caustic(vec2 p, float t) {
  vec2 q = p;
  p += 0.34 * vec2(sin(p.y * 1.3 + t * 0.9), cos(p.x * 1.1 - t * 0.7));
  p += 0.12 * vec2(sin(p.y * 3.1 - t), cos(p.x * 2.7 + t * 1.2));
  vec2 n = floor(p);
  vec2 f = fract(p);
  float f1 = 8.0;
  float f2 = 8.0;
  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      vec2 g = vec2(float(i), float(j));
      vec2 o = 0.5 + 0.42 * sin(t + TAU * hash(n + g));
      vec2 r = g + o - f;
      float d = dot(r, r);
      if (d < f1) {
        f2 = f1;
        f1 = d;
      } else if (d < f2) {
        f2 = d;
      }
    }
  }
  float edge = sqrt(f2) - sqrt(f1);
  // A sharp core and a soft halo, brighter in some patches than others.
  float line = pow(1.0 - smoothstep(0.0, 0.14, edge), 2.0);
  float halo = 1.0 - smoothstep(0.0, 0.32, edge);
  float glint = 0.6 + 0.4 * sin(q.x * 0.55 + t * 0.6) * cos(q.y * 0.45 - t * 0.5);
  return (line * 0.85 + halo * 0.18) * glint;
}

void main() {
  vec2 px = vec2(vUv.x, 1.0 - vUv.y) * uRes;
  vec2 bend = vec2(0.0);
  float focus = 0.0;
  for (int k = 0; k < ${RIPPLES}; k++) {
    vec4 r = uRipples[k];
    float age = uTime - r.z;
    if (r.w <= 0.0 || age < 0.0 || age > 4.0) {
      continue;
    }
    vec2 d = px - r.xy;
    float dist = length(d);
    float x = dist - age * 240.0;
    float env = r.w * exp(-age * 0.8) * exp(-x * x / 2600.0) / (1.0 + dist * 0.002);
    bend += (d / max(dist, 1.0)) * sin(x * 0.085) * env * 26.0;
    focus += cos(x * 0.085) * env;
  }
  vec2 uv = (px + bend) / ${CELL}.0;
  float t = uTime * 0.5;
  float c = caustic(uv, t);
  // A fainter, finer web drifting under the first gives the floor depth.
  c = max(c, caustic(uv * 1.9 + 7.3, t * 0.8 + 3.0) * 0.22);
  // A ring's crest focuses light like a lens and its trough spreads it, so
  // each ring shows as a bright band with a dim one beside it.
  c = clamp(c * (1.0 + focus * 1.2) + focus * 0.4, 0.0, 1.0);

  // Whatever floats on the surface blocks the light under it. The water
  // bends the shadow the same way it bends the light.
  vec2 sway = vec2(sin(uTime * 0.7), cos(uTime * 0.55)) * 2.5;
  vec2 s = (px - uShadow - bend * 1.4 - sway) / uRes;
  float shade = texture(uMask, s).r;

  vec3 floor = uWater * (1.0 - shade * 0.08);
  vec3 col = mix(floor, uLight, c * (1.0 - shade * 0.9));
  o = vec4(col, 1.0);
}`;

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) {
    return null;
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

/** Parses any CSS color, oklch included, by painting it into one pixel. */
function toRgb(color: string, probe: CanvasRenderingContext2D) {
  probe.clearRect(0, 0, 1, 1);
  probe.fillStyle = color;
  probe.fillRect(0, 0, 1, 1);
  const [r, g, b] = probe.getImageData(0, 0, 1, 1).data;
  return [r / 255, g / 255, b / 255];
}

interface Water {
  resize: (w: number, h: number, cssW: number, cssH: number) => void;
  setMask: (source: HTMLCanvasElement) => void;
  setColors: (water: number[], light: number[]) => void;
  setRipples: (data: Float32Array) => void;
  draw: (time: number) => void;
  destroy: () => void;
}

function createWater(gl: WebGL2RenderingContext): Water | null {
  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT);
  const program = gl.createProgram();
  if (!(vertex && fragment && program)) {
    return null;
  }
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.bindAttribLocation(program, 0, "aPos");
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    return null;
  }
  const at = (name: string) => gl.getUniformLocation(program, name);
  const u = {
    res: at("uRes"),
    time: at("uTime"),
    ripples: at("uRipples"),
    mask: at("uMask"),
    water: at("uWater"),
    light: at("uLight"),
    shadow: at("uShadow"),
  };

  const quad = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, quad);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]),
    gl.STATIC_DRAW
  );
  gl.enableVertexAttribArray(0);
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

  const mask = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, mask);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.texImage2D(
    gl.TEXTURE_2D,
    0,
    gl.R8,
    1,
    1,
    0,
    gl.RED,
    gl.UNSIGNED_BYTE,
    new Uint8Array([0])
  );

  // biome-ignore lint/correctness/useHookAtTopLevel: WebGL's useProgram, not a React hook.
  gl.useProgram(program);
  gl.uniform1i(u.mask, 0);
  gl.uniform2f(u.shadow, SHADOW_X, SHADOW_Y);

  return {
    resize: (w, h, cssW, cssH) => {
      gl.viewport(0, 0, w, h);
      gl.uniform2f(u.res, cssW, cssH);
    },
    setMask: (source) => {
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, mask);
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        source
      );
    },
    setColors: (water, light) => {
      gl.uniform3f(u.water, water[0], water[1], water[2]);
      gl.uniform3f(u.light, light[0], light[1], light[2]);
    },
    setRipples: (data) => {
      gl.uniform4fv(u.ripples, data);
    },
    draw: (time) => {
      gl.uniform1f(u.time, time);
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    },
    destroy: () => {
      gl.deleteTexture(mask);
      gl.deleteBuffer(quad);
      gl.deleteProgram(program);
      gl.deleteShader(vertex);
      gl.deleteShader(fragment);
    },
  };
}

/**
 * Paints everything that floats (`data-shadow` elements) into a soft mask,
 * in the root's coordinates, for the floor shadow.
 */
function drawMask(canvas: HTMLCanvasElement, root: HTMLElement) {
  const rect = root.getBoundingClientRect();
  canvas.width = Math.max(1, Math.round(rect.width));
  canvas.height = Math.max(1, Math.round(rect.height));
  const ctx = canvas.getContext("2d");
  if (!ctx) {
    return;
  }
  ctx.fillStyle = "black";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.filter = `blur(${SHADOW_BLUR}px)`;
  ctx.fillStyle = "white";
  for (const el of root.querySelectorAll<HTMLElement>("[data-shadow]")) {
    const box = el.getBoundingClientRect();
    const x = box.left - rect.left;
    const y = box.top - rect.top;
    if (el.dataset.shadow === "text") {
      const style = getComputedStyle(el);
      ctx.font = `${style.fontWeight} ${style.fontSize} ${style.fontFamily}`;
      ctx.letterSpacing = style.letterSpacing;
      ctx.textBaseline = "alphabetic";
      const word = el.textContent ?? "";
      const m = ctx.measureText(word);
      const baseline =
        y +
        (box.height + m.fontBoundingBoxAscent - m.fontBoundingBoxDescent) / 2;
      ctx.fillText(word, x, baseline);
    } else {
      const radius = Number.parseFloat(getComputedStyle(el).borderRadius) || 0;
      ctx.beginPath();
      ctx.roundRect(x, y, box.width, box.height, radius);
      ctx.fill();
    }
  }
}

export default function CausticsBackground({
  title = "Swim before work.",
  children,
  interactive = true,
  className,
}: CausticsBackgroundProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const waterRef = useRef<HTMLSpanElement>(null);
  const lightRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    const gl = canvas?.getContext("webgl2", {
      alpha: false,
      antialias: false,
      depth: false,
    });
    const probe = document
      .createElement("canvas")
      .getContext("2d", { willReadFrequently: true });
    const water = gl ? createWater(gl) : null;
    if (!(root && canvas && probe && water)) {
      return;
    }
    const reduceMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    const maskCanvas = document.createElement("canvas");
    const ripples = new Float32Array(RIPPLES * 4);
    const born = performance.now();
    const clock = () => (performance.now() - born) / 1000;
    let next = 0;
    let raf = 0;
    let visible = true;
    let colorKey = "";
    let width = 0;
    let height = 0;
    const hand = { x: 0, y: 0, t: 0, wake: 0 };

    const drop = (x: number, y: number, strength: number) => {
      ripples.set([x, y, clock(), strength], next * 4);
      next = (next + 1) % RIPPLES;
      water.setRipples(ripples);
    };

    const readColors = () => {
      const w = getComputedStyle(waterRef.current as Element).color;
      const l = getComputedStyle(lightRef.current as Element).color;
      const key = `${w}|${l}`;
      if (key === colorKey) {
        return false;
      }
      colorKey = key;
      water.setColors(toRgb(w, probe), toRgb(l, probe));
      return true;
    };

    const build = () => {
      const rect = root.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      if (width < 2 || height < 2) {
        return;
      }
      const dpr = Math.min(window.devicePixelRatio || 1, 1.5);
      canvas.width = Math.round(width * dpr);
      canvas.height = Math.round(height * dpr);
      water.resize(canvas.width, canvas.height, width, height);
      drawMask(maskCanvas, root);
      water.setMask(maskCanvas);
      water.draw(reduceMotion ? 8 : clock());
    };

    const frame = () => {
      raf = 0;
      if (!visible) {
        return;
      }
      water.draw(clock());
      raf = requestAnimationFrame(frame);
    };
    const start = () => {
      if (!raf && visible && !reduceMotion) {
        raf = requestAnimationFrame(frame);
      }
    };

    readColors();
    water.setRipples(ripples);
    build();
    canvas.style.opacity = "1";
    start();

    // One drop when the page opens, so the water shows it can be touched.
    const firstDrop = window.setTimeout(() => {
      if (!reduceMotion && interactive) {
        drop(width * 0.68, height * 0.3, 1.1);
      }
    }, 500);

    // Web fonts can land after the first mask; draw it again when they do.
    document.fonts?.ready.then(() => {
      if (rootRef.current) {
        build();
      }
    });

    const resizeObserver = new ResizeObserver(() => build());
    resizeObserver.observe(root);
    // A tab coming back must not wake a background that's scrolled away.
    let onScreen = true;
    const intersection = new IntersectionObserver(([entry]) => {
      onScreen = entry.isIntersecting;
      visible = onScreen && document.visibilityState === "visible";
      start();
    });
    intersection.observe(root);
    const onVisibility = () => {
      visible = onScreen && document.visibilityState === "visible";
      start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    // Follow light and dark mode without asking the app for a theme. Only
    // checked while the background is on screen.
    const colorTimer = window.setInterval(() => {
      if (!visible) {
        return;
      }
      if (readColors() && (reduceMotion || !raf)) {
        water.draw(reduceMotion ? 8 : clock());
      }
    }, 500);

    const local = (event: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      return { x: event.clientX - rect.left, y: event.clientY - rect.top };
    };
    const onMove = (event: PointerEvent) => {
      const p = local(event);
      const now = event.timeStamp;
      const dt = Math.max(1, now - hand.t);
      const speed = Math.hypot(p.x - hand.x, p.y - hand.y) / dt;
      // A quick pass over the water leaves a trail of small rings.
      if (hand.t && speed > WAKE_SPEED && now - hand.wake > WAKE_EVERY) {
        drop(p.x, p.y, Math.min(0.45, speed * 0.25));
        hand.wake = now;
      }
      hand.x = p.x;
      hand.y = p.y;
      hand.t = now;
    };
    const onLeave = () => {
      hand.t = 0;
    };
    const onDown = (event: PointerEvent) => {
      if ((event.target as HTMLElement).closest("a, button, input, textarea")) {
        return;
      }
      const p = local(event);
      drop(p.x, p.y, 1.4);
    };
    if (interactive && !reduceMotion) {
      root.addEventListener("pointermove", onMove);
      root.addEventListener("pointerleave", onLeave);
      root.addEventListener("pointerdown", onDown);
    }

    return () => {
      cancelAnimationFrame(raf);
      window.clearTimeout(firstDrop);
      window.clearInterval(colorTimer);
      resizeObserver.disconnect();
      intersection.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerleave", onLeave);
      root.removeEventListener("pointerdown", onDown);
      water.destroy();
    };
  }, [interactive]);

  const words = title.split(" ");

  return (
    <div
      className={cn(
        "relative min-h-[560px] w-full touch-pan-y overflow-hidden bg-[#cde5e4] text-zinc-900 dark:bg-[#06201f] dark:text-zinc-50",
        className
      )}
      ref={rootRef}
    >
      {/* Theme colors for the shader: the pool floor and its light. */}
      <span
        className="hidden text-[#cde5e4] dark:text-[#06201f]"
        ref={waterRef}
      />
      <span className="hidden text-white dark:text-[#3ea89d]" ref={lightRef} />
      <div aria-hidden="true" className="pointer-events-none absolute inset-0">
        <canvas
          className="h-full w-full opacity-0 transition-opacity duration-700 ease-out"
          ref={canvasRef}
        />
      </div>
      <div className="relative flex min-h-[560px] flex-col items-center justify-center gap-6 px-6 py-16 text-center">
        <h2 className="max-w-3xl text-balance font-semibold text-5xl tracking-[-0.045em] sm:text-7xl">
          {words.map((word, i) => (
            <span key={`${word}-${i.toString()}`}>
              <span data-shadow="text">{word}</span>
              {i < words.length - 1 ? " " : null}
            </span>
          ))}
        </h2>
        {children === undefined ? <DefaultContent /> : children}
      </div>
    </div>
  );
}

function DefaultContent() {
  return (
    <>
      <p className="max-w-md text-balance text-base text-zinc-600 leading-relaxed dark:text-zinc-300">
        Book a lane at any of 40 city pools. Lanes open at 6am, and the first
        swim is on us.
      </p>
      <div className="flex items-center gap-2">
        <a
          className="inline-flex h-10 items-center rounded-full bg-zinc-900 px-5 font-medium text-sm text-white transition-colors duration-150 hover:bg-zinc-700 dark:bg-zinc-50 dark:text-zinc-900 dark:hover:bg-zinc-200"
          data-shadow="box"
          href="#book"
        >
          Book a lane
        </a>
        <a
          className="inline-flex h-10 items-center rounded-full px-4 font-medium text-sm text-zinc-700 transition-colors duration-150 hover:bg-zinc-900/5 hover:text-zinc-900 dark:text-zinc-300 dark:hover:bg-white/10 dark:hover:text-zinc-50"
          href="#pools"
        >
          Find a pool
        </a>
      </div>
    </>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Clip Trimmer
 * @version: 1.0.0
 * @date: 2026-10-16
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import { Pause, Play } from "lucide-react";
import Image from "next/image";
import {
  type KeyboardEvent,
  type PointerEvent,
  useEffect,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

const FRAMES = 10;
// Handles pull to whole seconds within this many px.
const SNAP_PX = 5;

type Part = "start" | "end" | "range" | "seek";

export interface ClipRange {
  start: number;
  end: number;
}

export interface ClipTrimmerProps {
  /**
   * A wide image the demo pans across to stand in for footage. Swap the
   * preview and filmstrip for your own video and frame grabs.
   */
  src?: string;
  alt?: string;
  /** Clip length in seconds. */
  duration?: number;
  defaultRange?: ClipRange;
  /** The shortest clip you can trim to, in seconds. */
  minLength?: number;
  onRangeChange?: (range: ClipRange) => void;
  className?: string;
}

const PANORAMA =
  "https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=2400&h=800&fit=crop&auto=format&q=80";

const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v));

const formatClock = (s: number) => {
  const tenths = Math.round(s * 10);
  const whole = Math.floor(tenths / 10);
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}.${tenths % 10}`;
};

export default function ClipTrimmer({
  src = PANORAMA,
  alt = "A valley road at dusk",
  duration = 12,
  defaultRange = { start: 2.4, end: 9 },
  minLength = 1,
  onRangeChange,
  className,
}: ClipTrimmerProps) {
  const [range, setRange] = useState<ClipRange>(defaultRange);
  const [time, setTime] = useState(defaultRange.start);
  const [playing, setPlaying] = useState(false);
  const [active, setActive] = useState<Part | null>(null);
  const [snapped, setSnapped] = useState<number | null>(null);
  const stripRef = useRef<HTMLDivElement>(null);
  const rangeRef = useRef(range);
  const timeRef = useRef(time);
  const drag = useRef<{
    part: Part;
    x: number;
    from: ClipRange;
    moved: boolean;
  } | null>(null);

  rangeRef.current = range;

  useEffect(() => {
    onRangeChange?.(range);
  }, [range, onRangeChange]);

  // Playback loops inside the kept range.
  useEffect(() => {
    if (!playing) {
      return;
    }
    let frame = 0;
    let last = performance.now();
    const tick = (now: number) => {
      const { start, end } = rangeRef.current;
      let next = timeRef.current + (now - last) / 1000;
      last = now;
      if (next >= end || next < start) {
        next = start;
      }
      timeRef.current = next;
      setTime(next);
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [playing]);

  const seek = (t: number) => {
    const next = clamp(t, rangeRef.current.start, rangeRef.current.end);
    timeRef.current = next;
    setTime(next);
  };

  const pxPerSecond = () =>
    (stripRef.current?.getBoundingClientRect().width ?? 1) / duration;

  const secondsAt = (clientX: number) => {
    const rect = stripRef.current?.getBoundingClientRect();
    if (!rect) {
      return 0;
    }
    return clamp(((clientX - rect.left) / rect.width) * duration, 0, duration);
  };

  // A handle near a whole second pulls onto it, like a magnet.
  const snap = (t: number) => {
    const whole = Math.round(t);
    if (Math.abs(whole - t) * pxPerSecond() < SNAP_PX) {
      setSnapped(whole);
      return whole;
    }
    setSnapped(null);
    return t;
  };

  const moveHandle = (part: "start" | "end", t: number) => {
    const { start, end } = rangeRef.current;
    const next =
      part === "start"
        ? { start: clamp(snap(t), 0, end - minLength), end }
        : { start, end: clamp(snap(t), start + minLength, duration) };
    rangeRef.current = next;
    setRange(next);
    // The preview shows the frame you're cutting at.
    const at = part === "start" ? next.start : next.end;
    timeRef.current = at;
    setTime(at);
  };

  const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (!event.isPrimary || event.button !== 0 || drag.current) {
      return;
    }
    const target = event.target as HTMLElement;
    const part = (target.closest("[data-part]")?.getAttribute("data-part") ??
      "seek") as Part;
    event.currentTarget.setPointerCapture(event.pointerId);
    drag.current = { part, x: event.clientX, from: range, moved: false };
    setActive(part);
    if (part === "start" || part === "end") {
      setPlaying(false);
    } else if (part === "seek") {
      seek(secondsAt(event.clientX));
    }
  };

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d) {
      return;
    }
    const dx = event.clientX - d.x;
    if (Math.abs(dx) > 3) {
      d.moved = true;
    }
    if (d.part === "start" || d.part === "end") {
      moveHandle(d.part, d.from[d.part] + dx / pxPerSecond());
    } else if (d.part === "range" && d.moved) {
      const length = d.from.end - d.from.start;
      const start = clamp(
        d.from.start + dx / pxPerSecond(),
        0,
        duration - length
      );
      const next = { start, end: start + length };
      rangeRef.current = next;
      setRange(next);
      seek(timeRef.current);
    } else if (d.part === "seek") {
      seek(secondsAt(event.clientX));
    }
  };

  const endDrag = (event: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d) {
      return;
    }
    // A tap inside the kept range moves the playhead.
    if (d.part === "range" && !d.moved) {
      seek(secondsAt(event.clientX));
    }
    if (d.part === "start" || d.part === "end") {
      seek(rangeRef.current.start);
    }
    drag.current = null;
    setActive(null);
    setSnapped(null);
  };

  const handleKeyDown =
    (part: "start" | "end") => (event: KeyboardEvent<HTMLDivElement>) => {
      const step = event.shiftKey ? 1 : 0.1;
      const moves: Record<string, number> = {
        ArrowLeft: -step,
        ArrowDown: -step,
        ArrowRight: step,
        ArrowUp: step,
        Home: -duration,
        End: duration,
      };
      const move = moves[event.key];
      if (move === undefined) {
        return;
      }
      event.preventDefault();
      const { start, end } = rangeRef.current;
      const from = part === "start" ? start : end;
      const t = Math.round((from + move) * 10) / 10;
      const next =
        part === "start"
          ? { start: clamp(t, 0, end - minLength), end }
          : { start, end: clamp(t, start + minLength, duration) };
      rangeRef.current = next;
      setRange(next);
      seek(part === "start" ? next.start : next.end);
    };

  const togglePlay = () => {
    if (!playing && timeRef.current >= range.end - 0.05) {
      seek(range.start);
    }
    setPlaying((p) => !p);
  };

  const pct = (t: number) => (t / duration) * 100;
  const kept = range.end - range.start;
  const trimming = active === "start" || active === "end";
  const ticks = Array.from({ length: Math.floor(duration) + 1 }, (_, i) => i);
  // A longer, labelled tick every five seconds, like a tape ruler.
  const labelEvery = 5;

  return (
    <div
      className={cn(
        "w-full max-w-lg select-none rounded-3xl border border-zinc-200 bg-white p-4 text-zinc-900 dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-100",
        className
      )}
    >
      <div className="relative aspect-video overflow-hidden rounded-2xl bg-zinc-100 dark:bg-zinc-900">
        <Image
          alt={alt}
          className="pointer-events-none object-cover"
          draggable={false}
          fill
          sizes="(max-width: 512px) 100vw, 512px"
          src={src}
          style={{ objectPosition: `${pct(time)}% 50%` }}
          unoptimized
        />
        <span className="absolute bottom-3 left-3 rounded-full bg-black/55 px-2.5 py-1 font-medium text-[11px] text-white tabular-nums">
          {formatClock(time)}
        </span>
        <button
          aria-label={playing ? "Pause" : "Play"}
          className="absolute right-3 bottom-3 flex size-8 items-center justify-center rounded-full bg-black/55 text-white outline-none transition-colors duration-150 ease-out hover:bg-black/70 focus-visible:ring-2 focus-visible:ring-white"
          onClick={togglePlay}
          type="button"
        >
          {playing ? (
            <Pause aria-hidden className="size-3.5" fill="currentColor" />
          ) : (
            <Play
              aria-hidden
              className="size-3.5 translate-x-px"
              fill="currentColor"
            />
          )}
        </button>
      </div>

      <div className="mt-5 px-4">
        <div
          className="relative h-14 cursor-pointer touch-none"
          onLostPointerCapture={endDrag}
          onPointerCancel={endDrag}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={endDrag}
          ref={stripRef}
        >
          {/* Filmstrip: one wide shot, cut into frames. */}
          <div className="absolute inset-0 flex overflow-hidden rounded-lg bg-zinc-200 dark:bg-zinc-800">
            {Array.from({ length: FRAMES }, (_, i) => (
              <div
                className="relative h-full flex-1 border-black/10 border-r last:border-r-0"
                // biome-ignore lint/suspicious/noArrayIndexKey: fixed frame slots
                key={i}
              >
                <Image
                  alt=""
                  className="pointer-events-none object-cover"
                  draggable={false}
                  fill
                  sizes="64px"
                  src={src}
                  style={{
                    objectPosition: `${(i / (FRAMES - 1)) * 100}% 50%`,
                  }}
                  unoptimized
                />
              </div>
            ))}
          </div>

          {/* What gets cut is dimmed. Full-width layers moved by transform. */}
          <div className="pointer-events-none absolute inset-0 overflow-hidden rounded-lg">
            <div
              className="absolute inset-0 bg-white/75 dark:bg-zinc-950/75"
              style={{ transform: `translateX(${pct(range.start) - 100}%)` }}
            />
            <div
              className="absolute inset-0 bg-white/75 dark:bg-zinc-950/75"
              style={{ transform: `translateX(${pct(range.end)}%)` }}
            />
          </div>

          {/* Playhead */}
          <div
            className={cn(
              "pointer-events-none absolute -inset-y-1 left-0 w-full transition-opacity duration-150 ease-out",
              trimming ? "opacity-0" : "opacity-100"
            )}
            style={{ transform: `translateX(${pct(time)}%)` }}
          >
            <div className="relative h-full w-px -translate-x-1/2 bg-zinc-900 dark:bg-white">
              <span className="absolute -top-0.5 left-1/2 size-[7px] -translate-x-1/2 rounded-full bg-zinc-900 dark:bg-white" />
            </div>
          </div>

          {/* Kept range: the frame, its two handles and the drag area. */}
          <div
            className={cn(
              "absolute inset-y-0 border-orange-600 border-y-[3px]",
              active === "range" ? "cursor-grabbing" : "cursor-grab"
            )}
            data-part="range"
            style={{
              left: `${pct(range.start)}%`,
              width: `${pct(kept)}%`,
            }}
          >
            {(["start", "end"] as const).map((part) => (
              <div
                aria-label={part === "start" ? "Trim start" : "Trim end"}
                aria-valuemax={duration}
                aria-valuemin={0}
                aria-valuenow={Math.round(range[part] * 10) / 10}
                aria-valuetext={`${range[part].toFixed(1)} seconds`}
                className={cn(
                  "group absolute -inset-y-[3px] flex w-4 cursor-ew-resize items-center justify-center bg-orange-600 outline-none focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 dark:focus-visible:ring-offset-zinc-950",
                  part === "start"
                    ? "-left-4 rounded-l-lg"
                    : "-right-4 rounded-r-lg"
                )}
                data-part={part}
                key={part}
                onKeyDown={handleKeyDown(part)}
                role="slider"
                tabIndex={0}
              >
                <span
                  className={cn(
                    "h-5 w-[3px] rounded-full bg-white/60 transition-colors duration-150 ease-out",
                    active === part && "bg-white"
                  )}
                />
                {/* The exact cut point, while trimming. */}
                <span
                  className={cn(
                    "pointer-events-none absolute -top-8 rounded-md bg-zinc-900 px-1.5 py-0.5 text-[11px] text-white tabular-nums transition-opacity duration-150 ease-out dark:bg-zinc-100 dark:text-zinc-900",
                    active === part ? "opacity-100" : "opacity-0"
                  )}
                >
                  {formatClock(range[part])}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Ruler: whole seconds, the one a handle snapped to lights up. */}
        <div aria-hidden className="relative mt-2 h-5">
          {ticks.map((s) => (
            <span
              className="absolute top-0 flex -translate-x-1/2 flex-col items-center"
              key={s}
              style={{ left: `${pct(s)}%` }}
            >
              <span
                className={cn(
                  "w-px transition-colors duration-150 ease-out",
                  s % labelEvery === 0 ? "h-2" : "h-1",
                  snapped === s
                    ? "bg-orange-600"
                    : "bg-zinc-300 dark:bg-zinc-700"
                )}
              />
              {s % labelEvery === 0 && (
                <span
                  className={cn(
                    "mt-0.5 text-[10px] tabular-nums transition-colors duration-150 ease-out",
                    snapped === s
                      ? "text-orange-700 dark:text-orange-400"
                      : "text-zinc-400 dark:text-zinc-500"
                  )}
                >
                  {s}s
                </span>
              )}
            </span>
          ))}
        </div>
      </div>

      <div className="mt-3 flex items-center justify-between gap-3 px-1 text-sm">
        <p className="text-zinc-500 tabular-nums dark:text-zinc-400">
          <span className="font-medium text-zinc-900 dark:text-zinc-100">
            {kept.toFixed(1)}s
          </span>{" "}
          of {duration.toFixed(1)}s
        </p>
        <button
          className="rounded-full px-3 py-1 text-xs text-zinc-500 outline-none transition-colors duration-150 ease-out hover:bg-zinc-100 hover:text-zinc-900 focus-visible:ring-2 focus-visible:ring-zinc-400 disabled:pointer-events-none disabled:opacity-40 dark:text-zinc-400 dark:hover:bg-zinc-900 dark:hover:text-zinc-100"
          disabled={range.start === 0 && range.end === duration}
          onClick={() => {
            const full = { start: 0, end: duration };
            rangeRef.current = full;
            setRange(full);
            seek(timeRef.current);
          }}
          type="button"
        >
          Reset
        </button>
      </div>
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Command Button
 * @version: 2.0.0
 * @date: 2026-10-16
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 *
 * A button with its keyboard shortcut drawn as physical keycaps. The shortcut
 * works for real: pressing the keys anywhere on the page sinks each cap as
 * its key goes down and clicks the button when the combination matches.
 */

import {
  type ComponentProps,
  type ReactNode,
  useEffect,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

type Modifier = "mod" | "ctrl" | "alt" | "shift";

interface ParsedShortcut {
  modifiers: Modifier[];
  key: string;
}

interface CommandButtonProps extends ComponentProps<"button"> {
  children?: ReactNode;
  /**
   * The shortcut, as `+`-joined parts: `mod` (⌘ on Mac, Ctrl elsewhere),
   * `ctrl`, `alt`, `shift` and one key, e.g. `"mod+k"`, `"shift+n"`, `"c"`.
   */
  shortcut?: string;
  /**
   * Listen for the shortcut on the whole page. Shortcuts without `mod`,
   * `ctrl` or `alt` are ignored while typing in a field.
   */
  global?: boolean;
}

const APPLE_PLATFORM = /mac|iphone|ipad|ipod/i;
const MODIFIERS = new Set<Modifier>(["mod", "ctrl", "alt", "shift"]);

const parseShortcut = (shortcut: string): ParsedShortcut => {
  const parts = shortcut
    .toLowerCase()
    .split("+")
    .map((part) => part.trim())
    .filter(Boolean);
  const modifiers = parts.filter((part): part is Modifier =>
    MODIFIERS.has(part as Modifier)
  );
  const key = parts.find((part) => !MODIFIERS.has(part as Modifier)) ?? "k";
  return { modifiers, key };
};

const MAC_LABELS: Record<Modifier, string> = {
  mod: "⌘",
  ctrl: "⌃",
  alt: "⌥",
  shift: "⇧",
};
const PC_LABELS: Record<Modifier, string> = {
  mod: "Ctrl",
  ctrl: "Ctrl",
  alt: "Alt",
  shift: "Shift",
};
// aria-keyshortcuts takes KeyboardEvent.key names: Meta, not Command.
const ARIA_KEYS: Record<Modifier, [mac: string, pc: string]> = {
  mod: ["Meta", "Control"],
  ctrl: ["Control", "Control"],
  alt: ["Alt", "Alt"],
  shift: ["Shift", "Shift"],
};

const ariaKey = (key: string) => {
  if (key === "enter") {
    return "Enter";
  }
  if (key === "space") {
    return "Space";
  }
  return key.length === 1 ? key.toUpperCase() : key;
};

const keyLabel = (key: string) => {
  if (key === "enter") {
    return "↵";
  }
  if (key === "space") {
    return "Space";
  }
  return key.length === 1 ? key.toUpperCase() : key;
};

// Matches by physical key too, since Option on a Mac changes `event.key`
// (Option+K types "˚").
const isKey = (event: KeyboardEvent, key: string) => {
  const pressed = event.key.toLowerCase();
  if (key === "space") {
    return event.code === "Space";
  }
  return (
    pressed === key ||
    event.code === `Key${key.toUpperCase()}` ||
    event.code === `Digit${key}`
  );
};

const isModifierDown = (
  modifier: Modifier,
  event: KeyboardEvent,
  isMac: boolean
) => {
  switch (modifier) {
    case "mod":
      return isMac ? event.metaKey : event.ctrlKey;
    case "ctrl":
      return event.ctrlKey;
    case "alt":
      return event.altKey;
    case "shift":
      return event.shiftKey;
    default:
      return false;
  }
};

const matches = (
  event: KeyboardEvent,
  { modifiers, key }: ParsedShortcut,
  isMac: boolean
) => {
  if (!isKey(event, key)) {
    return false;
  }
  const wanted = {
    meta: modifiers.includes("mod") && isMac,
    ctrl: modifiers.includes("ctrl") || (modifiers.includes("mod") && !isMac),
    alt: modifiers.includes("alt"),
    shift: modifiers.includes("shift"),
  };
  return (
    event.metaKey === wanted.meta &&
    event.ctrlKey === wanted.ctrl &&
    event.altKey === wanted.alt &&
    event.shiftKey === wanted.shift
  );
};

const isTyping = (target: EventTarget | null) =>
  target instanceof HTMLElement &&
  (target.isContentEditable ||
    target.tagName === "INPUT" ||
    target.tagName === "TEXTAREA" ||
    target.tagName === "SELECT");

function Keycap({ label, pressed }: { label: string; pressed: boolean }) {
  return (
    <kbd
      className={cn(
        "inline-flex h-6 min-w-6 items-center justify-center rounded-md px-1.5 font-medium font-sans text-[11px] leading-none",
        "border border-zinc-200 bg-white text-zinc-600",
        "dark:border-white/10 dark:bg-zinc-800 dark:text-zinc-300",
        // The cap stands 2px above its base. Pressing sinks it onto the base:
        // a translate and a shorter shadow, never a scale.
        "shadow-[0_2px_0_0_var(--color-zinc-200)] dark:shadow-[0_2px_0_0_var(--color-zinc-950)]",
        "transition-[translate,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)]",
        "group-active/command:translate-y-0.5 group-active/command:shadow-none group-active/command:duration-75",
        pressed && "translate-y-0.5 shadow-none duration-75"
      )}
      data-pressed={pressed || undefined}
    >
      {label}
    </kbd>
  );
}

export default function CommandButton({
  className,
  children = "Search",
  shortcut = "mod+k",
  global = true,
  ...props
}: CommandButtonProps) {
  const buttonRef = useRef<HTMLButtonElement>(null);
  const [isMac, setIsMac] = useState(true);
  const [platformKnown, setPlatformKnown] = useState(false);
  const [held, setHeld] = useState<{ modifiers: Modifier[]; key: boolean }>({
    modifiers: [],
    key: false,
  });
  const parsed = parseShortcut(shortcut);
  const parsedRef = useRef(parsed);
  parsedRef.current = parsed;

  // The platform is unknown on the server, so the caps render invisible and
  // fade in once it is read, instead of swapping ⌘ for Ctrl in view.
  useEffect(() => {
    const platform =
      (navigator as Navigator & { userAgentData?: { platform?: string } })
        .userAgentData?.platform ?? navigator.platform;
    setIsMac(APPLE_PLATFORM.test(platform));
    setPlatformKnown(true);
  }, []);

  useEffect(() => {
    if (!global) {
      return;
    }
    const sync = (event: KeyboardEvent, isDown: boolean) => {
      const { modifiers, key } = parsedRef.current;
      const next = {
        modifiers: modifiers.filter((m) => isModifierDown(m, event, isMac)),
        key: isDown && isKey(event, key),
      };
      // Every key on the page lands here; only re-render when a cap moves.
      setHeld((current) =>
        current.key === next.key &&
        current.modifiers.join() === next.modifiers.join()
          ? current
          : next
      );
    };
    const handleKeyDown = (event: KeyboardEvent) => {
      const current = parsedRef.current;
      const needsModifier = current.modifiers.some((m) => m !== "shift");
      if (!needsModifier && isTyping(event.target)) {
        return;
      }
      sync(event, true);
      if (
        !event.repeat &&
        matches(event, current, isMac) &&
        !buttonRef.current?.disabled
      ) {
        event.preventDefault();
        buttonRef.current?.click();
      }
    };
    const handleKeyUp = (event: KeyboardEvent) => sync(event, false);
    const release = () =>
      setHeld((current) =>
        current.key || current.modifiers.length > 0
          ? { modifiers: [], key: false }
          : current
      );

    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);
    window.addEventListener("blur", release);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("keyup", handleKeyUp);
      window.removeEventListener("blur", release);
    };
  }, [global, isMac]);

  const labels = isMac ? MAC_LABELS : PC_LABELS;
  const keyshortcuts = [
    ...parsed.modifiers.map((m) => ARIA_KEYS[m][isMac ? 0 : 1]),
    ariaKey(parsed.key),
  ].join("+");

  return (
    <button
      aria-keyshortcuts={keyshortcuts}
      className={cn(
        "group/command inline-flex h-10 cursor-pointer items-center gap-3 rounded-xl py-1 pr-2 pl-3.5 font-medium text-sm",
        "border border-zinc-200 bg-white text-zinc-700",
        "dark:border-white/10 dark:bg-zinc-900 dark:text-zinc-200",
        "transition-[background-color,border-color] duration-150 ease-out",
        "hover:border-zinc-300 hover:bg-zinc-50 dark:hover:border-white/15 dark:hover:bg-zinc-800/70",
        "active:bg-zinc-100 dark:active:bg-zinc-800",
        "focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-zinc-400/50 focus-visible:ring-offset-2 dark:focus-visible:ring-offset-zinc-950",
        "disabled:pointer-events-none disabled:opacity-50",
        className
      )}
      ref={buttonRef}
      type="button"
      {...props}
    >
      {children}
      <span
        aria-hidden="true"
        className={cn(
          "flex items-center gap-1 pb-0.5 transition-opacity duration-150 ease-out",
          !platformKnown && "opacity-0"
        )}
      >
        {parsed.modifiers.map((modifier) => (
          <Keycap
            key={modifier}
            label={labels[modifier]}
            pressed={held.modifiers.includes(modifier)}
          />
        ))}
        <Keycap label={keyLabel(parsed.key)} pressed={held.key} />
      </span>
    </button>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Contact Sheet
 * @version: 1.0.0
