import { Check, ZoomIn } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

/** How much the loupe magnifies, and its size in px. */
const ZOOM = 3;
const LOUPE = 136;
const DRAW_EASE = [0.6, 0, 0.3, 1] as const;

export interface ContactFrame {
  /** A 3:2 image. */
  src: string;
  alt: string;
  /** Where this frame sits in the shot, 0 to 1. Frames from one scene differ a little. */
  x?: number;
  y?: number;
  /** 1 shows the whole image. */
  zoom?: number;
}

type Mark = "pick" | "reject";

export interface ContactSheetProps {
  frames?: ContactFrame[];
  /** Frames per strip. */
  perStrip?: number;
  /** Printed on the film edge before each frame number. */
  firstFrame?: number;
  title?: string;
  defaultMarks?: Record<number, Mark>;
  onExport?: (picked: number[]) => void;
  className?: string;
}

const unsplash = (id: string) =>
  `https://images.unsplash.com/photo-${id}?w=900&h=600&fit=crop&auto=format&q=75`;

const LAKE = unsplash("1501785888041-af3ef285b470");
const RIDGE = unsplash("1506905925346-21bda4d32df4");
const FOG = unsplash("1470071459604-3b5ec3a7fe05");
const PINES = unsplash("1441974231531-c6227db76b6e");
const VALLEY = unsplash("1469474968028-56623f02e42e");
const PORTRAIT = unsplash("1534528741775-53994a69daeb");

const DEMO_FRAMES: ContactFrame[] = [
  { src: LAKE, alt: "Lake under mountains, wide", zoom: 1 },
  {
    src: LAKE,
    alt: "Lake under mountains, closer",
    zoom: 1.25,
    x: 0.4,
    y: 0.6,
  },
  { src: FOG, alt: "Hills in fog", zoom: 1 },
  { src: FOG, alt: "Hills in fog, tighter", zoom: 1.3, x: 0.7, y: 0.5 },
  { src: PORTRAIT, alt: "Portrait, head and shoulders", zoom: 1, y: 0.3 },
  { src: PORTRAIT, alt: "Portrait, eyes closed in", zoom: 1.5, x: 0.5, y: 0.3 },
  { src: RIDGE, alt: "Ridge line at dusk", zoom: 1 },
  { src: RIDGE, alt: "Ridge line, the far peaks", zoom: 1.35, x: 0.85, y: 0.4 },
  { src: PINES, alt: "Pine forest, looking up", zoom: 1 },
  {
    src: PINES,
    alt: "Pine forest, light through trunks",
    zoom: 1.3,
    x: 0.3,
    y: 0.7,
  },
  { src: VALLEY, alt: "Valley road", zoom: 1 },
  { src: VALLEY, alt: "Valley road, the bend", zoom: 1.4, x: 0.6, y: 0.75 },
];

/** A small seeded random, so every frame keeps its own wobble. */
const seeded = (seed: number) => {
  let s = seed * 9301 + 49_297;
  return () => {
    s = (s * 9301 + 49_297) % 233_280;
    return s / 233_280;
  };
};

/**
 * A china-marker loop: a lopsided ellipse that runs past where it started,
 * drawn in a 100 x 100 box stretched over the frame.
 */
function loopPath(seed: number) {
  const rand = seeded(seed + 1);
  const start = -2.2 + rand() * 0.6;
  const sweep = Math.PI * 2 + 0.35 + rand() * 0.3;
  const tilt = (rand() - 0.5) * 0.12;
  const steps = 56;
  const points: string[] = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const a = start + sweep * t;
    // The hand drifts outward as it goes round, so the ends don't meet.
    const grow = 1 + t * 0.06;
    const wobble = 1 + Math.sin(a * 3 + seed) * 0.015;
    const rx = 52 * grow * wobble;
    const ry = 55 * grow * wobble;
    const x = 50 + Math.cos(a) * rx - Math.sin(a) * ry * tilt;
    const y = 50 + Math.sin(a) * ry + Math.cos(a) * rx * tilt;
    points.push(`${i === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return points.join(" ");
}

function MarkStroke({
  mark,
  index,
  reduceMotion,
}: {
  mark: Mark;
  index: number;
  reduceMotion: boolean;
}) {
  const draw = (delay: number) => ({
    initial: { pathLength: 0, opacity: 1 },
    animate: { pathLength: 1, opacity: 1 },
    transition: reduceMotion
      ? { duration: 0 }
      : {
          pathLength: { duration: 0.32, ease: DRAW_EASE, delay },
          opacity: { duration: 0 },
        },
  });
  const paths =
    mark === "pick"
      ? [loopPath(index)]
      : ["M14 16 Q 48 46 86 84", "M84 14 Q 54 50 16 86"];
  return (
    <motion.svg
      aria-hidden="true"
      className="pointer-events-none absolute -inset-1.5 z-10 h-[calc(100%+12px)] w-[calc(100%+12px)] overflow-visible text-red-600 dark:text-red-500"
      exit={{ opacity: 0, transition: { duration: reduceMotion ? 0 : 0.15 } }}
      preserveAspectRatio="none"
      viewBox="0 0 100 100"
    >
      {paths.map((d, i) => (
        <motion.path
          d={d}
          fill="none"
          key={d}
          stroke="currentColor"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth={3}
          vectorEffect="non-scaling-stroke"
          {...draw(i * 0.2)}
        />
      ))}
    </motion.svg>
  );
}

/** Image layer for a frame: the shot, framed and zoomed. */
const frameStyle = (frame: ContactFrame): CSSProperties => ({
  backgroundImage: `url("${frame.src}")`,
  backgroundSize: `${(frame.zoom ?? 1) * 100}%`,
  backgroundPosition: `${(frame.x ?? 0.5) * 100}% ${(frame.y ?? 0.5) * 100}%`,
});

interface Lens {
  frame: ContactFrame;
  /** Loupe center, in the sheet's px. */
  left: number;
  top: number;
  /** Background for the loupe. */
  size: string;
  position: string;
}

/** What the loupe shows over `frame`, for a pointer at (px, py) in it. */
function lensFor(
  frame: ContactFrame,
  rect: DOMRect,
  px: number,
  py: number
): Pick<Lens, "size" | "position"> {
  const zoom = frame.zoom ?? 1;
  const w = rect.width * zoom;
  const h = rect.height * zoom;
  const ix = px - (rect.width - w) * (frame.x ?? 0.5);
  const iy = py - (rect.height - h) * (frame.y ?? 0.5);
  return {
    size: `${w * ZOOM}px ${h * ZOOM}px`,
    position: `${LOUPE / 2 - ix * ZOOM}px ${LOUPE / 2 - iy * ZOOM}px`,
  };
}

const nextMark = (mark: Mark | undefined): Mark | undefined => {
  if (!mark) {
    return "pick";
  }
  return mark === "pick" ? "reject" : undefined;
};

function Frame({
  frame,
  index,
  number,
  mark,
  loupe,
  reduceMotion,
  onMark,
  onLens,
  onLeave,
}: {
  frame: ContactFrame;
  index: number;
  number: number;
  mark: Mark | undefined;
  loupe: boolean;
  reduceMotion: boolean;
  onMark: (index: number, mark: Mark | undefined) => void;
  onLens: (event: PointerEvent<HTMLButtonElement>, frame: ContactFrame) => void;
  onLeave: () => void;
}) {
  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    const keys: Record<string, Mark | undefined> = {
      p: mark === "pick" ? undefined : "pick",
      x: mark === "reject" ? undefined : "reject",
      Backspace: undefined,
    };
    if (event.key in keys) {
      event.preventDefault();
      onMark(index, keys[event.key]);
    }
  };
  let state = "";
  if (mark) {
    state = mark === "pick" ? ", picked" : ", struck";
  }
  return (
    <div className="relative">
      <button
        aria-label={`Frame ${number}: ${frame.alt}${state}`}
        className={cn(
          "relative block aspect-[3/2] w-full overflow-hidden bg-zinc-800 outline-none focus-visible:ring-2 focus-visible:ring-sky-400 focus-visible:ring-offset-2 focus-visible:ring-offset-zinc-950",
          loupe && "cursor-none"
        )}
        onClick={() => {
          // Lift the loupe so you see the mark go down.
          onLeave();
          onMark(index, nextMark(mark));
        }}
        onKeyDown={onKeyDown}
        onPointerLeave={onLeave}
        onPointerMove={(event) => onLens(event, frame)}
        type="button"
      >
        <span
          className={cn(
            "absolute inset-0 bg-no-repeat transition-opacity duration-200",
            mark === "reject" && "opacity-35"
          )}
          style={frameStyle(frame)}
        />
      </button>
      <AnimatePresence initial={false}>
        {mark && (
          <MarkStroke
            index={index}
            key={mark}
            mark={mark}
            reduceMotion={reduceMotion}
          />
        )}
      </AnimatePresence>
    </div>
  );
}

/** A row of sprocket holes along the film edge. */
function Sprockets() {
  return (
    <div
      aria-hidden="true"
      className="mx-1 h-[5px]"
      style={{
        backgroundImage:
          "repeating-linear-gradient(to right, var(--paper) 0 7px, transparent 7px 14px)",
      }}
    />
  );
}

/**
 * A photographer's contact sheet, for picking from a shoot. Click a frame to
 * circle it in china marker, again to strike it out, and hover to look
 * through a loupe at the detail before you decide.
 */
export default function ContactSheet({
  frames = DEMO_FRAMES,
  perStrip = 4,
  firstFrame = 12,
  title = "Roll 14 · Lisbon",
  defaultMarks = { 1: "pick", 5: "reject", 8: "pick" },
  onExport,
  className,
}: ContactSheetProps) {
  const [marks, setMarks] = useState<Record<number, Mark>>(defaultMarks);
  const [lens, setLens] = useState<Lens | null>(null);
  const [loupe, setLoupe] = useState(true);
  const [exported, setExported] = useState(false);
  const sheetRef = useRef<HTMLDivElement>(null);
  const reduceMotion = Boolean(useReducedMotion());

  const strips: number[][] = [];
  for (let i = 0; i < frames.length; i += perStrip) {
    strips.push(frames.slice(i, i + perStrip).map((_, k) => i + k));
  }
  const picked = Object.keys(marks)
    .map(Number)
    .filter((i) => marks[i] === "pick")
    .sort((a, b) => a - b);
  const struck = Object.values(marks).filter((m) => m === "reject").length;

  const mark = (index: number, next: Mark | undefined) => {
    setExported(false);
    setMarks((current) => {
      const copy = { ...current };
      if (next) {
        copy[index] = next;
      } else {
        Reflect.deleteProperty(copy, index);
      }
      return copy;
    });
  };

  const onLens = (
    event: PointerEvent<HTMLButtonElement>,
    frame: ContactFrame
  ) => {
    const sheet = sheetRef.current?.getBoundingClientRect();
    if (!(loupe && sheet) || event.pointerType !== "mouse") {
      setLens(null);
      return;
    }
    const rect = event.currentTarget.getBoundingClientRect();
    const px = event.clientX - rect.left;
    const py = event.clientY - rect.top;
    setLens({
      frame,
      left: event.clientX - sheet.left,
      top: event.clientY - sheet.top,
      ...lensFor(frame, rect, px, py),
    });
  };

  return (
    <div
      className={cn(
        "relative w-full max-w-2xl rounded-2xl border border-zinc-200 bg-white p-4 [--paper:#ffffff] sm:p-6 dark:border-zinc-800 dark:bg-zinc-900 dark:[--paper:#18181b]",
        className
      )}
      ref={sheetRef}
    >
      <div className="flex items-start justify-between gap-4">
        <div className="leading-tight">
          <p className="font-medium text-sm text-zinc-900 dark:text-zinc-100">
            {title}
          </p>
          <p className="mt-0.5 text-xs text-zinc-500 dark:text-zinc-400">
            Click to circle a frame, again to strike it.
          </p>
        </div>
        <button
          aria-pressed={loupe}
          className={cn(
            "flex h-8 shrink-0 items-center gap-1.5 rounded-full px-3 font-medium text-xs outline-none transition-colors duration-150 focus-visible:ring-2 focus-visible:ring-zinc-400",
            loupe
              ? "bg-zinc-900 text-white dark:bg-zinc-100 dark:text-zinc-900"
              : "bg-zinc-100 text-zinc-600 hover:bg-zinc-200 dark:bg-zinc-800 dark:text-zinc-300 dark:hover:bg-zinc-700"
          )}
          onClick={() => setLoupe((on) => !on)}
          type="button"
        >
          <ZoomIn aria-hidden className="size-3.5" />
          Loupe
        </button>
      </div>

      <div className="mt-4 space-y-3 sm:space-y-4">
        {strips.map((strip, s) => (
          <div className="rounded-[3px] bg-zinc-950 py-1" key={strip[0]}>
            <Sprockets />
            <div
              className="mt-1 grid gap-1 px-1"
              style={{ gridTemplateColumns: `repeat(${perStrip}, 1fr)` }}
            >
              {strip.map((i) => (
                <Frame
                  frame={frames[i]}
                  index={i}
                  key={i}
                  loupe={loupe}
                  mark={marks[i]}
                  number={firstFrame + i}
                  onLeave={() => setLens(null)}
                  onLens={onLens}
                  onMark={mark}
                  reduceMotion={reduceMotion}
                />
              ))}
            </div>
            <div
              aria-hidden="true"
              className="mt-0.5 grid px-1 font-mono text-[8px] text-orange-300/70 leading-3 sm:text-[9px]"
              style={{ gridTemplateColumns: `repeat(${perStrip}, 1fr)` }}
            >
              {strip.map((i) => (
                <span className="flex justify-between px-1" key={i}>
                  <span>{firstFrame + i}</span>
                  <span>▸{firstFrame + i}A</span>
                </span>
              ))}
            </div>
            <Sprockets />
            <span className="sr-only">Strip {s + 1}</span>
          </div>
        ))}
      </div>

      <div className="mt-4 flex items-center justify-between gap-3">
        <p className="text-xs text-zinc-500 tabular-nums dark:text-zinc-400">
          {picked.length} picked · {struck} struck
        </p>
        <div className="flex items-center gap-1.5">
          <button
            className="h-8 rounded-full px-3 font-medium text-xs text-zinc-600 outline-none transition-colors duration-150 hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-zinc-400 disabled:opacity-40 dark:text-zinc-300 dark:hover:bg-zinc-800"
            disabled={Object.keys(marks).length === 0}
            onClick={() => {
              setMarks({});
              setExported(false);
            }}
            type="button"
          >
            Clear
          </button>
          <button
            className={cn(
              "flex h-8 items-center gap-1.5 rounded-full px-3.5 font-medium text-xs tabular-nums outline-none transition-colors duration-200 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 disabled:opacity-40 dark:focus-visible:ring-offset-zinc-900",
              exported
                ? "bg-emerald-600 text-white dark:bg-emerald-500 dark:text-emerald-950"
                : "bg-zinc-900 text-white hover:bg-zinc-800 dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-white"
            )}
            disabled={picked.length === 0}
            onClick={() => {
              onExport?.(picked);
              setExported(true);
            }}
            type="button"
          >
            {exported && (
              <Check aria-hidden className="size-3.5" strokeWidth={2.5} />
            )}
            {exported ? "Sent to edit" : `Export ${picked.length}`}
          </button>
        </div>
      </div>

      <AnimatePresence>
        {lens && (
          <motion.div
            animate={{ opacity: 1 }}
            aria-hidden="true"
            className="pointer-events-none absolute z-20 rounded-full bg-zinc-900 bg-no-repeat shadow-[0_8px_24px_rgb(0_0_0/0.35),0_0_0_1px_rgb(255_255_255/0.5),0_0_0_4px_rgb(24_24_27/0.9)]"
            exit={{ opacity: 0 }}
            initial={{ opacity: 0 }}
            style={{
              width: LOUPE,
              height: LOUPE,
              left: lens.left - LOUPE / 2,
              top: lens.top - LOUPE / 2,
              backgroundImage: `url("${lens.frame.src}")`,
              backgroundSize: lens.size,
              backgroundPosition: lens.position,
            }}
            transition={{ duration: reduceMotion ? 0 : 0.12 }}
          />
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Cradle Text
 * @version: 1.0.0
 * @date: 2026-10-15
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import { useEffect, useRef } from "react";
import { cn } from "@/lib/utils";

export interface CradleTextProps {
  /** The line of letters hung from the rail. Keep it to one line. */
  text?: string;
  className?: string;
  /** Lift the first letter and let it go once, the first time it's seen. */
  intro?: boolean;
  /** How much speed a collision keeps, 0 to 1. Steel is about 0.95. */
  bounce?: number;
}

// Every letter hangs from the rail on a thread, a pendulum of the same
// length, so it swings like the balls of a Newton's cradle: letters that
// touch pass the knock along, and the one at the far end flies out.
const SUBSTEPS = 8;
const ITERATIONS = 3;
// One full swing takes this long, whatever the font size: a desk toy with
// strings about 12 cm long.
const PERIOD = 0.72;
// Air drag, per second. Most of the energy is lost in the clacks; the last
// small sway is damped harder so the cradle comes to rest in seconds.
const DRAG = 0.3;
const SETTLE_DRAG = 1.6;
const SETTLE_BELOW = 0.02;
// Furthest a letter can be pulled out, in radians.
const MAX_ANGLE = 1.15;
// A cursor sweeping through a letter knocks it, per px/s of its speed.
const SWEEP_PUSH = 0.22;
const MAX_SWEEP = 900;
// A tap sends a letter out to about this angle.
const TAP_ANGLE = 0.38;
// The intro pulls the first letter out this far, then lets go.
const INTRO_ANGLE = 0.62;
const INTRO_PULL = 520;
// Below this energy (radians, roughly) the cradle is at rest.
const REST = 0.0004;

interface Bob {
  el: HTMLElement;
  /** Ink edges and centre, in stage px, with the letter hanging still. */
  left: number;
  right: number;
  center: number;
  top: number;
  bottom: number;
  /** Where the letter's own box sits, to rotate it about its pivot. */
  boxLeft: number;
  boxTop: number;
  /** Space to the next letter at rest; they collide when it closes. */
  gap: number;
  phi: number;
  omega: number;
  held: boolean;
}

function clamp(x: number, min: number, max: number) {
  return Math.min(Math.max(x, min), max);
}

function easeOut(t: number) {
  return 1 - (1 - t) ** 4;
}

export default function CradleText({
  text = "Momentum",
  className,
  intro = true,
  bounce = 0.97,
}: CradleTextProps) {
  const stageRef = useRef<HTMLDivElement>(null);
  const lettersRef = useRef<HTMLSpanElement>(null);
  const railRef = useRef<HTMLSpanElement>(null);

  // biome-ignore lint/correctness/useExhaustiveDependencies: text renders the letter spans the effect reads
  useEffect(() => {
    const stage = stageRef.current;
    const lettersEl = lettersRef.current;
    const rail = railRef.current;
    const ink = document.createElement("canvas").getContext("2d");
    if (!(stage && lettersEl && rail && ink)) {
      return;
    }

    const reduceMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    const spans = Array.from(
      lettersEl.querySelectorAll<HTMLElement>("[data-letter]")
    );
    const restitution = clamp(bounce, 0, 1);
    const w0 = (2 * Math.PI) / PERIOD;

    let bobs: Bob[] = [];
    // Pivot height and the swing radius, measured to the letters' middle.
    let railY = 0;
    let radius = 1;
    let raf = 0;
    let last = 0;
    let visible = true;
    let pull: { bob: Bob; start: number; to: number } | null = null;
    let hand: {
      id: number;
      bob: Bob;
      startX: number;
      startTime: number;
      moved: boolean;
      prev: number;
      prevTime: number;
      spin: number;
    } | null = null;
    let sweep: { x: number; t: number; over: Bob | null } | null = null;

    const measure = () => {
      const stageBox = stage.getBoundingClientRect();
      const probe = lettersEl.lastElementChild as HTMLElement;
      const baseline = probe.getBoundingClientRect().bottom - stageBox.top;
      const style = getComputedStyle(lettersEl);
      const em = Number.parseFloat(style.fontSize);
      ink.font = style.font;
      railY = rail.getBoundingClientRect().top - stageBox.top + 0.5;
      radius = Math.max(baseline - em * 0.35 - railY, 1);
      bobs = spans.map((el) => {
        el.style.transform = "";
        const box = el.getBoundingClientRect();
        const m = ink.measureText(el.dataset.letter ?? "");
        const boxLeft = box.left - stageBox.left;
        const left = boxLeft - m.actualBoundingBoxLeft;
        const right = boxLeft + m.actualBoundingBoxRight;
        const top = baseline - m.actualBoundingBoxAscent;
        const center = (left + right) / 2;
        // The thread runs from the rail to the top of the ink.
        const thread = el.firstElementChild as HTMLElement;
        thread.style.left = `${center - boxLeft - 0.5}px`;
        thread.style.top = `${railY - (box.top - stageBox.top)}px`;
        thread.style.height = `${Math.max(top - railY, 0)}px`;
        return {
          el,
          left,
          right,
          center,
          top,
          bottom: baseline + m.actualBoundingBoxDescent,
          boxLeft,
          boxTop: box.top - stageBox.top,
          gap: 0,
          phi: 0,
          omega: 0,
          held: false,
        };
      });
      for (let i = 0; i + 1 < bobs.length; i++) {
        bobs[i].gap = Math.max(bobs[i + 1].left - bobs[i].right, 0);
      }
      pull = null;
      hand = null;
    };

    const draw = () => {
      for (const bob of bobs) {
        if (bob.phi === 0) {
          bob.el.style.transform = "";
          continue;
        }
        const px = bob.center - bob.boxLeft;
        const py = railY - bob.boxTop;
        // Swinging right turns the letter counter-clockwise about the rail.
        bob.el.style.transform = `translate3d(${px.toFixed(2)}px, ${py.toFixed(2)}px, 0) rotate(${(-bob.phi).toFixed(4)}rad) translate3d(${(-px).toFixed(2)}px, ${(-py).toFixed(2)}px, 0)`;
      }
    };

    const energy = () =>
      bobs.reduce(
        (e, b) => e + (b.omega / w0) ** 2 + 2 * (1 - Math.cos(b.phi)),
        0
      );

    /** Bounce two touching letters apart if they're closing. */
    const bounceApart = (a: Bob, b: Bob, wa: number, wb: number) => {
      const ca = Math.max(Math.cos(a.phi), 0.2);
      const cb = Math.max(Math.cos(b.phi), 0.2);
      const va = a.omega * radius * ca;
      const vb = b.omega * radius * cb;
      const closing = va - vb;
      if (closing <= 0) {
        return;
      }
      const impulse = ((1 + restitution) * closing) / (wa + wb);
      // A held letter (weight 0) keeps the hand's speed.
      a.omega = (va - wa * impulse) / (radius * ca);
      b.omega = (vb + wb * impulse) / (radius * cb);
    };

    /** Separate two letters that overlap and bounce them if they're closing. */
    const collide = (a: Bob, b: Bob) => {
      const xa = radius * Math.sin(a.phi);
      const xb = radius * Math.sin(b.phi);
      const depth = xa - xb - a.gap;
      const wa = a.held ? 0 : 1;
      const wb = b.held ? 0 : 1;
      if (depth <= 0 || wa + wb === 0) {
        return;
      }
      const share = depth / (wa + wb);
      a.phi = Math.asin(clamp((xa - wa * share) / radius, -1, 1));
      b.phi = Math.asin(clamp((xb + wb * share) / radius, -1, 1));
      bounceApart(a, b, wa, wb);
    };

    const swing = (h: number, drag: number) => {
      for (const bob of bobs) {
        if (!bob.held) {
          bob.omega -= w0 * w0 * Math.sin(bob.phi) * h;
          bob.omega *= 1 - drag * h;
          bob.phi += bob.omega * h;
        }
      }
    };

    const step = (dt: number) => {
      const h = dt / SUBSTEPS;
      const drag = energy() < SETTLE_BELOW ? SETTLE_DRAG : DRAG;
      for (let s = 0; s < SUBSTEPS; s++) {
        swing(h, drag);
        // Sweep both ways so a knock travels the whole row in one step,
        // the way it does through a real cradle.
        for (let it = 0; it < ITERATIONS; it++) {
          for (let i = 0; i + 1 < bobs.length; i++) {
            collide(bobs[i], bobs[i + 1]);
          }
          for (let i = bobs.length - 2; i >= 0; i--) {
            collide(bobs[i], bobs[i + 1]);
          }
        }
      }
    };

    const runPull = (now: number) => {
      if (!pull) {
        return;
      }
      const t = (now - pull.start) / INTRO_PULL;
      if (t >= 1.25) {
        pull.bob.held = false;
        pull.bob.omega = 0;
        pull = null;
        return;
      }
      pull.bob.held = true;
      pull.bob.phi = pull.to * easeOut(Math.min(t, 1));
      pull.bob.omega = 0;
    };

    const frame = (now: number) => {
      raf = 0;
      if (!visible) {
        return;
      }
      const dt = last ? Math.min((now - last) / 1000, 1 / 30) : 1 / 60;
      last = now;
      runPull(now);
      step(dt);
      draw();
      if (hand || pull || energy() > REST) {
        raf = requestAnimationFrame(frame);
        return;
      }
      for (const bob of bobs) {
        bob.phi = 0;
        bob.omega = 0;
      }
      draw();
    };

    const start = () => {
      if (!raf && visible) {
        last = 0;
        raf = requestAnimationFrame(frame);
      }
    };

    /** Pointer in stage px. */
    const local = (event: PointerEvent) => {
      const r = stage.getBoundingClientRect();
      return { x: event.clientX - r.left, y: event.clientY - r.top };
    };

    /** The letter under the pointer, where it hangs right now. */
    const bobAt = (x: number, y: number, slack: number) =>
      bobs.find((bob) => {
        const shift = radius * Math.sin(bob.phi);
        return (
          x > bob.left + shift - slack &&
          x < bob.right + shift + slack &&
          y > bob.top - slack &&
          y < bob.bottom + slack
        );
      });

    const onDown = (event: PointerEvent) => {
      if (hand || event.button !== 0) {
        return;
      }
      const p = local(event);
      const em = Number.parseFloat(getComputedStyle(lettersEl).fontSize);
      const bob = bobAt(p.x, p.y, em * 0.1);
      if (!bob) {
        return;
      }
      stage.setPointerCapture(event.pointerId);
      pull = null;
      bob.held = true;
      bob.omega = 0;
      hand = {
        id: event.pointerId,
        bob,
        startX: p.x - radius * Math.sin(bob.phi),
        startTime: event.timeStamp,
        moved: false,
        prev: bob.phi,
        prevTime: event.timeStamp,
        spin: 0,
      };
      stage.dataset.grabbing = "";
      start();
    };

    const onMove = (event: PointerEvent) => {
      const p = local(event);
      if (hand && event.pointerId === hand.id) {
        const dx = p.x - hand.startX;
        if (Math.abs(dx) > 3) {
          hand.moved = true;
        }
        // The letter follows the finger sideways along its arc.
        const phi = Math.asin(
          clamp(dx / radius, -Math.sin(MAX_ANGLE), Math.sin(MAX_ANGLE))
        );
        const dt = Math.max(event.timeStamp - hand.prevTime, 8) / 1000;
        const spin = (phi - hand.prev) / dt;
        hand.spin = hand.spin * 0.4 + spin * 0.6;
        hand.prev = phi;
        hand.prevTime = event.timeStamp;
        hand.bob.phi = phi;
        // Carried into its neighbours, the hand pushes them along.
        hand.bob.omega = hand.spin;
        start();
        return;
      }
      if (event.pointerType !== "mouse") {
        sweep = null;
        return;
      }
      const over = bobAt(p.x, p.y, 0) ?? null;
      if (sweep && over && over !== sweep.over && !over.held) {
        // Brushing through a letter knocks it the way the cursor moved.
        const dt = Math.max(event.timeStamp - sweep.t, 8) / 1000;
        const vx = clamp((p.x - sweep.x) / dt, -MAX_SWEEP, MAX_SWEEP);
        over.omega += (SWEEP_PUSH * vx) / radius;
        pull = null;
        start();
      }
      sweep = { x: p.x, t: event.timeStamp, over };
    };

    const onUp = (event: PointerEvent) => {
      if (!hand || event.pointerId !== hand.id) {
        return;
      }
      const { bob } = hand;
      bob.held = false;
      delete stage.dataset.grabbing;
      if (hand.moved) {
        // Let go from still if the hand stopped before releasing.
        const idle = event.timeStamp - hand.prevTime > 60;
        bob.omega = idle ? 0 : clamp(hand.spin, -w0 * 1.5, w0 * 1.5);
      } else {
        // A tap knocks the letter away from the side it was tapped on.
        const p = local(event);
        const side = p.x < bob.center + radius * Math.sin(bob.phi) ? 1 : -1;
        bob.omega += side * w0 * TAP_ANGLE;
      }
      hand = null;
      start();
    };

    const onLeave = () => {
      sweep = null;
    };

    measure();
    draw();

    let width = stage.clientWidth;
    const resizeObserver = new ResizeObserver(() => {
      if (stage.clientWidth === width) {
        return;
      }
      width = stage.clientWidth;
      measure();
      draw();
    });
    resizeObserver.observe(stage);
    document.fonts?.ready.then(() => {
      measure();
      draw();
    });

    let greeted = !intro || reduceMotion;
    let greetTimer = 0;
    const intersection = new IntersectionObserver(
      ([entry]) => {
        visible =
          entry.isIntersecting && document.visibilityState === "visible";
        if (!visible) {
          return;
        }
        if (!greeted && entry.intersectionRatio > 0.6) {
          greeted = true;
          greetTimer = window.setTimeout(() => {
            const first = bobs[0];
            if (first && !hand) {
              pull = { bob: first, start: performance.now(), to: -INTRO_ANGLE };
              start();
            }
          }, 400);
        }
        start();
      },
      { threshold: [0, 0.6] }
    );
    intersection.observe(stage);
    const onVisibility = () => {
      visible = document.visibilityState === "visible";
      if (visible) {
        start();
      }
    };
    document.addEventListener("visibilitychange", onVisibility);

    if (!reduceMotion) {
      stage.addEventListener("pointerdown", onDown);
      stage.addEventListener("pointermove", onMove);
      stage.addEventListener("pointerup", onUp);
      stage.addEventListener("pointercancel", onUp);
      stage.addEventListener("pointerleave", onLeave);
    }

    return () => {
      cancelAnimationFrame(raf);
      window.clearTimeout(greetTimer);
      resizeObserver.disconnect();
      intersection.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      stage.removeEventListener("pointerdown", onDown);
      stage.removeEventListener("pointermove", onMove);
      stage.removeEventListener("pointerup", onUp);
      stage.removeEventListener("pointercancel", onUp);
      stage.removeEventListener("pointerleave", onLeave);
    };
  }, [text, intro, bounce]);

  return (
    <div className={cn("@container flex w-full justify-center", className)}>
      <div
        className="relative cursor-grab touch-pan-y select-none px-[0.9em] pt-[1.5em] pb-[0.45em] font-semibold text-[clamp(2rem,11cqi,6rem)] text-zinc-900 leading-none tracking-tight data-[grabbing]:cursor-grabbing motion-reduce:cursor-default dark:text-zinc-100"
        ref={stageRef}
      >
        <span className="sr-only">{text}</span>
        {/* The rail the letters hang from. */}
        <span
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-[0.3em] h-px bg-zinc-300 dark:bg-zinc-700"
          ref={railRef}
        />
        <span
          aria-hidden="true"
          className="relative block whitespace-pre"
          ref={lettersRef}
        >
          {Array.from(text).map((char, index) =>
            char === " " ? (
              // biome-ignore lint/suspicious/noArrayIndexKey: letters repeat; their position is their identity.
              <span className="inline-block w-[0.32em]" key={index} />
            ) : (
              <span
                className="relative inline-block origin-top-left will-change-transform"
                data-letter={char}
                // biome-ignore lint/suspicious/noArrayIndexKey: letters repeat; their position is their identity.
                key={index}
              >
                <span className="absolute w-px bg-zinc-300 dark:bg-zinc-600" />
                {char}
              </span>
            )
          )}
          <span className="inline-block h-0 w-0" />
        </span>
      </div>
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Currency Transfer
 * @version: 3.0.0
 * @date: 2026-10-15
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import { CheckIcon, CopyIcon, RotateCcwIcon, XIcon } from "lucide-react";
import { useEffect, useState } from "react";
import { cn } from "@/lib/utils";

export type TransferStatus = "processing" | "completed" | "failed";

export interface TransferAccount {
  /** Amount sent from / received into this account. */
  amount: number;
  /** ISO currency code, e.g. "USD". */
  currency: string;
  /** Short symbol, e.g. "$". Defaults to the currency's own symbol. */
  symbol?: string;
  /** Bank or account name, e.g. "Chase Bank". */
  bank: string;
  /** Last digits of the account number, shown masked. */
  last4?: string;
  /** Account holder, shown on the receiving side, e.g. "Lena Fischer". */
  name?: string;
}

export interface CurrencyTransferProps {
  from?: TransferAccount;
  to?: TransferAccount;
  /** Units of `to.currency` per one unit of `from.currency`. */
  rate?: number;
  /** Transaction reference, copyable from the footer. */
  txnId?: string;
  /** When the rate was locked, e.g. "10:45 AM". */
  timestamp?: string;
  /**
   * Controlled status. While "processing" the steps run up to the last
   * one and wait there. Leave unset for a demo that completes on its own.
   */
  status?: TransferStatus;
  /** BCP 47 locale for amounts, symbols and the rate. */
  locale?: string;
  /** Shows a Retry button when the transfer has failed. */
  onRetry?: () => void;
  className?: string;
}

const DEFAULT_FROM: TransferAccount = {
  amount: 500,
  currency: "USD",
  symbol: "$",
  bank: "Chase",
  last4: "4589",
};

const DEFAULT_TO: TransferAccount = {
  amount: 460,
  currency: "EUR",
  symbol: "€",
  bank: "Deutsche Bank",
  last4: "7823",
  name: "Lena Fischer",
};

const EASE_OUT_CSS = "cubic-bezier(0.23, 1, 0.32, 1)";
const EASE_IN_OUT_CSS = "cubic-bezier(0.77, 0, 0.175, 1)";
// Each step takes this long in the demo, and while processing.
const STEP_MS = 1100;
// Steps done at first render: the payment has already been taken.
const FIRST_DONE = 1;
// While processing, the run waits on the last step (arrival).
const WAIT_AT = 3;
const DIGIT_STAGGER_MS = 30;
// Longer than a UI transition on purpose: it is the one moment the card
// explains (the money changing currency), and it happens once.
const DIGIT_ROLL_MS = 550;
// How long the rail takes to reach the next step; that step's spinner
// waits for it, so progress reads as flowing down the line.
const RAIL_MS = 350;
const COPIED_MS = 1500;
const NOT_LETTER = /[^\p{L}]+/u;

function formatNumber(value: number, locale: string, digits: number) {
  return new Intl.NumberFormat(locale, {
    minimumFractionDigits: digits,
    maximumFractionDigits: digits,
  }).format(value);
}

function getCurrencySymbol(currency: string, locale: string) {
  try {
    const parts = new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      currencyDisplay: "narrowSymbol",
    }).formatToParts(0);
    return (
      parts.find((part) => part.type === "currency")?.value ??
      currency.charAt(0)
    );
  } catch {
    // Not an ISO 4217 code.
    return currency.charAt(0);
  }
}

const symbolOf = (account: TransferAccount, locale: string) =>
  account.symbol ?? getCurrencySymbol(account.currency, locale);

const initialsOf = (name: string) =>
  name
    .split(NOT_LETTER)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part.charAt(0).toUpperCase())
    .join("");

/**
 * An odometer: each digit is a 0-9 strip in a one-digit window, moved with
 * translateY. Columns are keyed from the right so a changing length keeps
 * them aligned, and the right-most column moves first.
 */
function RollingNumber({ value }: { value: string }) {
  const chars = Array.from(value);
  return (
    <span aria-hidden="true" className="inline-flex select-none tabular-nums">
      {chars.map((char, index) => {
        const fromRight = chars.length - index;
        const digit = Number.parseInt(char, 10);
        if (Number.isNaN(digit)) {
          return <span key={`s-${fromRight}`}>{char}</span>;
        }
        return (
          <span
            className="relative inline-block h-[1lh] overflow-hidden"
            key={`d-${fromRight}`}
          >
            {/* Sizes the window to one digit. */}
            <span className="invisible">0</span>
            <span
              // Reduced motion is handled in CSS, so the server and the
              // client render the same markup.
              className="absolute inset-x-0 top-0 flex flex-col motion-reduce:transition-none!"
              style={{
                transform: `translateY(${-digit * 10}%)`,
                transition: `transform ${DIGIT_ROLL_MS}ms ${EASE_OUT_CSS} ${(fromRight - 1) * DIGIT_STAGGER_MS}ms`,
              }}
            >
              {"0123456789".split("").map((n) => (
                <span className="h-[1lh]" key={n}>
                  {n}
                </span>
              ))}
            </span>
          </span>
        );
      })}
    </span>
  );
}

/** Two symbols in one cell, crossfading, so the amount never shifts. */
function SwapSymbol({
  from,
  to,
  showTo,
}: {
  from: string;
  to: string;
  showTo: boolean;
}) {
  const face =
    "col-start-1 row-start-1 text-right transition-[opacity,filter] duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-[opacity]";
  return (
    <span aria-hidden="true" className="inline-grid">
      <span className={cn(face, showTo && "opacity-0 blur-[3px]")}>{from}</span>
      <span className={cn(face, !showTo && "opacity-0 blur-[3px]")}>{to}</span>
    </span>
  );
}

type StepState = "done" | "active" | "pending" | "failed";

function StepNode({ state }: { state: StepState }) {
  return (
    <span className="relative flex size-5 shrink-0 items-center justify-center">
      {/* Pending: an empty ring. Active: the ring with a turning arc. */}
      <span
        className={cn(
          "absolute inset-0 rounded-full border-[1.5px] transition-colors duration-200 ease-out",
          (state === "pending" || state === "active") &&
            "border-zinc-200 dark:border-zinc-700",
          state === "done" &&
            "border-zinc-900 bg-zinc-900 dark:border-zinc-100 dark:bg-zinc-100",
          state === "failed" && "border-red-500 bg-red-500"
        )}
      />
      {state === "active" && (
        // Fades in once the rail has arrived, then turns. A quick turn
        // reads as fast progress; reduced motion keeps the still arc.
        <span
          className="absolute inset-0 animate-[kokonutui-ct-in_200ms_ease-out_both] motion-reduce:animate-none"
          style={{ animationDelay: `${RAIL_MS - 100}ms` }}
        >
          <svg
            aria-hidden="true"
            className="size-full animate-spin text-zinc-900 [animation-duration:750ms] motion-reduce:animate-none dark:text-zinc-100"
            fill="none"
            viewBox="0 0 20 20"
          >
            <path
              d="M10 1.25A8.75 8.75 0 0 1 18.75 10"
              stroke="currentColor"
              strokeLinecap="round"
              strokeWidth="1.5"
            />
          </svg>
        </span>
      )}
      {state === "done" && (
        <svg
          aria-hidden="true"
          className="relative size-3 text-white dark:text-zinc-900"
          fill="none"
          viewBox="0 0 12 12"
        >
          {/* The tick draws once, as the step finishes. */}
          <path
            className="animate-[kokonutui-ct-draw_300ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none"
            d="M2.5 6.25 5 8.5l4.5-5"
            pathLength={1}
            stroke="currentColor"
            strokeDasharray="1"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="1.75"
          />
        </svg>
      )}
      {state === "failed" && (
        <XIcon
          aria-hidden="true"
          className="relative size-3 text-white"
          strokeWidth={3}
        />
      )}
    </span>
  );
}

/** The reference, with a copy button that confirms in place. */
function TxnId({ id }: { id: string }) {
  const [copied, setCopied] = useState(false);
  useEffect(() => {
    if (!copied) {
      return;
    }
    const timer = setTimeout(() => setCopied(false), COPIED_MS);
    return () => clearTimeout(timer);
  }, [copied]);

  const icon =
    "col-start-1 row-start-1 size-3 transition-[opacity,filter] duration-150 ease-out";
  return (
    <button
      aria-label={copied ? "Reference copied" : `Copy reference ${id}`}
      className="-mx-1.5 -my-1 inline-flex items-center gap-1.5 rounded-md px-1.5 py-1 font-mono text-zinc-600 transition-colors duration-150 hover:bg-zinc-100 hover:text-zinc-900 focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-zinc-400/50 dark:text-zinc-300 dark:hover:bg-zinc-800 dark:hover:text-zinc-100"
      onClick={() => {
        navigator.clipboard
          ?.writeText(id)
          .then(() => setCopied(true))
          .catch(() => {
            // Clipboard blocked (permissions, insecure origin): no tick.
          });
      }}
      type="button"
    >
      {id}
      <span aria-hidden="true" className="grid size-3 place-items-center">
        <CopyIcon
          className={cn(icon, copied ? "opacity-0 blur-[2px]" : "opacity-60")}
        />
        <CheckIcon
          className={cn(
            icon,
            "text-emerald-600 dark:text-emerald-400",
            copied ? "opacity-100" : "opacity-0 blur-[2px]"
          )}
          strokeWidth={3}
        />
      </span>
    </button>
  );
}

const STATUSES: TransferStatus[] = ["processing", "completed", "failed"];

const PILL: Record<TransferStatus, { label: string; className: string }> = {
  processing: {
    label: "In progress",
    className: "bg-zinc-100 text-zinc-600 dark:bg-zinc-800 dark:text-zinc-300",
  },
  completed: {
    label: "Arrived",
    className:
      "bg-emerald-500/10 text-emerald-700 dark:bg-emerald-400/10 dark:text-emerald-300",
  },
  failed: {
    label: "Failed",
    className:
      "bg-red-500/10 text-red-700 dark:bg-red-400/10 dark:text-red-300",
  },
};

/**
 * Steps done so far. Runs a step at a time while processing and waits on
 * the last one; a fresh "processing" (a retry) starts over.
 */
function useProgress(status: TransferStatus) {
  const [progress, setProgress] = useState(FIRST_DONE);
  const [runFor, setRunFor] = useState(status);
  if (runFor !== status) {
    setRunFor(status);
    if (status === "processing") {
      setProgress(FIRST_DONE);
    }
  }
  useEffect(() => {
    if (status !== "processing" || progress >= WAIT_AT) {
      return;
    }
    const timer = setTimeout(() => setProgress((p) => p + 1), STEP_MS);
    return () => clearTimeout(timer);
  }, [status, progress]);
  return status === "completed" ? 4 : progress;
}

export default function CurrencyTransfer({
  from = DEFAULT_FROM,
  to = DEFAULT_TO,
  rate = 0.92,
  txnId = "TXN-DAB3UL494",
  timestamp = "10:45 AM",
  status,
  locale = "en-US",
  onRetry,
  className,
}: CurrencyTransferProps = {}) {
  const isControlled = status !== undefined;
  const [demoStatus, setDemoStatus] = useState<TransferStatus>("processing");
  const current = status ?? demoStatus;
  const done = useProgress(current);

  // Demo only: once the run reaches the last step, the money arrives.
  useEffect(() => {
    if (isControlled || current !== "processing" || done < WAIT_AT) {
      return;
    }
    const timer = setTimeout(() => setDemoStatus("completed"), STEP_MS);
    return () => clearTimeout(timer);
  }, [isControlled, current, done]);

  const converted = done >= 2;
  const shown = converted ? to : from;
  const recipient = to.name ?? to.bank;
  const toAccount = `${to.bank}${to.last4 ? ` ••${to.last4}` : ""}`;
  const fromAccount = `${from.bank}${from.last4 ? ` ••${from.last4}` : ""}`;
  const rateText = `1 ${from.currency} = ${formatNumber(rate, locale, 4)} ${to.currency}`;
  const arrived = current === "completed";

  const steps = [
    { id: "paid", title: "Payment received", detail: `From ${fromAccount}` },
    { id: "converted", title: `Converted to ${to.currency}`, detail: rateText },
    { id: "sent", title: `Sent to ${to.bank}`, detail: toAccount },
    {
      id: "arrived",
      title: arrived ? "Arrived" : "Arriving",
      detail: arrived
        ? `${recipient} can use it now`
        : "Usually within a minute",
    },
  ];

  const stateOf = (index: number): StepState => {
    if (index < done) {
      return "done";
    }
    if (index === done) {
      return current === "failed" ? "failed" : "active";
    }
    return "pending";
  };

  return (
    <div
      className={cn(
        "mx-auto w-full max-w-sm rounded-2xl bg-white p-5 ring-1 ring-zinc-200/80 dark:bg-zinc-900 dark:ring-zinc-800",
        "shadow-[0_1px_2px_rgb(0_0_0/0.04),0_8px_24px_-12px_rgb(0_0_0/0.12)]",
        className
      )}
    >
      {/* Tick draw and text blur-in; prefixed so they cannot clash with app
          CSS, and hoisted once however many cards are on the page. */}
      <style href="kokonutui-currency-transfer" precedence="default">
        {
          "@keyframes kokonutui-ct-draw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}@keyframes kokonutui-ct-in{from{opacity:0;filter:blur(2px)}}"
        }
      </style>
      <output aria-live="polite" className="sr-only">
        {arrived &&
          `Transfer arrived. ${formatNumber(to.amount, locale, 2)} ${to.currency} to ${recipient}.`}
        {current === "failed" && `Transfer failed. Refunded to ${fromAccount}.`}
        {current === "processing" && steps[Math.min(done, 3)].title}
      </output>

      {/* Who it's for, and where it stands. */}
      <div className="flex items-center gap-3">
        <span
          aria-hidden="true"
          className="flex size-9 shrink-0 items-center justify-center rounded-full bg-zinc-100 font-medium text-xs text-zinc-700 dark:bg-zinc-800 dark:text-zinc-200"
        >
          {initialsOf(recipient)}
        </span>
        <div className="min-w-0 flex-1 leading-tight">
          <p className="truncate font-medium text-sm text-zinc-900 dark:text-zinc-100">
            {recipient}
          </p>
          <p className="truncate text-xs text-zinc-500 dark:text-zinc-400">
            {toAccount}
          </p>
        </div>
        {/* Every label sits in one cell, so the pill keeps its width and
            the words crossfade instead of snapping. */}
        <span
          className={cn(
            "inline-grid h-6 shrink-0 items-center rounded-full px-2 font-medium text-[11px] transition-colors duration-200 ease-out",
            PILL[current].className
          )}
        >
          {STATUSES.map((key) => (
            <span
              aria-hidden={key !== current}
              className={cn(
                "col-start-1 row-start-1 text-center transition-[opacity,filter] duration-200 ease-out motion-reduce:transition-[opacity]",
                key === current ? "opacity-100" : "opacity-0 blur-[2px]"
              )}
              key={key}
            >
              {PILL[key].label}
            </span>
          ))}
        </span>
      </div>

      {/* The amount converts in place once the conversion step is done. */}
      <div className="mt-6">
        <p className="font-semibold text-4xl text-zinc-900 tracking-tight dark:text-zinc-50">
          <span className="sr-only">
            {formatNumber(shown.amount, locale, 2)} {shown.currency}
          </span>
          <SwapSymbol
            from={symbolOf(from, locale)}
            showTo={converted}
            to={symbolOf(to, locale)}
          />
          <RollingNumber value={formatNumber(shown.amount, locale, 2)} />
        </p>
        <p className="mt-1 text-xs text-zinc-500 tabular-nums dark:text-zinc-400">
          {formatNumber(from.amount, locale, 2)} {from.currency} sent ·{" "}
          {formatNumber(to.amount, locale, 2)} {to.currency} received
        </p>
      </div>

      <ol className="mt-6">
        {steps.map((step, index) => {
          const state = stateOf(index);
          const last = index === steps.length - 1;
          return (
            <li className="flex gap-3" key={step.id}>
              <div className="flex flex-col items-center">
                <StepNode state={state} />
                {!last && (
                  // When a step finishes, the rail runs down to the next one.
                  <span className="relative my-1 w-[1.5px] flex-1 overflow-hidden rounded-full bg-zinc-200 dark:bg-zinc-800">
                    <span
                      className={cn(
                        "absolute inset-0 origin-top bg-zinc-900 transition-[scale] motion-reduce:transition-none dark:bg-zinc-100",
                        index < done ? "scale-y-100" : "scale-y-0"
                      )}
                      style={{
                        transitionDuration: `${RAIL_MS}ms`,
                        transitionTimingFunction: EASE_IN_OUT_CSS,
                      }}
                    />
                  </span>
                )}
              </div>
              <div className={cn("min-w-0 flex-1", !last && "pb-4")}>
                <p
                  className={cn(
                    "text-sm leading-5 transition-colors duration-200 ease-out",
                    state === "pending"
                      ? "text-zinc-400 dark:text-zinc-500"
                      : "text-zinc-900 dark:text-zinc-100",
                    state === "failed" && "text-red-600 dark:text-red-400"
                  )}
                >
                  {/* Keyed, so changed words blur in rather than snap. */}
                  <span
                    className="block animate-[kokonutui-ct-in_200ms_ease-out_both] motion-reduce:animate-none"
                    key={state === "failed" ? "failed" : step.title}
                  >
                    {state === "failed" ? "Couldn't complete" : step.title}
                  </span>
                </p>
                <p
                  className={cn(
                    "mt-0.5 text-xs tabular-nums transition-colors duration-200 ease-out",
                    state === "pending"
                      ? "text-zinc-400 dark:text-zinc-500"
                      : "text-zinc-500 dark:text-zinc-400"
                  )}
                >
                  <span
                    className="block animate-[kokonutui-ct-in_200ms_ease-out_both] motion-reduce:animate-none"
                    key={state === "failed" ? "failed" : step.detail}
                  >
                    {state === "failed"
                      ? `Refunded to ${fromAccount}`
                      : step.detail}
                  </span>
                </p>
                {state === "failed" && onRetry && (
                  <button
                    className="mt-2 inline-flex h-7 animate-[kokonutui-ct-in_200ms_ease-out_150ms_both] items-center gap-1.5 rounded-md bg-zinc-900 px-2.5 font-medium text-white text-xs transition-colors duration-150 hover:bg-zinc-700 focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-zinc-400/50 motion-reduce:animate-none dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-zinc-300"
                    onClick={onRetry}
                    type="button"
                  >
                    <RotateCcwIcon aria-hidden="true" className="size-3" />
                    Retry
                  </button>
                )}
              </div>
            </li>
          );
        })}
      </ol>

      <div className="mt-5 flex items-center justify-between border-zinc-100 border-t pt-4 text-xs dark:border-zinc-800">
        <TxnId id={txnId} />
        <span className="text-zinc-400 dark:text-zinc-500">
          Rate locked {timestamp}
        </span>
      </div>
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Detent Dial
 * @version: 1.0.0
 * @date: 2026-10-13
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import {
  AnimatePresence,
  type AnimationPlaybackControls,
  animate,
  motion,
  useMotionValue,
  useMotionValueEvent,
  useReducedMotion,
  useTransform,
  type Variants,
} from "motion/react";
import {
  type KeyboardEvent,
  type PointerEvent,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

// The dial sweeps 270°, from 7:30 to 4:30 on a clock face.
const SWEEP = 270;
const START_ANGLE = -135;
// How far (deg) the knob can be wound past either end. The pull flattens
// out as it approaches this, so it slows down instead of hitting a wall.
const MAX_OVERSHOOT = 16;
// While dragging, the knob is pulled this much toward the nearest notch,
// which is what makes it feel like it clicks from one step to the next.
const DETENT_PULL = 0.65;
const MAX_TICKS = 56;
// The swell that follows the indicator round the ring: extra length (px)
// at its peak, and how many degrees it spreads either side.
const WAVE_HEIGHT = 9;
const WAVE_WIDTH = 12;
// Pointer movement this close to the centre gives wild angle jumps.
const DEAD_ZONE = 14;
// Below this speed (fraction of the range per second) a release just
// settles into the nearest notch instead of coasting.
const FLICK_THRESHOLD = 0.4;
const VELOCITY_WINDOW_MS = 80;
// Seconds of travel a flick is worth: release speed × COAST = distance coasted.
const COAST = 0.3;
const SETTLE_SPRING = { type: "spring", duration: 0.35, bounce: 0.2 } as const;
const EASE_OUT = [0.23, 1, 0.32, 1] as const;

function damp(distance: number, max: number) {
  return max * (1 - Math.exp(-distance / max));
}

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max);
}

function snap(value: number, min: number, step: number) {
  return Number((Math.round((value - min) / step) * step + min).toFixed(10));
}

function polar(cx: number, cy: number, radius: number, angle: number) {
  const rad = (angle * Math.PI) / 180;
  // Rounded so the server and the browser, whose trig can differ in the
  // last digits, render identical markup.
  return {
    x: Math.round((cx + radius * Math.sin(rad)) * 100) / 100,
    y: Math.round((cy - radius * Math.cos(rad)) * 100) / 100,
  };
}

function pointerAngle(event: PointerEvent, rect: DOMRect) {
  const dx = event.clientX - (rect.left + rect.width / 2);
  const dy = event.clientY - (rect.top + rect.height / 2);
  return {
    angle: (Math.atan2(dx, -dy) * 180) / Math.PI,
    distance: Math.hypot(dx, dy),
  };
}

// navigator.vibrate is a no-op where unsupported (iOS, desktop). On
// Android it gives each notch a faint tick under the finger.
function hapticTick() {
  if (typeof navigator !== "undefined" && "vibrate" in navigator) {
    navigator.vibrate(1);
  }
}

export interface DetentDialProps {
  /** Accessible name, also shown inside the knob. */
  label?: string;
  min?: number;
  max?: number;
  step?: number;
  /** Initial value when uncontrolled. Double-clicking the knob returns here. */
  defaultValue?: number;
  /** Controlled value. */
  value?: number;
  onValueChange?: (value: number) => void;
  /** Formats the readout, the end labels and `aria-valuetext`. */
  formatValue?: (value: number) => string;
  /** Diameter in px. */
  size?: number;
  disabled?: boolean;
  className?: string;
}

export default function DetentDial({
  label = "Temperature",
  min = 16,
  max = 30,
  step = 0.5,
  defaultValue = 21,
  value: valueProp,
  onValueChange,
  formatValue = (v) => `${v.toFixed(1)}°`,
  size = 240,
  disabled = false,
  className,
}: DetentDialProps) {
  const labelId = useId();
  const knobRef = useRef<HTMLDivElement>(null);
  const tickRefs = useRef<(SVGLineElement | null)[]>([]);
  // The length last written to each tick, so a frame only touches the few
  // ticks the swell is actually passing over.
  const tickLengths = useRef<number[]>([]);
  const reduceMotion = useReducedMotion();
  const range = max - min;

  const initial = clamp(valueProp ?? defaultValue, min, max);
  const [value, setValue] = useState(initial);
  const [direction, setDirection] = useState<1 | -1>(1);
  const [grabbing, setGrabbing] = useState(false);
  const committed = useRef(initial);
  const pointerType = useRef("mouse");

  // The raw, unsnapped position in value units. It can run past min/max
  // while winding; everything visual is derived from it.
  const raw = useMotionValue(initial);
  const animation = useRef<AnimationPlaybackControls | null>(null);
  const drag = useRef<{
    id: number;
    // Measured once on grab: reading layout on every move forces the
    // browser to recalculate it after each frame's writes.
    rect: DOMRect;
    lastAngle: number;
    samples: { t: number; v: number }[];
  } | null>(null);

  const rotation = useTransform(raw, (r) => {
    const degPerUnit = range === 0 ? 0 : SWEEP / range;
    if (r < min) {
      return START_ANGLE - damp((min - r) * degPerUnit, MAX_OVERSHOOT);
    }
    if (r > max) {
      return START_ANGLE + SWEEP + damp((r - max) * degPerUnit, MAX_OVERSHOOT);
    }
    const notch = snap(r, min, step);
    const pulled = notch + (r - notch) * (1 - DETENT_PULL);
    return START_ANGLE + (pulled - min) * degPerUnit;
  });

  // Only re-render when the dial crosses into a new notch, not per frame.
  useMotionValueEvent(raw, "change", (r) => {
    const next = clamp(snap(r, min, step), min, max);
    if (next === committed.current) {
      return;
    }
    setDirection(next > committed.current ? 1 : -1);
    committed.current = next;
    setValue(next);
    onValueChange?.(next);
    if (pointerType.current === "touch") {
      hapticTick();
    }
  });

  // Follow a controlled value when the parent changes it.
  useEffect(() => {
    if (valueProp === undefined || drag.current) {
      return;
    }
    const next = clamp(valueProp, min, max);
    if (next !== committed.current) {
      animation.current?.stop();
      committed.current = next;
      setValue(next);
      raw.jump(next);
    }
  }, [valueProp, min, max, raw]);

  useEffect(() => () => animation.current?.stop(), []);

  const settleTo = (target: number) => {
    animation.current?.stop();
    animation.current = animate(
      raw,
      target,
      reduceMotion ? { duration: 0 } : SETTLE_SPRING
    );
  };

  // Keyboard and wheel steps jump straight to the value. They repeat fast,
  // and an animation on each would trail behind the input.
  const stepBy = (delta: number) => {
    animation.current?.stop();
    const target = clamp(snap(committed.current + delta, min, step), min, max);
    pointerType.current = "keyboard";
    raw.jump(target);
  };

  const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (disabled || drag.current) {
      return;
    }
    if (event.pointerType === "mouse" && event.button !== 0) {
      return;
    }
    const rect = event.currentTarget.getBoundingClientRect();
    const { angle } = pointerAngle(event, rect);
    animation.current?.stop();
    pointerType.current = event.pointerType;
    event.currentTarget.setPointerCapture(event.pointerId);
    drag.current = {
      id: event.pointerId,
      rect,
      lastAngle: angle,
      samples: [{ t: event.timeStamp, v: raw.get() }],
    };
    setGrabbing(true);
  };

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const current = drag.current;
    if (!current || current.id !== event.pointerId) {
      return;
    }
    const { angle, distance } = pointerAngle(event, current.rect);
    if (distance < DEAD_ZONE) {
      current.lastAngle = angle;
      return;
    }
    // Unwrap so crossing 6 o'clock doesn't read as a 360° jump.
    let delta = angle - current.lastAngle;
    if (delta > 180) {
      delta -= 360;
    } else if (delta < -180) {
      delta += 360;
    }
    current.lastAngle = angle;
    const next = raw.get() + (delta / SWEEP) * range;
    raw.set(next);
    current.samples.push({ t: event.timeStamp, v: next });
    while (
      current.samples.length > 2 &&
      event.timeStamp - current.samples[0].t > VELOCITY_WINDOW_MS
    ) {
      current.samples.shift();
    }
  };

  const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
    const current = drag.current;
    if (!current || current.id !== event.pointerId) {
      return;
    }
    drag.current = null;
    setGrabbing(false);

    const first = current.samples[0];
    const last = current.samples.at(-1) ?? first;
    const elapsed = (last.t - first.t) / 1000;
    // Holding still before letting go is a placement, not a flick.
    const paused = event.timeStamp - last.t > VELOCITY_WINDOW_MS;
    const velocity = elapsed > 0 && !paused ? (last.v - first.v) / elapsed : 0;
    const position = raw.get();
    const inBounds = position >= min && position <= max;

    if (
      reduceMotion ||
      !inBounds ||
      Math.abs(velocity) < range * FLICK_THRESHOLD
    ) {
      settleTo(clamp(snap(position, min, step), min, max));
      return;
    }
    // A flick coasts, slows down, and lands on a notch. If it runs out of
    // room it bounces off the end instead of stopping dead.
    animation.current?.stop();
    // Project where the flick would coast to, land that on a notch, then
    // spring there carrying the release velocity. If the projection runs
    // past an end, the spring overshoots it a little and settles back.
    const target = clamp(
      snap(position + velocity * COAST, min, step),
      min,
      max
    );
    animation.current = animate(raw, target, {
      type: "spring",
      velocity,
      stiffness: 140,
      damping: 24,
      restDelta: 0.005,
    });
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (disabled) {
      return;
    }
    const big = Math.max(step, snap(range / 10, 0, step));
    const keySteps: Record<string, number> = {
      ArrowUp: step,
      ArrowRight: step,
      ArrowDown: -step,
      ArrowLeft: -step,
      PageUp: big,
      PageDown: -big,
      Home: min - committed.current,
      End: max - committed.current,
    };
    if (!(event.key in keySteps)) {
      return;
    }
    event.preventDefault();
    stepBy(keySteps[event.key]);
  };

  // The wheel only turns the dial once it has focus, so scrolling the page
  // past it never changes the value by accident. The listener is attached
  // once and reads the latest props through a ref.
  const wheelStep = useRef({ disabled, step, stepBy });
  wheelStep.current = { disabled, step, stepBy };
  useEffect(() => {
    const knob = knobRef.current;
    if (!knob) {
      return;
    }
    let accumulated = 0;
    const onWheel = (event: WheelEvent) => {
      const latest = wheelStep.current;
      if (latest.disabled || document.activeElement !== knob) {
        return;
      }
      event.preventDefault();
      accumulated += event.deltaY;
      // Trackpads send many tiny deltas; one notch per ~40px of scroll.
      while (Math.abs(accumulated) >= 40) {
        const sign = Math.sign(accumulated);
        accumulated -= sign * 40;
        latest.stepBy(-sign * latest.step);
      }
    };
    knob.addEventListener("wheel", onWheel, { passive: false });
    return () => knob.removeEventListener("wheel", onWheel);
  }, []);

  const center = size / 2;
  const tickCount = Math.max(1, Math.min(Math.round(range / step), MAX_TICKS));
  const valueFraction = range === 0 ? 0 : (value - min) / range;
  const activeTick = Math.round(valueFraction * tickCount);
  const knobSize = size * 0.64;
  const outer = size / 2 - 6;

  // Ticks swell as the indicator passes them, following its exact angle
  // (not the snapped value), so a wave travels round the ring as you turn.
  function tickLength(i: number, indicatorAngle: number) {
    const angle = START_ANGLE + (i / tickCount) * SWEEP;
    // Min, mid and max read as the scale's anchors, like a ruler's inch marks.
    const anchor = i === 0 || i === tickCount || i * 2 === tickCount;
    const major = i % 5 === 0;
    let base = 6;
    if (anchor) {
      base = 14;
    } else if (major) {
      base = 10;
    }
    const distance = (angle - indicatorAngle) / WAVE_WIDTH;
    // Rounded to a tenth of a pixel: finer changes aren't visible, and
    // skipping them leaves most ticks untouched on any given frame.
    return (
      Math.round((base + WAVE_HEIGHT * Math.exp(-distance * distance)) * 10) /
      10
    );
  }

  function tickGeometry(i: number, length: number) {
    const angle = START_ANGLE + (i / tickCount) * SWEEP;
    return {
      a: polar(center, center, outer - length, angle),
      b: polar(center, center, outer, angle),
    };
  }

  // Written straight to the lines each frame; no re-render while turning.
  useMotionValueEvent(rotation, "change", (indicatorAngle) => {
    for (let i = 0; i <= tickCount; i++) {
      const line = tickRefs.current[i];
      const length = tickLength(i, indicatorAngle);
      if (!line || tickLengths.current[i] === length) {
        continue;
      }
      tickLengths.current[i] = length;
      const { a } = tickGeometry(i, length);
      line.setAttribute("x1", String(a.x));
      line.setAttribute("y1", String(a.y));
    }
  });
  const minLabel = polar(center, center, outer + 2, START_ANGLE - 12);
  const maxLabel = polar(center, center, outer + 2, START_ANGLE + SWEEP + 12);

  return (
    <div
      className={cn(
        "relative select-none",
        disabled && "opacity-50",
        className
      )}
      style={{ width: size, height: size }}
    >
      <svg
        aria-hidden="true"
        className="absolute inset-0"
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        width={size}
      >
        {Array.from({ length: tickCount + 1 }, (_, i) => {
          const lit = i <= activeTick;
          const current = i === activeTick;
          const length = tickLength(i, rotation.get());
          tickLengths.current[i] = length;
          const { a, b } = tickGeometry(i, length);
          return (
            <line
              className={cn(
                "transition-[stroke] duration-150",
                current && "stroke-orange-600 dark:stroke-orange-400",
                !current &&
                  (lit
                    ? "stroke-zinc-900 dark:stroke-zinc-100"
                    : "stroke-zinc-300 dark:stroke-zinc-700")
              )}
              // biome-ignore lint/suspicious/noArrayIndexKey: ticks are positional.
              key={i}
              ref={(node) => {
                tickRefs.current[i] = node;
              }}
              strokeLinecap="round"
              strokeWidth={current ? 2 : 1.5}
              x1={a.x}
              x2={b.x}
              y1={a.y}
              y2={b.y}
            />
          );
        })}
      </svg>

      <span
        aria-hidden="true"
        className="absolute -translate-x-1/2 text-[11px] text-zinc-400 tabular-nums"
        style={{ left: minLabel.x, top: minLabel.y }}
      >
        {formatValue(min)}
      </span>
      <span
        aria-hidden="true"
        className="absolute -translate-x-1/2 text-[11px] text-zinc-400 tabular-nums"
        style={{ left: maxLabel.x, top: maxLabel.y }}
      >
        {formatValue(max)}
      </span>

      <div
        aria-disabled={disabled || undefined}
        aria-labelledby={labelId}
        aria-valuemax={max}
        aria-valuemin={min}
        aria-valuenow={value}
        aria-valuetext={formatValue(value)}
        className={cn(
          "absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 touch-none rounded-full outline-none",
          "border border-zinc-200 bg-white shadow-[0_1px_2px_rgb(0_0_0/0.06),0_12px_32px_-12px_rgb(0_0_0/0.25)] dark:border-zinc-800 dark:bg-zinc-900 dark:shadow-[0_1px_2px_rgb(0_0_0/0.4),0_12px_32px_-12px_rgb(0_0_0/0.8)]",
          "transition-[border-color] duration-150 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-4 focus-visible:ring-offset-white dark:focus-visible:ring-offset-zinc-950",
          grabbing
            ? "cursor-grabbing border-zinc-300 dark:border-zinc-700"
            : "cursor-grab",
          disabled && "cursor-not-allowed"
        )}
        onDoubleClick={() => {
          if (!disabled) {
            pointerType.current = "mouse";
            settleTo(clamp(defaultValue, min, max));
          }
        }}
        onKeyDown={handleKeyDown}
        onLostPointerCapture={handlePointerUp}
        onPointerCancel={handlePointerUp}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        ref={knobRef}
        role="slider"
        style={{ width: knobSize, height: knobSize }}
        tabIndex={disabled ? -1 : 0}
      >
        {/* Only the indicator turns; the readout stays upright. */}
        <motion.div
          aria-hidden="true"
          className="absolute inset-0"
          style={{ rotate: rotation }}
        >
          <span className="absolute top-2.5 left-1/2 h-3 w-[3px] -translate-x-1/2 rounded-full bg-zinc-900 dark:bg-zinc-100" />
        </motion.div>

        <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center">
          <span
            className="text-xs text-zinc-500 dark:text-zinc-400"
            id={labelId}
          >
            {label}
          </span>
          <RollingValue
            direction={direction}
            reduceMotion={Boolean(reduceMotion)}
            text={formatValue(value)}
          />
        </div>
      </div>
    </div>
  );
}

/**
 * Each character rolls on its own, so going from 21.5 to 22.0 only moves
 * the digits that changed. A touch of blur hides the overlap between the
 * outgoing and incoming glyph.
 */
// `custom` is the signed offset of the latest change. AnimatePresence hands
// the current value to the leaving glyph too, so it always exits opposite to
// the one coming in.
const rollVariants: Variants = {
  // A full transform string rather than `y`, so Motion can hand the roll to
  // the compositor instead of stepping it on the main thread.
  enter: (offset: number) => ({
    opacity: 0,
    transform: `translateY(${offset}px)`,
    filter: offset === 0 ? "blur(0px)" : "blur(2px)",
  }),
  center: { opacity: 1, transform: "translateY(0px)", filter: "blur(0px)" },
  exit: (offset: number) => ({
    opacity: 0,
    transform: `translateY(${-offset}px)`,
    filter: offset === 0 ? "blur(0px)" : "blur(2px)",
  }),
};

function RollingValue({
  text,
  direction,
  reduceMotion,
}: {
  text: string;
  direction: 1 | -1;
  reduceMotion: boolean;
}) {
  const offset = reduceMotion ? 0 : direction * 10;
  return (
    <span
      aria-hidden="true"
      className="relative flex font-medium text-3xl text-zinc-900 tabular-nums tracking-tight dark:text-zinc-100"
    >
      {text.split("").map((char, index) => (
        <span
          className="relative inline-flex overflow-hidden"
          // Position is the identity: the same slot keeps its node.
          // biome-ignore lint/suspicious/noArrayIndexKey: characters are positional.
          key={index}
        >
          <AnimatePresence custom={offset} initial={false} mode="popLayout">
            <motion.span
              animate="center"
              custom={offset}
              exit="exit"
              initial="enter"
              key={char}
              transition={{ duration: 0.16, ease: EASE_OUT }}
              variants={rollVariants}
            >
              {char}
            </motion.span>
          </AnimatePresence>
        </span>
      ))}
    </span>
  );
}

// biome-ignore-all lint/suspicious/noBitwiseOperators: the noise hash is bit arithmetic.
"use client";

/**
 * @author: @dorianbaffier
 * @description: Dot Field
 * @version: 1.0.0
 * @date: 2026-10-14
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import { type ReactNode, useEffect, useRef } from "react";
import { cn } from "@/lib/utils";

export interface DotFieldProps {
  className?: string;
  /** Content shown over the field. Pass `null` for a bare background. */
  children?: ReactNode;
  /** Distance between dots, in px. */
  spacing?: number;
  /** Let a swipe push the dots and a click send a shockwave. */
  interactive?: boolean;
  /** Seed for the halftone pattern, so a page always opens on the same one. */
  seed?: number;
}

// Width of a light or dark patch in the idle halftone, in px.
const NOISE_SCALE = 240;
// How fast the halftone pattern drifts through time.
const NOISE_SPEED = 0.07;
// The noise is sampled on every third dot and blended in between.
const TONE_STEP = 3;
// The idle drift is slow; a frame every 33ms is plenty for it.
const IDLE_FRAME_MS = 33;
// The membrane. Each dot is pulled back to its rest point (ANCHOR), towards
// its four neighbours (COUPLING, which makes a disturbance travel as a wave)
// and loses speed to DAMPING. Units are per second squared.
const ANCHOR = 26;
const COUPLING = 340;
const DAMPING = 2.4;
// Physics runs in fixed steps so the springs behave the same at any refresh
// rate.
const STEP = 1 / 120;
// The pointer: radius it reaches (px), how much of its velocity it hands to
// the dots it passes (per second), and the fastest swipe it counts (px/s).
const POINTER_RADIUS = 72;
const POINTER_GAIN = 14;
const POINTER_MAX_SPEED = 2600;
// Share of the swipe speed that also pushes dots sideways, out of its path,
// so the wake opens into a V like water behind a boat.
const POINTER_PART = 0.45;
// A click: how fast the ring travels (px/s), how thick it is (px), how hard
// it shoves (px/s²) and how long it lives (s).
const SHOCK_SPEED = 620;
const SHOCK_WIDTH = 34;
const SHOCK_FORCE = 5200;
const SHOCK_LIFE = 1.3;
// Squeezed dots grow and stretched ones shrink, so the wake reads as a band
// of darker and lighter tone, like ink in a halftone print.
const COMPRESSION_GAIN = 3;
// Dot sizes are snapped to this many steps; each step is one path.
const BUCKETS = 10;
// Below these the field counts as settled and the physics sleeps.
const REST_SPEED = 2;
const REST_OFFSET = 0.15;

interface Shock {
  x: number;
  y: number;
  age: number;
}

interface Pointer {
  x: number;
  y: number;
  lastX: number;
  lastY: number;
  inside: boolean;
}

/** Seeded 3D gradient noise (Ken Perlin's improved noise), about -1 to 1. */
function createNoise(seed: number) {
  const p = Array.from({ length: 256 }, (_, i) => i);
  let state = seed >>> 0 || 1;
  const random = () => {
    state = (state * 1_664_525 + 1_013_904_223) >>> 0;
    return state / 4_294_967_296;
  };
  for (let i = 255; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [p[i], p[j]] = [p[j], p[i]];
  }
  const perm = new Uint8Array(512);
  for (let i = 0; i < 512; i++) {
    perm[i] = p[i & 255];
  }
  const fade = (t: number) => t * t * t * (t * (t * 6 - 15) + 10);
  const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
  const grad = (hash: number, x: number, y: number, z: number) => {
    const h = hash & 15;
    const u = h < 8 ? x : y;
    let v = z;
    if (h < 4) {
      v = y;
    } else if (h === 12 || h === 14) {
      v = x;
    }
    return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v);
  };

  return (x: number, y: number, z: number) => {
    const X = Math.floor(x) & 255;
    const Y = Math.floor(y) & 255;
    const Z = Math.floor(z) & 255;
    const fx = x - Math.floor(x);
    const fy = y - Math.floor(y);
    const fz = z - Math.floor(z);
    const u = fade(fx);
    const v = fade(fy);
    const w = fade(fz);
    const A = perm[X] + Y;
    const AA = perm[A] + Z;
    const AB = perm[A + 1] + Z;
    const B = perm[X + 1] + Y;
    const BA = perm[B] + Z;
    const BB = perm[B + 1] + Z;
    return lerp(
      lerp(
        lerp(grad(perm[AA], fx, fy, fz), grad(perm[BA], fx - 1, fy, fz), u),
        lerp(
          grad(perm[AB], fx, fy - 1, fz),
          grad(perm[BB], fx - 1, fy - 1, fz),
          u
        ),
        v
      ),
      lerp(
        lerp(
          grad(perm[AA + 1], fx, fy, fz - 1),
          grad(perm[BA + 1], fx - 1, fy, fz - 1),
          u
        ),
        lerp(
          grad(perm[AB + 1], fx, fy - 1, fz - 1),
          grad(perm[BB + 1], fx - 1, fy - 1, fz - 1),
          u
        ),
        v
      ),
      w
    );
  };
}

/** The grid of dots and the state of every spring, in flat arrays. */
interface Field {
  cols: number;
  rows: number;
  spacing: number;
  originX: number;
  originY: number;
  /** Idle size of each dot from the noise, 0 to 1. */
  tone: Float32Array;
  /** The noise on a coarser grid, blended into `tone`. */
  coarse: Float32Array;
  ox: Float32Array;
  oy: Float32Array;
  vx: Float32Array;
  vy: Float32Array;
  ax: Float32Array;
  ay: Float32Array;
}

function createField(width: number, height: number, spacing: number): Field {
  // One extra dot past each edge, so the membrane has no visible border.
  const cols = Math.ceil(width / spacing) + 3;
  const rows = Math.ceil(height / spacing) + 3;
  const size = cols * rows;
  return {
    cols,
    rows,
    spacing,
    originX: (width - (cols - 1) * spacing) / 2,
    originY: (height - (rows - 1) * spacing) / 2,
    tone: new Float32Array(size),
    coarse: new Float32Array(
      (Math.ceil((cols - 1) / TONE_STEP) + 1) *
        (Math.ceil((rows - 1) / TONE_STEP) + 1)
    ),
    ox: new Float32Array(size),
    oy: new Float32Array(size),
    vx: new Float32Array(size),
    vy: new Float32Array(size),
    ax: new Float32Array(size),
    ay: new Float32Array(size),
  };
}

/**
 * The idle halftone. The noise is smooth over a few hundred px, so it is
 * sampled on every TONE_STEP-th dot and blended in between, which costs a
 * ninth of sampling every dot.
 */
function sampleTone(
  field: Field,
  noise: (x: number, y: number, z: number) => number,
  time: number
) {
  const { cols, rows, spacing, originX, originY, tone, coarse } = field;
  const z = time * NOISE_SPEED;
  const step = spacing * TONE_STEP;
  const coarseCols = Math.ceil((cols - 1) / TONE_STEP) + 1;
  const coarseRows = Math.ceil((rows - 1) / TONE_STEP) + 1;
  for (let j = 0; j < coarseRows; j++) {
    const ny = (originY + j * step) / NOISE_SCALE;
    for (let i = 0; i < coarseCols; i++) {
      const nx = (originX + i * step) / NOISE_SCALE;
      const n =
        noise(nx, ny, z) * 0.75 +
        noise(nx * 2.1 + 9.3, ny * 2.1 + 3.7, z * 1.3) * 0.25;
      coarse[j * coarseCols + i] = Math.min(1, Math.max(0, 0.5 + n * 1.1));
    }
  }
  for (let j = 0; j < rows; j++) {
    const cj = Math.min(Math.floor(j / TONE_STEP), coarseRows - 2);
    const fy = j / TONE_STEP - cj;
    for (let i = 0; i < cols; i++) {
      const ci = Math.min(Math.floor(i / TONE_STEP), coarseCols - 2);
      const fx = i / TONE_STEP - ci;
      const a = cj * coarseCols + ci;
      const top = coarse[a] + (coarse[a + 1] - coarse[a]) * fx;
      const bottom =
        coarse[a + coarseCols] +
        (coarse[a + coarseCols + 1] - coarse[a + coarseCols]) * fx;
      tone[j * cols + i] = top + (bottom - top) * fy;
    }
  }
}

/** Sum of the four neighbours; past the border counts as a still dot. */
function neighbours(
  values: Float32Array,
  field: Field,
  i: number,
  j: number
): number {
  const { cols, rows } = field;
  const k = j * cols + i;
  let sum = 0;
  if (i > 0) {
    sum += values[k - 1];
  }
  if (i < cols - 1) {
    sum += values[k + 1];
  }
  if (j > 0) {
    sum += values[k - cols];
  }
  if (j < rows - 1) {
    sum += values[k + cols];
  }
  return sum;
}

/** Spring force on every dot: back to rest, towards neighbours, damping. */
function accelerate(field: Field) {
  const { cols, rows, ox, oy, vx, vy, ax, ay } = field;
  for (let j = 0; j < rows; j++) {
    for (let i = 0; i < cols; i++) {
      const k = j * cols + i;
      const sx = neighbours(ox, field, i, j);
      const sy = neighbours(oy, field, i, j);
      ax[k] += -ANCHOR * ox[k] + COUPLING * (sx - 4 * ox[k]) - DAMPING * vx[k];
      ay[k] += -ANCHOR * oy[k] + COUPLING * (sy - 4 * oy[k]) - DAMPING * vy[k];
    }
  }
}

/** A ring travelling out from each click, shoving the dots it crosses. */
function applyShocks(field: Field, shocks: Shock[]) {
  const { cols, rows, spacing, originX, originY, ax, ay } = field;
  for (const shock of shocks) {
    const reach = shock.age * SHOCK_SPEED;
    const fade = 1 - shock.age / SHOCK_LIFE;
    const force = SHOCK_FORCE * fade * fade;
    const outer = reach + SHOCK_WIDTH;
    const inner = Math.max(0, reach - SHOCK_WIDTH);
    // Only the rows and columns the ring's box touches.
    const i0 = Math.max(0, Math.floor((shock.x - outer - originX) / spacing));
    const i1 = Math.min(
      cols - 1,
      Math.ceil((shock.x + outer - originX) / spacing)
    );
    const j0 = Math.max(0, Math.floor((shock.y - outer - originY) / spacing));
    const j1 = Math.min(
      rows - 1,
      Math.ceil((shock.y + outer - originY) / spacing)
    );
    for (let j = j0; j <= j1; j++) {
      const dy = originY + j * spacing - shock.y;
      for (let i = i0; i <= i1; i++) {
        const dx = originX + i * spacing - shock.x;
        const dist = Math.hypot(dx, dy);
        if (dist < inner || dist > outer || dist === 0) {
          continue;
        }
        const band = 1 - Math.abs(dist - reach) / SHOCK_WIDTH;
        const k = j * cols + i;
        ax[k] += (dx / dist) * force * band;
        ay[k] += (dy / dist) * force * band;
      }
    }
  }
}

/**
 * The pointer hands part of its velocity to the dots near the path it took
 * since the last frame. A slow drift barely stirs them; a fast swipe drags
 * a strip of the membrane along, and the springs turn that into a wake.
 */
function applyPointer(field: Field, pointer: Pointer, dt: number) {
  const segX = pointer.x - pointer.lastX;
  const segY = pointer.y - pointer.lastY;
  pointer.lastX = pointer.x;
  pointer.lastY = pointer.y;
  const length = Math.hypot(segX, segY);
  if (!pointer.inside || length < 0.5 || dt <= 0) {
    return false;
  }
  const speed = Math.min(length / dt, POINTER_MAX_SPEED);
  const pvx = (segX / length) * speed;
  const pvy = (segY / length) * speed;
  const { cols, rows, spacing, originX, originY, vx, vy } = field;
  const startX = pointer.x - segX;
  const startY = pointer.y - segY;
  const minX = Math.min(startX, pointer.x) - POINTER_RADIUS;
  const maxX = Math.max(startX, pointer.x) + POINTER_RADIUS;
  const minY = Math.min(startY, pointer.y) - POINTER_RADIUS;
  const maxY = Math.max(startY, pointer.y) + POINTER_RADIUS;
  const i0 = Math.max(0, Math.floor((minX - originX) / spacing));
  const i1 = Math.min(cols - 1, Math.ceil((maxX - originX) / spacing));
  const j0 = Math.max(0, Math.floor((minY - originY) / spacing));
  const j1 = Math.min(rows - 1, Math.ceil((maxY - originY) / spacing));
  const lengthSq = length * length;
  const gain = Math.min(1, POINTER_GAIN * dt);
  for (let j = j0; j <= j1; j++) {
    const py = originY + j * spacing;
    for (let i = i0; i <= i1; i++) {
      const px = originX + i * spacing;
      // Distance from the dot to the swipe segment.
      const t = Math.min(
        1,
        Math.max(0, ((px - startX) * segX + (py - startY) * segY) / lengthSq)
      );
      const awayX = px - startX - segX * t;
      const awayY = py - startY - segY * t;
      const dist = Math.hypot(awayX, awayY);
      if (dist >= POINTER_RADIUS) {
        continue;
      }
      const falloff = 1 - dist / POINTER_RADIUS;
      const k = j * cols + i;
      const amount = gain * falloff * falloff;
      const side = dist > 0 ? (speed * POINTER_PART) / dist : 0;
      vx[k] += (pvx + awayX * side - vx[k]) * amount;
      vy[k] += (pvy + awayY * side - vy[k]) * amount;
    }
  }
  return true;
}

/** One fixed physics step. Returns whether anything is still moving. */
function integrate(field: Field, shocks: Shock[], h: number) {
  const { ox, oy, vx, vy, ax, ay } = field;
  ax.fill(0);
  ay.fill(0);
  applyShocks(field, shocks);
  accelerate(field);
  let moving = false;
  for (let k = 0; k < ox.length; k++) {
    vx[k] += ax[k] * h;
    vy[k] += ay[k] * h;
    ox[k] += vx[k] * h;
    oy[k] += vy[k] * h;
    if (
      !moving &&
      (Math.abs(vx[k]) > REST_SPEED ||
        Math.abs(vy[k]) > REST_SPEED ||
        Math.abs(ox[k]) > REST_OFFSET ||
        Math.abs(oy[k]) > REST_OFFSET)
    ) {
      moving = true;
    }
  }
  return moving;
}

/** How much the membrane is squeezed (+) or stretched (-) at one dot. */
function compression(field: Field, i: number, j: number) {
  const { cols, rows, spacing, ox, oy } = field;
  const k = j * cols + i;
  const left = i > 0 ? ox[k - 1] : 0;
  const right = i < cols - 1 ? ox[k + 1] : 0;
  const up = j > 0 ? oy[k - cols] : 0;
  const down = j < rows - 1 ? oy[k + cols] : 0;
  return -(right - left + down - up) / (2 * spacing);
}

/**
 * Draw every dot. Sizes are snapped to a few steps and each step is one
 * path, so the whole field is a handful of fills instead of thousands.
 */
function draw(
  ctx: CanvasRenderingContext2D,
  field: Field,
  size: { width: number; height: number; color: string },
  moving: boolean
) {
  const { cols, rows, spacing, originX, originY, tone, ox, oy } = field;
  const maxRadius = spacing * 0.42;
  const paths = Array.from({ length: BUCKETS }, () => new Path2D());
  const filled = new Uint8Array(BUCKETS);
  for (let j = 0; j < rows; j++) {
    for (let i = 0; i < cols; i++) {
      const k = j * cols + i;
      let amount = 0.12 + 0.6 * tone[k];
      if (moving) {
        amount *= 1 + COMPRESSION_GAIN * compression(field, i, j);
      }
      const bucket = Math.round(
        Math.min(1, Math.max(0, amount)) * (BUCKETS - 1)
      );
      if (bucket === 0) {
        continue;
      }
      const radius = (maxRadius * bucket) / (BUCKETS - 1);
      const x = originX + i * spacing + ox[k];
      const y = originY + j * spacing + oy[k];
      const path = paths[bucket];
      path.moveTo(x + radius, y);
      path.arc(x, y, radius, 0, Math.PI * 2);
      filled[bucket] = 1;
    }
  }
  ctx.clearRect(0, 0, size.width, size.height);
  ctx.fillStyle = size.color;
  for (let b = 1; b < BUCKETS; b++) {
    if (filled[b]) {
      // Larger dots are a touch more opaque, which deepens the tone range.
      ctx.globalAlpha = 0.2 + (0.32 * b) / (BUCKETS - 1);
      ctx.fill(paths[b]);
    }
  }
  ctx.globalAlpha = 1;
}

export default function DotField({
  className,
  children,
  spacing = 16,
  interactive = true,
  seed = 7,
}: DotFieldProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    if (!(root && canvas && ctx)) {
      return;
    }

    const reduceMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    const noise = createNoise(seed);
    const gap = Math.max(6, spacing);
    const size = { width: 0, height: 0, color: "" };
    let field = createField(0, 0, gap);

    const pointer: Pointer = {
      x: 0,
      y: 0,
      lastX: 0,
      lastY: 0,
      inside: false,
    };
    const shocks: Shock[] = [];
    let time = 0;
    let last = 0;
    let lastTone = 0;
    let carry = 0;
    // What the last physics step found. Frames shorter than STEP (144Hz
    // screens) run no step, so they go by this rather than settle early.
    let stirring = false;
    let awake = false;
    let raf = 0;
    let visible = true;

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      size.width = rect.width;
      size.height = rect.height;
      canvas.width = Math.round(size.width * dpr);
      canvas.height = Math.round(size.height * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      size.color = getComputedStyle(canvas).color;
      field = createField(size.width, size.height, gap);
      sampleTone(field, noise, time);
      awake = false;
    };

    const physics = (dt: number) => {
      const pushed = applyPointer(field, pointer, dt);
      carry = Math.min(carry + dt, STEP * 6);
      while (carry >= STEP) {
        carry -= STEP;
        for (const shock of shocks) {
          shock.age += STEP;
        }
        while (shocks.length > 0 && shocks[0].age > SHOCK_LIFE) {
          shocks.shift();
        }
        stirring = integrate(field, shocks, STEP);
      }
      if (!(pushed || stirring || shocks.length > 0)) {
        // Settled: put every dot exactly home and let the physics sleep.
        field.ox.fill(0);
        field.oy.fill(0);
        field.vx.fill(0);
        field.vy.fill(0);
        awake = false;
      }
    };

    const frame = (now: number) => {
      raf = 0;
      if (!visible) {
        return;
      }
      const dt = last ? Math.min((now - last) / 1000, 0.05) : 0;
      last = now;
      time += dt;
      const wasAwake = awake;
      if (awake) {
        physics(dt);
      }
      const toneDue = now - lastTone >= IDLE_FRAME_MS;
      if (toneDue) {
        sampleTone(field, noise, time);
        lastTone = now;
      }
      // The drift alone gets about 30 frames a second; a wake gets every one.
      if (wasAwake || toneDue) {
        draw(ctx, field, size, wasAwake);
      }
      raf = requestAnimationFrame(frame);
    };

    const start = () => {
      if (!raf && visible && !reduceMotion) {
        last = 0;
        raf = requestAnimationFrame(frame);
      }
    };

    const wake = () => {
      if (!awake) {
        awake = true;
        carry = 0;
        stirring = true;
      }
      start();
    };

    resize();
    draw(ctx, field, size, false);
    canvas.style.opacity = "1";
    start();

    const redraw = () => {
      resize();
      draw(ctx, field, size, false);
    };
    const resizeObserver = new ResizeObserver(redraw);
    resizeObserver.observe(canvas);

    // Moving the window to a screen with another pixel ratio doesn't resize
    // the canvas, so watch the ratio too or the dots go soft.
    let dprQuery: MediaQueryList | null = null;
    const watchDpr = () => {
      dprQuery?.removeEventListener("change", onDpr);
      dprQuery = window.matchMedia(
        `(resolution: ${window.devicePixelRatio}dppx)`
      );
      dprQuery.addEventListener("change", onDpr);
    };
    const onDpr = () => {
      redraw();
      watchDpr();
    };
    watchDpr();

    // Stop drawing entirely while the field is scrolled away or the tab is
    // in the background.
    let onScreen = true;
    const updateVisible = () => {
      visible = onScreen && document.visibilityState === "visible";
      if (visible) {
        start();
      }
    };
    const intersection = new IntersectionObserver(([entry]) => {
      onScreen = entry.isIntersecting;
      updateVisible();
    });
    intersection.observe(root);
    document.addEventListener("visibilitychange", updateVisible);

    // Follow light and dark mode without asking the app for a theme. Only
    // checked while the field is on screen.
    const colorTimer = window.setInterval(() => {
      if (!visible) {
        return;
      }
      const next = getComputedStyle(canvas).color;
      if (next !== size.color) {
        size.color = next;
        if (reduceMotion) {
          draw(ctx, field, size, false);
        }
      }
    }, 500);

    const local = (event: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      return { x: event.clientX - rect.left, y: event.clientY - rect.top };
    };
    const onMove = (event: PointerEvent) => {
      const point = local(event);
      if (!pointer.inside) {
        // Start from where the pointer came in, not where it last left.
        pointer.lastX = point.x;
        pointer.lastY = point.y;
        pointer.inside = true;
      }
      pointer.x = point.x;
      pointer.y = point.y;
      if (
        Math.abs(pointer.x - pointer.lastX) > 0.5 ||
        Math.abs(pointer.y - pointer.lastY) > 0.5
      ) {
        wake();
      }
    };
    const onLeave = () => {
      pointer.inside = false;
    };
    const onDown = (event: PointerEvent) => {
      // Clicks on the content (links, buttons) are not meant for the field,
      // and neither are right or middle clicks.
      if (
        event.button !== 0 ||
        (event.target as HTMLElement).closest(
          "a, button, input, textarea, select, label, [role='button']"
        )
      ) {
        return;
      }
      const point = local(event);
      pointer.x = point.x;
      pointer.y = point.y;
      pointer.lastX = point.x;
      pointer.lastY = point.y;
      pointer.inside = true;
      shocks.push({ ...point, age: 0 });
      if (shocks.length > 3) {
        shocks.shift();
      }
      wake();
    };
    if (interactive && !reduceMotion) {
      root.addEventListener("pointermove", onMove);
      root.addEventListener("pointerleave", onLeave);
      root.addEventListener("pointerdown", onDown);
    }

    return () => {
      cancelAnimationFrame(raf);
      resizeObserver.disconnect();
      dprQuery?.removeEventListener("change", onDpr);
      intersection.disconnect();
      document.removeEventListener("visibilitychange", updateVisible);
      window.clearInterval(colorTimer);
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerleave", onLeave);
      root.removeEventListener("pointerdown", onDown);
    };
  }, [spacing, interactive, seed]);

  return (
    <div
      className={cn(
        "relative flex min-h-[560px] w-full items-center justify-center overflow-hidden bg-white text-zinc-900 dark:bg-zinc-950 dark:text-zinc-100",
        className
      )}
      ref={rootRef}
    >
      {/* Faded out at the edges so the field sits into the page around it. */}
      <div aria-hidden="true" className="pointer-events-none absolute inset-0">
        <canvas
          className="h-full w-full opacity-0 transition-opacity duration-500 ease-out"
          ref={canvasRef}
          style={{
            // Fade at the edges, and quieter in the middle where the
            // content usually sits so text stays easy to read.
            maskImage:
              "radial-gradient(ellipse 75% 70% at 50% 50%, #000 40%, transparent 100%), radial-gradient(ellipse 34% 22% at 50% 50%, rgb(0 0 0 / 0.35), #000 100%)",
            maskComposite: "intersect",
          }}
        />
      </div>
      {children === undefined ? <DefaultContent /> : children}
    </div>
  );
}

function DefaultContent() {
  return (
    <div className="relative flex max-w-xl flex-col items-center gap-4 px-6 text-center">
      <h1 className="font-semibold text-4xl tracking-tight sm:text-5xl">
        Leave a mark
      </h1>
      <p className="max-w-sm text-base text-zinc-500 dark:text-zinc-400">
        A halftone membrane. Swipe fast to leave a wake, click to send a
        shockwave through it.
      </p>
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Drape Background
 * @version: 1.0.0
 * @date: 2026-10-14
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import { type ReactNode, useEffect, useRef } from "react";
import { cn } from "@/lib/utils";

export interface DrapeBackgroundProps {
  className?: string;
  /** Content shown over the curtain. Pass `null` for a bare background. */
  children?: ReactNode;
  /** Strength of the breeze. 0 lets the curtain hang still. */
  wind?: number;
  /** Depth of the pleats along the top, in px. */
  pleat?: number;
  /** Push the fabric with the cursor and grab it to drag it around. */
  interactive?: boolean;
}

// Simulation, in px and seconds, stepped at a fixed rate so it behaves the
// same at any refresh rate.
const STEP = 1 / 60;
const GRAVITY = 980;
const DAMPING = 0.986;
const ITERATIONS = 4;
// Roughly this many columns across the surface, never finer than MIN_CELL.
const COLUMNS = 46;
const MIN_CELL = 16;
// The top edge is gathered onto a rod: pins sit closer than the cloth
// between them, and the slack falls into folds.
const GATHER = 0.8;
const PLEAT_PERIOD = 4;
// How far the hand reaches into the cloth, and how hard it pushes.
const HAND_RADIUS = 120;
const HAND_PUSH = 7;
const HAND_DRAG = 2.4;
// Stiffness of the skip-one links that keep folds round instead of creased.
const BEND = 0.35;
// Perspective: distance from the eye to the screen plane, in px.
const FOCAL = 1400;
// Below this much movement per step, with no wind, the cloth is asleep.
const REST = 0.02;

interface Cloth {
  cols: number;
  rows: number;
  rest: number;
  pos: Float32Array;
  prev: Float32Array;
  pinned: Uint8Array;
  pins: Float32Array;
  links: Uint32Array;
  lengths: Float32Array;
  stiffness: Float32Array;
}

/**
 * Links between neighbours hold the weave; skip-one links give it a little
 * body, so it folds in curves instead of creasing.
 */
function createLinks(cols: number, rows: number, rest: number) {
  const links: number[] = [];
  const lengths: number[] = [];
  const stiffness: number[] = [];
  const link = (a: number, b: number, length: number, stiff: number) => {
    links.push(a, b);
    lengths.push(length);
    stiffness.push(stiff);
  };
  for (let j = 0; j < rows; j++) {
    for (let i = 0; i < cols; i++) {
      const a = j * cols + i;
      if (i + 1 < cols && j > 0) {
        link(a, a + 1, rest, 1);
      }
      if (j + 1 < rows) {
        link(a, a + cols, rest, 1);
      }
      if (i + 2 < cols && j > 0) {
        link(a, a + 2, rest * 2, BEND);
      }
      if (j + 2 < rows) {
        link(a, a + cols * 2, rest * 2, BEND);
      }
    }
  }
  return { links, lengths, stiffness };
}

function createCloth(width: number, height: number, pleat: number): Cloth {
  const rest = Math.max(MIN_CELL, (width * 1.16) / COLUMNS / GATHER);
  const spacing = rest * GATHER;
  const cols = Math.ceil((width * 1.16) / spacing) + 1;
  const rows = Math.ceil((height * 1.12) / rest) + 1;
  const left = (width - (cols - 1) * spacing) / 2;
  const top = -rest * 0.5;
  const count = cols * rows;
  const pos = new Float32Array(count * 3);
  const pinned = new Uint8Array(count);
  const pins = new Float32Array(cols * 3);

  // Folds a little uneven, as a hand-gathered curtain hangs.
  const folds = Array.from({ length: cols }, (_, i) => {
    let phase = 0;
    for (let c = 0; c < i; c++) {
      phase += ((Math.PI * 2) / PLEAT_PERIOD) * (1 + 0.3 * Math.sin(c * 0.9));
    }
    return pleat * Math.sin(phase) * (0.8 + 0.2 * Math.cos(i * 0.37));
  });
  for (let j = 0; j < rows; j++) {
    for (let i = 0; i < cols; i++) {
      const k = (j * cols + i) * 3;
      const z = folds[i];
      pos[k] = left + i * spacing;
      pos[k + 1] = top + j * rest;
      pos[k + 2] = z;
      if (j === 0) {
        pinned[i] = 1;
        pins.set([pos[k], pos[k + 1], z], i * 3);
      }
    }
  }

  const { links, lengths, stiffness } = createLinks(cols, rows, rest);

  return {
    cols,
    rows,
    rest,
    pos,
    prev: pos.slice(),
    pinned,
    pins,
    links: Uint32Array.from(links),
    lengths: Float32Array.from(lengths),
    stiffness: Float32Array.from(stiffness),
  };
}

interface Forces {
  time: number;
  wind: number;
  hand: { x: number; y: number; vx: number; vy: number; on: boolean };
  grab: { index: number; x: number; y: number } | null;
}

const accel: [number, number, number] = [0, 0, 0];

/** Gravity, the breeze and the hand, acting on a point at (x, y). */
function accelerate(x: number, y: number, forces: Forces) {
  const { time, wind, hand } = forces;
  accel[0] = 0;
  accel[1] = GRAVITY;
  accel[2] = 0;
  if (wind > 0) {
    // Gusts: slow sine waves that roll across the curtain and swell.
    const gust =
      Math.sin(x * 0.006 + time * 0.9) * 0.6 +
      Math.sin(x * 0.013 - time * 1.7 + y * 0.004) * 0.4;
    const swell = 0.6 + 0.4 * Math.sin(time * 0.35);
    accel[2] += gust * swell * wind * 260 * (y / 600);
    accel[0] += Math.sin(time * 0.5 + y * 0.003) * wind * 30;
  }
  if (hand.on) {
    const dx = x - hand.x;
    const dy = y - hand.y;
    const d2 = dx * dx + dy * dy;
    if (d2 < HAND_RADIUS * HAND_RADIUS) {
      const fall = 1 - Math.sqrt(d2) / HAND_RADIUS;
      const f = fall * fall;
      // Press the fabric back, and drag it a little along with the hand.
      accel[2] += f * HAND_PUSH * 1000;
      accel[0] += f * hand.vx * HAND_DRAG * 60;
      accel[1] += f * hand.vy * HAND_DRAG * 60;
    }
  }
  return accel;
}

/** Verlet step: move every free point under its forces. */
function integrate(cloth: Cloth, forces: Forces) {
  const { pos, prev, pinned } = cloth;
  const dt2 = STEP * STEP;
  let motion = 0;
  for (let n = 0; n < pinned.length; n++) {
    if (pinned[n]) {
      continue;
    }
    const k = n * 3;
    const x = pos[k];
    const y = pos[k + 1];
    const z = pos[k + 2];
    const [ax, ay, az] = accelerate(x, y, forces);
    const vx = (x - prev[k]) * DAMPING;
    const vy = (y - prev[k + 1]) * DAMPING;
    const vz = (z - prev[k + 2]) * DAMPING;
    prev[k] = x;
    prev[k + 1] = y;
    prev[k + 2] = z;
    pos[k] = x + vx + ax * dt2;
    pos[k + 1] = y + vy + ay * dt2;
    pos[k + 2] = z + vz + az * dt2;
    motion += Math.abs(vx) + Math.abs(vy) + Math.abs(vz);
  }
  return motion / pinned.length;
}

function relax(cloth: Cloth, grab: Forces["grab"]) {
  const { pos, pinned, links, lengths, stiffness, pins } = cloth;
  for (let it = 0; it < ITERATIONS; it++) {
    for (let l = 0; l < lengths.length; l++) {
      const a = links[l * 2];
      const b = links[l * 2 + 1];
      const ka = a * 3;
      const kb = b * 3;
      const dx = pos[kb] - pos[ka];
      const dy = pos[kb + 1] - pos[ka + 1];
      const dz = pos[kb + 2] - pos[ka + 2];
      const d = Math.sqrt(dx * dx + dy * dy + dz * dz) || 1;
      const diff = (d - lengths[l]) / d;
      // Bend links only resist being squeezed, so folds stay soft.
      if (stiffness[l] < 1 && diff > 0) {
        continue;
      }
      // Pinned points don't move; links between two pins aren't made.
      const wa = 1 - pinned[a];
      const wb = 1 - pinned[b];
      const s = (diff * stiffness[l]) / (wa + wb);
      pos[ka] += dx * s * wa;
      pos[ka + 1] += dy * s * wa;
      pos[ka + 2] += dz * s * wa;
      pos[kb] -= dx * s * wb;
      pos[kb + 1] -= dy * s * wb;
      pos[kb + 2] -= dz * s * wb;
    }
    if (grab) {
      const k = grab.index * 3;
      pos[k] = grab.x;
      pos[k + 1] = grab.y;
    }
    for (let i = 0; i < cloth.cols; i++) {
      pos.set(pins.subarray(i * 3, i * 3 + 3), i * 3);
    }
  }
}

/** Interleaved position and normal for every point, for the GPU. */
function writeVertices(cloth: Cloth, out: Float32Array) {
  const { cols, rows, pos } = cloth;
  for (let j = 0; j < rows; j++) {
    for (let i = 0; i < cols; i++) {
      const n = j * cols + i;
      const l = (j * cols + Math.max(i - 1, 0)) * 3;
      const r = (j * cols + Math.min(i + 1, cols - 1)) * 3;
      const u = (Math.max(j - 1, 0) * cols + i) * 3;
      const d = (Math.min(j + 1, rows - 1) * cols + i) * 3;
      const ax = pos[r] - pos[l];
      const ay = pos[r + 1] - pos[l + 1];
      const az = pos[r + 2] - pos[l + 2];
      const bx = pos[d] - pos[u];
      const by = pos[d + 1] - pos[u + 1];
      const bz = pos[d + 2] - pos[u + 2];
      // Down × across points out of the screen, towards the viewer.
      let nx = by * az - bz * ay;
      let ny = bz * ax - bx * az;
      let nz = bx * ay - by * ax;
      const len = Math.sqrt(nx * nx + ny * ny + nz * nz) || 1;
      nx /= len;
      ny /= len;
      nz /= len;
      const o = n * 6;
      out[o] = pos[n * 3];
      out[o + 1] = pos[n * 3 + 1];
      out[o + 2] = pos[n * 3 + 2];
      out[o + 3] = nx;
      out[o + 4] = ny;
      out[o + 5] = nz;
    }
  }
}

const VERTEX = `
attribute vec3 aPos;
attribute vec3 aNormal;
uniform vec2 uSize;
uniform float uFocal;
varying vec3 vNormal;
void main() {
  float s = uFocal / (uFocal + aPos.z);
  vec2 p = uSize * 0.5 + (aPos.xy - uSize * 0.5) * s;
  gl_Position = vec4(p.x / uSize.x * 2.0 - 1.0, 1.0 - p.y / uSize.y * 2.0, clamp(aPos.z / 4000.0, -1.0, 1.0), 1.0);
  vNormal = aNormal;
}`;

// Soft wrapped light from the top left and a satin sheen, blended between
// two theme colors so the curtain sits in the page in light and dark mode.
const FRAGMENT = `
precision mediump float;
uniform vec3 uLit;
uniform vec3 uShade;
varying vec3 vNormal;
void main() {
  vec3 n = normalize(vNormal);
  if (n.z > 0.0) n = -n;
  vec3 light = normalize(vec3(-0.45, -0.55, -0.7));
  float diffuse = max(dot(n, light), 0.0);
  float wrap = diffuse * 0.8 + 0.2;
  float sheen = pow(max(dot(reflect(-light, n), vec3(0.0, 0.0, -1.0)), 0.0), 18.0);
  float t = clamp(wrap * wrap + sheen * 0.15, 0.0, 1.0);
  gl_FragColor = vec4(mix(uShade, uLit, t), 1.0);
}`;

function compile(gl: WebGLRenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) {
    return null;
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  return shader;
}

function createRenderer(gl: WebGLRenderingContext) {
  const program = gl.createProgram();
  const vs = compile(gl, gl.VERTEX_SHADER, VERTEX);
  const fs = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT);
  if (!(program && vs && fs)) {
    return null;
  }
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    return null;
  }
  // biome-ignore lint/correctness/useHookAtTopLevel: a WebGL call, not a React hook.
  gl.useProgram(program);
  const vertexBuffer = gl.createBuffer();
  const indexBuffer = gl.createBuffer();
  const aPos = gl.getAttribLocation(program, "aPos");
  const aNormal = gl.getAttribLocation(program, "aNormal");
  gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
  gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
  gl.enableVertexAttribArray(aPos);
  gl.enableVertexAttribArray(aNormal);
  gl.vertexAttribPointer(aPos, 3, gl.FLOAT, false, 24, 0);
  gl.vertexAttribPointer(aNormal, 3, gl.FLOAT, false, 24, 12);
  gl.enable(gl.DEPTH_TEST);
  gl.depthFunc(gl.LEQUAL);
  return {
    uSize: gl.getUniformLocation(program, "uSize"),
    uFocal: gl.getUniformLocation(program, "uFocal"),
    uLit: gl.getUniformLocation(program, "uLit"),
    uShade: gl.getUniformLocation(program, "uShade"),
    setMesh(cols: number, rows: number) {
      const indices = new Uint16Array((cols - 1) * (rows - 1) * 6);
      let o = 0;
      for (let j = 0; j < rows - 1; j++) {
        for (let i = 0; i < cols - 1; i++) {
          const a = j * cols + i;
          indices.set([a, a + 1, a + cols, a + 1, a + cols + 1, a + cols], o);
          o += 6;
        }
      }
      gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, indices, gl.STATIC_DRAW);
      return indices.length;
    },
    destroy() {
      gl.deleteBuffer(vertexBuffer);
      gl.deleteBuffer(indexBuffer);
      gl.deleteProgram(program);
      gl.deleteShader(vs);
      gl.deleteShader(fs);
    },
  };
}

/** Any CSS color (oklch included) as 0-1 RGB, via a 1px canvas. */
function toRgb(color: string, probe: CanvasRenderingContext2D) {
  probe.clearRect(0, 0, 1, 1);
  probe.fillStyle = color;
  probe.fillRect(0, 0, 1, 1);
  const [r, g, b] = probe.getImageData(0, 0, 1, 1).data;
  return [r / 255, g / 255, b / 255] as const;
}

export default function DrapeBackground({
  className,
  children,
  wind = 1,
  pleat = 34,
  interactive = true,
}: DrapeBackgroundProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const litRef = useRef<HTMLSpanElement>(null);
  const shadeRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    const gl = canvas?.getContext("webgl", { antialias: true });
    const probe = document
      .createElement("canvas")
      .getContext("2d", { willReadFrequently: true });
    if (!(root && canvas && gl && probe)) {
      return;
    }
    const renderer = createRenderer(gl);
    if (!renderer) {
      return;
    }

    const reduceMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    const forces: Forces = {
      time: 0,
      wind: reduceMotion ? 0 : wind,
      hand: { x: 0, y: 0, vx: 0, vy: 0, on: false },
      grab: null,
    };

    let width = 0;
    let height = 0;
    let cloth: Cloth | null = null;
    let vertices = new Float32Array(0);
    let indexCount = 0;
    let raf = 0;
    let last = 0;
    let carry = 0;
    let quiet = 0;
    let visible = true;
    let colorKey = "";

    const readColors = () => {
      const lit = getComputedStyle(litRef.current as Element).color;
      const shade = getComputedStyle(shadeRef.current as Element).color;
      if (`${lit}|${shade}` === colorKey) {
        return false;
      }
      colorKey = `${lit}|${shade}`;
      gl.uniform3fv(renderer.uLit, toRgb(lit, probe));
      gl.uniform3fv(renderer.uShade, toRgb(shade, probe));
      return true;
    };

    const draw = () => {
      if (!cloth) {
        return;
      }
      writeVertices(cloth, vertices);
      gl.bufferData(gl.ARRAY_BUFFER, vertices, gl.DYNAMIC_DRAW);
      // biome-ignore lint/suspicious/noBitwiseOperators: WebGL clear flags.
      gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
      gl.drawElements(gl.TRIANGLES, indexCount, gl.UNSIGNED_SHORT, 0);
    };

    const build = () => {
      const rect = canvas.getBoundingClientRect();
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      width = rect.width;
      height = rect.height;
      if (width < 2 || height < 2) {
        return;
      }
      canvas.width = Math.round(width * dpr);
      canvas.height = Math.round(height * dpr);
      gl.viewport(0, 0, canvas.width, canvas.height);
      gl.uniform2f(renderer.uSize, width, height);
      gl.uniform1f(renderer.uFocal, FOCAL);
      cloth = createCloth(width, height, pleat);
      vertices = new Float32Array(cloth.cols * cloth.rows * 6);
      indexCount = renderer.setMesh(cloth.cols, cloth.rows);
      // Let it fall and settle before the first frame, so it opens hanging.
      const settleForces = { ...forces, hand: { ...forces.hand, on: false } };
      for (let i = 0; i < 180; i++) {
        settleForces.time = forces.time + i * STEP;
        integrate(cloth, settleForces);
        relax(cloth, null);
      }
      draw();
    };

    const frame = (now: number) => {
      raf = 0;
      if (!(visible && cloth)) {
        return;
      }
      carry += last ? Math.min((now - last) / 1000, 0.1) : STEP;
      last = now;
      let moved = 0;
      let steps = 0;
      while (carry >= STEP && steps < 3) {
        forces.time += STEP;
        moved = integrate(cloth, forces);
        relax(cloth, forces.grab);
        carry -= STEP;
        steps++;
      }
      carry = Math.min(carry, STEP);
      forces.hand.vx *= 0.8;
      forces.hand.vy *= 0.8;
      draw();
      quiet = moved < REST ? quiet + 1 : 0;
      const awake =
        forces.wind > 0 || forces.hand.on || forces.grab || quiet < 30;
      if (awake) {
        raf = requestAnimationFrame(frame);
      }
    };

    const start = () => {
      if (!raf && visible && !reduceMotion) {
        last = 0;
        quiet = 0;
        raf = requestAnimationFrame(frame);
      }
    };

    readColors();
    gl.clearColor(0, 0, 0, 0);
    build();
    canvas.style.opacity = "1";
    start();

    const resizeObserver = new ResizeObserver(() => {
      build();
      start();
    });
    resizeObserver.observe(canvas);

    // A tab coming back must not wake a background that's scrolled away.
    let onScreen = true;
    const intersection = new IntersectionObserver(([entry]) => {
      onScreen = entry.isIntersecting;
      visible = onScreen && document.visibilityState === "visible";
      start();
    });
    intersection.observe(root);
    const onVisibility = () => {
      visible = onScreen && document.visibilityState === "visible";
      start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    // Follow light and dark mode without asking the app for a theme. Only
    // checked while the background is on screen.
    const colorTimer = window.setInterval(() => {
      if (!visible) {
        return;
      }
      if (readColors() && !raf) {
        draw();
      }
    }, 500);

    const local = (event: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      return { x: event.clientX - rect.left, y: event.clientY - rect.top };
    };

    /** The point drawn nearest the pointer, within reach. */
    const nearest = (x: number, y: number) => {
      if (!cloth) {
        return -1;
      }
      let best = -1;
      let bestD = 70 * 70;
      for (let n = cloth.cols; n < cloth.pinned.length; n++) {
        const k = n * 3;
        const s = FOCAL / (FOCAL + cloth.pos[k + 2]);
        const px = width / 2 + (cloth.pos[k] - width / 2) * s;
        const py = height / 2 + (cloth.pos[k + 1] - height / 2) * s;
        const d = (px - x) ** 2 + (py - y) ** 2;
        if (d < bestD) {
          bestD = d;
          best = n;
        }
      }
      return best;
    };

    const onMove = (event: PointerEvent) => {
      const p = local(event);
      const hand = forces.hand;
      if (forces.grab) {
        forces.grab.x = p.x;
        forces.grab.y = p.y;
      } else if (event.pointerType === "mouse") {
        if (hand.on) {
          hand.vx = hand.vx * 0.5 + (p.x - hand.x) * 0.5;
          hand.vy = hand.vy * 0.5 + (p.y - hand.y) * 0.5;
        }
        hand.on = true;
      }
      hand.x = p.x;
      hand.y = p.y;
      start();
    };
    const onLeave = () => {
      forces.hand.on = false;
    };
    const onDown = (event: PointerEvent) => {
      // Clicks on the content (links, buttons) are not meant for the cloth.
      if ((event.target as HTMLElement).closest("a, button, input, textarea")) {
        return;
      }
      const p = local(event);
      const index = nearest(p.x, p.y);
      if (index < 0) {
        return;
      }
      event.preventDefault();
      root.setPointerCapture(event.pointerId);
      forces.grab = { index, ...p };
      forces.hand.on = false;
      root.dataset.grabbing = "";
      start();
    };
    const onUp = () => {
      forces.grab = null;
      delete root.dataset.grabbing;
    };
    if (interactive && !reduceMotion) {
      root.addEventListener("pointermove", onMove);
      root.addEventListener("pointerleave", onLeave);
      root.addEventListener("pointerdown", onDown);
      root.addEventListener("pointerup", onUp);
      root.addEventListener("pointercancel", onUp);
    }

    return () => {
      cancelAnimationFrame(raf);
      resizeObserver.disconnect();
      intersection.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      window.clearInterval(colorTimer);
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerleave", onLeave);
      root.removeEventListener("pointerdown", onDown);
      root.removeEventListener("pointerup", onUp);
      root.removeEventListener("pointercancel", onUp);
      renderer.destroy();
    };
  }, [wind, pleat, interactive]);

  return (
    <div
      className={cn(
        "relative flex min-h-[560px] w-full touch-pan-y items-center justify-center overflow-hidden bg-zinc-100 text-zinc-900 data-[grabbing]:cursor-grabbing dark:bg-zinc-950 dark:text-zinc-100",
        className
      )}
      ref={rootRef}
    >
      {/* Theme colors for the shader: the lit face and the deepest fold. */}
      <span className="hidden text-white dark:text-zinc-800" ref={litRef} />
      <span className="hidden text-zinc-300 dark:text-black" ref={shadeRef} />
      <div aria-hidden="true" className="pointer-events-none absolute inset-0">
        <canvas
          className="h-full w-full opacity-0 transition-opacity duration-700 ease-out"
          ref={canvasRef}
        />
      </div>
      {children === undefined ? <DefaultContent /> : children}
    </div>
  );
}

function DefaultContent() {
  return (
    <div className="pointer-events-none relative flex max-w-xl flex-col items-center gap-4 px-6 text-center">
      <h1 className="font-semibold text-4xl tracking-tight sm:text-5xl">
        Behind the curtain
      </h1>
      <p className="max-w-sm text-base text-zinc-500 dark:text-zinc-400">
        A pleated curtain in a light breeze. Sweep the cursor through it, or
        grab a fold and pull.
      </p>
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Dynamic Text. Morphing text where letters are physical
 * objects: shared letters travel to their new place on a spring arc, leaving
 * letters fall off the baseline, entering letters drop in and land, and digits
 * roll like a counter. Also has a `decode` mode (cells scramble and lock left
 * to right) and a `cycle` mode (the greeting rhythm).
 * @version: 2.0.0
 * @date: 2026-10-14
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import {
  type RefObject,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

export interface Greeting {
  text: string;
  /** BCP 47 language tag, so screen readers pronounce each word correctly. */
  lang?: string;
}

export type DynamicTextMode = "morph" | "decode" | "cycle";

export interface DynamicTextProps {
  /**
   * `morph`: letters travel, fall and land. `decode`: monospace cells scramble
   * and lock left to right. `cycle`: morphs through `words` with a greeting
   * rhythm (a long first word, faster middle words, a hold on the last).
   */
  mode?: DynamicTextMode;
  /** The string to show. Change it to animate. When set, `words` is ignored. */
  text?: string;
  /** Words to rotate through when `text` is not set. */
  words?: (string | Greeting)[];
  /**
   * Milliseconds each word holds. In `cycle` mode this is the first word's
   * hold; the middle words speed up from there.
   */
  interval?: number;
  /** Start over after the last word. Defaults to true, except in `cycle`. */
  loop?: boolean;
  /** Called once the last word is shown. Never called when looping. */
  onComplete?: () => void;
  className?: string;
}

const MORPH_WORDS = ["Create", "Iterate", "Repeat", "Ship"];
const DECODE_WORDS = ["Hello, world", "Build 4096 ready", "All systems go"];
const GREETINGS: Greeting[] = [
  { text: "Hello", lang: "en" },
  { text: "こんにちは", lang: "ja" },
  { text: "Bonjour", lang: "fr" },
  { text: "Hola", lang: "es" },
  { text: "안녕하세요", lang: "ko" },
  { text: "Ciao", lang: "it" },
  { text: "Hallo", lang: "de" },
  { text: "Hello", lang: "en" },
];

const DEFAULT_WORDS: Record<DynamicTextMode, (string | Greeting)[]> = {
  morph: MORPH_WORDS,
  decode: DECODE_WORDS,
  cycle: GREETINGS,
};
const DEFAULT_INTERVAL: Record<DynamicTextMode, number> = {
  morph: 2200,
  decode: 2800,
  cycle: 900,
};

/* Text helpers ---------------------------------------------------------- */

const segmenter =
  typeof Intl !== "undefined" && "Segmenter" in Intl
    ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
    : null;

/** Splits into user-perceived characters, so emoji and Hangul stay whole. */
function splitGraphemes(value: string): string[] {
  return segmenter
    ? Array.from(segmenter.segment(value), (s) => s.segment)
    : Array.from(value);
}

const isDigit = (char: string) => char >= "0" && char <= "9";
const isBlank = (char: string) => char.trim() === "";
const clamp01 = (n: number) => Math.min(1, Math.max(0, n));

function toGreeting(word: string | Greeting): Greeting {
  return typeof word === "string" ? { text: word } : word;
}

/** How long word `index` of `count` holds before the next one. */
function holdFor(
  mode: DynamicTextMode,
  index: number,
  count: number,
  interval: number
) {
  if (mode !== "cycle") {
    return interval;
  }
  if (index === 0) {
    return interval;
  }
  if (index === count - 1) {
    return interval * 2;
  }
  // The middle words accelerate, like someone getting into the rhythm.
  return Math.max(90, interval * 0.36 * 0.8 ** (index - 1));
}

function useReducedMotionRef() {
  const ref = useRef(false);
  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => {
      ref.current = query.matches;
    };
    sync();
    query.addEventListener("change", sync);
    return () => query.removeEventListener("change", sync);
  }, []);
  return ref;
}

/** True while the element is on screen and the tab is visible. */
function useRunning(ref: RefObject<HTMLElement | null>) {
  const [running, setRunning] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) {
      return;
    }
    let inView = false;
    const sync = () =>
      setRunning(inView && document.visibilityState === "visible");
    const observer = new IntersectionObserver((entries) => {
      inView = entries.some((e) => e.isIntersecting);
      sync();
    });
    observer.observe(el);
    document.addEventListener("visibilitychange", sync);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", sync);
    };
  }, [ref]);
  return running;
}

/* Morph physics --------------------------------------------------------- */

type Phase = "rest" | "travel" | "drop" | "fall" | "roll" | "fade";

interface Glyph {
  id: number;
  char: string;
  digit: boolean;
  /** Digit position counted from the right, so prices roll like counters. */
  slot: number;
  el: HTMLSpanElement | null;
  phase: Phase;
  leaving: boolean;
  delay: number;
  x: number;
  vx: number;
  tx: number;
  x0: number;
  arc: number;
  y: number;
  vy: number;
  ty: number;
  r: number;
  vr: number;
  tr: number;
  sq: number;
  vsq: number;
  o: number;
}

interface Token {
  char: string;
  x: number;
  digit: boolean;
  slot: number;
}

interface GlyphView {
  id: number;
  char: string;
}

const STEP = 1 / 120;
const damping = (k: number, zeta: number) => 2 * zeta * Math.sqrt(k);
const TRAVEL_K = 140;
const TRAVEL_C = damping(TRAVEL_K, 0.8);
const LIFT_K = 300;
const LIFT_C = damping(LIFT_K, 0.9);
const ROLL_K = 200;
const ROLL_C = damping(ROLL_K, 0.86);
const SQUASH_K = 1400;
const SQUASH_C = damping(SQUASH_K, 0.6);
const TILT_K = 140;
const TILT_C = damping(TILT_K, 0.7);
const WIDTH_K = 220;
const WIDTH_C = damping(WIDTH_K, 1);
/** Distances below are in em, so the motion scales with the font. */
const GRAVITY = 32;
const DROP = 0.7;
const FALL_FADE = 0.9;
const ROLL = 0.75;
const LAND_SQUASH = -0.16;
const ENTER_STAGGER = 0.035;
/** Long strings share this much stagger, so the last letter isn't late. */
const MAX_ENTER_SPREAD = 0.45;
const FADE_RATE = 7;

function paint(g: Glyph) {
  if (!g.el) {
    return;
  }
  const sy = 1 + g.sq;
  const sx = 1 - g.sq * 0.6;
  g.el.style.transform = `translate3d(${g.x.toFixed(2)}px, ${g.y.toFixed(2)}px, 0) rotate(${g.r.toFixed(2)}deg) scale(${sx.toFixed(3)}, ${sy.toFixed(3)})`;
  g.el.style.opacity = g.o.toFixed(3);
}

function stepSquash(g: Glyph, h: number) {
  if (g.sq === 0 && g.vsq === 0) {
    return;
  }
  g.vsq += (-SQUASH_K * g.sq - SQUASH_C * g.vsq) * h;
  g.sq += g.vsq * h;
  if (Math.abs(g.sq) < 0.001 && Math.abs(g.vsq) < 0.01) {
    g.sq = 0;
    g.vsq = 0;
  }
}

function stepTravel(g: Glyph, h: number) {
  // Lift along a shallow arc that peaks halfway, so crossing letters pass
  // over and under each other instead of through.
  const span = Math.abs(g.tx - g.x0);
  const p = span < 0.5 ? 1 : clamp01(1 - Math.abs(g.tx - g.x) / span);
  g.ty = g.arc * 4 * p * (1 - p);
  g.vx += (-TRAVEL_K * (g.x - g.tx) - TRAVEL_C * g.vx) * h;
  g.x += g.vx * h;
  g.vy += (-LIFT_K * (g.y - g.ty) - LIFT_C * g.vy) * h;
  g.y += g.vy * h;
  g.o = Math.min(1, g.o + FADE_RATE * h);
}

function stepDrop(g: Glyph, h: number, em: number) {
  g.vy += GRAVITY * em * h;
  g.y += g.vy * h;
  if (g.y >= 0) {
    // Landing: one squash, then the spring takes it back.
    g.y = 0;
    g.vy = 0;
    g.sq = LAND_SQUASH;
    g.phase = "rest";
  }
  g.o = clamp01(1 + g.y / (DROP * em));
}

function stepFall(g: Glyph, h: number, em: number) {
  g.vy += GRAVITY * em * h;
  g.y += g.vy * h;
  g.x += g.vx * h;
  g.vr += (-TILT_K * (g.r - g.tr) - TILT_C * g.vr) * h;
  g.r += g.vr * h;
  g.o = Math.min(g.o, clamp01(1 - g.y / (FALL_FADE * em)));
}

function stepRoll(g: Glyph, h: number, em: number) {
  g.vy += (-ROLL_K * (g.y - g.ty) - ROLL_C * g.vy) * h;
  g.y += g.vy * h;
  g.o = clamp01(1 - Math.abs(g.y) / (ROLL * em));
}

function stepFade(g: Glyph, h: number) {
  g.o = clamp01(g.o + (g.leaving ? -FADE_RATE : FADE_RATE) * h);
}

function stepGlyph(g: Glyph, h: number, em: number) {
  switch (g.phase) {
    case "travel":
      stepTravel(g, h);
      break;
    case "drop":
      stepDrop(g, h, em);
      break;
    case "fall":
      stepFall(g, h, em);
      break;
    case "roll":
      stepRoll(g, h, em);
      break;
    case "fade":
      stepFade(g, h);
      break;
    default:
      break;
  }
  stepSquash(g, h);
}

const isGone = (g: Glyph) => g.leaving && g.o <= 0.002;

/** Moves a glyph into rest once it has arrived. Returns true while moving. */
function settle(g: Glyph): boolean {
  if (g.leaving) {
    return !isGone(g);
  }
  const arrived =
    Math.abs(g.x - g.tx) < 0.05 &&
    Math.abs(g.vx) < 0.5 &&
    Math.abs(g.y) < 0.05 &&
    Math.abs(g.vy) < 0.5;
  const done =
    (g.phase === "travel" && arrived) ||
    (g.phase === "roll" && arrived) ||
    (g.phase === "fade" && g.o >= 1);
  if (done) {
    g.x = g.tx;
    g.y = 0;
    g.vx = 0;
    g.vy = 0;
    g.o = 1;
    g.phase = "rest";
  }
  return g.phase !== "rest" || g.sq !== 0;
}

/** Direction digits roll: 1 when the number grew (old goes up, new comes up). */
function rollDirection(previous: Glyph[], tokens: Token[]) {
  const before = Number(
    previous
      .filter((g) => g.digit)
      .map((g) => g.char)
      .join("")
  );
  const after = Number(
    tokens
      .filter((t) => t.digit)
      .map((t) => t.char)
      .join("")
  );
  return after < before ? -1 : 1;
}

/** Squeezes the entering stagger so a long string doesn't trickle in. */
function capStagger(glyphs: Glyph[], entering: number) {
  const spread = entering * ENTER_STAGGER;
  if (spread <= MAX_ENTER_SPREAD) {
    return;
  }
  for (const g of glyphs) {
    g.delay *= MAX_ENTER_SPREAD / spread;
  }
}

class MorphEngine {
  glyphs: Glyph[] = [];
  /** The glyphs that spell the current text, in order. */
  order: Glyph[] = [];
  root: HTMLSpanElement | null = null;
  onChange: (() => void) | null = null;
  reduced = false;
  started = false;
  em = 16;
  w = 0;
  vw = 0;
  tw = 0;
  private nextId = 0;
  private raf = 0;
  private last = 0;
  private readonly refs = new Map<
    number,
    (el: HTMLSpanElement | null) => void
  >();

  views(): GlyphView[] {
    return this.glyphs.map((g) => ({ id: g.id, char: g.char }));
  }

  refFor(id: number) {
    let ref = this.refs.get(id);
    if (!ref) {
      ref = (el: HTMLSpanElement | null) => {
        const glyph = this.glyphs.find((g) => g.id === id);
        if (glyph) {
          glyph.el = el;
          paint(glyph);
        }
      };
      this.refs.set(id, ref);
    }
    return ref;
  }

  private create(t: Token): Glyph {
    const glyph: Glyph = {
      id: this.nextId++,
      char: t.char,
      digit: t.digit,
      slot: t.slot,
      el: null,
      phase: "rest",
      leaving: false,
      delay: 0,
      x: t.x,
      vx: 0,
      tx: t.x,
      x0: t.x,
      arc: 0,
      y: 0,
      vy: 0,
      ty: 0,
      r: 0,
      vr: 0,
      tr: 0,
      sq: 0,
      vsq: 0,
      o: 1,
    };
    this.glyphs.push(glyph);
    return glyph;
  }

  private move(g: Glyph, t: Token, instant: boolean) {
    g.slot = t.slot;
    g.tx = t.x;
    if (instant) {
      g.x = t.x;
      g.y = 0;
      g.vx = 0;
      g.vy = 0;
      g.phase = g.o < 1 ? "fade" : "rest";
      return;
    }
    if (g.phase === "rest" && Math.abs(t.x - g.x) < 0.5) {
      g.x = t.x;
      return;
    }
    // Redirects keep the current position and velocity: no restart.
    g.x0 = g.x;
    g.delay = 0;
    const distance = t.x - g.x;
    g.arc =
      -Math.sign(distance) *
      Math.min(0.22 * this.em, Math.abs(distance) * 0.14);
    g.phase = "travel";
  }

  private enter(g: Glyph, dir: number, instant: boolean, index: number) {
    g.o = 0;
    if (instant) {
      g.phase = "fade";
      return;
    }
    if (g.digit) {
      g.y = dir * ROLL * this.em;
      g.ty = 0;
      g.phase = "roll";
      return;
    }
    g.y = -DROP * this.em;
    g.phase = "drop";
    g.delay = index * ENTER_STAGGER;
  }

  private leave(g: Glyph, dir: number, instant: boolean) {
    g.leaving = true;
    g.delay = 0;
    if (instant) {
      g.phase = "fade";
      return;
    }
    if (g.digit) {
      g.phase = "roll";
      g.ty = -dir * ROLL * 1.2 * this.em;
      return;
    }
    // Tip toward the side it sits on, 5-15°, and drift that way a little.
    const side = g.x + this.em * 0.3 < this.tw / 2 ? -1 : 1;
    g.tr = side * (5 + ((g.id * 7) % 11));
    g.vx = side * 0.4 * this.em;
    g.vy = Math.max(g.vy, 0);
    g.phase = "fall";
  }

  /** Re-places the current text after a resize or a font load. */
  place(tokens: Token[], width: number) {
    if (tokens.length !== this.order.length) {
      return;
    }
    tokens.forEach((t, i) => {
      const g = this.order[i];
      if (g) {
        g.tx = t.x;
        if (g.phase === "rest") {
          g.x = t.x;
          paint(g);
        }
      }
    });
    this.tw = width;
    if (!this.raf) {
      this.w = width;
      this.paintWidth();
    }
  }

  update(tokens: Token[], width: number) {
    if (!this.started) {
      // First paint: put everything in place, no animation.
      this.started = true;
      this.order = tokens.map((t) => this.create(t));
      this.w = width;
      this.tw = width;
      this.paintWidth();
      return;
    }
    const instant = this.reduced;
    const letters = new Map<string, Glyph[]>();
    const slots = new Map<number, Glyph>();
    for (const g of this.order) {
      if (g.digit) {
        slots.set(g.slot, g);
      } else {
        letters.set(g.char, [...(letters.get(g.char) ?? []), g]);
      }
    }
    const dir = rollDirection(this.order, tokens);
    const next: Glyph[] = [];
    let entering = 0;
    for (const t of tokens) {
      let old: Glyph | undefined;
      if (t.digit) {
        old = slots.get(t.slot);
        slots.delete(t.slot);
      } else {
        old = letters.get(t.char)?.shift();
      }
      if (old && old.char === t.char) {
        this.move(old, t, instant);
        next.push(old);
        continue;
      }
      if (old) {
        this.leave(old, dir, instant);
      }
      const g = this.create(t);
      this.enter(g, dir, instant, entering++);
      next.push(g);
    }
    capStagger(next, entering);
    for (const list of letters.values()) {
      for (const g of list) {
        this.leave(g, dir, instant);
      }
    }
    for (const g of slots.values()) {
      this.leave(g, dir, instant);
    }
    this.order = next;
    this.tw = width;
    if (instant) {
      this.w = width;
      this.vw = 0;
      this.paintWidth();
    }
  }

  private paintWidth() {
    if (this.root) {
      this.root.style.width = `${this.w.toFixed(2)}px`;
    }
  }

  private stepWidth(dt: number) {
    if (Math.abs(this.w - this.tw) < 0.1 && Math.abs(this.vw) < 0.1) {
      if (this.w !== this.tw) {
        this.w = this.tw;
        this.vw = 0;
        this.paintWidth();
      }
      return false;
    }
    let t = dt;
    while (t > 1e-6) {
      const h = Math.min(STEP, t);
      this.vw += (-WIDTH_K * (this.w - this.tw) - WIDTH_C * this.vw) * h;
      this.w += this.vw * h;
      t -= h;
    }
    this.paintWidth();
    return true;
  }

  private stepAll(dt: number) {
    let moving = false;
    for (const g of this.glyphs) {
      if (g.delay > 0) {
        g.delay -= dt;
        moving = true;
        continue;
      }
      let t = dt;
      while (t > 1e-6) {
        const h = Math.min(STEP, t);
        stepGlyph(g, h, this.em);
        t -= h;
      }
      if (settle(g)) {
        moving = true;
      }
      paint(g);
    }
    return moving;
  }

  private readonly tick = (now: number) => {
    const dt = this.last ? Math.min(0.05, (now - this.last) / 1000) : 1 / 60;
    this.last = now;
    const moving = this.stepAll(dt);
    const resizing = this.stepWidth(dt);
    if (this.glyphs.some(isGone)) {
      for (const g of this.glyphs) {
        if (isGone(g)) {
          this.refs.delete(g.id);
        }
      }
      this.glyphs = this.glyphs.filter((g) => !isGone(g));
      this.onChange?.();
    }
    // Sleep once everything has settled.
    this.raf = moving || resizing ? requestAnimationFrame(this.tick) : 0;
  };

  kick() {
    if (!this.raf) {
      this.last = 0;
      this.raf = requestAnimationFrame(this.tick);
    }
  }

  stop() {
    cancelAnimationFrame(this.raf);
    this.raf = 0;
  }
}

/** Reads where each character of `text` sits, from the hidden measure row. */
function measureTokens(measure: HTMLElement, text: string) {
  const chars = splitGraphemes(text);
  const cells = measure.children;
  const tokens: Token[] = [];
  chars.forEach((char, i) => {
    const cell = cells[i] as HTMLElement | undefined;
    if (!cell || isBlank(char)) {
      return;
    }
    tokens.push({ char, x: cell.offsetLeft, digit: isDigit(char), slot: 0 });
  });
  let slot = 0;
  for (let i = tokens.length - 1; i >= 0; i--) {
    const t = tokens[i];
    if (t?.digit) {
      t.slot = slot++;
    }
  }
  return { tokens, width: measure.offsetWidth };
}

function MorphLayer({
  text,
  reducedRef,
}: {
  text: string;
  reducedRef: RefObject<boolean>;
}) {
  const chars = splitGraphemes(text);
  const rootRef = useRef<HTMLSpanElement>(null);
  const measureRef = useRef<HTMLSpanElement>(null);
  const engineRef = useRef<MorphEngine | null>(null);
  if (!engineRef.current) {
    engineRef.current = new MorphEngine();
  }
  const engine = engineRef.current;
  // Server and first client render lay the text out in flow; after mount the
  // glyphs switch to absolutely positioned, physics-driven spans.
  const [live, setLive] = useState(false);
  const [views, setViews] = useState<GlyphView[]>([]);

  useLayoutEffect(() => {
    engine.root = rootRef.current;
    engine.onChange = () => setViews(engine.views());
    setLive(true);
    return () => engine.stop();
  }, [engine]);

  useLayoutEffect(() => {
    const root = rootRef.current;
    const measure = measureRef.current;
    if (!(live && root && measure)) {
      return;
    }
    engine.em = Number.parseFloat(getComputedStyle(root).fontSize) || 16;
    engine.reduced = reducedRef.current;
    const { tokens, width } = measureTokens(measure, text);
    engine.update(tokens, width);
    setViews(engine.views());
    engine.kick();
  }, [engine, live, text, reducedRef]);

  // Fonts loading or the font size changing move the letters: re-place them.
  useEffect(() => {
    const root = rootRef.current;
    const measure = measureRef.current;
    if (!(live && root && measure)) {
      return;
    }
    const observer = new ResizeObserver(() => {
      engine.em = Number.parseFloat(getComputedStyle(root).fontSize) || 16;
      const { tokens, width } = measureTokens(measure, text);
      engine.place(tokens, width);
    });
    observer.observe(measure);
    return () => observer.disconnect();
  }, [engine, live, text]);

  return (
    <span className="relative inline-block align-baseline" ref={rootRef}>
      <span
        aria-hidden="true"
        className="pointer-events-none invisible absolute top-0 left-0"
        ref={measureRef}
      >
        {chars.map((char, i) => (
          // biome-ignore lint/suspicious/noArrayIndexKey: characters are positional.
          <span key={i}>{char}</span>
        ))}
      </span>
      {live ? (
        <>
          <span aria-hidden="true" className="inline-block w-0">
            {"​"}
          </span>
          {views.map((view) => (
            <span
              aria-hidden="true"
              className="absolute top-0 left-0 origin-[50%_80%]"
              key={view.id}
              ref={engine.refFor(view.id)}
            >
              {view.char}
            </span>
          ))}
        </>
      ) : (
        <span aria-hidden="true">
          {chars.map((char, i) => (
            // biome-ignore lint/suspicious/noArrayIndexKey: characters are positional.
            <span key={i}>{char}</span>
          ))}
        </span>
      )}
    </span>
  );
}

/* Decode ---------------------------------------------------------------- */

const UPPER = "ABCDEFGHIJKLMNOPQRSTUVWXYZ#%&*+=<>/";
const LOWER = "abcdefghijklmnopqrstuvwxyz#%&*+=<>/";
const DIGITS = "0123456789";
const SWAP_EVERY = 0.05;
const FLASH_FOR = 0.05;

function poolFor(char: string) {
  if (isDigit(char)) {
    return DIGITS;
  }
  return char.toLowerCase() === char ? LOWER : UPPER;
}

const randomFrom = (pool: string) =>
  pool[Math.floor(Math.random() * pool.length)] ?? "";

function writeCell(cell: Element | undefined, char: string) {
  const node = cell?.firstChild;
  if (node && node.nodeValue !== char) {
    node.nodeValue = char;
  }
}

interface DecodeCell {
  el: HTMLElement;
  char: string;
  lockAt: number;
  swapAt: number;
  state: "scramble" | "flash" | "done";
}

function stepCell(cell: DecodeCell, t: number) {
  if (cell.state === "flash") {
    if (t >= cell.lockAt + FLASH_FOR) {
      cell.el.removeAttribute("data-flash");
      cell.state = "done";
    }
    return;
  }
  if (t >= cell.lockAt) {
    writeCell(cell.el, cell.char);
    cell.el.removeAttribute("data-scramble");
    cell.el.setAttribute("data-flash", "");
    cell.state = "flash";
    return;
  }
  if (t >= cell.swapAt) {
    writeCell(cell.el, randomFrom(poolFor(cell.char)));
    cell.swapAt = t + SWAP_EVERY;
  }
}

function DecodeLayer({
  text,
  running,
  reducedRef,
}: {
  text: string;
  running: boolean;
  reducedRef: RefObject<boolean>;
}) {
  const chars = splitGraphemes(text);
  const hostRef = useRef<HTMLSpanElement>(null);
  /** What the cells settled on last time, so only changed cells scramble. */
  const shownRef = useRef<string[] | null>(null);

  useEffect(() => {
    const host = hostRef.current;
    if (!(host && running)) {
      return;
    }
    const next = splitGraphemes(text);
    const previous = shownRef.current;
    shownRef.current = next;
    const els = Array.from(host.children) as HTMLElement[];
    // A previous run may have left scrambled glyphs behind: reset to the text.
    els.forEach((el, i) => {
      writeCell(el, next[i] ?? "");
      el.removeAttribute("data-scramble");
      el.removeAttribute("data-flash");
    });
    const changed = next
      .map((char, i) => ({ char, i }))
      .filter(({ char, i }) => !isBlank(char) && previous?.[i] !== char);
    if (changed.length === 0) {
      return;
    }
    if (reducedRef.current) {
      host.animate([{ opacity: 0 }, { opacity: 1 }], {
        duration: 160,
        easing: "ease-out",
      });
      return;
    }
    const stagger = Math.min(0.05, 0.75 / changed.length);
    const cells: DecodeCell[] = [];
    changed.forEach(({ char, i }, rank) => {
      const el = els[i];
      if (el) {
        el.setAttribute("data-scramble", "");
        cells.push({
          el,
          char,
          lockAt: 0.15 + rank * stagger,
          swapAt: 0,
          state: "scramble",
        });
      }
    });
    // One rAF writes every cell: no React render per tick, no layout shift.
    let raf = 0;
    let start = 0;
    const tick = (now: number) => {
      start ||= now;
      const t = (now - start) / 1000;
      for (const cell of cells) {
        stepCell(cell, t);
      }
      raf = cells.every((c) => c.state === "done")
        ? 0
        : requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      for (const cell of cells) {
        writeCell(cell.el, cell.char);
        cell.el.removeAttribute("data-scramble");
        cell.el.removeAttribute("data-flash");
      }
    };
  }, [text, running, reducedRef]);

  return (
    <span aria-hidden="true" className="font-mono" ref={hostRef}>
      {chars.map((char, i) => (
        <span
          className="inline-block w-[1ch] text-center data-flash:text-(--dynamic-text-accent) data-scramble:opacity-45"
          // biome-ignore lint/suspicious/noArrayIndexKey: cells are positional.
          key={i}
        >
          {char}
        </span>
      ))}
    </span>
  );
}

/* Component ------------------------------------------------------------- */

const DynamicText = ({
  mode = "morph",
  text,
  words,
  interval,
  loop,
  onComplete,
  className,
}: DynamicTextProps) => {
  const list = (words ?? DEFAULT_WORDS[mode]).map(toGreeting);
  const count = list.length;
  const hold = interval ?? DEFAULT_INTERVAL[mode];
  const repeat = loop ?? mode !== "cycle";
  const controlled = text !== undefined;
  const rootRef = useRef<HTMLSpanElement>(null);
  const reducedRef = useReducedMotionRef();
  const running = useRunning(rootRef);
  // Counts every advance; the shown word is derived from it.
  const [step, setStep] = useState(0);
  const index = repeat ? step % Math.max(count, 1) : Math.min(step, count - 1);
  const isLast = index === count - 1;
  const isDone = !(controlled || repeat) && isLast;
  const onCompleteRef = useRef(onComplete);

  useEffect(() => {
    onCompleteRef.current = onComplete;
  }, [onComplete]);

  useEffect(() => {
    if (controlled || isDone || !running || count < 2) {
      return;
    }
    const id = setTimeout(
      () => setStep((s) => s + 1),
      holdFor(mode, index, count, hold)
    );
    return () => clearTimeout(id);
  }, [controlled, isDone, running, count, mode, index, hold]);

  useEffect(() => {
    if (isDone) {
      onCompleteRef.current?.();
    }
  }, [isDone]);

  const current: Greeting = controlled
    ? { text }
    : (list[index] ?? { text: "" });

  return (
    <span
      className={cn(
        "inline-block whitespace-pre tabular-nums [--dynamic-text-accent:var(--color-emerald-600)] dark:[--dynamic-text-accent:var(--color-emerald-400)]",
        className
      )}
      lang={current.lang}
      ref={rootRef}
    >
      {/* Only announce text the app sets; words rotating on their own would
          talk over the reader every couple of seconds. */}
      <span aria-live={controlled ? "polite" : "off"} className="sr-only">
        {current.text}
      </span>
      {mode === "decode" ? (
        <DecodeLayer
          reducedRef={reducedRef}
          running={running}
          text={current.text}
        />
      ) : (
        <MorphLayer reducedRef={reducedRef} text={current.text} />
      )}
    </span>
  );
};

export default DynamicText;

