import { RotateCw, Upload, X } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type ChangeEvent,
  type ClipboardEvent,
  type DragEvent,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

export interface FileError {
  message: string;
  code: string;
}

export interface UploadHelpers {
  /** Report upload progress from 0 to 100. */
  onProgress: (percent: number) => void;
  /** Aborted when the row is removed or the component unmounts. */
  signal: AbortSignal;
}

export interface FileUploadProps {
  /**
   * Uploads one file. Called once per file, a few at a time. Resolve to mark
   * the row done, reject to show the error with a Retry button. When omitted,
   * uploads are simulated over `uploadDelay`.
   */
  onUpload?: (file: File, helpers: UploadHelpers) => Promise<void>;
  onUploadSuccess?: (file: File) => void;
  /** Called for validation errors and failed uploads. */
  onUploadError?: (error: FileError, file: File) => void;
  /** Called with every uploaded file once nothing is queued or in flight. */
  onComplete?: (files: File[]) => void;
  /** Called when a row is removed (cancelling its upload if needed). */
  onFileRemove?: (file: File) => void;
  /** MIME types ("image/png"), wildcards ("image/*") or extensions (".pdf"). */
  acceptedFileTypes?: string[];
  /** Maximum size of each file in bytes. Defaults to 5 MB. */
  maxFileSize?: number;
  /** Accept several files at once. Defaults to true. */
  multiple?: boolean;
  /** Maximum number of files in the list. Defaults to 5. */
  maxFiles?: number;
  /** Simulated upload duration per file in ms, used without `onUpload`. */
  uploadDelay?: number;
  /** Simulated uploads only: the first attempt of every third file fails. */
  simulateFailure?: boolean;
  validateFile?: (file: File) => FileError | null;
  className?: string;
}

type ItemStatus = "queued" | "uploading" | "done" | "error" | "rejected";

interface QueueItem {
  id: string;
  file: File;
  index: number;
  status: ItemStatus;
  progress: number;
  attempts: number;
  error?: FileError;
  previewUrl?: string;
}

const DEFAULT_MAX_FILE_SIZE = 5 * 1024 * 1024;
const CONCURRENCY = 3;
const SIMULATED_TICK = 80;
const EASE_OUT = [0.23, 1, 0.32, 1] as const;
const FILE_SIZES = ["B", "KB", "MB", "GB", "TB"] as const;
// Module constant, so the default does not change identity every render.
const NO_ACCEPTED_TYPES: string[] = [];

const formatBytes = (bytes: number): string => {
  if (!bytes) {
    return "0 B";
  }
  const i = Math.min(
    Math.floor(Math.log(bytes) / Math.log(1024)),
    FILE_SIZES.length - 1
  );
  const value = bytes / 1024 ** i;
  return `${value >= 10 || i === 0 ? Math.round(value) : Number(value.toFixed(1))} ${FILE_SIZES[i]}`;
};

// Accepts exact MIME types ("image/png"), wildcards ("image/*") and
// extensions (".pdf"), like the input's `accept` attribute.
const matchesAcceptedType = (file: File, acceptedType: string): boolean => {
  const accepted = acceptedType.trim().toLowerCase();
  if (!accepted) {
    return false;
  }
  if (accepted.startsWith(".")) {
    return file.name.toLowerCase().endsWith(accepted);
  }
  const fileType = file.type.toLowerCase();
  if (accepted.endsWith("/*")) {
    return fileType.startsWith(accepted.slice(0, -1));
  }
  return fileType === accepted;
};

// ".pdf" -> "PDF", "image/svg+xml" -> "SVG", "image/*" -> "images".
const describeAcceptedType = (acceptedType: string): string => {
  const accepted = acceptedType.trim();
  if (accepted.startsWith(".")) {
    return accepted.slice(1).toUpperCase();
  }
  const [kind = "", subtype = ""] = accepted.split("/");
  if (subtype === "*") {
    return `${kind.toLowerCase()}s`;
  }
  return subtype.split("+")[0].toUpperCase();
};

const describeAcceptedTypes = (acceptedTypes: string[]): string => {
  const labels = acceptedTypes.map(describeAcceptedType).filter(Boolean);
  if (!labels.length) {
    return "Any file";
  }
  const text =
    labels.length > 1
      ? `${labels.slice(0, -1).join(", ")} or ${labels.at(-1)}`
      : labels[0];
  return text.charAt(0).toUpperCase() + text.slice(1);
};

const extensionOf = (name: string): string => {
  const dot = name.lastIndexOf(".");
  if (dot <= 0 || dot === name.length - 1) {
    return "FILE";
  }
  return name
    .slice(dot + 1)
    .slice(0, 4)
    .toUpperCase();
};

const clampProgress = (value: number) => Math.min(Math.max(value, 0), 100);

const isFileDrag = (e: { dataTransfer: DataTransfer | null }) =>
  Boolean(e.dataTransfer?.types.includes("Files"));

const countDraggedFiles = (dataTransfer: DataTransfer): number => {
  let count = 0;
  for (const item of dataTransfer.items) {
    if (item.kind === "file") {
      count += 1;
    }
  }
  return count;
};

// Default upload: advances in uneven steps, like a real network would.
const simulateUpload = (
  { onProgress, signal }: UploadHelpers,
  duration: number,
  shouldFail: boolean
): Promise<void> =>
  new Promise((resolve, reject) => {
    if (duration <= 0) {
      resolve();
      return;
    }
    let progress = 0;
    const interval = setInterval(() => {
      progress = Math.min(
        progress +
          (100 * SIMULATED_TICK * (0.4 + Math.random() * 1.2)) / duration,
        100
      );
      if (shouldFail && progress >= 58) {
        clearInterval(interval);
        reject(new Error("Connection lost"));
        return;
      }
      onProgress(progress);
      if (progress >= 100) {
        clearInterval(interval);
        resolve();
      }
    }, SIMULATED_TICK);
    signal.addEventListener(
      "abort",
      () => {
        clearInterval(interval);
        reject(new DOMException("Upload cancelled", "AbortError"));
      },
      { once: true }
    );
  });

const buildItems = (
  files: File[],
  {
    room,
    validate,
    nextId,
  }: {
    room: number;
    validate: (file: File) => FileError | null;
    nextId: () => { id: string; index: number };
  }
) => {
  const added: QueueItem[] = [];
  let accepted = 0;
  let skipped = 0;
  for (const file of files) {
    const error = validate(file) ?? undefined;
    if (!error && accepted >= room) {
      skipped += 1;
      continue;
    }
    if (!error) {
      accepted += 1;
    }
    const { id, index } = nextId();
    added.push({
      id,
      file,
      index,
      status: error ? "rejected" : "queued",
      progress: 0,
      attempts: 0,
      error,
      previewUrl:
        !error && file.type.startsWith("image/")
          ? URL.createObjectURL(file)
          : undefined,
    });
  }
  return { added, skipped };
};

const summarize = (items: QueueItem[]) => {
  let done = 0;
  let failed = 0;
  let busy = false;
  for (const item of items) {
    if (item.status === "done") {
      done += 1;
    } else if (item.status === "error" || item.status === "rejected") {
      failed += 1;
    } else {
      busy = true;
    }
  }
  return { done, failed, busy };
};

const zoneCopy = ({
  isFull,
  overZone,
  windowDrag,
  multiple,
  limit,
  maxFileSize,
  acceptedFileTypes,
}: {
  isFull: boolean;
  overZone: number;
  windowDrag: boolean;
  multiple: boolean;
  limit: number;
  maxFileSize: number;
  acceptedFileTypes: string[];
}) => {
  const noun = multiple ? "files" : "a file";
  if (isFull) {
    return {
      title: "File limit reached",
      showBrowse: false,
      hint: "Remove a file to add another",
    };
  }
  const sizeHint =
    maxFileSize > 0 && Number.isFinite(maxFileSize)
      ? ` up to ${formatBytes(maxFileSize)}`
      : "";
  const hint = `${describeAcceptedTypes(acceptedFileTypes)}${sizeHint}${multiple ? ` · ${limit} max` : ""}`;
  if (overZone) {
    return {
      title: `Release to add ${overZone} ${overZone === 1 ? "file" : "files"}`,
      showBrowse: false,
      hint,
    };
  }
  if (windowDrag) {
    return { title: `Drop ${noun} here`, showBrowse: false, hint };
  }
  return { title: `Drop ${noun} here or `, showBrowse: true, hint };
};

const FileThumb = ({ item }: { item: QueueItem }) => {
  if (item.previewUrl) {
    return (
      <span
        aria-hidden="true"
        className="size-9 shrink-0 rounded-md bg-center bg-cover bg-zinc-100 ring-1 ring-black/5 ring-inset dark:bg-zinc-800 dark:ring-white/10"
        style={{ backgroundImage: `url("${item.previewUrl}")` }}
      />
    );
  }
  return (
    <span
      aria-hidden="true"
      className="flex size-9 shrink-0 items-center justify-center rounded-md border border-zinc-200 bg-zinc-50 font-medium font-mono text-[9px] text-zinc-500 tracking-wide dark:border-zinc-800 dark:bg-zinc-900 dark:text-zinc-400"
    >
      {extensionOf(item.file.name)}
    </span>
  );
};

const DoneCheck = ({ reduceMotion }: { reduceMotion: boolean | null }) => (
  <svg
    aria-hidden="true"
    className="size-4 text-emerald-600 dark:text-emerald-400"
    fill="none"
    viewBox="0 0 16 16"
  >
    <motion.path
      animate={{ pathLength: 1 }}
      d="M3.5 8.5 6.5 11.5 12.5 4.5"
      initial={{ pathLength: reduceMotion ? 1 : 0 }}
      stroke="currentColor"
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth="1.75"
      transition={{ duration: 0.32, ease: EASE_OUT, delay: 0.05 }}
    />
  </svg>
);

const statusLine = (item: QueueItem): string => {
  switch (item.status) {
    case "queued":
      return "Waiting";
    case "uploading":
      return `${Math.round(item.progress)}%`;
    case "done":
      return "Uploaded";
    case "error":
    case "rejected":
      return item.error?.message ?? "Upload failed";
    default:
      return "";
  }
};

const iconButton =
  "flex size-7 shrink-0 items-center justify-center rounded-md text-zinc-400 outline-none transition-colors duration-150 hover:bg-zinc-100 hover:text-zinc-900 focus-visible:ring-2 focus-visible:ring-zinc-900/20 active:bg-zinc-200 dark:text-zinc-500 dark:active:bg-zinc-700 dark:focus-visible:ring-white/25 dark:hover:bg-zinc-800 dark:hover:text-zinc-100";

const QueueRow = ({
  item,
  reduceMotion,
  onRemove,
  onRetry,
}: {
  item: QueueItem;
  reduceMotion: boolean | null;
  onRemove: (id: string) => void;
  onRetry: (id: string) => void;
}) => {
  const failed = item.status === "error" || item.status === "rejected";
  const inFlight = item.status === "uploading" || item.status === "queued";
  const name = item.file.name;

  return (
    <motion.li
      animate={{ height: "auto", opacity: 1 }}
      className="overflow-hidden"
      exit={{
        height: 0,
        opacity: 0,
        transition: {
          height: { duration: reduceMotion ? 0 : 0.2, ease: EASE_OUT },
          opacity: { duration: 0.12, ease: EASE_OUT },
        },
      }}
      initial={{ height: 0, opacity: 0 }}
      transition={{
        height: reduceMotion
          ? { duration: 0 }
          : { type: "spring", duration: 0.35, bounce: 0 },
        opacity: {
          duration: 0.2,
          ease: EASE_OUT,
          delay: reduceMotion ? 0 : 0.05,
        },
      }}
    >
      <div className="group/row relative flex items-center gap-3 px-1 py-2.5">
        <FileThumb item={item} />

        <div className="min-w-0 flex-1">
          <p className="truncate font-medium text-[13px] text-zinc-900 leading-5 dark:text-zinc-100">
            {name}
          </p>
          <p
            className={cn(
              "truncate text-xs tabular-nums leading-4",
              failed
                ? "text-red-600 dark:text-red-400"
                : "text-zinc-500 dark:text-zinc-400"
            )}
          >
            <span className="text-zinc-500 dark:text-zinc-400">
              {formatBytes(item.file.size)}
            </span>
            <span
              aria-hidden="true"
              className="px-1 text-zinc-300 dark:text-zinc-600"
            >
              ·
            </span>
            {statusLine(item)}
          </p>
        </div>

        <div className="flex shrink-0 items-center gap-1">
          {item.status === "done" && (
            <span className="flex size-7 items-center justify-center">
              <DoneCheck reduceMotion={reduceMotion} />
            </span>
          )}
          {item.status === "error" && (
            <button
              aria-label={`Retry ${name}`}
              className={cn(iconButton, "w-auto gap-1 px-2 text-xs")}
              onClick={() => onRetry(item.id)}
              type="button"
            >
              <RotateCw aria-hidden="true" className="size-3" />
              Retry
            </button>
          )}
          <button
            aria-label={inFlight ? `Cancel ${name}` : `Remove ${name}`}
            className={iconButton}
            onClick={() => onRemove(item.id)}
            type="button"
          >
            <X aria-hidden="true" className="size-3.5" />
          </button>
        </div>

        {/* The row's hairline divider doubles as its progress bar. */}
        <div className="absolute inset-x-1 bottom-0 h-px bg-zinc-100 dark:bg-zinc-800/80">
          <div
            aria-label={`Uploading ${name}`}
            aria-valuemax={100}
            aria-valuemin={0}
            aria-valuenow={Math.round(item.progress)}
            className={cn(
              "h-full origin-left transition-[transform,opacity,background-color] duration-200 ease-linear",
              // A retry starts from zero at once instead of rewinding.
              item.progress === 0 && "transition-none",
              item.status === "done" &&
                "bg-emerald-500 opacity-0 delay-300 duration-300 ease-out dark:bg-emerald-400",
              failed && "bg-red-500 dark:bg-red-400",
              inFlight && "bg-zinc-900 dark:bg-zinc-100"
            )}
            role="progressbar"
            style={{ transform: `scaleX(${item.progress / 100})` }}
          />
        </div>
      </div>
    </motion.li>
  );
};

export default function FileUpload({
  onUpload,
  onUploadSuccess,
  onUploadError,
  onComplete,
  onFileRemove,
  acceptedFileTypes = NO_ACCEPTED_TYPES,
  maxFileSize = DEFAULT_MAX_FILE_SIZE,
  multiple = true,
  maxFiles = 5,
  uploadDelay = 2000,
  simulateFailure = false,
  validateFile,
  className,
}: FileUploadProps) {
  const [items, setItems] = useState<QueueItem[]>([]);
  const [notice, setNotice] = useState<string | null>(null);
  const [windowDrag, setWindowDrag] = useState(false);
  const [overZone, setOverZone] = useState(0);
  const reduceMotion = useReducedMotion();
  const baseId = useId();
  const hintId = `${baseId}-hint`;
  const inputRef = useRef<HTMLInputElement>(null);
  const zoneRef = useRef<HTMLButtonElement>(null);
  const nextIndex = useRef(0);
  const controllers = useRef(new Map<string, AbortController>());
  const previewUrls = useRef(new Map<string, string>());
  const wasBusy = useRef(false);

  // Latest callbacks, read from async upload code without re-running effects.
  const latest = useRef({
    onUpload,
    onUploadSuccess,
    onUploadError,
    onComplete,
    uploadDelay,
    simulateFailure,
  });
  useEffect(() => {
    latest.current = {
      onUpload,
      onUploadSuccess,
      onUploadError,
      onComplete,
      uploadDelay,
      simulateFailure,
    };
  });

  const limit = multiple ? Math.max(1, maxFiles) : 1;
  const counted = items.filter((item) => item.status !== "rejected").length;
  const isFull = counted >= limit;

  const updateItem = useCallback(
    (id: string, patch: Partial<QueueItem>) =>
      setItems((prev) =>
        prev.map((item) => (item.id === id ? { ...item, ...patch } : item))
      ),
    []
  );

  const runUpload = useCallback(
    (item: QueueItem) => {
      const controller = new AbortController();
      controllers.current.set(item.id, controller);
      const { signal } = controller;
      const cb = latest.current;

      const onProgress = (percent: number) => {
        if (!signal.aborted) {
          updateItem(item.id, { progress: clampProgress(percent) });
        }
      };
      const succeed = () => {
        if (signal.aborted) {
          return;
        }
        controllers.current.delete(item.id);
        updateItem(item.id, { status: "done", progress: 100 });
        latest.current.onUploadSuccess?.(item.file);
      };
      const fail = (reason: unknown) => {
        if (signal.aborted) {
          return;
        }
        controllers.current.delete(item.id);
        const error = {
          message:
            reason instanceof Error && reason.message
              ? reason.message
              : "Upload failed",
          code: "UPLOAD_FAILED",
        };
        updateItem(item.id, { status: "error", error });
        latest.current.onUploadError?.(error, item.file);
      };

      if (cb.onUpload) {
        const upload = cb.onUpload;
        Promise.resolve()
          .then(() => upload(item.file, { onProgress, signal }))
          .then(succeed, fail);
        return;
      }
      const shouldFail =
        cb.simulateFailure && item.attempts === 1 && item.index % 3 === 1;
      simulateUpload({ onProgress, signal }, cb.uploadDelay, shouldFail).then(
        succeed,
        fail
      );
    },
    [updateItem]
  );

  // Scheduler: keep up to CONCURRENCY uploads in flight.
  useEffect(() => {
    const active = items.filter((item) => item.status === "uploading").length;
    const toStart = items
      .filter((item) => item.status === "queued")
      .slice(0, Math.max(0, CONCURRENCY - active))
      .filter((item) => !controllers.current.has(item.id))
      .map((item) => ({ ...item, attempts: item.attempts + 1 }));
    if (!toStart.length) {
      return;
    }
    const started = new Map(toStart.map((item) => [item.id, item]));
    setItems((prev) =>
      prev.map((item) => {
        const next = started.get(item.id);
        return next ? { ...next, status: "uploading", progress: 0 } : item;
      })
    );
    for (const item of toStart) {
      runUpload(item);
    }
  }, [items, runUpload]);

  // Settle: report once nothing is queued or in flight.
  useEffect(() => {
    const busy = items.some(
      (item) => item.status === "queued" || item.status === "uploading"
    );
    // Cancelling everything clears the list; that is not a completion.
    if (wasBusy.current && !busy && items.length > 0) {
      latest.current.onComplete?.(
        items.filter((item) => item.status === "done").map((item) => item.file)
      );
    }
    wasBusy.current = busy;
  }, [items]);

  // Abort uploads and free previews on unmount.
  useEffect(() => {
    const ctrl = controllers.current;
    const urls = previewUrls.current;
    return () => {
      for (const controller of ctrl.values()) {
        controller.abort();
      }
      ctrl.clear();
      for (const url of urls.values()) {
        URL.revokeObjectURL(url);
      }
      urls.clear();
    };
  }, []);

  // A file dragged anywhere over the window wakes the drop zone, and a drop
  // that misses it does not make the browser navigate away to the file.
  useEffect(() => {
    let depth = 0;
    const onEnter = (e: globalThis.DragEvent) => {
      if (!isFileDrag(e)) {
        return;
      }
      depth += 1;
      setWindowDrag(true);
    };
    const onLeave = (e: globalThis.DragEvent) => {
      if (!isFileDrag(e)) {
        return;
      }
      depth = Math.max(0, depth - 1);
      if (depth === 0) {
        setWindowDrag(false);
      }
    };
    const onOver = (e: globalThis.DragEvent) => {
      if (isFileDrag(e)) {
        e.preventDefault();
      }
    };
    const onEnd = (e: globalThis.DragEvent) => {
      if (isFileDrag(e)) {
        e.preventDefault();
      }
      depth = 0;
      setWindowDrag(false);
      setOverZone(0);
    };
    window.addEventListener("dragenter", onEnter);
    window.addEventListener("dragleave", onLeave);
    window.addEventListener("dragover", onOver);
    window.addEventListener("drop", onEnd);
    window.addEventListener("dragend", onEnd);
    return () => {
      window.removeEventListener("dragenter", onEnter);
      window.removeEventListener("dragleave", onLeave);
      window.removeEventListener("dragover", onOver);
      window.removeEventListener("drop", onEnd);
      window.removeEventListener("dragend", onEnd);
    };
  }, []);

  const validate = useCallback(
    (file: File): FileError | null => {
      if (
        acceptedFileTypes.length &&
        !acceptedFileTypes.some((type) => matchesAcceptedType(file, type))
      ) {
        return {
          message: `Not ${describeAcceptedTypes(acceptedFileTypes)}`,
          code: "INVALID_FILE_TYPE",
        };
      }
      if (file.size > maxFileSize) {
        return {
          message: `Larger than ${formatBytes(maxFileSize)}`,
          code: "FILE_TOO_LARGE",
        };
      }
      return validateFile?.(file) ?? null;
    },
    [acceptedFileTypes, maxFileSize, validateFile]
  );

  const addFiles = useCallback(
    (fileList: FileList | File[] | null) => {
      const files = Array.from(fileList ?? []);
      if (!files.length) {
        return;
      }
      const { added, skipped } = buildItems(files, {
        room: Math.max(0, limit - counted),
        validate,
        nextId: () => {
          const index = nextIndex.current;
          nextIndex.current += 1;
          return { id: `${baseId}-${index}`, index };
        },
      });
      for (const item of added) {
        if (item.previewUrl) {
          previewUrls.current.set(item.id, item.previewUrl);
        }
        if (item.error) {
          onUploadError?.(item.error, item.file);
        }
      }
      setNotice(
        skipped
          ? `${skipped} ${skipped === 1 ? "file was" : "files were"} not added. The limit is ${limit}.`
          : null
      );
      if (added.length) {
        setItems((prev) => [...prev, ...added]);
      }
    },
    [baseId, counted, limit, onUploadError, validate]
  );

  const removeItem = useCallback(
    (id: string) => {
      controllers.current.get(id)?.abort();
      controllers.current.delete(id);
      const url = previewUrls.current.get(id);
      if (url) {
        URL.revokeObjectURL(url);
        previewUrls.current.delete(id);
      }
      const item = items.find((i) => i.id === id);
      setItems((prev) => prev.filter((i) => i.id !== id));
      setNotice(null);
      if (item) {
        onFileRemove?.(item.file);
      }
    },
    [items, onFileRemove]
  );

  // The clicked button leaves with its row, so focus returns to the drop
  // zone instead of falling back to the page.
  const removeAndRefocus = useCallback(
    (id: string) => {
      removeItem(id);
      zoneRef.current?.focus({ preventScroll: true });
    },
    [removeItem]
  );

  const clearAll = useCallback(() => {
    for (const item of items) {
      removeItem(item.id);
    }
    zoneRef.current?.focus({ preventScroll: true });
  }, [items, removeItem]);

  const retryItem = useCallback(
    (id: string) =>
      updateItem(id, { status: "queued", progress: 0, error: undefined }),
    [updateItem]
  );

  const openPicker = () => {
    if (!isFull) {
      inputRef.current?.click();
    }
  };

  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    addFiles(e.target.files);
    e.target.value = "";
  };

  const handleZoneDrag = (e: DragEvent<HTMLButtonElement>) => {
    if (!isFileDrag(e)) {
      return;
    }
    e.preventDefault();
    e.dataTransfer.dropEffect = isFull ? "none" : "copy";
    setOverZone(Math.max(1, countDraggedFiles(e.dataTransfer)));
  };

  const handleZoneLeave = (e: DragEvent<HTMLButtonElement>) => {
    if (
      e.relatedTarget instanceof Node &&
      e.currentTarget.contains(e.relatedTarget)
    ) {
      return;
    }
    setOverZone(0);
  };

  const handleZoneDrop = (e: DragEvent<HTMLButtonElement>) => {
    e.preventDefault();
    setOverZone(0);
    setWindowDrag(false);
    if (!isFull) {
      addFiles(e.dataTransfer.files);
    }
  };

  const handlePaste = (e: ClipboardEvent<HTMLButtonElement>) => {
    if (e.clipboardData.files.length) {
      e.preventDefault();
      addFiles(e.clipboardData.files);
    }
  };

  const { done, failed, busy } = summarize(items);
  const { title, showBrowse, hint } = zoneCopy({
    isFull,
    overZone,
    windowDrag,
    multiple,
    limit,
    maxFileSize,
    acceptedFileTypes,
  });

  const armed = windowDrag && !isFull;
  const over = overZone > 0 && !isFull;

  return (
    <div
      className={cn(
        "mx-auto w-full max-w-sm rounded-xl border border-zinc-200 bg-white p-2 shadow-xs dark:border-zinc-800 dark:bg-zinc-950",
        className
      )}
    >
      <button
        aria-describedby={hintId}
        aria-disabled={isFull || undefined}
        className={cn(
          "group/zone flex w-full flex-col items-center gap-3 rounded-lg border border-dashed px-4 py-6 text-center outline-none transition-colors duration-150 ease-out",
          "focus-visible:border-zinc-400 focus-visible:ring-2 focus-visible:ring-zinc-900/10 dark:focus-visible:border-zinc-500 dark:focus-visible:ring-white/15",
          isFull
            ? "cursor-not-allowed border-zinc-200 bg-zinc-50/50 dark:border-zinc-800 dark:bg-zinc-900/30"
            : "cursor-pointer border-zinc-300 bg-zinc-50/60 hover:border-zinc-400 hover:bg-zinc-50 active:bg-zinc-100 dark:border-zinc-700 dark:bg-zinc-900/40 dark:active:bg-zinc-900 dark:hover:border-zinc-600 dark:hover:bg-zinc-900/70",
          armed &&
            "border-zinc-500 bg-zinc-50 dark:border-zinc-500 dark:bg-zinc-900/70",
          over &&
            "border-zinc-900 border-solid bg-zinc-100 dark:border-zinc-200 dark:bg-zinc-900"
        )}
        onClick={openPicker}
        onDragEnter={handleZoneDrag}
        onDragLeave={handleZoneLeave}
        onDragOver={handleZoneDrag}
        onDrop={handleZoneDrop}
        onPaste={handlePaste}
        ref={zoneRef}
        type="button"
      >
        <span
          aria-hidden="true"
          className={cn(
            "flex size-9 items-center justify-center rounded-lg border bg-white shadow-xs transition-colors duration-150 dark:bg-zinc-950",
            armed || over
              ? "border-zinc-300 text-zinc-900 dark:border-zinc-600 dark:text-zinc-100"
              : "border-zinc-200 text-zinc-500 dark:border-zinc-800 dark:text-zinc-400"
          )}
        >
          <Upload
            className={cn(
              "size-4 transition-[translate] duration-200 ease-out",
              (armed || over) && "motion-safe:-translate-y-0.5"
            )}
          />
        </span>
        <span className="flex flex-col gap-1">
          <span
            className={cn(
              "font-medium text-sm transition-colors duration-150",
              isFull
                ? "text-zinc-500 dark:text-zinc-400"
                : "text-zinc-900 dark:text-zinc-100"
            )}
          >
            {title}
            {showBrowse && (
              <span className="underline decoration-zinc-300 underline-offset-[3px] transition-colors duration-150 group-hover/zone:decoration-zinc-900 dark:decoration-zinc-600 dark:group-hover/zone:decoration-zinc-100">
                browse
              </span>
            )}
          </span>
          <span
            className="text-xs text-zinc-500 tabular-nums dark:text-zinc-400"
            id={hintId}
          >
            {hint}
          </span>
        </span>
      </button>

      <input
        accept={acceptedFileTypes.join(",") || undefined}
        className="hidden"
        multiple={multiple}
        onChange={handleInputChange}
        ref={inputRef}
        tabIndex={-1}
        type="file"
      />

      {notice && (
        <p
          className="mt-2 px-1 text-red-600 text-xs dark:text-red-400"
          role="alert"
        >
          {notice}
        </p>
      )}

      <ul aria-label="Files" className="mt-1 px-1">
        <AnimatePresence initial={false}>
          {items.map((item) => (
            <QueueRow
              item={item}
              key={item.id}
              onRemove={removeAndRefocus}
              onRetry={retryItem}
              reduceMotion={reduceMotion}
            />
          ))}
        </AnimatePresence>
      </ul>

      <AnimatePresence initial={false}>
        {items.length > 0 && (
          <motion.div
            animate={{ height: "auto", opacity: 1 }}
            className="overflow-hidden"
            exit={{ height: 0, opacity: 0 }}
            initial={{ height: 0, opacity: 0 }}
            transition={{
              duration: reduceMotion ? 0 : 0.2,
              ease: EASE_OUT,
            }}
          >
            <div className="flex items-center justify-between px-2 pt-2 pb-0.5">
              <output
                aria-live="polite"
                className="text-xs text-zinc-500 tabular-nums dark:text-zinc-400"
              >
                <span className="text-zinc-900 dark:text-zinc-100">{done}</span>{" "}
                of {items.length} uploaded
                {failed > 0 && (
                  <span className="text-red-600 dark:text-red-400">
                    {" "}
                    · {failed} failed
                  </span>
                )}
              </output>
              <button
                className="-mr-1 rounded-md px-1.5 py-1 text-xs text-zinc-500 outline-none transition-colors duration-150 hover:text-zinc-900 focus-visible:ring-2 focus-visible:ring-zinc-900/20 active:text-zinc-600 dark:text-zinc-400 dark:active:text-zinc-300 dark:focus-visible:ring-white/25 dark:hover:text-zinc-100"
                onClick={clearAll}
                type="button"
              >
                {busy ? "Cancel all" : "Clear"}
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

FileUpload.displayName = "FileUpload";

// biome-ignore-all lint/suspicious/noBitwiseOperators: the noise hash is bit arithmetic.
"use client";

/**
 * @author: @dorianbaffier
 * @description: Wind. Streamlines that part around the cursor, swirl in its wake and scatter on click.
 * @version: 2.0.0
 * @date: 2026-10-14
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import { type ReactNode, useEffect, useRef } from "react";
import { cn } from "@/lib/utils";

export interface FlowFieldProps {
  className?: string;
  /** Content drawn over the wind, such as a hero's heading. */
  children?: ReactNode;
  /** Multiplies the number of particles (about 700 at 1). */
  density?: number;
  /** How fast the wind blows. 0 holds a still frame. */
  speed?: number;
  /** The cursor parts the streams and stirs a wake; a click sends a gust. */
  interactive?: boolean;
}

// Particles at density 1. Narrow screens get fewer.
const BASE_COUNT = 700;
// Wind speed in px/s at speed 1, and the size of its bends (px).
const WIND = 64;
const NOISE_SCALE = 340;
// How far the wind may turn from left-to-right, in radians.
const TURN = 1.15;
// How quickly a particle takes up the local wind (per second). Lower values
// give them more momentum.
const RESPONSE = 9;
// Trails fade with this time constant (seconds).
const TRAIL_TAU = 0.22;
// The cursor is a disc of this radius (px) that the air flows around.
const DISC_RADIUS = 64;
const DISC_FOLLOW = 18;
const DISC_RISE = 7;
// Moving faster than this (px/s) sheds vortices behind the disc.
const SHED_SPEED = 150;
const SHED_MS = 42;
const MAX_VORTICES = 30;
// Each shed vortex: core radius (px), strength per px/s of cursor speed,
// how fast it weakens (s) and how fast its core spreads (s).
const VORTEX_CORE = 30;
const VORTEX_GAIN = 0.62 * Math.PI * 2 * VORTEX_CORE * 0.5;
const VORTEX_TAU = 1.1;
const VORTEX_SPREAD = 0.5;
const MAX_CURSOR_SPEED = 1600;
// A click sends a ring of wind outwards.
const GUST_MS = 1300;
const GUST_SPEED = 0.62; // px per ms
const GUST_WIDTH = 64;
const GUST_STRENGTH = 560; // px/s at the crest
// Four alpha levels: each is one stroked path, so a frame is four draw calls.
const BUCKETS = [0.18, 0.34, 0.54, 0.8] as const;
// Segments longer than this are a wrap or a push, not motion.
const MAX_SEGMENT = 40;
// The drift alone is slow; half the frame rate looks the same and costs
// half as much. Anything following the hand gets every frame.
const IDLE_FRAME_MS = 33;
// Destination-out can't fade the last few alpha levels in small steps, so
// while frames are short a stronger pass clears that residue once a second.
const CLEANUP_MS = 1000;
const CLEANUP_ALPHA = 0.24;
// The still frame used for reduced motion and speed 0.
const STILL_LINES = 340;
const STILL_STEPS = 18;
const STILL_DT = 0.05;

/** Seeded 3D gradient noise (Ken Perlin's improved noise), about -1 to 1. */
function createNoise(seed: number) {
  const p = Array.from({ length: 256 }, (_, i) => i);
  let state = seed >>> 0 || 1;
  const random = () => {
    state = (state * 1_664_525 + 1_013_904_223) >>> 0;
    return state / 4_294_967_296;
  };
  for (let i = 255; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [p[i], p[j]] = [p[j], p[i]];
  }
  const perm = new Uint8Array(512);
  for (let i = 0; i < 512; i++) {
    perm[i] = p[i & 255];
  }
  const fade = (t: number) => t * t * t * (t * (t * 6 - 15) + 10);
  const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
  const grad = (hash: number, x: number, y: number, z: number) => {
    const h = hash & 15;
    const u = h < 8 ? x : y;
    let v = z;
    if (h < 4) {
      v = y;
    } else if (h === 12 || h === 14) {
      v = x;
    }
    return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v);
  };

  return (x: number, y: number, z: number) => {
    const X = Math.floor(x) & 255;
    const Y = Math.floor(y) & 255;
    const Z = Math.floor(z) & 255;
    const fx = x - Math.floor(x);
    const fy = y - Math.floor(y);
    const fz = z - Math.floor(z);
    const u = fade(fx);
    const v = fade(fy);
    const w = fade(fz);
    const A = perm[X] + Y;
    const AA = perm[A] + Z;
    const AB = perm[A + 1] + Z;
    const B = perm[X + 1] + Y;
    const BA = perm[B] + Z;
    const BB = perm[B + 1] + Z;
    return lerp(
      lerp(
        lerp(grad(perm[AA], fx, fy, fz), grad(perm[BA], fx - 1, fy, fz), u),
        lerp(
          grad(perm[AB], fx, fy - 1, fz),
          grad(perm[BB], fx - 1, fy - 1, fz),
          u
        ),
        v
      ),
      lerp(
        lerp(
          grad(perm[AA + 1], fx, fy, fz - 1),
          grad(perm[BA + 1], fx - 1, fy, fz - 1),
          u
        ),
        lerp(
          grad(perm[AB + 1], fx, fy - 1, fz - 1),
          grad(perm[BB + 1], fx - 1, fy - 1, fz - 1),
          u
        ),
        v
      ),
      w
    );
  };
}

type Noise = ReturnType<typeof createNoise>;

/** The cursor, as a solid disc the air has to go around. */
interface Disc {
  x: number;
  y: number;
  targetX: number;
  targetY: number;
  vx: number;
  vy: number;
  /** 0 to 1: grows when the cursor arrives, shrinks when it leaves. */
  amount: number;
  on: boolean;
  lastShed: number;
  side: number;
}

/** A Lamb-Oseen vortex shed by the moving disc. */
interface Vortex {
  x: number;
  y: number;
  gamma: number;
  age: number;
}

interface Gust {
  x: number;
  y: number;
  start: number;
}

interface Air {
  noise: Noise;
  time: number;
  wind: number;
  disc: Disc;
  vortices: Vortex[];
  gusts: Gust[];
  now: number;
}

// Scratch vector the field functions write into, so a frame allocates
// nothing per particle.
const out = { x: 0, y: 0 };

/** The undisturbed wind: left to right, turned by slowly drifting noise. */
function baseWind(air: Air, x: number, y: number) {
  const t = air.time;
  const angle =
    air.noise((x - t * WIND * 0.6) / NOISE_SCALE, y / NOISE_SCALE, t * 0.06) *
    TURN;
  out.x = Math.cos(angle) * air.wind;
  out.y = Math.sin(angle) * air.wind;
}

/**
 * Potential flow around a disc: the local wind (relative to the moving disc)
 * plus a doublet, so streams split ahead of it, speed up round its sides and
 * close up behind. In complex form, u - iv = conj(w) - (w - V) R^2 / z^2.
 */
function addDisc(disc: Disc, x: number, y: number) {
  const radius = DISC_RADIUS * disc.amount;
  const dx = x - disc.x;
  const dy = y - disc.y;
  const r2 = Math.max(dx * dx + dy * dy, radius * radius);
  const k = (radius * radius) / (r2 * r2);
  const rx = out.x - disc.vx;
  const ry = out.y - disc.vy;
  const p = dx * dx - dy * dy;
  const q = -2 * dx * dy;
  out.x -= k * (rx * p - ry * q);
  out.y += k * (rx * q + ry * p);
}

function addVortices(vortices: Vortex[], x: number, y: number) {
  for (const v of vortices) {
    const dx = x - v.x;
    const dy = y - v.y;
    const r2 = dx * dx + dy * dy + 1;
    const core = VORTEX_CORE * VORTEX_CORE * (1 + v.age / VORTEX_SPREAD);
    const swirl =
      ((v.gamma * Math.exp(-v.age / VORTEX_TAU)) / (2 * Math.PI * r2)) *
      (1 - Math.exp(-r2 / core));
    out.x -= swirl * dy;
    out.y += swirl * dx;
  }
}

function addGusts(gusts: Gust[], now: number, x: number, y: number) {
  for (const g of gusts) {
    const age = now - g.start;
    const dx = x - g.x;
    const dy = y - g.y;
    const r = Math.hypot(dx, dy) + 0.001;
    const d = r - age * GUST_SPEED;
    const fadeOut = 1 - age / GUST_MS;
    const push =
      GUST_STRENGTH *
      fadeOut *
      fadeOut *
      Math.exp(-(d * d) / (2 * GUST_WIDTH * GUST_WIDTH));
    out.x += (push * dx) / r;
    out.y += (push * dy) / r;
  }
}

/** The air's velocity at one point, written into `out`. */
function velocityAt(air: Air, x: number, y: number) {
  baseWind(air, x, y);
  if (air.disc.amount > 0.002) {
    addDisc(air.disc, x, y);
  }
  if (air.vortices.length > 0) {
    addVortices(air.vortices, x, y);
  }
  if (air.gusts.length > 0) {
    addGusts(air.gusts, air.now, x, y);
  }
}

/** Glide the disc after the cursor and shed vortices off its sides. */
function stepDisc(disc: Disc, vortices: Vortex[], dt: number, now: number) {
  const px = disc.x;
  const py = disc.y;
  const follow = 1 - Math.exp(-DISC_FOLLOW * dt);
  disc.x += (disc.targetX - disc.x) * follow;
  disc.y += (disc.targetY - disc.y) * follow;
  const goal = disc.on ? 1 : 0;
  disc.amount += (goal - disc.amount) * (1 - Math.exp(-DISC_RISE * dt));
  if (disc.amount < 0.002 && !disc.on) {
    disc.amount = 0;
  }
  const smooth = 1 - Math.exp(-14 * dt);
  disc.vx += ((disc.x - px) / dt - disc.vx) * smooth;
  disc.vy += ((disc.y - py) / dt - disc.vy) * smooth;

  const speed = Math.hypot(disc.vx, disc.vy);
  if (
    speed < SHED_SPEED ||
    disc.amount < 0.5 ||
    now - disc.lastShed < SHED_MS
  ) {
    return;
  }
  disc.lastShed = now;
  disc.side = -disc.side;
  const ux = disc.vx / speed;
  const uy = disc.vy / speed;
  const radius = DISC_RADIUS * disc.amount;
  // Alternate sides, like the vortex street behind a cylinder. The air
  // dragged along the disc's flank sets which way each one spins.
  vortices.push({
    x: disc.x - ux * radius * 0.9 - uy * disc.side * radius * 0.55,
    y: disc.y - uy * radius * 0.9 + ux * disc.side * radius * 0.55,
    gamma: disc.side * VORTEX_GAIN * Math.min(speed, MAX_CURSOR_SPEED),
    age: 0,
  });
  if (vortices.length > MAX_VORTICES) {
    vortices.shift();
  }
}

/** Age the wake: vortices drift downwind and weaken until they're gone. */
function stepWake(air: Air, dt: number) {
  for (const v of air.vortices) {
    baseWind(air, v.x, v.y);
    v.x += out.x * 0.85 * dt;
    v.y += out.y * 0.85 * dt;
    v.age += dt;
  }
  while (air.vortices.length > 0 && air.vortices[0].age > VORTEX_TAU * 3.5) {
    air.vortices.shift();
  }
  while (air.gusts.length > 0 && air.now - air.gusts[0].start > GUST_MS) {
    air.gusts.shift();
  }
}

/** Particle state as flat arrays: cheap to walk 700 times a frame. */
class Particles {
  count = 0;
  width = 0;
  height = 0;
  x = new Float32Array(0);
  y = new Float32Array(0);
  vx = new Float32Array(0);
  vy = new Float32Array(0);
  life = new Float32Array(0);
  maxLife = new Float32Array(0);
  pace = new Float32Array(0);

  resize(count: number, width: number, height: number) {
    if (count === this.count) {
      // Same count, new size: stretch the particles over the new area so a
      // wider canvas doesn't start with an empty strip.
      const sx = this.width > 0 ? width / this.width : 1;
      const sy = this.height > 0 ? height / this.height : 1;
      for (let i = 0; i < count; i++) {
        this.x[i] *= sx;
        this.y[i] *= sy;
      }
      this.width = width;
      this.height = height;
      return;
    }
    this.width = width;
    this.height = height;
    this.count = count;
    this.x = new Float32Array(count);
    this.y = new Float32Array(count);
    this.vx = new Float32Array(count);
    this.vy = new Float32Array(count);
    this.life = new Float32Array(count);
    this.maxLife = new Float32Array(count);
    this.pace = new Float32Array(count);
    for (let i = 0; i < count; i++) {
      this.spawn(i, width, height);
      // Start part way through their lives so they don't all fade together.
      this.life[i] = Math.random() * this.maxLife[i];
    }
  }

  spawn(i: number, width: number, height: number) {
    this.x[i] = Math.random() * width;
    this.y[i] = Math.random() * height;
    this.vx[i] = 0;
    this.vy[i] = 0;
    this.life[i] = 0;
    this.maxLife[i] = 3 + Math.random() * 5;
    this.pace[i] = 0.75 + Math.random() * 0.5;
  }
}

/** Fade in at birth and out before respawning, so nothing pops. */
function envelope(life: number, maxLife: number) {
  return Math.min(1, life / 0.6, (maxLife - life) / 0.6);
}

function bucketOf(intensity: number) {
  return Math.max(0, Math.min(BUCKETS.length - 1, Math.floor(intensity * 4)));
}

/** Wrap a particle that blew off one edge back in on the opposite one. */
function wrap(v: number, size: number) {
  if (v < -8) {
    return v + size + 16;
  }
  if (v > size + 8) {
    return v - size - 16;
  }
  return v;
}

interface StepContext {
  air: Air;
  particles: Particles;
  paths: Path2D[];
  width: number;
  height: number;
  dt: number;
}

/** Push a particle the disc swept over back out to its surface. */
function keepOutOfDisc(p: Particles, i: number, disc: Disc) {
  if (disc.amount === 0) {
    return;
  }
  const radius = DISC_RADIUS * disc.amount;
  const dx = p.x[i] - disc.x;
  const dy = p.y[i] - disc.y;
  const r2 = dx * dx + dy * dy;
  if (r2 >= radius * radius || r2 < 0.0001) {
    return;
  }
  const r = Math.sqrt(r2);
  p.x[i] = disc.x + (dx / r) * radius;
  p.y[i] = disc.y + (dy / r) * radius;
}

function stepParticle(c: StepContext, i: number) {
  const { air, particles: p, dt } = c;
  p.life[i] += dt;
  if (p.life[i] > p.maxLife[i]) {
    p.spawn(i, c.width, c.height);
    return;
  }
  const x0 = p.x[i];
  const y0 = p.y[i];
  velocityAt(air, x0, y0);
  const take = 1 - Math.exp(-RESPONSE * dt);
  p.vx[i] += (out.x * p.pace[i] - p.vx[i]) * take;
  p.vy[i] += (out.y * p.pace[i] - p.vy[i]) * take;
  p.x[i] = wrap(x0 + p.vx[i] * dt, c.width);
  p.y[i] = wrap(y0 + p.vy[i] * dt, c.height);
  keepOutOfDisc(p, i, air.disc);

  const sx = p.x[i] - x0;
  const sy = p.y[i] - y0;
  if (sx * sx + sy * sy > MAX_SEGMENT * MAX_SEGMENT) {
    return;
  }
  // Faster air draws darker, so the wake and the flanks of the disc stand
  // out against the drift.
  const pace = Math.hypot(p.vx[i], p.vy[i]) / (air.wind * 2.4 + 1);
  const intensity = envelope(p.life[i], p.maxLife[i]) * Math.min(1, 0.4 + pace);
  const path = c.paths[bucketOf(intensity)];
  path.moveTo(x0, y0);
  path.lineTo(p.x[i], p.y[i]);
}

function strokeBuckets(ctx: CanvasRenderingContext2D, paths: Path2D[]) {
  for (let b = 0; b < BUCKETS.length; b++) {
    ctx.globalAlpha = BUCKETS[b];
    ctx.stroke(paths[b]);
  }
  ctx.globalAlpha = 1;
}

/** Streamlines traced from random seeds: a still picture of the wind. */
function drawStill(
  ctx: CanvasRenderingContext2D,
  air: Air,
  size: { width: number; height: number },
  lines: number
) {
  const paths = BUCKETS.map(() => new Path2D());
  for (let n = 0; n < lines; n++) {
    let x = Math.random() * size.width;
    let y = Math.random() * size.height;
    for (let s = 0; s < STILL_STEPS; s++) {
      baseWind(air, x, y);
      const nx = x + out.x * STILL_DT;
      const ny = y + out.y * STILL_DT;
      // Each line darkens towards its head, like a trail.
      const path = paths[bucketOf((s / STILL_STEPS) * 0.75)];
      path.moveTo(x, y);
      path.lineTo(nx, ny);
      x = nx;
      y = ny;
    }
  }
  strokeBuckets(ctx, paths);
}

function createAir(speed: number): Air {
  return {
    noise: createNoise(7),
    time: 0,
    // A still frame (speed 0) is still traced with the default wind.
    wind: WIND * (speed > 0 ? speed : 1),
    disc: {
      x: 0,
      y: 0,
      targetX: 0,
      targetY: 0,
      vx: 0,
      vy: 0,
      amount: 0,
      on: false,
      lastShed: 0,
      side: 1,
    },
    vortices: [],
    gusts: [],
    now: 0,
  };
}

/** Pointer events (on the window) mapped onto the disc and gusts. */
function bindPointer(
  root: HTMLElement,
  air: Air,
  wake: () => void,
  isVisible: () => boolean
) {
  const local = (event: PointerEvent) => {
    const rect = root.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    const inside = x >= 0 && y >= 0 && x <= rect.width && y <= rect.height;
    return { x, y, inside };
  };
  const onLeave = () => {
    air.disc.on = false;
  };
  const onMove = (event: PointerEvent) => {
    // A finger only stirs the air while it's down.
    if (
      !isVisible() ||
      (event.pointerType === "touch" && event.buttons === 0)
    ) {
      return;
    }
    const point = local(event);
    const disc = air.disc;
    if (!point.inside) {
      disc.on = false;
      return;
    }
    if (disc.amount < 0.05) {
      // Appear where the cursor came in rather than sliding over from the
      // last place it left.
      disc.x = point.x;
      disc.y = point.y;
      disc.vx = 0;
      disc.vy = 0;
    }
    disc.targetX = point.x;
    disc.targetY = point.y;
    disc.on = true;
    wake();
  };
  const onOut = (event: PointerEvent) => {
    if (!event.relatedTarget) {
      onLeave();
    }
  };
  const onUp = (event: PointerEvent) => {
    if (event.pointerType === "touch") {
      onLeave();
    }
  };
  const onDown = (event: PointerEvent) => {
    if (!isVisible() || event.button !== 0) {
      return;
    }
    // Clicks on the content (links, buttons, fields) are not gusts.
    const target = event.target instanceof Element ? event.target : null;
    if (
      target?.closest(
        "a, button, input, textarea, select, label, [role='button']"
      )
    ) {
      return;
    }
    const point = local(event);
    if (!point.inside) {
      return;
    }
    air.gusts.push({ x: point.x, y: point.y, start: performance.now() });
    if (air.gusts.length > 4) {
      air.gusts.shift();
    }
    onMove(event);
    wake();
  };

  const options = { passive: true };
  window.addEventListener("pointermove", onMove, options);
  window.addEventListener("pointerdown", onDown, options);
  window.addEventListener("pointerup", onUp, options);
  window.addEventListener("pointercancel", onLeave, options);
  document.addEventListener("pointerout", onOut, options);
  window.addEventListener("blur", onLeave);
  return () => {
    window.removeEventListener("pointermove", onMove);
    window.removeEventListener("pointerdown", onDown);
    window.removeEventListener("pointerup", onUp);
    window.removeEventListener("pointercancel", onLeave);
    document.removeEventListener("pointerout", onOut);
    window.removeEventListener("blur", onLeave);
  };
}

export default function FlowField({
  className,
  children,
  density = 1,
  speed = 1,
  interactive = true,
}: FlowFieldProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    if (!(root && canvas && ctx)) {
      return;
    }

    const still =
      speed <= 0 ||
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const air = createAir(speed);
    const particles = new Particles();
    const size = { width: 0, height: 0 };
    let color = "";
    let raf = 0;
    let lastStep = 0;
    let lastCleanup = 0;
    let visible = true;

    const countFor = (w: number) =>
      Math.round(BASE_COUNT * Math.max(density, 0) * (w < 520 ? 0.6 : 1));

    const paintStill = () => {
      ctx.clearRect(0, 0, size.width, size.height);
      ctx.strokeStyle = color;
      const lines = (countFor(size.width) * STILL_LINES) / BASE_COUNT;
      drawStill(ctx, air, size, Math.round(lines));
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      size.width = rect.width;
      size.height = rect.height;
      canvas.width = Math.round(size.width * dpr);
      canvas.height = Math.round(size.height * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.lineCap = "butt";
      ctx.lineWidth = 1.2;
      color = getComputedStyle(canvas).color;
      particles.resize(countFor(size.width), size.width, size.height);
      if (still) {
        paintStill();
      }
    };

    const isActive = () =>
      air.disc.on ||
      air.disc.amount > 0 ||
      air.vortices.length > 0 ||
      air.gusts.length > 0;

    // Trails fade by erasing a little alpha each frame, so the canvas stays
    // transparent over whatever background sits behind it.
    const fade = (dt: number, now: number) => {
      ctx.globalCompositeOperation = "destination-out";
      ctx.fillStyle = "#000";
      ctx.globalAlpha = 1 - Math.exp(-dt / TRAIL_TAU);
      ctx.fillRect(0, 0, size.width, size.height);
      if (dt < 0.025 && now - lastCleanup > CLEANUP_MS) {
        lastCleanup = now;
        ctx.globalAlpha = CLEANUP_ALPHA;
        ctx.fillRect(0, 0, size.width, size.height);
      }
      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = "source-over";
    };

    const frame = (now: number) => {
      raf = 0;
      if (!visible) {
        return;
      }
      raf = requestAnimationFrame(frame);
      if (!isActive() && now - lastStep < IDLE_FRAME_MS - 4) {
        return;
      }
      const dt = lastStep ? Math.min((now - lastStep) / 1000, 0.05) : 1 / 60;
      lastStep = now;
      air.now = now;
      air.time += dt * speed;
      stepDisc(air.disc, air.vortices, dt, now);
      stepWake(air, dt);

      fade(dt, now);
      const paths = BUCKETS.map(() => new Path2D());
      const step: StepContext = {
        air,
        particles,
        paths,
        width: size.width,
        height: size.height,
        dt,
      };
      for (let i = 0; i < particles.count; i++) {
        stepParticle(step, i);
      }
      ctx.strokeStyle = color;
      strokeBuckets(ctx, paths);
    };

    const start = () => {
      if (!raf && visible && !still) {
        lastStep = 0;
        raf = requestAnimationFrame(frame);
      }
    };

    resize();
    canvas.style.opacity = "1";
    start();

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(canvas);

    // Moving the window to a screen with another pixel ratio doesn't resize
    // the canvas, so watch the ratio too or the trails go soft.
    let dprQuery: MediaQueryList | null = null;
    const watchDpr = () => {
      dprQuery?.removeEventListener("change", onDpr);
      dprQuery = window.matchMedia(
        `(resolution: ${window.devicePixelRatio}dppx)`
      );
      dprQuery.addEventListener("change", onDpr);
    };
    const onDpr = () => {
      resize();
      watchDpr();
    };
    watchDpr();

    // Stop drawing entirely while the wind is scrolled away or the tab is
    // in the background.
    let onScreen = true;
    const update = () => {
      visible = onScreen && document.visibilityState === "visible";
      start();
    };
    const intersection = new IntersectionObserver(([entry]) => {
      onScreen = entry.isIntersecting;
      update();
    });
    intersection.observe(root);
    document.addEventListener("visibilitychange", update);

    // Follow light and dark mode without asking the app for a theme. Only
    // checked while the wind is on screen.
    const colorTimer = window.setInterval(() => {
      if (!visible) {
        return;
      }
      const next = getComputedStyle(canvas).color;
      if (next !== color) {
        color = next;
        if (still) {
          paintStill();
        }
      }
    }, 500);

    // Listened for on the window, so content layered on top (a heading, a
    // button) still has the wind flowing round the cursor beneath it.
    const unbind =
      interactive && !still
        ? bindPointer(root, air, start, () => visible)
        : undefined;

    return () => {
      cancelAnimationFrame(raf);
      resizeObserver.disconnect();
      dprQuery?.removeEventListener("change", onDpr);
      intersection.disconnect();
      document.removeEventListener("visibilitychange", update);
      window.clearInterval(colorTimer);
      unbind?.();
    };
  }, [density, speed, interactive]);

  return (
    <div
      className={cn(
        "pointer-events-none absolute inset-0 overflow-hidden",
        className
      )}
      ref={rootRef}
    >
      <div aria-hidden="true" className="absolute inset-0">
        <canvas
          className="h-full w-full opacity-0 transition-opacity duration-700 ease-out"
          ref={canvasRef}
        />
      </div>
      {children === undefined || children === null ? null : (
        <div className="pointer-events-auto relative h-full w-full">
          {children}
        </div>
      )}
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Focal Point Picker
 * @version: 1.0.0
 * @date: 2026-10-16
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import Image from "next/image";
import {
  type KeyboardEvent,
  type PointerEvent,
  useEffect,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

export interface FocalPoint {
  /** 0 to 1 from the left. */
  x: number;
  /** 0 to 1 from the top. */
  y: number;
}

export interface FocalCrop {
  label: string;
  /** Width over height. */
  ratio: number;
}

export interface FocalPointPickerProps {
  src?: string;
  alt?: string;
  /** The image's natural width over height. */
  imageRatio?: number;
  defaultValue?: FocalPoint;
  /** The crops your layouts use; each previews the point live. */
  crops?: FocalCrop[];
  onValueChange?: (point: FocalPoint) => void;
  className?: string;
}

const PHOTO =
  "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=1600&h=1067&fit=crop&auto=format&q=80";

const DEFAULT_CROPS: FocalCrop[] = [
  { label: "Avatar", ratio: 1 },
  { label: "Banner", ratio: 16 / 9 },
  { label: "Story", ratio: 9 / 16 },
];

const EASE = "cubic-bezier(0.23, 1, 0.32, 1)";

const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v));

/**
 * The window a cover-fit crop shows, as fractions of the image, centred on
 * the point as far as the edges allow; and the object-position that shows it.
 */
function cropWindow(point: FocalPoint, imageRatio: number, ratio: number) {
  const w = Math.min(1, ratio / imageRatio);
  const h = Math.min(1, imageRatio / ratio);
  const left = clamp(point.x - w / 2, 0, 1 - w);
  const top = clamp(point.y - h / 2, 0, 1 - h);
  return {
    left,
    top,
    w,
    h,
    position: `${w < 1 ? (left / (1 - w)) * 100 : 50}% ${h < 1 ? (top / (1 - h)) * 100 : 50}%`,
  };
}

const pct = (v: number) => `${Math.round(v * 100)}%`;

const CORNERS = [
  "top-0 left-0 border-t border-l",
  "top-0 right-0 border-t border-r",
  "bottom-0 left-0 border-b border-l",
  "right-0 bottom-0 border-r border-b",
];

/** Thin L-shaped crop marks, like a viewfinder, at the corners of the parent. */
function CropCorners({ className }: { className?: string }) {
  return (
    <span aria-hidden className={cn("pointer-events-none absolute", className)}>
      {CORNERS.map((corner) => (
        <span
          className={cn(
            "absolute size-2.5 border-white drop-shadow-[0_0_1px_rgb(0_0_0/0.6)]",
            corner
          )}
          key={corner}
        />
      ))}
    </span>
  );
}

export default function FocalPointPicker({
  src = PHOTO,
  alt = "Peaks above a sea of clouds",
  imageRatio = 3 / 2,
  defaultValue = { x: 0.68, y: 0.38 },
  crops = DEFAULT_CROPS,
  onValueChange,
  className,
}: FocalPointPickerProps) {
  const [point, setPoint] = useState(defaultValue);
  const [dragging, setDragging] = useState(false);
  // The crop whose window is drawn on the source, from hovering its preview.
  const [shown, setShown] = useState<number | null>(null);
  // A click glides the point; a drag follows the finger exactly.
  const [gliding, setGliding] = useState(false);
  const frameRef = useRef<HTMLDivElement>(null);
  const pointRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    onValueChange?.(point);
  }, [point, onValueChange]);

  const pointAt = (clientX: number, clientY: number) => {
    const rect = frameRef.current?.getBoundingClientRect();
    if (!rect) {
      return point;
    }
    return {
      x: clamp((clientX - rect.left) / rect.width, 0, 1),
      y: clamp((clientY - rect.top) / rect.height, 0, 1),
    };
  };

  const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (!event.isPrimary || event.button !== 0) {
      return;
    }
    event.currentTarget.setPointerCapture(event.pointerId);
    const onPoint = pointRef.current?.contains(event.target as Node);
    setGliding(!onPoint);
    setDragging(true);
    setPoint(pointAt(event.clientX, event.clientY));
  };

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    if (!dragging) {
      return;
    }
    setGliding(false);
    setPoint(pointAt(event.clientX, event.clientY));
  };

  const endDrag = () => setDragging(false);

  const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    const step = event.shiftKey ? 0.1 : 0.01;
    const moves: Record<string, [number, number]> = {
      ArrowLeft: [-step, 0],
      ArrowRight: [step, 0],
      ArrowUp: [0, -step],
      ArrowDown: [0, step],
    };
    const move = moves[event.key];
    if (!move) {
      return;
    }
    event.preventDefault();
    setGliding(false);
    setPoint((p) => ({
      x: clamp(Math.round((p.x + move[0]) * 100) / 100, 0, 1),
      y: clamp(Math.round((p.y + move[1]) * 100) / 100, 0, 1),
    }));
  };

  const glide = gliding ? `transform 280ms ${EASE}` : "none";
  const shownCrop =
    shown === null ? null : cropWindow(point, imageRatio, crops[shown].ratio);

  return (
    <div
      className={cn(
        "w-full max-w-xl select-none rounded-3xl border border-zinc-200 bg-white p-4 text-zinc-900 dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-100",
        className
      )}
    >
      <div
        className="relative cursor-crosshair touch-none overflow-hidden rounded-2xl bg-zinc-100 dark:bg-zinc-900"
        onLostPointerCapture={endDrag}
        onPointerCancel={endDrag}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={endDrag}
        ref={frameRef}
        style={{ aspectRatio: imageRatio }}
      >
        <Image
          alt={alt}
          className="pointer-events-none object-cover"
          draggable={false}
          fill
          sizes="(max-width: 576px) 100vw, 576px"
          src={src}
          unoptimized
        />

        {/* The hovered crop's window: everything it cuts is dimmed. */}
        <div
          aria-hidden
          className={cn(
            "pointer-events-none absolute shadow-[0_0_0_9999px_rgb(0_0_0/0.45)] outline outline-1 outline-white/60 transition-[left,top,width,height,opacity] duration-200",
            shownCrop ? "opacity-100" : "opacity-0"
          )}
          style={{
            left: pct(shownCrop?.left ?? 0),
            top: pct(shownCrop?.top ?? 0),
            width: pct(shownCrop?.w ?? 1),
            height: pct(shownCrop?.h ?? 1),
            transitionTimingFunction: EASE,
          }}
        >
          <CropCorners className="inset-1.5" />
        </div>

        {/* Full-size layer moved by the point, so dragging skips layout. */}
        <div
          className="pointer-events-none absolute inset-0"
          style={{
            transform: `translate(${point.x * 100}%, ${point.y * 100}%)`,
            transition: glide,
          }}
        >
          <button
            aria-label={`Focal point, ${pct(point.x)} from the left, ${pct(point.y)} from the top. Move with the arrow keys.`}
            className={cn(
              "pointer-events-auto absolute top-0 left-0 size-10 -translate-x-1/2 -translate-y-1/2 cursor-grab rounded-full outline-none focus-visible:ring-2 focus-visible:ring-white focus-visible:ring-offset-2 focus-visible:ring-offset-black/40",
              dragging && "cursor-grabbing"
            )}
            onKeyDown={handleKeyDown}
            ref={pointRef}
            type="button"
          >
            {/* Hairline crosshair, open at the centre around the dot. */}
            <span className="absolute inset-0 drop-shadow-[0_0_1px_rgb(0_0_0/0.7)]">
              <span className="absolute top-1/2 left-0 h-px w-[15px] -translate-y-1/2 bg-white" />
              <span className="absolute top-1/2 right-0 h-px w-[15px] -translate-y-1/2 bg-white" />
              <span className="absolute top-0 left-1/2 h-[15px] w-px -translate-x-1/2 bg-white" />
              <span className="absolute bottom-0 left-1/2 h-[15px] w-px -translate-x-1/2 bg-white" />
            </span>
            <span className="absolute top-1/2 left-1/2 size-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-orange-600 ring-1 ring-white" />
          </button>
        </div>
      </div>

      <div className="mt-4 flex items-end gap-3">
        {crops.map((crop, i) => {
          const c = cropWindow(point, imageRatio, crop.ratio);
          return (
            <button
              className="group min-w-0 text-left outline-none"
              key={crop.label}
              onBlur={() => setShown(null)}
              onFocus={() => setShown(i)}
              onPointerEnter={(event) => {
                if (event.pointerType === "mouse") {
                  setShown(i);
                }
              }}
              onPointerLeave={() => setShown(null)}
              style={{ flex: `${crop.ratio} 1 0` }}
              type="button"
            >
              <span
                className={cn(
                  "relative block overflow-hidden rounded-lg bg-zinc-100 ring-offset-2 transition-shadow duration-150 ease-out group-focus-visible:ring-2 group-focus-visible:ring-zinc-400 dark:bg-zinc-900 dark:ring-offset-zinc-950",
                  shown === i && "ring-2 ring-zinc-900 dark:ring-zinc-100"
                )}
                style={{ aspectRatio: crop.ratio }}
              >
                <Image
                  alt=""
                  className="pointer-events-none object-cover"
                  draggable={false}
                  fill
                  sizes="200px"
                  src={src}
                  style={{
                    objectPosition: c.position,
                    transition: gliding
                      ? `object-position 280ms ${EASE}`
                      : "none",
                  }}
                  unoptimized
                />
                <CropCorners className="inset-1" />
              </span>
              <span className="mt-1.5 block truncate text-xs text-zinc-500 dark:text-zinc-400">
                {crop.label}
              </span>
            </button>
          );
        })}
      </div>

      <div className="mt-3 flex items-center justify-between gap-3 border-zinc-200 border-t pt-3 text-xs dark:border-zinc-800">
        <span className="text-zinc-500 dark:text-zinc-400">
          Drag the point, or hover a crop to see it
        </span>
        <code className="shrink-0 font-mono text-zinc-900 tabular-nums dark:text-zinc-100">
          {pct(point.x)} {pct(point.y)}
        </code>
      </div>
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Glitch Text (Signal Text). Flat text that bursts into hard-cut
 * horizontal bands with a thin red/cyan channel split, on idle, hover, or as
 * the transition to new text.
 * @version: 2.0.0
 * @date: 2026-10-14
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import type { CSSProperties, PointerEvent } from "react";
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

/**
 * - `idle`: a burst every 4-9s while on screen, plus on text changes.
 * - `hover`: a burst on pointer enter (or tap), plus on text changes.
 * - `change`: only text changes glitch; the burst is the transition.
 */
export type GlitchTextTrigger = "idle" | "hover" | "change";

export type GlitchTextIntensity = "subtle" | "medium" | "strong";

export interface GlitchTextProps {
  /** Text to render. Changing it glitches over to the new text. */
  text?: string;
  /** What starts a burst. Defaults to `idle`. */
  trigger?: GlitchTextTrigger;
  /** Band count, displacement and channel split. Defaults to `medium`. */
  intensity?: GlitchTextIntensity;
  /** Color of the leading channel during a burst. The other one is cyan. */
  accent?: string;
  className?: string;
  /** Root element. A span by default, so it also fits inside a heading. */
  as?: "span" | "div" | "p" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6";
}

interface Settings {
  /** Horizontal bands the text is cut into. */
  bands: number;
  /** Max sideways jump of a band, in em (so it scales with the font). */
  shift: number;
  /** Max red/cyan channel offset, in px. */
  split: number;
  /** Hard-cut frames per burst. */
  frames: number;
  /** Length of one frame, in ms. */
  frame: number;
}

const INTENSITY: Record<GlitchTextIntensity, Settings> = {
  subtle: { bands: 3, shift: 0.05, split: 1, frames: 5, frame: 55 },
  medium: { bands: 4, shift: 0.12, split: 2, frames: 6, frame: 55 },
  strong: { bands: 5, shift: 0.18, split: 3, frames: 7, frame: 50 },
};

const MAX_BANDS = 5;
const BAND_IDS = Array.from({ length: MAX_BANDS }, (_, i) => `band-${i}`);
const DEFAULT_ACCENT = "oklch(0.63 0.24 25)";
const CYAN = "oklch(0.78 0.14 205)";
// Each keyframe holds until the next one: a glitch cuts, it doesn't glide.
const HOLD = "steps(1, end)";
const FIRST_IDLE = 1200;
const IDLE_MIN = 4000;
const IDLE_SPREAD = 5000;
// Chance that a band stays put on a given frame, so the cut reads as broken
// signal rather than a uniform shake.
const STILL_CHANCE = 0.3;

const round = (n: number) => Math.round(n * 1000) / 1000;

const prefersReducedMotion = () =>
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/** Keyframes that hold each value for one frame, then end on the last one. */
const held = (frames: Keyframe[]): Keyframe[] => [
  ...frames.map((k, i) => ({ ...k, offset: i / frames.length, easing: HOLD })),
  { ...frames.at(-1), offset: 1 },
];

/** Random band boundaries from 0 to 100%, no band much thinner than another. */
const randomCuts = (count: number) => {
  const weights = Array.from({ length: count }, () => 0.55 + Math.random());
  const total = weights.reduce((a, b) => a + b, 0);
  const cuts = [0];
  for (const w of weights) {
    cuts.push(round((cuts.at(-1) ?? 0) + (w / total) * 100));
  }
  return cuts;
};

const jump = (max: number) => {
  if (Math.random() < STILL_CHANCE) {
    return 0;
  }
  const sign = Math.random() < 0.5 ? -1 : 1;
  return round(sign * (0.25 + 0.75 * Math.random()) * max);
};

/** Sideways positions of one band: off on frame one, home on the last. */
const bandPath = (s: Settings, forceMove: boolean) =>
  Array.from({ length: s.frames }, (_, f) => {
    if (f === s.frames - 1) {
      return 0;
    }
    const x = jump(s.shift);
    return f === 0 && forceMove && x === 0 ? round(s.shift * 0.6) : x;
  });

interface Shown {
  /** Text the bands show first during a change burst. */
  from: string | null;
  to: string;
  /** Bumped on every text change. */
  id: number;
}

const LAYER = "col-start-1 row-start-1 grid";
const TEXT = "col-start-1 row-start-1";
const GHOST = "pointer-events-none select-none opacity-0";

function LayerText({ from, to }: { from: string | null; to: string }) {
  return (
    <>
      {from !== null && (
        <span className={cn(TEXT, "opacity-0")} data-text="from">
          {from}
        </span>
      )}
      <span className={TEXT} data-text="to">
        {to}
      </span>
    </>
  );
}

const GlitchText = ({
  text = "Signal Text",
  trigger = "idle",
  intensity = "medium",
  accent = DEFAULT_ACCENT,
  className,
  as: Root = "span",
}: GlitchTextProps) => {
  const layersRef = useRef<HTMLSpanElement>(null);
  const animsRef = useRef<Animation[]>([]);
  const runningRef = useRef(false);
  const intensityRef = useRef(intensity);
  intensityRef.current = intensity;

  const [shown, setShown] = useState<Shown>({ from: null, to: text, id: 0 });
  if (shown.to !== text) {
    setShown({ from: shown.to, to: text, id: shown.id + 1 });
  }

  const stop = useCallback(() => {
    for (const a of animsRef.current) {
      a.cancel();
    }
    animsRef.current = [];
    runningRef.current = false;
  }, []);

  /** Runs one burst. With `swap`, the bands cut from old text to new midway. */
  const burst = useCallback(
    (swap: boolean, onDone?: () => void) => {
      const root = layersRef.current;
      if (!root) {
        return;
      }
      stop();
      const s = INTENSITY[intensityRef.current];
      const opts: KeyframeAnimationOptions = {
        duration: s.frames * s.frame,
        fill: "none",
      };
      const anims: Animation[] = [];
      const run = (el: Element, frames: Keyframe[]) => {
        anims.push(el.animate(held(frames), opts));
      };

      const base = root.querySelector('[data-layer="base"]');
      if (base) {
        run(base, [{ opacity: 0 }]);
      }

      // The bands tile the text top to bottom, so at rest they rebuild it.
      // The outer edges reach past the box to keep ascenders and descenders.
      const cuts = randomCuts(s.bands);
      const bands = root.querySelectorAll<HTMLElement>('[data-layer="band"]');
      const mover = Math.floor(Math.random() * s.bands);
      bands.forEach((band, i) => {
        if (i >= s.bands) {
          return;
        }
        const top = i === 0 ? -50 : cuts[i];
        const bottom = i === s.bands - 1 ? -50 : round(100 - cuts[i + 1]);
        band.style.clipPath = `inset(${top}% -25% ${bottom}% -25%)`;
        run(
          band,
          bandPath(s, i === mover).map((x) => ({
            opacity: 1,
            transform: `translate3d(${x}em, 0, 0)`,
          }))
        );
      });

      // Red and cyan copies sit behind the bands and peek out on either side.
      const channels = root.querySelectorAll('[data-layer="channel"]');
      const offsets = Array.from({ length: s.frames }, () =>
        Math.max(1, Math.ceil(Math.random() * s.split))
      );
      channels.forEach((channel, c) => {
        const dir = c === 0 ? -1 : 1;
        run(
          channel,
          offsets.map((d, f) => ({
            opacity: f === s.frames - 1 ? 0 : 1,
            transform: `translate3d(${dir * d}px, 0, 0)`,
          }))
        );
      });

      if (swap) {
        const half = Math.ceil(s.frames / 2);
        const flip = (selector: string, before: number) => {
          for (const el of root.querySelectorAll(selector)) {
            run(
              el,
              Array.from({ length: s.frames }, (_, f) => ({
                opacity: f < half ? before : 1 - before,
              }))
            );
          }
        };
        flip('[data-layer]:not([data-layer="base"]) [data-text="from"]', 1);
        flip('[data-layer]:not([data-layer="base"]) [data-text="to"]', 0);
      }

      animsRef.current = anims;
      runningRef.current = true;
      const last = anims.at(-1);
      if (last) {
        last.onfinish = () => {
          animsRef.current = [];
          runningRef.current = false;
          onDone?.();
        };
      }
    },
    [stop]
  );

  // Text changed: the burst is the transition. A layout effect, so the new
  // text never paints clean before the bands take over.
  useLayoutEffect(() => {
    if (shown.from === null) {
      return;
    }
    const id = shown.id;
    const settle = () =>
      setShown((s) => (s.id === id ? { ...s, from: null } : s));
    if (prefersReducedMotion()) {
      settle();
      return;
    }
    burst(true, settle);
  }, [shown.from, shown.id, burst]);

  // Idle: a rare burst every 4-9s, only while on screen and the tab is visible.
  useEffect(() => {
    const root = layersRef.current;
    if (trigger !== "idle" || !root) {
      return;
    }
    let visible = false;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const schedule = (delay: number) => {
      clearTimeout(timer);
      timer = setTimeout(() => {
        if (
          !(document.hidden || runningRef.current || prefersReducedMotion())
        ) {
          burst(false);
        }
        schedule(IDLE_MIN + Math.random() * IDLE_SPREAD);
      }, delay);
    };
    const update = () => {
      if (visible && !document.hidden) {
        if (timer === undefined) {
          schedule(FIRST_IDLE);
        }
      } else {
        clearTimeout(timer);
        timer = undefined;
      }
    };
    const io = new IntersectionObserver(([entry]) => {
      visible = entry?.isIntersecting ?? false;
      update();
    });
    io.observe(root);
    document.addEventListener("visibilitychange", update);
    return () => {
      io.disconnect();
      document.removeEventListener("visibilitychange", update);
      clearTimeout(timer);
    };
  }, [trigger, burst]);

  useEffect(() => stop, [stop]);

  const onPointer = (e: PointerEvent) => {
    // Mouse bursts on enter; touch and pen burst on press, since they can't hover.
    const isMouse = e.pointerType === "mouse";
    if (
      trigger !== "hover" ||
      (e.type === "pointerenter") !== isMouse ||
      runningRef.current ||
      prefersReducedMotion()
    ) {
      return;
    }
    burst(false);
  };

  const { from, to } = shown;

  return (
    <Root
      className={cn(
        "relative inline-block text-zinc-900 dark:text-zinc-100",
        className
      )}
      onPointerDown={onPointer}
      onPointerEnter={onPointer}
      style={{ "--glitch-accent": accent } as CSSProperties}
    >
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="relative inline-grid" ref={layersRef}>
        <span
          className={cn(LAYER, GHOST)}
          data-layer="channel"
          style={{ color: "var(--glitch-accent)" }}
        >
          <LayerText from={from} to={to} />
        </span>
        <span
          className={cn(LAYER, GHOST)}
          data-layer="channel"
          style={{ color: CYAN }}
        >
          <LayerText from={from} to={to} />
        </span>
        <span className={LAYER} data-layer="base">
          <LayerText from={from} to={to} />
        </span>
        {BAND_IDS.map((id) => (
          <span className={cn(LAYER, GHOST)} data-layer="band" key={id}>
            <LayerText from={from} to={to} />
          </span>
        ))}
      </span>
    </Root>
  );
};

export default GlitchText;

