/* ------------------------------- Now Playing ------------------------------ */

export interface NowPlayingProps {
  tracks?: NowPlayingTrack[];
  /** Index of the track loaded first. */
  defaultTrack?: number;
  /** Start playing on mount. */
  autoPlay?: boolean;
  /** The one accent colour: meter, progress and label art. */
  accent?: string;
  /** Wraps the card in the glass shadow and SVG refraction (Chromium only). */
  glassEffect?: boolean;
  onTrackChange?: (index: number) => void;
  className?: string;
}

const ICON_BUTTON =
  "inline-flex size-10 items-center justify-center rounded-full text-zinc-600 transition-colors duration-150 hover:bg-zinc-100 hover:text-zinc-900 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-400 active:bg-zinc-200 dark:text-zinc-400 dark:active:bg-zinc-700 dark:hover:bg-zinc-800 dark:hover:text-zinc-100";

const FRAME =
  "@container/now-playing w-full max-w-sm rounded-3xl border border-zinc-200 p-5 shadow-sm dark:border-zinc-800";

export function NowPlaying({
  tracks = DEFAULT_TRACKS,
  defaultTrack = 0,
  autoPlay = true,
  accent = "#f97316",
  glassEffect = false,
  onTrackChange,
  className,
}: NowPlayingProps) {
  const list = tracks.length > 0 ? tracks : DEFAULT_TRACKS;
  const [trackIndex, setTrackIndex] = React.useState(() =>
    clamp(defaultTrack, 0, list.length - 1)
  );
  const track = list[trackIndex] ?? DEFAULT_TRACKS[0];
  const [playing, setPlaying] = React.useState(autoPlay);
  const [clock, setClock] = React.useState<{ s: number; dir: 1 | -1 }>({
    s: 0,
    dir: 1,
  });

  const engineRef = React.useRef<Engine | null>(null);
  if (engineRef.current === null) {
    engineRef.current = createEngine(track.duration, autoPlay);
  }
  const rootRef = React.useRef<HTMLDivElement>(null);
  const discRef = React.useRef<HTMLDivElement>(null);
  const fillRef = React.useRef<HTMLDivElement>(null);
  const railRef = React.useRef<HTMLDivElement>(null);
  const rpmRef = React.useRef<HTMLSpanElement>(null);
  const barRefs = React.useRef<(HTMLSpanElement | null)[]>([]);
  const wakeRef = React.useRef<() => void>(() => undefined);
  const clockRef = React.useRef(0);

  // Read through refs so the loop is set up once and never restarted.
  const listRef = React.useRef(list);
  listRef.current = list;
  const trackIndexRef = React.useRef(trackIndex);
  trackIndexRef.current = trackIndex;
  const onTrackChangeRef = React.useRef(onTrackChange);
  onTrackChangeRef.current = onTrackChange;

  const loadTrack = React.useCallback((index: number) => {
    const all = listRef.current;
    const nextIndex = ((index % all.length) + all.length) % all.length;
    const e = engineRef.current;
    if (e) {
      e.time = 0;
      e.duration = all[nextIndex]?.duration ?? 1;
    }
    trackIndexRef.current = nextIndex;
    setTrackIndex(nextIndex);
    onTrackChangeRef.current?.(nextIndex);
    wakeRef.current();
  }, []);

  // One rAF loop drives the clock, the meter and the disc whenever it is
  // off cruise. It sleeps once everything rests, and while off screen.
  React.useEffect(() => {
    const e = engineRef.current;
    if (!e) {
      return;
    }
    let raf = 0;
    let last = 0;

    const render = () => {
      paint(e, discRef.current, fillRef.current, rpmRef.current);
      const s = Math.floor(e.time);
      if (s !== clockRef.current) {
        const dir = s > clockRef.current ? 1 : -1;
        clockRef.current = s;
        setClock({ s, dir });
      }
    };

    const handleEnds = () => {
      if (e.time >= e.duration) {
        if (e.playing && !e.held && !e.barDrag) {
          loadTrack(trackIndexRef.current + 1);
          return;
        }
        e.time = e.duration;
      }
      if (e.time < 0) {
        e.time = 0;
      }
    };

    const isAwake = () =>
      e.playing || e.held || e.barDrag || e.omega !== 0 || e.env > 0;

    const tick = (now: number) => {
      const dt = last ? Math.min((now - last) / 1000, MAX_DT) : 0;
      last = now;
      if (e.held) {
        e.scrubOmega *= Math.exp(-dt / HOLD_SETTLE_S);
      } else if (!e.barDrag) {
        integrateDisc(e, dt, discRef.current);
      }
      handleEnds();
      updateMeter(e, dt, barRefs.current);
      render();
      if (isAwake() && e.visible) {
        raf = requestAnimationFrame(tick);
      } else {
        raf = 0;
        last = 0;
      }
    };

    const wake = () => {
      render();
      if (raf === 0 && e.visible) {
        last = 0;
        raf = requestAnimationFrame(tick);
      }
    };
    wakeRef.current = wake;

    let inView = true;
    const sync = () => {
      e.visible = inView && !document.hidden;
      if (e.visible) {
        e.cruise?.play();
        wake();
      } else {
        e.cruise?.pause();
        cancelAnimationFrame(raf);
        raf = 0;
      }
    };
    const observer = new IntersectionObserver(([entry]) => {
      inView = entry?.isIntersecting ?? true;
      sync();
    });
    if (rootRef.current) {
      observer.observe(rootRef.current);
    }
    document.addEventListener("visibilitychange", sync);

    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const syncMotion = () => {
      e.reduced = media.matches;
      if (e.reduced) {
        stopCruise(e, discRef.current);
      }
      wake();
    };
    syncMotion();
    media.addEventListener("change", syncMotion);

    return () => {
      cancelAnimationFrame(raf);
      observer.disconnect();
      document.removeEventListener("visibilitychange", sync);
      media.removeEventListener("change", syncMotion);
      e.cruise?.cancel();
      e.cruise = null;
    };
  }, [loadTrack]);

  const togglePlay = () => {
    const e = engineRef.current;
    if (!e) {
      return;
    }
    const nextPlaying = !e.playing;
    if (nextPlaying && e.time >= e.duration) {
      e.time = 0;
    }
    e.playing = nextPlaying;
    if (!nextPlaying) {
      // Hand the disc back to the loop so it can spin down.
      stopCruise(e, discRef.current);
    }
    setPlaying(nextPlaying);
    wakeRef.current();
  };

  const previous = () => {
    const e = engineRef.current;
    if (e && e.time > RESTART_THRESHOLD) {
      e.time = 0;
      wakeRef.current();
      return;
    }
    loadTrack(trackIndexRef.current - 1);
  };

  const next = () => loadTrack(trackIndexRef.current + 1);

  /* ---------------------------- Disc scrubbing ---------------------------- */

  const pointerAngle = (e: Engine, clientX: number, clientY: number) => {
    const dx = clientX - e.center.x;
    const dy = clientY - e.center.y;
    return {
      angle: (Math.atan2(dy, dx) * 180) / Math.PI,
      distance: Math.hypot(dx, dy),
    };
  };

  const onDiscDown = (event: React.PointerEvent<HTMLDivElement>) => {
    const e = engineRef.current;
    if (!e || event.button !== 0 || e.pointerId !== null) {
      return;
    }
    e.pointerId = event.pointerId;
    event.currentTarget.setPointerCapture(event.pointerId);
    const rect = event.currentTarget.getBoundingClientRect();
    e.center = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
    // A finger on the record stops it dead, cruise animation included.
    stopCruise(e, discRef.current);
    e.held = true;
    e.omega = 0;
    e.scrubOmega = 0;
    e.pointerAngle = pointerAngle(e, event.clientX, event.clientY).angle;
    e.lastMoveAt = performance.now();
    e.samples = [{ t: e.lastMoveAt, a: e.angle }];
    wakeRef.current();
  };

  const onDiscMove = (event: React.PointerEvent<HTMLDivElement>) => {
    const e = engineRef.current;
    if (!e?.held || e.pointerId !== event.pointerId) {
      return;
    }
    const { angle, distance } = pointerAngle(e, event.clientX, event.clientY);
    if (distance < DEAD_ZONE) {
      e.pointerAngle = angle;
      return;
    }
    // Unwrap across the ±180° seam.
    let delta = angle - e.pointerAngle;
    delta -= Math.round(delta / 360) * 360;
    e.pointerAngle = angle;

    const now = performance.now();
    const dt = Math.max(now - e.lastMoveAt, 1) / 1000;
    e.lastMoveAt = now;
    const instant = clamp(delta / dt, -MAX_OMEGA, MAX_OMEGA);
    e.scrubOmega += (instant - e.scrubOmega) * 0.35;

    // Track time follows the angle; faster turns cover more of the song.
    e.angle += delta;
    e.time = clamp(
      e.time + (delta / CRUISE) * scrubGain(e.scrubOmega),
      0,
      e.duration
    );

    e.samples.push({ t: now, a: e.angle });
    while (
      e.samples.length > 2 &&
      now - (e.samples[0]?.t ?? now) > VELOCITY_WINDOW_MS
    ) {
      e.samples.shift();
    }
    if (discRef.current) {
      discRef.current.style.transform = rotate(e.angle);
    }
  };

  const onDiscUp = (event: React.PointerEvent<HTMLDivElement>) => {
    const e = engineRef.current;
    if (!e?.held || e.pointerId !== event.pointerId) {
      return;
    }
    e.pointerId = null;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    e.held = false;
    const now = performance.now();
    const first = e.samples[0];
    let velocity = 0;
    if (first && now - e.lastMoveAt < STALE_MOVE_MS && now > first.t) {
      velocity = ((e.angle - first.a) / (now - first.t)) * 1000;
    }
    // It keeps the spin you gave it, then eases back to cruise.
    e.omega = e.reduced ? 0 : clamp(velocity, -MAX_OMEGA, MAX_OMEGA);
    e.scrubOmega = 0;
    wakeRef.current();
  };

  /* ----------------------------- Scrubber bar ----------------------------- */

  const seekFromPointer = (clientX: number) => {
    const e = engineRef.current;
    const rail = railRef.current;
    if (!(e && rail?.parentElement)) {
      return;
    }
    // The rail stretches, so measure its parent, which never moves.
    const rect = rail.parentElement.getBoundingClientRect();
    const x = clientX - rect.left;
    e.time = clamp(x / rect.width, 0, 1) * e.duration;

    // Past either end the rail stretches toward the pointer and thins,
    // giving less the further you pull.
    let over = 0;
    if (x < 0) {
      over = -damp(-x, RUBBER_MAX);
    } else if (x > rect.width) {
      over = damp(x - rect.width, RUBBER_MAX);
    }
    const stretch = 1 + Math.abs(over) / rect.width;
    const thin = 1 - (0.35 * Math.abs(over)) / RUBBER_MAX;
    rail.style.transition = "none";
    rail.style.transformOrigin = over < 0 ? "right center" : "left center";
    rail.style.transform =
      over === 0 ? "" : `scale(${stretch.toFixed(4)}, ${thin.toFixed(3)})`;
    wakeRef.current();
  };

  const onBarDown = (event: React.PointerEvent<HTMLDivElement>) => {
    const e = engineRef.current;
    if (!e || event.button !== 0 || e.pointerId !== null) {
      return;
    }
    e.pointerId = event.pointerId;
    event.currentTarget.setPointerCapture(event.pointerId);
    e.barDrag = true;
    seekFromPointer(event.clientX);
  };

  const onBarMove = (event: React.PointerEvent<HTMLDivElement>) => {
    const e = engineRef.current;
    if (e?.barDrag && e.pointerId === event.pointerId) {
      seekFromPointer(event.clientX);
    }
  };

  const onBarUp = (event: React.PointerEvent<HTMLDivElement>) => {
    const e = engineRef.current;
    if (!e?.barDrag || e.pointerId !== event.pointerId) {
      return;
    }
    e.pointerId = null;
    e.barDrag = false;
    const rail = railRef.current;
    if (rail) {
      rail.style.transition = RUBBER_RETURN;
      rail.style.transform = "";
    }
    wakeRef.current();
  };

  const onBarKey = (event: React.KeyboardEvent<HTMLDivElement>) => {
    const e = engineRef.current;
    if (!e) {
      return;
    }
    const targets: Record<string, number> = {
      ArrowRight: e.time + SEEK_STEP,
      ArrowUp: e.time + SEEK_STEP,
      ArrowLeft: e.time - SEEK_STEP,
      ArrowDown: e.time - SEEK_STEP,
      Home: 0,
      End: e.duration - 1,
    };
    const target = targets[event.key];
    if (target === undefined) {
      return;
    }
    event.preventDefault();
    e.time = clamp(target, 0, e.duration);
    wakeRef.current();
  };

  const body = (
    <>
      <style>{ROLL_KEYFRAMES}</style>
      <div className="flex items-center gap-5">
        <div className="relative @[22rem]/now-playing:size-32 size-28 shrink-0">
          <div
            className="size-full cursor-grab touch-none select-none rounded-full shadow-[0_6px_16px_-6px_rgba(0,0,0,0.45)] active:cursor-grabbing"
            data-now-playing-disc=""
            onLostPointerCapture={onDiscUp}
            onPointerCancel={onDiscUp}
            onPointerDown={onDiscDown}
            onPointerMove={onDiscMove}
            onPointerUp={onDiscUp}
            ref={discRef}
            title="Spin to scrub"
          >
            <Disc artwork={track.artwork ?? trackIndex % 3} />
          </div>
          <Tonearm down={playing} />
        </div>

        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <span aria-hidden="true" className="flex h-3.5 items-end gap-0.5">
              {Array.from({ length: BAR_COUNT }, (_, i) => (
                <span
                  className="h-full w-[3px] origin-bottom rounded-[1px] bg-(--now-playing-accent)"
                  // biome-ignore lint/suspicious/noArrayIndexKey: fixed set of bars
                  key={i}
                  ref={(node) => {
                    barRefs.current[i] = node;
                  }}
                  style={{ transform: `scaleY(${BAR_REST})` }}
                />
              ))}
            </span>
            <span className="font-medium text-[11px] text-zinc-500 uppercase tracking-wider dark:text-zinc-400">
              Now playing
            </span>
          </div>
          <h3 className="mt-2 truncate font-semibold text-base text-zinc-900 dark:text-zinc-50">
            {track.title}
          </h3>
          <p className="truncate text-sm text-zinc-500 dark:text-zinc-400">
            {track.artist}
          </p>
          <span
            className="mt-2 inline-block font-mono text-[11px] text-zinc-400 tabular-nums dark:text-zinc-500"
            ref={rpmRef}
          >
            {autoPlay ? "33⅓ rpm" : "0 rpm"}
          </span>
        </div>
      </div>

      <div className="mt-5">
        <div
          aria-label="Seek"
          aria-valuemax={track.duration}
          aria-valuemin={0}
          aria-valuenow={clock.s}
          aria-valuetext={`${formatTime(clock.s)} of ${formatTime(track.duration)}`}
          className="group/seek -my-2 cursor-pointer touch-none py-2 outline-none"
          onKeyDown={onBarKey}
          onLostPointerCapture={onBarUp}
          onPointerCancel={onBarUp}
          onPointerDown={onBarDown}
          onPointerMove={onBarMove}
          onPointerUp={onBarUp}
          role="slider"
          tabIndex={0}
        >
          <div className="h-1.5">
            <div
              className="h-full overflow-hidden rounded-full bg-zinc-200 ring-zinc-400 ring-offset-2 ring-offset-white group-focus-visible/seek:ring-2 dark:bg-zinc-800 dark:ring-offset-zinc-900"
              ref={railRef}
            >
              <div
                className="h-full w-full origin-left bg-(--now-playing-accent)"
                ref={fillRef}
                style={{ transform: "scaleX(0)" }}
              />
            </div>
          </div>
        </div>
        <div className="mt-2 flex justify-between font-medium text-xs text-zinc-500 tabular-nums dark:text-zinc-400">
          <RollingTime direction={clock.dir} seconds={clock.s} />
          <span>{formatTime(track.duration)}</span>
        </div>
      </div>

      <div className="mt-3 flex items-center justify-center gap-3">
        <button
          aria-label="Previous track"
          className={ICON_BUTTON}
          onClick={previous}
          type="button"
        >
          <SkipBack className="size-5" fill="currentColor" />
        </button>
        <button
          aria-label={playing ? "Pause" : "Play"}
          className="inline-flex size-12 items-center justify-center rounded-full bg-zinc-900 text-white transition-colors duration-150 hover:bg-zinc-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 focus-visible:ring-offset-white active:bg-zinc-600 dark:bg-zinc-100 dark:text-zinc-900 dark:active:bg-zinc-300 dark:focus-visible:ring-offset-zinc-900 dark:hover:bg-white"
          onClick={togglePlay}
          type="button"
        >
          {playing ? (
            <Pause className="size-5" fill="currentColor" />
          ) : (
            <Play className="size-5 translate-x-px" fill="currentColor" />
          )}
        </button>
        <button
          aria-label="Next track"
          className={ICON_BUTTON}
          onClick={next}
          type="button"
        >
          <SkipForward className="size-5" fill="currentColor" />
        </button>
      </div>
    </>
  );

  const style = { "--now-playing-accent": accent } as React.CSSProperties;

  if (glassEffect) {
    return (
      <div className="w-full max-w-sm" ref={rootRef} style={style}>
        <LiquidGlassCard
          className={cn(FRAME, "bg-white/50 dark:bg-zinc-900/50", className)}
          glassEffect
          glassSize="sm"
        >
          {body}
        </LiquidGlassCard>
      </div>
    );
  }

  return (
    <div
      className={cn(FRAME, "bg-white dark:bg-zinc-900", className)}
      ref={rootRef}
      style={style}
    >
      {body}
    </div>
  );
}

export { LiquidButton, LiquidGlassCard, NowPlaying as NotificationCenter };
export default NowPlaying;

"use client";

/**
 * @author: @dorianbaffier
 * @description: Liquid Slider
 * @version: 1.0.0
 * @date: 2026-10-14
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import {
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

const WIDTH = 280;
const HEIGHT = 360;
// The glass is a cylinder seen from a little above: its rim and floor are
// ellipses RY tall, its walls run from LEFT to RIGHT.
const LEFT = 84;
const RIGHT = 196;
const CX = (LEFT + RIGHT) / 2;
const RADIUS = (RIGHT - LEFT) / 2;
const RY = 9;
const RIM_Y = 104;
const FLOOR_Y = 312;
// Where the surface sits when the glass is empty and when it is full.
const EMPTY_Y = FLOOR_Y;
const FULL_Y = RIM_Y + 16;

// The surface is a row of columns that each bob up and down and pull on
// their neighbours: a 1D wave. Heights in px, time in seconds.
const COLUMNS = 34;
const STEP = 1 / 120;
const SPREAD = 2600;
const TENSION = 30;
const DAMPING = 2.4;
// Neighbouring columns drag on each other's speed, which smooths out
// the short, jagged ripples and leaves the long sloshes.
const VISCOSITY = 22;
const MAX_WAVE = 16;
// While dragging, the surface under the finger is pulled towards it this
// hard, and the finger's sideways speed piles the liquid up ahead of it.
const GRAB = 900;
const GRAB_REACH = 2.6;
const GRAB_MAX = 14;
const STIR = 0.55;
// The level chases its target on a spring: fast, but not instant, so a quick
// drag leaves the liquid behind the finger for a moment.
const LEVEL_STIFFNESS = 220;
const LEVEL_DAMPING = 26;
const MAX_BUBBLES = 14;
const REST_EPSILON = 0.02;

interface Bubble {
  x: number;
  y: number;
  r: number;
  speed: number;
  phase: number;
}

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max);
}

function haptic() {
  if (typeof navigator !== "undefined" && "vibrate" in navigator) {
    navigator.vibrate(4);
  }
}

// How far in front of / behind the centre line the surface ellipse reaches at
// each column, precomputed and rounded so server and browser markup match.
const COLUMN_X: number[] = [];
const DEPTH: number[] = [];
for (let i = 0; i < COLUMNS; i++) {
  const t = i / (COLUMNS - 1);
  const x = LEFT + t * (RIGHT - LEFT);
  COLUMN_X.push(Math.round(x * 100) / 100);
  const u = (x - CX) / RADIUS;
  DEPTH.push(Math.round(RY * Math.sqrt(Math.max(0, 1 - u * u)) * 100) / 100);
}

function levelToY(level: number) {
  return EMPTY_Y - level * (EMPTY_Y - FULL_Y);
}

function f(n: number) {
  return n.toFixed(2);
}

/** The top of the liquid: from the back edge across, then the front back. */
function surfacePath(levelY: number, heights: Float64Array) {
  let d = "";
  for (let i = 0; i < COLUMNS; i++) {
    const y = Math.min(levelY + heights[i] - DEPTH[i], FLOOR_Y);
    d += `${i === 0 ? "M" : "L"}${f(COLUMN_X[i])} ${f(y)}`;
  }
  for (let i = COLUMNS - 1; i >= 0; i--) {
    const y = Math.min(levelY + heights[i] + DEPTH[i], FLOOR_Y + DEPTH[i]);
    d += `L${f(COLUMN_X[i])} ${f(y)}`;
  }
  return `${d}Z`;
}

/** The body: the front edge of the surface, down the wall, along the floor. */
function bodyPath(levelY: number, heights: Float64Array) {
  let d = "";
  for (let i = 0; i < COLUMNS; i++) {
    const y = Math.min(levelY + heights[i] + DEPTH[i], FLOOR_Y + DEPTH[i]);
    d += `${i === 0 ? "M" : "L"}${f(COLUMN_X[i])} ${f(y)}`;
  }
  d += `L${RIGHT} ${FLOOR_Y} A${RADIUS} ${RY} 0 0 1 ${LEFT} ${FLOOR_Y}Z`;
  return d;
}

/** A thin line along the front lip, where light catches the surface. */
function lipPath(levelY: number, heights: Float64Array) {
  let d = "";
  for (let i = 1; i < COLUMNS - 1; i++) {
    const y = Math.min(levelY + heights[i] + DEPTH[i], FLOOR_Y + DEPTH[i]);
    d += `${i === 1 ? "M" : "L"}${f(COLUMN_X[i])} ${f(y)}`;
  }
  return d;
}

/** Surface height (px from the level) at an x, between two columns. */
function heightAt(heights: Float64Array, x: number) {
  const t = clamp((x - LEFT) / (RIGHT - LEFT), 0, 1) * (COLUMNS - 1);
  const i = Math.floor(t);
  const j = Math.min(i + 1, COLUMNS - 1);
  return heights[i] + (heights[j] - heights[i]) * (t - i);
}

const FLAT = new Float64Array(COLUMNS);

export interface LiquidSliderProps {
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Shown after the number. */
  unit?: string;
  label?: string;
  /** Formats the readout and `aria-valuetext`. */
  formatValue?: (value: number) => string;
  className?: string;
}

const defaultFormat = (value: number) => value.toLocaleString("en-US");

export default function LiquidSlider({
  value: valueProp,
  defaultValue = 1250,
  onValueChange,
  min = 0,
  max = 2000,
  step = 50,
  unit = "ml",
  label = "Water today",
  formatValue = defaultFormat,
  className,
}: LiquidSliderProps) {
  const [internal, setInternal] = useState(defaultValue);
  const value = clamp(valueProp ?? internal, min, max);
  const [dragging, setDragging] = useState(false);
  const labelId = useId();

  const surfaceRef = useRef<SVGPathElement>(null);
  const bodyRef = useRef<SVGPathElement>(null);
  const lipRef = useRef<SVGPathElement>(null);
  const bubblesRef = useRef<(SVGCircleElement | null)[]>([]);
  const svgRef = useRef<SVGSVGElement>(null);

  const fraction = (max - min > 0 ? (value - min) / (max - min) : 0) || 0;
  const initialY = levelToY(fraction);

  const sim = useRef({
    heights: new Float64Array(COLUMNS),
    speeds: new Float64Array(COLUMNS),
    accels: new Float64Array(COLUMNS),
    level: fraction,
    levelSpeed: 0,
    target: fraction,
    bubbles: [] as Bubble[],
    raf: 0,
    last: 0,
    carry: 0,
    // Pointer, while held: where it is, in drawing units, and its sideways
    // speed.
    held: false,
    pointerId: -1,
    px: 0,
    py: 0,
    pvx: 0,
    lastPx: 0,
    lastT: 0,
    reduceMotion: false,
    seed: 1,
  });

  // Handlers outlive the render they came from; read the props here.
  const latest = useRef({ value, min, max, step, onValueChange });
  latest.current = { value, min, max, step, onValueChange };

  const commit = useCallback(
    (next: number) => {
      const { min: lo, max: hi, step: inc } = latest.current;
      const snapped = clamp(
        Number((Math.round((next - lo) / inc) * inc + lo).toFixed(10)),
        lo,
        hi
      );
      if (snapped === latest.current.value) {
        return;
      }
      // A light tick each time the level crosses a quarter.
      const quarter = (hi - lo) / 4;
      if (
        Math.floor((snapped - lo) / quarter) !==
        Math.floor((latest.current.value - lo) / quarter)
      ) {
        haptic();
      }
      latest.current.value = snapped;
      if (valueProp === undefined) {
        setInternal(snapped);
      }
      latest.current.onValueChange?.(snapped);
    },
    [valueProp]
  );

  const random = useCallback(() => {
    // Deterministic, so bubbles never depend on Math.random during render.
    const s = sim.current;
    s.seed = (s.seed * 16_807) % 2_147_483_647;
    return s.seed / 2_147_483_647;
  }, []);

  const draw = useCallback(() => {
    const s = sim.current;
    const y = levelToY(s.level);
    surfaceRef.current?.setAttribute("d", surfacePath(y, s.heights));
    bodyRef.current?.setAttribute("d", bodyPath(y, s.heights));
    lipRef.current?.setAttribute("d", lipPath(y, s.heights));
    for (let i = 0; i < MAX_BUBBLES; i++) {
      const el = bubblesRef.current[i];
      const b = s.bubbles[i];
      if (!el) {
        continue;
      }
      if (b) {
        const wobble = Math.sin(b.phase) * 1.6;
        el.setAttribute("cx", f(b.x + wobble));
        el.setAttribute("cy", f(b.y));
        el.setAttribute("r", f(b.r));
        el.style.opacity = "1";
      } else {
        el.style.opacity = "0";
      }
    }
  }, []);

  // The level rides a spring towards its target. When it rises fast, the
  // pour drags bubbles in from the floor.
  const stepLevel = useCallback(() => {
    const s = sim.current;
    const force =
      (s.target - s.level) * LEVEL_STIFFNESS - s.levelSpeed * LEVEL_DAMPING;
    s.levelSpeed += force * STEP;
    s.level += s.levelSpeed * STEP;
    if (
      s.levelSpeed > 0.5 &&
      s.bubbles.length < MAX_BUBBLES &&
      random() < s.levelSpeed * 0.05
    ) {
      s.bubbles.push({
        x: LEFT + 10 + random() * (RIGHT - LEFT - 20),
        y: FLOOR_Y + 2,
        r: 1.2 + random() * 2,
        speed: 40 + random() * 50,
        phase: random() * Math.PI * 2,
      });
    }
  }, [random]);

  // One step of the wave: each column accelerates towards its neighbours'
  // average and back to rest, then the volume is re-levelled so the waves
  // only move liquid around.
  const stepWaves = useCallback(() => {
    const s = sim.current;
    const { heights: h, speeds: v, accels: a } = s;
    const levelY = levelToY(s.level);
    let mean = 0;
    for (let i = 0; i < COLUMNS; i++) {
      const l = i === 0 ? 0 : i - 1;
      const r = i === COLUMNS - 1 ? i : i + 1;
      let accel =
        SPREAD * (h[l] + h[r] - 2 * h[i]) +
        VISCOSITY * (v[l] + v[r] - 2 * v[i]) -
        TENSION * h[i] -
        DAMPING * v[i];
      if (s.held) {
        const reach = (COLUMN_X[i] - s.px) / ((RIGHT - LEFT) / COLUMNS);
        const weight = Math.exp(-(reach * reach) / (GRAB_REACH * GRAB_REACH));
        const pull = clamp(s.py - (levelY + h[i]), -GRAB_MAX, GRAB_MAX);
        accel += GRAB * pull * weight * 0.05;
        accel -= STIR * s.pvx * ((i - (COLUMNS - 1) / 2) / COLUMNS) * 60;
      }
      a[i] = accel;
    }
    for (let i = 0; i < COLUMNS; i++) {
      v[i] += a[i] * STEP;
      h[i] = clamp(h[i] + v[i] * STEP, -MAX_WAVE, MAX_WAVE);
      mean += h[i];
    }
    mean /= COLUMNS;
    let energy = 0;
    for (let i = 0; i < COLUMNS; i++) {
      h[i] -= mean;
      energy += Math.abs(h[i]) + Math.abs(v[i]) * STEP;
    }
    return energy / COLUMNS;
  }, []);

  // Bubbles rise with a wobble and pop at the surface, leaving a ripple.
  const stepBubbles = useCallback(() => {
    const s = sim.current;
    const levelY = levelToY(s.level);
    for (let i = s.bubbles.length - 1; i >= 0; i--) {
      const b = s.bubbles[i];
      b.y -= b.speed * STEP;
      b.phase += STEP * 9;
      if (b.y <= levelY + heightAt(s.heights, b.x) + 1) {
        const col = Math.round(((b.x - LEFT) / (RIGHT - LEFT)) * (COLUMNS - 1));
        s.speeds[clamp(col, 0, COLUMNS - 1)] -= 30 * b.r;
        s.bubbles.splice(i, 1);
      }
    }
  }, []);

  const tick = useCallback(
    (now: number) => {
      const s = sim.current;
      s.raf = 0;
      const elapsed = s.last ? Math.min((now - s.last) / 1000, 0.05) : STEP;
      s.last = now;
      s.carry += elapsed;
      let energy = 0;
      while (s.carry >= STEP) {
        stepLevel();
        energy = stepWaves();
        stepBubbles();
        s.carry -= STEP;
      }
      // The sideways speed fades when the pointer stops moving.
      s.pvx *= 0.85;
      draw();
      const settled =
        !s.held &&
        energy < REST_EPSILON &&
        Math.abs(s.target - s.level) < 0.0005 &&
        Math.abs(s.levelSpeed) < 0.001 &&
        s.bubbles.length === 0;
      if (settled) {
        s.level = s.target;
        s.heights.fill(0);
        s.speeds.fill(0);
        s.last = 0;
        draw();
        return;
      }
      s.raf = requestAnimationFrame(tick);
    },
    [draw, stepBubbles, stepLevel, stepWaves]
  );

  const wake = useCallback(() => {
    const s = sim.current;
    if (s.reduceMotion) {
      s.level = s.target;
      s.levelSpeed = 0;
      s.heights.fill(0);
      s.speeds.fill(0);
      s.bubbles.length = 0;
      draw();
      return;
    }
    if (!s.raf) {
      s.raf = requestAnimationFrame(tick);
    }
  }, [draw, tick]);

  useEffect(() => {
    const s = sim.current;
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    s.reduceMotion = query.matches;
    const onChange = () => {
      s.reduceMotion = query.matches;
    };
    query.addEventListener("change", onChange);
    // Pause while the tab is hidden; the loop picks up again on return.
    const onVisibility = () => {
      if (document.hidden && s.raf) {
        cancelAnimationFrame(s.raf);
        s.raf = 0;
        s.last = 0;
      } else if (!document.hidden) {
        wake();
      }
    };
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      query.removeEventListener("change", onChange);
      document.removeEventListener("visibilitychange", onVisibility);
      cancelAnimationFrame(s.raf);
      s.raf = 0;
    };
  }, [wake]);

  // A value set from outside (a controlled prop, or a keypress) moves the
  // target; the liquid follows on its own.
  useEffect(() => {
    const s = sim.current;
    if (s.held) {
      return;
    }
    if (Math.abs(s.target - fraction) > 1e-6) {
      s.target = fraction;
      wake();
    }
  }, [fraction, wake]);

  const localPoint = (event: PointerEvent) => {
    const rect = svgRef.current?.getBoundingClientRect();
    if (!rect) {
      return { x: 0, y: 0 };
    }
    return {
      x: ((event.clientX - rect.left) / rect.width) * WIDTH,
      y: ((event.clientY - rect.top) / rect.height) * HEIGHT,
    };
  };

  const follow = (event: PointerEvent) => {
    const s = sim.current;
    const point = localPoint(event);
    const now = event.timeStamp;
    if (s.lastT && now > s.lastT) {
      const vx = ((point.x - s.lastPx) / (now - s.lastT)) * 1000;
      s.pvx = s.pvx * 0.6 + clamp(vx, -900, 900) * 0.4;
    }
    s.lastPx = point.x;
    s.lastT = now;
    s.px = clamp(point.x, LEFT, RIGHT);
    s.py = clamp(point.y, FULL_Y, EMPTY_Y);
    const raw = clamp((EMPTY_Y - point.y) / (EMPTY_Y - FULL_Y), 0, 1);
    s.target = raw;
    const { min: lo, max: hi } = latest.current;
    commit(lo + raw * (hi - lo));
    wake();
  };

  const handlePointerDown = (event: PointerEvent<SVGSVGElement>) => {
    if (event.pointerType === "mouse" && event.button !== 0) {
      return;
    }
    const s = sim.current;
    // A second finger mid-drag is ignored rather than jumping the level.
    if (s.held) {
      return;
    }
    event.preventDefault();
    // Focus without scrolling, so the keyboard picks up where the hand left.
    (event.currentTarget.parentElement as HTMLElement | null)?.focus({
      preventScroll: true,
    });
    event.currentTarget.setPointerCapture(event.pointerId);
    s.held = true;
    s.pointerId = event.pointerId;
    s.lastT = 0;
    s.pvx = 0;
    setDragging(true);
    follow(event);
  };

  const handlePointerMove = (event: PointerEvent<SVGSVGElement>) => {
    const s = sim.current;
    if (s.held && s.pointerId === event.pointerId) {
      follow(event);
    }
  };

  const handlePointerUp = (event: PointerEvent<SVGSVGElement>) => {
    const s = sim.current;
    if (!s.held || s.pointerId !== event.pointerId) {
      return;
    }
    s.held = false;
    setDragging(false);
    // Settle on the step the readout shows.
    const { value: v, min: lo, max: hi } = latest.current;
    s.target = hi - lo > 0 ? (v - lo) / (hi - lo) : 0;
    wake();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const { min: lo, max: hi, step: inc } = latest.current;
    const big = Math.max(inc, (hi - lo) / 10);
    const moves: Record<string, number> = {
      ArrowUp: value + inc,
      ArrowRight: value + inc,
      ArrowDown: value - inc,
      ArrowLeft: value - inc,
      PageUp: value + big,
      PageDown: value - big,
      Home: lo,
      End: hi,
    };
    const next = Object.hasOwn(moves, event.key) ? moves[event.key] : null;
    if (next === null) {
      return;
    }
    event.preventDefault();
    commit(next);
    // A drop in the middle, so the key gets a ripple too.
    const s = sim.current;
    if (!s.reduceMotion) {
      s.speeds[Math.floor(COLUMNS / 2)] += next > value ? -90 : 90;
      wake();
    }
  };

  const ticks = [0, 0.25, 0.5, 0.75, 1];
  const initialSurface = surfacePath(initialY, FLAT);
  const initialBody = bodyPath(initialY, FLAT);
  const initialLip = lipPath(initialY, FLAT);

  return (
    <div
      aria-labelledby={labelId}
      aria-orientation="vertical"
      aria-valuemax={max}
      aria-valuemin={min}
      aria-valuenow={value}
      aria-valuetext={`${formatValue(value)} ${unit}`.trim()}
      className={cn(
        "relative select-none overflow-hidden rounded-3xl border border-zinc-200 bg-white text-zinc-900 outline-none focus-visible:outline-2 focus-visible:outline-zinc-400 focus-visible:outline-offset-2 dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-100",
        className
      )}
      onKeyDown={handleKeyDown}
      role="slider"
      style={{ width: WIDTH, height: HEIGHT }}
      tabIndex={0}
    >
      <div className="pointer-events-none absolute inset-x-0 top-0 p-6">
        <p className="text-sm text-zinc-500" id={labelId}>
          {label}
        </p>
        <p className="mt-0.5 font-medium text-2xl tabular-nums tracking-tight">
          {formatValue(value)}
          <span className="ml-1 text-base text-zinc-400">{unit}</span>
        </p>
      </div>

      <svg
        aria-hidden="true"
        className={cn(
          "absolute inset-0 touch-none",
          dragging ? "cursor-grabbing" : "cursor-grab"
        )}
        height={HEIGHT}
        onLostPointerCapture={handlePointerUp}
        onPointerCancel={handlePointerUp}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        ref={svgRef}
        viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
        width={WIDTH}
      >
        <defs>
          <clipPath id={`${labelId}-glass`}>
            <path
              d={`M${LEFT} ${RIM_Y} L${RIGHT} ${RIM_Y} L${RIGHT} ${FLOOR_Y} A${RADIUS} ${RY} 0 0 1 ${LEFT} ${FLOOR_Y} Z`}
            />
          </clipPath>
        </defs>

        {/* The back of the glass. */}
        <path
          className="fill-zinc-50 dark:fill-zinc-900/60"
          d={`M${LEFT} ${RIM_Y} A${RADIUS} ${RY} 0 0 1 ${RIGHT} ${RIM_Y} L${RIGHT} ${FLOOR_Y} A${RADIUS} ${RY} 0 0 1 ${LEFT} ${FLOOR_Y} Z`}
        />
        <path
          className="fill-none stroke-zinc-200 dark:stroke-zinc-800"
          d={`M${LEFT} ${FLOOR_Y} A${RADIUS} ${RY} 0 0 1 ${RIGHT} ${FLOOR_Y}`}
          strokeWidth={1}
        />

        <g clipPath={`url(#${labelId}-glass)`}>
          <path className="fill-sky-500" d={initialBody} ref={bodyRef} />
          {Array.from({ length: MAX_BUBBLES }, (_, i) => (
            <circle
              className="fill-white/25 stroke-white/70"
              cx={CX}
              cy={FLOOR_Y}
              // biome-ignore lint/suspicious/noArrayIndexKey: a fixed pool of circles reused by index
              key={i}
              r={1}
              ref={(el) => {
                bubblesRef.current[i] = el;
              }}
              strokeWidth={0.75}
              style={{ opacity: 0 }}
            />
          ))}
          <path
            className="fill-sky-300 dark:fill-sky-400"
            d={initialSurface}
            ref={surfaceRef}
          />
          <path
            className="fill-none stroke-white/60"
            d={initialLip}
            ref={lipRef}
            strokeLinecap="round"
            strokeWidth={1}
          />
        </g>

        {/* Graduations, printed on the front of the glass. */}
        {ticks.map((t) => {
          const y = Math.round(levelToY(t) + RY * 0.55);
          const tickValue = min + t * (max - min);
          return (
            <g key={t}>
              <line
                className="stroke-zinc-900/25 dark:stroke-white/30"
                strokeWidth={1}
                x1={RIGHT - 14}
                x2={RIGHT - 4}
                y1={y}
                y2={y}
              />
              <text
                className="fill-zinc-400 text-[10px] tabular-nums dark:fill-zinc-500"
                dominantBaseline="middle"
                x={RIGHT + 8}
                y={y}
              >
                {formatValue(tickValue)}
              </text>
            </g>
          );
        })}

        {/* The glass itself: rim, walls and the front of the floor. */}
        <ellipse
          className="fill-none stroke-zinc-300 dark:stroke-zinc-700"
          cx={CX}
          cy={RIM_Y}
          rx={RADIUS}
          ry={RY}
          strokeWidth={1.5}
        />
        <path
          className="fill-none stroke-zinc-300 dark:stroke-zinc-700"
          d={`M${LEFT} ${RIM_Y} L${LEFT} ${FLOOR_Y} A${RADIUS} ${RY} 0 0 0 ${RIGHT} ${FLOOR_Y} L${RIGHT} ${RIM_Y}`}
          strokeWidth={1.5}
        />
        {/* A strip of reflection down the left wall. */}
        <line
          className="stroke-white/50 dark:stroke-white/10"
          strokeLinecap="round"
          strokeWidth={3}
          x1={LEFT + 9}
          x2={LEFT + 9}
          y1={RIM_Y + 22}
          y2={FLOOR_Y - 14}
        />
      </svg>
    </div>
  );
}

import type { CSSProperties, HTMLAttributes } from "react";
