interface LoaderProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "title" | "children"> {
  title?: string;
  /** Pass an empty string to show the title alone. */
  subtitle?: string;
  size?: "sm" | "md" | "lg";
}

const SIZE_CONFIG = {
  sm: {
    container: "size-20",
    titleClass: "text-sm font-medium",
    subtitleClass: "text-xs",
    spacing: "space-y-2",
    maxWidth: "max-w-48",
  },
  md: {
