const RINGS: { id: string; style: CSSProperties }[] = [
  {
    id: "outer",
    style: {
      background:
        "conic-gradient(from 0deg, transparent 0deg, currentColor 90deg, transparent 180deg)",
      mask: ringMask("transparent 35%, black 37%, black 39%, transparent 41%"),
      WebkitMask: ringMask(
        "transparent 35%, black 37%, black 39%, transparent 41%"
      ),
      opacity: 0.8,
      animationDuration: "3s",
    },
  },
  {
    id: "primary",
    style: {
      background:
        "conic-gradient(from 0deg, transparent 0deg, currentColor 120deg, color-mix(in srgb, currentColor 50%, transparent) 240deg, transparent 360deg)",
      mask: ringMask("transparent 42%, black 44%, black 48%, transparent 50%"),
      WebkitMask: ringMask(
        "transparent 42%, black 44%, black 48%, transparent 50%"
      ),
      opacity: 0.9,
      animationDuration: "1.2s",
    },
  },
  {
    id: "counter",
    style: {
      background:
        "conic-gradient(from 180deg, transparent 0deg, color-mix(in srgb, currentColor 60%, transparent) 45deg, transparent 90deg)",
      mask: ringMask("transparent 52%, black 54%, black 56%, transparent 58%"),
      WebkitMask: ringMask(
        "transparent 52%, black 54%, black 56%, transparent 58%"
      ),
      opacity: 0.35,
      animationDuration: "4s",
      animationDirection: "reverse",
    },
  },
  {
    id: "accent",
    style: {
      background:
        "conic-gradient(from 270deg, transparent 0deg, color-mix(in srgb, currentColor 40%, transparent) 20deg, transparent 40deg)",
      mask: ringMask("transparent 61%, black 62%, black 63%, transparent 64%"),
      WebkitMask: ringMask(
        "transparent 61%, black 62%, black 63%, transparent 64%"
      ),
      opacity: 0.5,
      animationDuration: "3.5s",
    },
  },
];

export default function Loader({
  title = "Configuring your account...",
  subtitle = "Please wait while we prepare everything for you",
  size = "md",
  className,
  ...props
}: LoaderProps) {
  const config = SIZE_CONFIG[size];

  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-8 p-8",
        className
      )}
      {...props}
    >
      <div
        aria-hidden="true"
        className={cn("relative text-black dark:text-white", config.container)}
      >
        {RINGS.map((ring) => (
          <div
            className="absolute inset-0 rounded-full motion-safe:animate-spin motion-reduce:animate-pulse"
            key={ring.id}
            style={ring.style}
          />
        ))}
      </div>

      <output
        aria-live="polite"
        className={cn(
          "block text-center starting:opacity-0 transition-opacity duration-200 ease-out",
          config.spacing,
          config.maxWidth
        )}
      >
        <span
          className={cn(
            config.titleClass,
            "block text-black/90 leading-[1.15] tracking-[-0.02em] antialiased dark:text-white/90"
          )}
        >
          {title}
        </span>
        {subtitle && (
          <span
            className={cn(
              config.subtitleClass,
              "block font-normal text-black/60 leading-[1.45] tracking-[-0.01em] antialiased dark:text-white/60"
            )}
          >
            {subtitle}
          </span>
        )}
      </output>
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Location Picker
 * @version: 1.0.0
 * @date: 2026-10-22
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import { Check, Footprints, LocateFixed } from "lucide-react";
import {
  AnimatePresence,
  animate,
  motion,
  useMotionValue,
  useReducedMotion,
  useTransform,
} from "motion/react";
import {
  type KeyboardEvent,
  type PointerEvent,
  useEffect,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

const EASE_OUT = [0.23, 1, 0.32, 1] as const;
const GLIDE = { type: "spring", stiffness: 260, damping: 32 } as const;
/** The drawn town, in px. */
const W = 1200;
const H = 1080;
/** Map pixels walked in a minute. */
const WALK = 70;
/** A pickup this close to a crossing is named by the crossing. */
const CORNER = 30;
const KEY_STEP = 64;
/** The town is drawn at this scale, so a few blocks fit around the pin. */
const ZOOM = 0.62;

interface Street {
  name: string;
  width: number;
  from: [number, number];
  to: [number, number];
}

const AVENUES = [
  "Mercer Ave",
  "Hudson Ave",
  "Grand Ave",
  "Orchard Ave",
  "Bowery",
];
const AVENUE_X = [180, 380, 580, 780, 980];
const CROSS_Y = [120, 280, 440, 600, 760, 920];

const STREETS: Street[] = [
  ...AVENUES.map(
    (name, i): Street => ({
      name,
      width: 12,
      from: [AVENUE_X[i], 0],
      to: [AVENUE_X[i], H],
    })
  ),
  ...CROSS_Y.map(
    (y, i): Street => ({
      name: `${["1st", "2nd", "3rd", "4th", "5th", "6th"][i]} St`,
      width: 8,
      from: [0, y],
      to: [W, y],
    })
  ),
  { name: "Broadway", width: 12, from: [120, 1020], to: [1140, 60] },
];

/** No pickups in the river or the park. */
const RIVER_X = 112;
const PARK = { x: 598, y: 456, w: 166, h: 128 };
const YOU: [number, number] = [470, 660];

const inPark = (x: number, y: number) =>
  x > PARK.x - 4 &&
  x < PARK.x + PARK.w + 4 &&
  y > PARK.y - 4 &&
  y < PARK.y + PARK.h + 4;

/** Points along every street where a car can stop. */
const STOPS = STREETS.flatMap((street, s) => {
  const [x0, y0] = street.from;
  const [x1, y1] = street.to;
  const steps = Math.ceil(Math.hypot(x1 - x0, y1 - y0) / 6);
  const out: { x: number; y: number; s: number; t: number }[] = [];
  for (let k = 0; k <= steps; k++) {
    const t = k / steps;
    const x = x0 + (x1 - x0) * t;
    const y = y0 + (y1 - y0) * t;
    if (x > RIVER_X + 14 && !inPark(x, y) && y > 20 && y < H - 20) {
      out.push({ x, y, s, t });
    }
  }
  return out;
});

function nearestStop(x: number, y: number) {
  let best = STOPS[0];
  let bestD = Number.POSITIVE_INFINITY;
  for (const stop of STOPS) {
    const d = (stop.x - x) ** 2 + (stop.y - y) ** 2;
    if (d < bestD) {
      bestD = d;
      best = stop;
    }
  }
  return best;
}

const distanceTo = (street: Street, x: number, y: number) => {
  const [x0, y0] = street.from;
  const [x1, y1] = street.to;
  const dx = x1 - x0;
  const dy = y1 - y0;
  const t = Math.max(
    0,
    Math.min(1, ((x - x0) * dx + (y - y0) * dy) / (dx * dx + dy * dy))
  );
  return Math.hypot(x0 + dx * t - x, y0 + dy * t - y);
};

/** "Grand Ave & 3rd St" at a corner, "214 Grand Ave" along the block. */
function addressFor(stop: (typeof STOPS)[number]) {
  const street = STREETS[stop.s];
  const corner = STREETS.find(
    (other, i) => i !== stop.s && distanceTo(other, stop.x, stop.y) < CORNER
  );
  if (corner) {
    return `${street.name} & ${corner.name}`;
  }
  const number = 100 + Math.round(stop.t * 220) * 2;
  return `${number} ${street.name}`;
}

interface Lot {
  x: number;
  y: number;
  w: number;
  h: number;
}

/** Split a block into lots and leave a few empty, like a real one. */
function lotsIn(block: Lot, rand: () => number, out: Lot[]) {
  const cols = block.w > 120 ? 3 : 2;
  const rows = block.h > 100 ? 2 : 1;
  const gap = 8;
  const lw = (block.w - gap * (cols - 1)) / cols;
  const lh = (block.h - gap * (rows - 1)) / rows;
  for (let a = 0; a < cols; a++) {
    for (let b = 0; b < rows; b++) {
      const shrink = rand() * 0.25;
      if (rand() > 0.25) {
        out.push({
          x: block.x + a * (lw + gap),
          y: block.y + b * (lh + gap),
          w: lw * (1 - shrink),
          h: lh * (1 - shrink * 0.6),
        });
      }
    }
  }
}

/** A seeded town of buildings, so every block has a little texture. */
function buildings() {
  let seed = 7;
  const rand = () => {
    seed = (seed * 9301 + 49_297) % 233_280;
    return seed / 233_280;
  };
  const xs = [RIVER_X + 14, ...AVENUE_X, W];
  const ys = [0, ...CROSS_Y, H];
  const out: Lot[] = [];
  for (let i = 0; i < xs.length - 1; i++) {
    for (let j = 0; j < ys.length - 1; j++) {
      const block = {
        x: xs[i] + 14,
        y: ys[j] + 12,
        w: xs[i + 1] - xs[i] - 28,
        h: ys[j + 1] - ys[j] - 24,
      };
      const open = inPark(block.x + block.w / 2, block.y + block.h / 2);
      if (block.w >= 20 && block.h >= 20 && !open) {
        lotsIn(block, rand, out);
      }
    }
  }
  return out;
}

const BUILDINGS = buildings();
/** Where the pickup starts: the curb a block or so from you. */
