type Status = "moving" | "locating" | "ready";

function AddressLine({
  status,
  address,
  minutes,
  reduceMotion,
}: {
  status: Status;
  address: string;
  minutes: number;
  reduceMotion: boolean;
}) {
  let line = address;
  if (status === "moving") {
    line = "Move the map to set your pickup";
  } else if (status === "locating") {
    line = "Finding the curb…";
  }
  return (
    <div
      aria-live="polite"
      className="relative h-10 min-w-0 flex-1 overflow-hidden"
    >
      <AnimatePresence initial={false} mode="popLayout">
        <motion.div
          animate={{ opacity: 1, y: 0 }}
          className="absolute inset-0 flex flex-col justify-center leading-tight"
          exit={{ opacity: 0, y: -8 }}
          initial={{ opacity: 0, y: 8 }}
          key={line}
          transition={{ duration: reduceMotion ? 0 : 0.18, ease: EASE_OUT }}
        >
          <p
            className={cn(
              "truncate text-sm",
              status === "ready"
                ? "font-medium text-zinc-900 dark:text-zinc-100"
                : "text-zinc-500 dark:text-zinc-400"
            )}
          >
            {line}
          </p>
          {status === "ready" && (
            <p className="flex items-center gap-1 text-xs text-zinc-500 tabular-nums dark:text-zinc-400">
              <Footprints aria-hidden className="size-3" />
              {minutes < 1 ? "Right where you are" : `${minutes} min walk`}
            </p>
          )}
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

export interface LocationPickerProps {
  /** Called with the street address when the pickup is confirmed. */
  onConfirm?: (pickup: { address: string; x: number; y: number }) => void;
  className?: string;
}

/**
 * Setting a pickup point the way ride apps do. Drag the map under a fixed
 * pin: the pin lifts off its shadow while you move, the map glides so it
 * lands on the nearest curb, and the pin drops and the street rolls in.
 * The river and the park won't take a pickup.
 */
export default function LocationPicker({
  onConfirm,
  className,
}: LocationPickerProps) {
  const mapRef = useRef<HTMLButtonElement>(null);
  const cx = useMotionValue(START.x);
  const cy = useMotionValue(START.y);
  const [view, setView] = useState({ w: 360, h: 300 });
  const [lifted, setLifted] = useState(false);
  const [status, setStatus] = useState<Status>("ready");
  const [stop, setStop] = useState(START);
  const [confirmed, setConfirmed] = useState(false);
  const drag = useRef({ x: 0, y: 0, cx: 0, cy: 0, moved: false, on: false });
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const reduceMotion = Boolean(useReducedMotion());

  const tx = useTransform(cx, (v) => -v * ZOOM);
  const ty = useTransform(cy, (v) => -v * ZOOM);

  useEffect(() => {
    const el = mapRef.current;
    if (!el) {
      return;
    }
    const measure = () => setView({ w: el.clientWidth, h: el.clientHeight });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => {
      observer.disconnect();
      clearTimeout(timer.current);
      // A glide finishing after unmount would start the lookup timer again.
      cx.stop();
      cy.stop();
    };
  }, [cx, cy]);

  const clampX = (v: number) =>
    Math.min(W - view.w / 2 / ZOOM, Math.max(view.w / 2 / ZOOM, v));
  const clampY = (v: number) =>
    Math.min(H - view.h / 2 / ZOOM, Math.max(view.h / 2 / ZOOM, v));

  /** Glide to the curb nearest (x, y), then put the pin down there. */
  const settle = (x: number, y: number) => {
    const next = nearestStop(x, y);
    setLifted(true);
    setStatus("locating");
    setConfirmed(false);
    clearTimeout(timer.current);
    const land = () => {
      setLifted(false);
      // A beat to "look up" the street, like a real geocoder would.
      timer.current = setTimeout(
        () => {
          setStop(next);
          setStatus("ready");
        },
        reduceMotion ? 0 : 260
      );
    };
    if (reduceMotion) {
      cx.set(next.x);
      cy.set(next.y);
      land();
      return;
    }
    animate(cx, next.x, GLIDE);
    animate(cy, next.y, { ...GLIDE, onComplete: land });
  };

  const onDown = (event: PointerEvent<HTMLButtonElement>) => {
    if (event.button !== 0) {
      return;
    }
    cx.stop();
    cy.stop();
    event.currentTarget.setPointerCapture(event.pointerId);
    drag.current = {
      x: event.clientX,
      y: event.clientY,
      cx: cx.get(),
      cy: cy.get(),
      moved: false,
      on: true,
    };
  };

  const onMove = (event: PointerEvent<HTMLButtonElement>) => {
    const d = drag.current;
    if (!d.on) {
      return;
    }
    const dx = event.clientX - d.x;
    const dy = event.clientY - d.y;
    if (!d.moved && Math.hypot(dx, dy) > 4) {
      d.moved = true;
      clearTimeout(timer.current);
      setLifted(true);
      setStatus("moving");
      setConfirmed(false);
    }
    if (d.moved) {
      cx.set(clampX(d.cx - dx / ZOOM));
      cy.set(clampY(d.cy - dy / ZOOM));
    }
  };

  const onUp = (event: PointerEvent<HTMLButtonElement>) => {
    const d = drag.current;
    if (!d.on) {
      return;
    }
    d.on = false;
    if (d.moved) {
      settle(cx.get(), cy.get());
      return;
    }
    // A tap moves the pickup to where you tapped.
    const rect = event.currentTarget.getBoundingClientRect();
    settle(
      clampX(cx.get() + (event.clientX - rect.left - view.w / 2) / ZOOM),
      clampY(cy.get() + (event.clientY - rect.top - view.h / 2) / ZOOM)
    );
  };

  const onKey = (event: KeyboardEvent<HTMLButtonElement>) => {
    const moves: Record<string, [number, number]> = {
      ArrowUp: [0, -KEY_STEP],
      ArrowDown: [0, KEY_STEP],
      ArrowLeft: [-KEY_STEP, 0],
      ArrowRight: [KEY_STEP, 0],
    };
    const move = moves[event.key];
    if (move) {
      event.preventDefault();
      settle(clampX(cx.get() + move[0]), clampY(cy.get() + move[1]));
    }
  };

  const address = addressFor(stop);
  const minutes = Math.round(
    Math.hypot(stop.x - YOU[0], stop.y - YOU[1]) / WALK
  );
  const spring = reduceMotion
    ? { duration: 0 }
    : { type: "spring" as const, duration: 0.42, bounce: 0.35 };

  return (
    <div
      className={cn(
        "w-full max-w-sm rounded-3xl border border-zinc-200 bg-white p-2 dark:border-zinc-800 dark:bg-zinc-950",
        className
      )}
    >
      <div className="relative">
        <button
          aria-label={`Pickup map. ${status === "ready" ? `Pickup at ${address}.` : ""} Drag or use arrow keys to move it.`}
          className="relative block h-72 w-full cursor-grab touch-none select-none overflow-hidden rounded-2xl outline-none focus-visible:ring-2 focus-visible:ring-zinc-400 active:cursor-grabbing"
          onKeyDown={onKey}
          onPointerCancel={onUp}
          onPointerDown={onDown}
          onPointerMove={onMove}
          onPointerUp={onUp}
          ref={mapRef}
          type="button"
        >
          <motion.svg
            aria-hidden="true"
            className="absolute"
            height={H * ZOOM}
            style={{ x: tx, y: ty, left: view.w / 2, top: view.h / 2 }}
            viewBox={`0 0 ${W} ${H}`}
            width={W * ZOOM}
          >
            <Town />
            {/* The walk from you to the pickup. */}
            <motion.line
              animate={{ opacity: status === "ready" ? 1 : 0 }}
              className="stroke-sky-500"
              initial={false}
              strokeDasharray="0 7"
              strokeLinecap="round"
              strokeWidth={3}
              transition={{ duration: reduceMotion ? 0 : 0.2 }}
              x1={YOU[0]}
              x2={stop.x}
              y1={YOU[1]}
              y2={stop.y}
            />
            <circle
              className="fill-sky-500/15"
              cx={YOU[0]}
              cy={YOU[1]}
              r={22}
            />
            <circle
              className="fill-sky-500 stroke-white dark:stroke-zinc-900"
              cx={YOU[0]}
              cy={YOU[1]}
              r={7}
              strokeWidth={3}
            />
          </motion.svg>
          <Pin lifted={lifted} spring={spring} />
        </button>
        <button
          aria-label="Back to my location"
          className="absolute right-3 bottom-3 flex size-9 items-center justify-center rounded-full bg-white text-zinc-700 shadow-[0_1px_3px_rgb(0_0_0/0.15),0_0_0_1px_rgb(0_0_0/0.04)] outline-none transition-colors duration-150 hover:text-zinc-950 focus-visible:ring-2 focus-visible:ring-zinc-400 dark:bg-zinc-800 dark:text-zinc-200 dark:hover:text-white"
          onClick={() => settle(YOU[0], YOU[1])}
          type="button"
        >
          <LocateFixed aria-hidden className="size-4" />
        </button>
      </div>

      <div className="flex items-center gap-3 px-3 pt-3 pb-1">
        <AddressLine
          address={address}
          minutes={minutes}
          reduceMotion={reduceMotion}
          status={status}
        />
      </div>
      <div className="p-1">
        <button
          className={cn(
            "flex h-11 w-full items-center justify-center gap-2 rounded-xl font-medium text-sm outline-none transition-colors duration-200 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 disabled:opacity-40 dark:focus-visible:ring-offset-zinc-950",
            confirmed
              ? "bg-emerald-600 text-white dark:bg-emerald-500 dark:text-emerald-950"
              : "bg-zinc-900 text-white hover:bg-zinc-800 dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-white"
          )}
          disabled={status !== "ready"}
          onClick={() => {
            onConfirm?.({ address, x: stop.x, y: stop.y });
            setConfirmed(true);
          }}
          type="button"
        >
          <AnimatePresence initial={false} mode="popLayout">
            <motion.span
              animate={{ opacity: 1, y: 0 }}
              className="inline-flex items-center gap-2"
              exit={{ opacity: 0, y: -8 }}
              initial={{ opacity: 0, y: 8 }}
              key={confirmed ? "done" : "confirm"}
              transition={{ duration: reduceMotion ? 0 : 0.18, ease: EASE_OUT }}
            >
              {confirmed ? (
                <>
                  <Check aria-hidden className="size-4" strokeWidth={2.5} />
                  Driver on the way
                </>
              ) : (
                "Confirm pickup"
              )}
            </motion.span>
          </AnimatePresence>
        </button>
      </div>
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Marker Text
 * @version: 1.0.0
 * @date: 2026-10-21
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import { RotateCcw } from "lucide-react";
import {
  createContext,
  type ElementType,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

export type MarkType = "highlight" | "underline" | "circle" | "box" | "strike";

export interface MarkProps {
  children: ReactNode;
  /** How the phrase is marked. */
  type?: MarkType;
  /** Any CSS color. Each type has its own default. */
  color?: string;
  /** Pen width in px. Defaults to a width that suits the font size. */
  strokeWidth?: number;
  className?: string;
}

export interface MarkerTextProps {
  children: ReactNode;
  /**
   * Controlled. `true` draws the marks, `false` hides them. Leave it out and
   * they draw once, the first time the text is mostly on screen.
   */
  show?: boolean;
  /** Milliseconds between one mark finishing and the next one starting. */
  gap?: number;
  /** Called after the last mark lands. */
  onDrawn?: () => void;
  as?: ElementType;
  className?: string;
}

type Pt = [number, number];

interface Rect {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

interface Stroke {
  key: string;
  /** The ink, a filled outline. */
  shape: string;
  /** The pen's path, used as a mask that uncovers the ink as it travels. */
  pen: string;
  penWidth: number;
  length: number;
  color: string;
  /** Behind the text (highlights) or over it (everything else). */
  under: boolean;
  /** Highlighter ink is see-through; pens are solid. */
  alpha: number;
  delay: number;
  duration: number;
}

interface Entry {
  el: HTMLElement;
  type: MarkType;
  color?: string;
  strokeWidth?: number;
}

const DEFAULT_COLOR: Record<MarkType, string> = {
  highlight: "#facc15",
  underline: "#f97316",
  circle: "#2563eb",
  box: "#16a34a",
  strike: "#dc2626",
};

// How fast the pen travels, in px per ms. A hand slows down on long strokes,
// so durations are clamped rather than strictly proportional.
const PEN_SPEED = 0.9;
const HIGHLIGHT_SPEED = 1.15;
const MIN_MS = 260;
const MAX_MS = 820;
// Lifting the pen between two lines of the same mark.
const LINE_GAP = 60;
// A hand accelerates into a stroke and eases out of it.
const PEN_EASE = "cubic-bezier(0.45, 0.05, 0.25, 1)";
// The layers are 1px boxes that overflow, so masks need an explicit region.
const MASK_SPAN = 20_000;

/** Deterministic noise, so a resize redraws the same wobble. */
function random(seed: number) {
  let n = seed;
  return () => {
    n += 1;
    const x = Math.sin(n * 12.9898 + seed * 78.233) * 43_758.5453;
    return x - Math.floor(x);
  };
}

function hash(text: string) {
  let h = 7;
  for (const char of text) {
    h = (h * 31 + (char.codePointAt(0) ?? 0)) % 1_000_003;
  }
  return h;
}

const r1 = (n: number) => Math.round(n * 10) / 10;

function polyline(points: Pt[]) {
  return points
    .map(([x, y], i) => `${i === 0 ? "M" : "L"}${r1(x)} ${r1(y)}`)
    .join("");
}

function lengthOf(points: Pt[]) {
  let total = 0;
  for (let i = 1; i < points.length; i++) {
    total += Math.hypot(
      points[i][0] - points[i - 1][0],
      points[i][1] - points[i - 1][1]
    );
  }
  return total;
}

/**
 * A pen stroke as a filled shape: the centre line offset to both sides by
 * half the width at each point, with round ends. Unlike an SVG stroke, the
 * width can change along the way, which is what makes it read as ink.
 */
function outline(points: Pt[], widths: number[]) {
  const left: Pt[] = [];
  const right: Pt[] = [];
  const last = points.length - 1;
  for (let i = 0; i <= last; i++) {
    const prev = points[Math.max(0, i - 1)];
    const next = points[Math.min(last, i + 1)];
    const dx = next[0] - prev[0];
    const dy = next[1] - prev[1];
    const len = Math.hypot(dx, dy) || 1;
    const half = widths[i] / 2;
    const nx = (-dy / len) * half;
    const ny = (dx / len) * half;
    left.push([points[i][0] + nx, points[i][1] + ny]);
    right.push([points[i][0] - nx, points[i][1] - ny]);
  }
  const endCap = r1(widths[last] / 2);
  const startCap = r1(widths[0] / 2);
  const back = right.reverse();
  return `${polyline(left)}A${endCap} ${endCap} 0 0 0 ${r1(back[0][0])} ${r1(
    back[0][1]
  )}${polyline(back).replace("M", "L")}A${startCap} ${startCap} 0 0 0 ${r1(
    left[0][0]
  )} ${r1(left[0][1])}Z`;
}

/** Pressure along a stroke: the pen lands, presses, then lifts off. */
function pressure(t: number, base: number) {
  const land = Math.min(1, t / 0.1);
  const lift = Math.min(1, (1 - t) / 0.18);
  return (
    base * (0.45 + 0.55 * Math.sin((land * Math.PI) / 2)) * (0.55 + 0.45 * lift)
  );
}

/** A slow, uneven wave for edges that should look hand drawn. */
function wobble(rand: () => number, amp: number) {
  const p1 = rand() * Math.PI * 2;
  const p2 = rand() * Math.PI * 2;
  const f1 = 1 + rand() * 1.5;
  const f2 = 3 + rand() * 3;
  return (t: number) =>
    amp *
    (0.7 * Math.sin(t * f1 * Math.PI + p1) +
      0.3 * Math.sin(t * f2 * Math.PI + p2));
}

function sample(count: number, at: (t: number) => Pt) {
  const points: Pt[] = [];
  for (let i = 0; i <= count; i++) {
    points.push(at(i / count));
  }
  return points;
}

function penStroke(
  points: Pt[],
  width: number,
  key: string,
  color: string
): Omit<Stroke, "delay" | "duration"> {
  const widths = points.map((_, i) => pressure(i / (points.length - 1), width));
  return {
    key,
    shape: outline(points, widths),
    pen: polyline(points),
    penWidth: width * 4,
    length: lengthOf(points),
    color,
    under: false,
    alpha: 1,
  };
}

function strokesFor(
  entry: Entry,
  lines: Rect[],
  seed: number,
  index: number
): Omit<Stroke, "delay" | "duration">[] {
  const rand = random(seed);
  const color = entry.color ?? DEFAULT_COLOR[entry.type];
  const lineHeight = lines[0].bottom - lines[0].top;
  const width =
    entry.strokeWidth ?? Math.min(4.5, Math.max(1.6, lineHeight * 0.085));

  if (entry.type === "highlight") {
    return lines.map((line, i) => {
      const h = line.bottom - line.top;
      const top = wobble(rand, 0.9);
      const bottom = wobble(rand, 0.9);
      // The chisel tip leaves slanted ends, and the stroke drifts a little
      // off level across the line.
      const chisel = h * 0.2;
      const tilt = (rand() - 0.5) * Math.min(3, h * 0.08);
      const x0 = line.left - 3 - rand() * 2;
      const x1 = line.right + 3 + rand() * 3;
      const y0 = line.top + h * 0.08;
      const y1 = line.bottom - h * 0.02;
      const steps = Math.max(6, Math.round((x1 - x0) / 14));
      const edge = (y: number, wave: (t: number) => number, dx: number) =>
        sample(steps, (t) => [
          x0 + dx + (x1 - x0) * t,
          y + wave(t) + tilt * (t - 0.5),
        ]);
      const upper = edge(y0, top, chisel * 0.5);
      const lower = edge(y1, bottom, -chisel * 0.5).reverse();
      const mid = (y0 + y1) / 2;
      const pen: Pt[] = [
        [x0 - chisel, mid],
        [x1 + chisel, mid + tilt * 0.5],
      ];
      return {
        key: `${index}-${i}`,
        shape: `${polyline(upper)}${polyline(lower).replace("M", "L")}Z`,
        pen: polyline(pen),
        penWidth: h * 1.8,
        length: lengthOf(pen),
        color,
        under: true,
        alpha: 0.42,
      };
    });
  }

  if (entry.type === "underline" || entry.type === "strike") {
    return lines.map((line, i) => {
      const h = line.bottom - line.top;
      const bow = (rand() - 0.5) * 3;
      const slope = (rand() - 0.5) * (entry.type === "strike" ? 4 : 2.4);
      const wave = wobble(rand, 0.5);
      const x0 = line.left - 2 - rand() * 3;
      const x1 = line.right + 2 + rand() * 4;
      const y =
        entry.type === "strike"
          ? line.top + h * 0.56
          : line.bottom + Math.max(1, h * 0.04);
      const steps = Math.max(8, Math.round((x1 - x0) / 6));
      const points = sample(steps, (t) => [
        x0 + (x1 - x0) * t,
        y + Math.sin(t * Math.PI) * bow + slope * (t - 0.5) + wave(t),
      ]);
      return penStroke(points, width, `${index}-${i}`, color);
    });
  }

  // Circles and boxes don't wrap (see `Mark`), but if the phrase is longer
  // than a line anyway, each line gets its own.
  return lines.map((line, i) =>
    entry.type === "circle"
      ? circleStroke(line, rand, width, `${index}-${i}`, color)
      : boxStroke(line, rand, width, `${index}-${i}`, color)
  );
}

function circleStroke(
  box: Rect,
  rand: () => number,
  width: number,
  key: string,
  color: string
) {
  const cx = (box.left + box.right) / 2;
  const cy = (box.top + box.bottom) / 2;
  const rx = (box.right - box.left) / 2 + 8;
  const ry = (box.bottom - box.top) / 2 + 4;
  const tilt = ((rand() - 0.5) * 6 * Math.PI) / 180;
  const start = -Math.PI * (0.62 + rand() * 0.12);
  // A hand never closes a loop exactly: it runs past the start and drifts
  // outward, so the two ends cross instead of meeting.
  const sweep = Math.PI * 2 + 0.45 + rand() * 0.2;
  const drift = 0.05 + rand() * 0.04;
  const wave = wobble(rand, 0.025);
  const steps = Math.max(48, Math.round((rx + ry) / 3));
  const points = sample(steps, (t) => {
    const a = start + sweep * t;
    const grow = 1 - drift / 2 + drift * t + wave(t);
    const x = Math.cos(a) * rx * grow;
    const y = Math.sin(a) * ry * grow;
    return [
      cx + x * Math.cos(tilt) - y * Math.sin(tilt),
      cy + x * Math.sin(tilt) + y * Math.cos(tilt),
    ];
  });
  return penStroke(points, width, key, color);
}

/**
 * One continuous stroke round four slightly bowed sides, overshooting the
 * first corner at the end.
 */
function boxStroke(
  box: Rect,
  rand: () => number,
  width: number,
  key: string,
  color: string
) {
  const padX = 5;
  const padY = 3;
  const corners: Pt[] = [
    [box.left - padX - rand() * 2, box.top - padY + (rand() - 0.5) * 2],
    [box.right + padX + rand() * 2, box.top - padY + (rand() - 0.5) * 2],
    [box.right + padX + (rand() - 0.5) * 2, box.bottom + padY + rand() * 2],
    [box.left - padX + (rand() - 0.5) * 2, box.bottom + padY + rand() * 2],
  ];
  const points: Pt[] = [];
  for (let side = 0; side < 4; side++) {
    const a = corners[side];
    const b = corners[(side + 1) % 4];
    const bow = (rand() - 0.5) * 3;
    const len = Math.hypot(b[0] - a[0], b[1] - a[1]);
    const nx = -(b[1] - a[1]) / len;
    const ny = (b[0] - a[0]) / len;
    const steps = Math.max(6, Math.round(len / 8));
    for (let s = side === 0 ? 0 : 1; s <= steps; s++) {
      const t = s / steps;
      const lift = Math.sin(t * Math.PI) * bow;
      points.push([
        a[0] + (b[0] - a[0]) * t + nx * lift,
        a[1] + (b[1] - a[1]) * t + ny * lift,
      ]);
    }
  }
  const first = corners[0];
  const second = corners[1];
  const over = 14 / Math.hypot(second[0] - first[0], second[1] - first[1]);
  points.push([
    first[0] + (second[0] - first[0]) * over,
    first[1] + (second[1] - first[1]) * over + 1.5,
  ]);
  return penStroke(points, width, key, color);
}

interface Registry {
  add: (id: string, entry: Entry) => () => void;
}

const MarkerContext = createContext<Registry | null>(null);

/**
 * A phrase to mark. Use it inside `MarkerText`, which draws every mark in
 * reading order. Highlights render as `<mark>` and strikes as `<s>`, so the
 * meaning survives without the drawing.
 */
export function Mark({
  children,
  type = "highlight",
  color,
  strokeWidth,
  className,
}: MarkProps) {
  const registry = useContext(MarkerContext);
  const ref = useRef<HTMLElement>(null);
  const id = useId();

  useLayoutEffect(() => {
    if (!(registry && ref.current)) {
      return;
    }
    return registry.add(id, { el: ref.current, type, color, strokeWidth });
  }, [registry, id, type, color, strokeWidth]);

  const Tag = (() => {
    if (type === "highlight") {
      return "mark";
    }
    if (type === "strike") {
      return "s";
    }
    return "span";
  })();

  return (
    <Tag
      className={cn(
        "bg-transparent text-inherit no-underline",
        (type === "circle" || type === "box") && "whitespace-nowrap",
        className
      )}
      data-mark={type}
      ref={ref}
    >
      {children}
    </Tag>
  );
}

export function MarkerText({
  children,
  show,
  gap = 140,
  onDrawn,
  as: Tag = "div",
  className,
}: MarkerTextProps) {
  const rootRef = useRef<HTMLElement>(null);
  const entries = useRef(new Map<string, Entry>());
  const [strokes, setStrokes] = useState<Stroke[]>([]);
  const [seen, setSeen] = useState(false);
  // `armed` turns the transitions on. Hiding is instant, drawing is not.
  const [armed, setArmed] = useState(false);
  const [reduced, setReduced] = useState(false);
  const measureRef = useRef<() => void>(() => undefined);
  const onDrawnRef = useRef(onDrawn);
  onDrawnRef.current = onDrawn;
  const maskId = useId().replace(/:/g, "");

  const visible = show ?? seen;

  const measure = useCallback(() => {
    const root = rootRef.current;
    if (!root) {
      return;
    }
    const origin = root.getBoundingClientRect();
    // Reading order is document order, whatever order the marks mounted in.
    const order = Array.from(root.querySelectorAll("[data-mark]"));
    const ordered = [...entries.current.values()].sort(
      (a, b) => order.indexOf(a.el) - order.indexOf(b.el)
    );
    const next: Stroke[] = [];
    let clock = 0;
    ordered.forEach((entry, index) => {
      const lines = Array.from(entry.el.getClientRects())
        .filter((r) => r.width > 1)
        .map((r) => ({
          left: r.left - origin.left,
          top: r.top - origin.top,
          right: r.right - origin.left,
          bottom: r.bottom - origin.top,
        }));
      if (lines.length === 0) {
        return;
      }
      const seed = hash(`${entry.el.textContent ?? ""}${index}`);
      const speed = entry.type === "highlight" ? HIGHLIGHT_SPEED : PEN_SPEED;
      const made = strokesFor(entry, lines, seed, index);
      made.forEach((stroke, i) => {
        const duration = Math.min(
          MAX_MS,
          Math.max(MIN_MS, stroke.length / speed)
        );
        next.push({ ...stroke, delay: clock, duration });
        clock += duration + (i < made.length - 1 ? LINE_GAP : 0);
      });
      clock += gap;
    });
    setStrokes(next);
  }, [gap]);
  measureRef.current = measure;

  const registry = useRef<Registry>({
    add: (id, entry) => {
      entries.current.set(id, entry);
      measureRef.current();
      return () => {
        entries.current.delete(id);
        measureRef.current();
      };
    },
  });

  useEffect(() => {
    const root = rootRef.current;
    if (!root) {
      return;
    }
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(query.matches);
    const resize = new ResizeObserver(() => measureRef.current());
    resize.observe(root);
    // Web fonts can swap in after the first measure and move every line.
    document.fonts?.ready.then(() => measureRef.current());
    const view = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setSeen(true);
          view.disconnect();
        }
      },
      { threshold: 0.6 }
    );
    view.observe(root);
    return () => {
      resize.disconnect();
      view.disconnect();
    };
  }, []);

  // Draw on the frame after the hidden state has painted, so going from
  // hidden to shown always runs the transition, even on a replay.
  useEffect(() => {
    if (!visible) {
      setArmed(false);
      return;
    }
    let second = 0;
    const first = requestAnimationFrame(() => {
      second = requestAnimationFrame(() => setArmed(true));
    });
    return () => {
      cancelAnimationFrame(first);
      cancelAnimationFrame(second);
    };
  }, [visible]);

  const totalRef = useRef(0);
  totalRef.current = strokes.reduce(
    (end, s) => Math.max(end, s.delay + s.duration),
    0
  );
  const hasStrokes = strokes.length > 0;

  // Reports once per draw. Re-measuring mid-draw (a resize) doesn't restart
  // the clock.
  useEffect(() => {
    if (!(armed && hasStrokes)) {
      return;
    }
    const timer = window.setTimeout(
      () => onDrawnRef.current?.(),
      reduced ? 0 : totalRef.current
    );
    return () => window.clearTimeout(timer);
  }, [armed, hasStrokes, reduced]);

  const layer = (under: boolean) => (
    <svg
      aria-hidden="true"
      className={cn(
        "pointer-events-none absolute top-0 left-0 overflow-visible",
        under ? "-z-10" : "z-10"
      )}
      height="1"
      width="1"
    >
      {strokes
        .filter((s) => s.under === under)
        .map((s) => {
          const id = `${maskId}-${s.key}`;
          return (
            <g key={s.key}>
              <mask
                height={MASK_SPAN}
                id={id}
                maskUnits="userSpaceOnUse"
                width={MASK_SPAN}
                x={-MASK_SPAN / 2}
                y={-MASK_SPAN / 2}
              >
                <path
                  d={s.pen}
                  fill="none"
                  stroke="white"
                  strokeDasharray={s.length + 1}
                  strokeDashoffset={armed ? 0 : s.length + 1}
                  strokeLinecap={under ? "butt" : "round"}
                  strokeLinejoin="round"
                  strokeWidth={s.penWidth}
                  style={{
                    transition:
                      armed && !reduced
                        ? `stroke-dashoffset ${s.duration}ms ${PEN_EASE} ${s.delay}ms`
                        : "none",
                  }}
                />
              </mask>
              <path
                d={s.shape}
                fill={s.color}
                fillOpacity={s.alpha}
                mask={`url(#${id})`}
              />
            </g>
          );
        })}
    </svg>
  );

  return (
    <MarkerContext.Provider value={registry.current}>
      <Tag className={cn("relative isolate", className)} ref={rootRef}>
        {layer(true)}
        {children}
        {layer(false)}
      </Tag>
    </MarkerContext.Provider>
  );
}

