import { ChevronLeft, ChevronRight } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type KeyboardEvent,
  type PointerEvent,
  useEffect,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

const EASE_OUT = [0.23, 1, 0.32, 1] as const;
const DAY_MS = 86_400_000;
const WEEKDAYS = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"];
const MONTHS = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];
/** Height of one week row, in px. The pill is drawn in the same units. */
const ROW = 52;

export interface Night {
  price: number;
  /** Sold out: you can't sleep here this night, but you can check out. */
  blocked?: boolean;
}

export interface StayPickerProps {
  /** First month shown, as YYYY-MM. */
  month?: string;
  /** Price and availability for one night, by date (YYYY-MM-DD). */
  getNight?: (date: string) => Night;
  /** Fewest nights one booking can be. */
  minNights?: number;
  currency?: string;
  onReserve?: (stay: {
    checkIn: string;
    checkOut: string;
    total: number;
  }) => void;
  className?: string;
}

/** Days since 1970, so ranges can cross months. */
const dayOf = (y: number, m: number, d: number) => Date.UTC(y, m, d) / DAY_MS;

const isoOf = (day: number) =>
  new Date(day * DAY_MS).toISOString().slice(0, 10);

const shortDate = (day: number) => {
  const date = new Date(day * DAY_MS);
  return `${MONTHS[date.getUTCMonth()].slice(0, 3)} ${date.getUTCDate()}`;
};

/** Seeded so the server and the browser price the same night the same way. */
function demoNight(iso: string): Night {
  const [y, m, d] = iso.split("-").map(Number);
  const day = dayOf(y, m - 1, d);
  let seed = (day * 7919) % 2_147_483_647;
  seed = (seed * 16_807) % 2_147_483_647;
  const weekday = (new Date(day * DAY_MS).getUTCDay() + 6) % 7;
  const weekend = weekday === 4 || weekday === 5;
  const price = 150 + (weekend ? 45 : 0) + (seed % 7) * 8;
  return { price, blocked: seed % 11 === 0 };
}

function useMonth(initial: string) {
  const [y, m] = initial.split("-").map(Number);
  return useState({ year: y, month: m - 1 });
}

interface Segment {
  row: number;
  from: number;
  to: number;
  roundLeft: boolean;
  roundRight: boolean;
}

const ARROW_STEP: Record<string, number> = {
  ArrowLeft: -1,
  ArrowRight: 1,
  ArrowUp: -7,
  ArrowDown: 7,
};

/**
 * Where a stay from `from` can end if you aim for `to`: it can't run
 * through a sold-out night, and it can't be shorter than the minimum.
 */
function settleStay(
  from: number,
  to: number,
  minNights: number,
  blocked: (day: number) => boolean | undefined
): { end: number | null; note: string | null } {
  let end = to;
  let note: string | null = null;
  for (let d = from; d < to; d++) {
    if (blocked(d)) {
      end = d;
      note = `Sold out from ${shortDate(d)}`;
      break;
    }
  }
  if (end - from >= minNights) {
    return { end, note };
  }
  for (let d = from; d < from + minNights; d++) {
    if (blocked(d)) {
      return {
        end: null,
        note: `${minNights}-night minimum, and ${shortDate(d)} is sold out`,
      };
    }
  }
  return {
    end: from + minNights,
    note:
      to - from < minNights
        ? `${minNights}-night minimum, so we added a night`
        : note,
  };
}

/**
 * One row of the pill as a clip over a full-width bar, so it grows and
 * shrinks on the GPU. Ends are round only where the stay starts or stops.
 */
function clipFor(s: Segment) {
  const left = (s.from / 7) * 100;
  const right = 100 - ((s.to + 1) / 7) * 100;
  const l = s.roundLeft ? "22px" : "0px";
  const r = s.roundRight ? "22px" : "0px";
  return `inset(0% ${right}% 0% ${left}% round ${l} ${r} ${r} ${l})`;
}

/** The stay, cut into one segment per week row it crosses. */
function segmentsFor(
  start: number | null,
  end: number | null,
  first: number,
  daysIn: number,
  lead: number
) {
  const segments: Segment[] = [];
  if (start === null || end === null) {
    return segments;
  }
  const a = Math.max(start, first);
  const b = Math.min(end, first + daysIn - 1);
  const ia = a - first + lead;
  const ib = b - first + lead;
  for (
    let row = Math.floor(ia / 7);
    a <= b && row <= Math.floor(ib / 7);
    row++
  ) {
    const from = Math.max(ia, row * 7);
    const to = Math.min(ib, row * 7 + 6);
    segments.push({
      row,
      from: from % 7,
      to: to % 7,
      roundLeft: from === ia && a === start,
      roundRight: to === ib && b === end,
    });
  }
  return segments;
}

function summaryFor(start: number | null, end: number | null) {
  if (start === null) {
    return "Pick a check-in night";
  }
  if (end === null) {
    return `Check-in ${shortDate(start)}. Now pick check-out`;
  }
  return `${shortDate(start)} – ${shortDate(end)} · ${end - start} nights`;
}

function dayTone(edge: boolean, blocked: boolean | undefined) {
  if (edge) {
    return "";
  }
  return blocked
    ? "text-zinc-400 line-through decoration-zinc-300 dark:text-zinc-600 dark:decoration-zinc-700"
    : "text-zinc-900 dark:text-zinc-100";
}

function priceTone(edge: boolean, cheap: boolean) {
  if (edge) {
    return "text-white/70 dark:text-zinc-900/60";
  }
  return cheap
    ? "text-emerald-600 dark:text-emerald-400"
    : "text-zinc-400 dark:text-zinc-500";
}

function DayCell({
  day,
  cell,
  label,
  night,
  cheap,
  edge,
  hoverEnd,
  inStay,
  focusable,
  money,
  onKeyDown,
}: {
  day: number;
  cell: number;
  label: number;
  night: Night;
  cheap: number;
  edge: boolean;
  hoverEnd: boolean;
  inStay: boolean;
  focusable: boolean;
  money: (n: number) => string;
  onKeyDown: (event: KeyboardEvent<HTMLButtonElement>, day: number) => void;
}) {
  return (
    <button
      aria-label={`${shortDate(day)}, ${night.blocked ? "sold out" : `${money(night.price)} a night`}`}
      aria-pressed={edge}
      className="group absolute flex flex-col items-center justify-center outline-none"
      data-day={day}
      onKeyDown={(event) => onKeyDown(event, day)}
      style={{
        left: `${((cell % 7) / 7) * 100}%`,
        top: Math.floor(cell / 7) * ROW,
        width: `${100 / 7}%`,
        height: ROW,
      }}
      tabIndex={focusable ? 0 : -1}
      type="button"
    >
      <span
        className={cn(
          "relative flex size-11 flex-col items-center justify-center rounded-full leading-none transition-colors duration-150",
          "group-focus-visible:ring-2 group-focus-visible:ring-zinc-400",
          edge && "bg-zinc-900 text-white dark:bg-zinc-100 dark:text-zinc-900",
          hoverEnd && "ring-1 ring-zinc-900 ring-inset dark:ring-zinc-100",
          !(edge || inStay || night.blocked) &&
            "group-hover:bg-zinc-100 dark:group-hover:bg-zinc-900"
        )}
      >
        {night.blocked && !edge && (
          <span
            aria-hidden="true"
            className="absolute inset-1 rounded-full text-zinc-200 dark:text-zinc-800"
            style={{
              backgroundImage:
                "repeating-linear-gradient(135deg, currentColor 0 1px, transparent 1px 5px)",
            }}
          />
        )}
        <span
          className={cn(
            "relative font-medium text-[13px] tabular-nums",
            dayTone(edge, night.blocked)
          )}
        >
          {label}
        </span>
        {!night.blocked && (
          <span
            className={cn(
              "relative mt-1 text-[10px] tabular-nums",
              priceTone(edge, night.price <= cheap)
            )}
          >
            {night.price}
          </span>
        )}
      </span>
    </button>
  );
}

/**
 * A date range for booking stays. Every night shows its price, sold-out
 * nights are hatched, and the stay is drawn as one pill that wraps from
 * row to row as you drag across the weeks.
 */
export default function StayPicker({
  month: initialMonth = "2026-11",
  getNight = demoNight,
  minNights = 2,
  currency = "$",
  onReserve,
  className,
}: StayPickerProps) {
  const [view, setView] = useMonth(initialMonth);
  const [direction, setDirection] = useState(1);
  const [start, setStart] = useState<number | null>(null);
  const [end, setEnd] = useState<number | null>(null);
  const [hover, setHover] = useState<number | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [reserved, setReserved] = useState(false);
  const reduceMotion = Boolean(useReducedMotion());

  const dragging = useRef(false);
  // The month grid is keyed, so a ref on it goes null once the old month
  // finishes leaving; the card itself stays put.
  const rootRef = useRef<HTMLDivElement>(null);
  const noteTimer = useRef<ReturnType<typeof setTimeout>>(undefined);

  useEffect(() => () => clearTimeout(noteTimer.current), []);

  const first = dayOf(view.year, view.month, 1);
  const daysIn = new Date(Date.UTC(view.year, view.month + 1, 0)).getUTCDate();
  const lead = (new Date(first * DAY_MS).getUTCDay() + 6) % 7;
  const rows = Math.ceil((lead + daysIn) / 7);
  const nights = new Map<number, Night>();
  const nightOf = (day: number) => {
    let night = nights.get(day);
    if (!night) {
      night = getNight(isoOf(day));
      nights.set(day, night);
    }
    return night;
  };

  const days = Array.from({ length: daysIn }, (_, i) => first + i);
  const prices = days
    .filter((d) => !nightOf(d).blocked)
    .map((d) => nightOf(d).price);
  // The month's lowest price is marked, so the good nights stand out.
  const cheap = prices.length ? Math.min(...prices) : 0;

  const say = (text: string) => {
    setNote(text);
    clearTimeout(noteTimer.current);
    noteTimer.current = setTimeout(() => setNote(null), 2600);
  };

  const settle = (from: number, to: number, speak: boolean) => {
    const result = settleStay(from, to, minNights, (d) => nightOf(d).blocked);
    if (speak && result.note) {
      say(result.note);
    }
    return result.end;
  };

  const picking = start !== null && end === null;
  const shownEnd =
    picking && hover !== null && hover > start
      ? settle(start, hover, false)
      : end;

  const begin = (day: number) => {
    if (nightOf(day).blocked) {
      say("Sold out that night");
      return;
    }
    setStart(day);
    setEnd(null);
    setReserved(false);
  };

  const choose = (day: number) => {
    if (start === null || end !== null || day <= start) {
      begin(day);
      return;
    }
    const out = settle(start, day, true);
    if (out === null) {
      return;
    }
    setEnd(out);
    setHover(null);
  };

  const dayAt = (event: PointerEvent) => {
    const el = document.elementFromPoint(event.clientX, event.clientY);
    const cell = el?.closest<HTMLElement>("[data-day]");
    return cell ? Number(cell.dataset.day) : null;
  };

  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) {
      return;
    }
    const day = dayAt(event);
    if (day === null) {
      return;
    }
    dragging.current = true;
    // A press on a fresh day starts a stay; a press while picking ends one.
    if (start === null || end !== null || day <= start) {
      begin(day);
    }
    event.currentTarget.setPointerCapture(event.pointerId);
  };

  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const day = dayAt(event);
    if (day === null) {
      return;
    }
    if (start !== null && end === null) {
      setHover(day);
    }
  };

  const onPointerUp = (event: PointerEvent<HTMLDivElement>) => {
    if (!dragging.current) {
      return;
    }
    dragging.current = false;
    const day = dayAt(event);
    if (day !== null && start !== null && day > start && end === null) {
      choose(day);
    }
  };

  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>, day: number) => {
    if (event.key in ARROW_STEP) {
      event.preventDefault();
      const next = day + ARROW_STEP[event.key];
      const focusDay = () =>
        rootRef.current
          ?.querySelector<HTMLElement>(`[data-day="${next}"]`)
          ?.focus();
      if (next < first || next >= first + daysIn) {
        // Off the edge of the month: turn the page, then land on the day.
        go(next < first ? -1 : 1);
        requestAnimationFrame(focusDay);
      } else {
        focusDay();
      }
      if (start !== null && end === null) {
        setHover(next);
      }
    } else if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      choose(day);
    }
  };

  const go = (delta: number) => {
    setDirection(delta);
    setView(({ year, month }) => {
      const m = month + delta;
      return { year: year + Math.floor(m / 12), month: ((m % 12) + 12) % 12 };
    });
  };

  const segments = segmentsFor(start, shownEnd ?? null, first, daysIn, lead);

  const stayNights =
    start !== null && end !== null
      ? Array.from({ length: end - start }, (_, i) => nightOf(start + i).price)
      : [];
  const total = stayNights.reduce((sum, p) => sum + p, 0);
  const money = (n: number) => `${currency}${n.toLocaleString("en-US")}`;

  const spring = reduceMotion
    ? { duration: 0 }
    : { type: "spring" as const, duration: 0.35, bounce: 0 };
  const fade = { duration: reduceMotion ? 0 : 0.18, ease: EASE_OUT };

  const summary = summaryFor(start, end);
  // The one day Tab lands on: check-in when it's in this month, else the 1st.
  const tabDay =
    start !== null && start >= first && start < first + daysIn ? start : first;

  return (
    <div
      className={cn(
        "w-full max-w-sm select-none rounded-3xl border border-zinc-200 bg-white p-4 dark:border-zinc-800 dark:bg-zinc-950",
        className
      )}
      ref={rootRef}
    >
      <div className="flex items-center justify-between px-1">
        <div className="relative h-5 flex-1 overflow-hidden">
          <AnimatePresence custom={direction} initial={false} mode="popLayout">
            <motion.p
              animate={{ opacity: 1, x: 0 }}
              className="font-medium text-sm text-zinc-900 dark:text-zinc-100"
              exit={{ opacity: 0, x: -12 * direction }}
              initial={{ opacity: 0, x: 12 * direction }}
              key={`${view.year}-${view.month}`}
              transition={fade}
            >
              {MONTHS[view.month]} {view.year}
            </motion.p>
          </AnimatePresence>
        </div>
        <div className="flex gap-1">
          {[-1, 1].map((delta) => (
            <button
              aria-label={delta < 0 ? "Previous month" : "Next month"}
              className="flex size-8 items-center justify-center rounded-full text-zinc-500 outline-none transition-colors duration-150 hover:bg-zinc-100 hover:text-zinc-900 focus-visible:ring-2 focus-visible:ring-zinc-400 dark:text-zinc-400 dark:hover:bg-zinc-900 dark:hover:text-zinc-100"
              key={delta}
              onClick={() => go(delta)}
              type="button"
            >
              {delta < 0 ? (
                <ChevronLeft aria-hidden className="size-4" />
              ) : (
                <ChevronRight aria-hidden className="size-4" />
              )}
            </button>
          ))}
        </div>
      </div>

      <div className="mt-3 grid grid-cols-7 text-center text-[11px] text-zinc-400 dark:text-zinc-500">
        {WEEKDAYS.map((d) => (
          <span key={d}>{d}</span>
        ))}
      </div>

      <AnimatePresence custom={direction} initial={false} mode="popLayout">
        <motion.div
          animate={{ opacity: 1, x: 0 }}
          className="mt-1"
          exit={{ opacity: 0, x: -16 * direction }}
          initial={{ opacity: 0, x: 16 * direction }}
          key={`${view.year}-${view.month}`}
          transition={fade}
        >
          <div
            className="relative touch-none"
            onPointerCancel={() => {
              dragging.current = false;
            }}
            onPointerDown={onPointerDown}
            onPointerLeave={() => setHover(null)}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            style={{ height: rows * ROW }}
          >
            {/* The stay: one pill per row, ends rounded only where the stay
              really starts and stops, so it reads as a single shape. */}
            {segments.map((s) => (
              <motion.div
                animate={{ clipPath: clipFor(s), opacity: 1 }}
                aria-hidden="true"
                className={cn(
                  "pointer-events-none absolute inset-x-0 h-11 bg-zinc-100 dark:bg-zinc-800/70",
                  picking && "bg-zinc-100/70 dark:bg-zinc-800/50"
                )}
                initial={{
                  clipPath: clipFor({
                    ...s,
                    to: s.from,
                    roundLeft: true,
                    roundRight: true,
                  }),
                  opacity: 0,
                }}
                key={s.row}
                style={{ top: s.row * ROW + (ROW - 44) / 2 }}
                transition={{ ...spring, opacity: fade }}
              />
            ))}

            {days.map((day, i) => (
              <DayCell
                cell={i + lead}
                cheap={cheap}
                day={day}
                edge={
                  day === start || day === end || (day === shownEnd && !picking)
                }
                focusable={day === tabDay}
                hoverEnd={picking && day === shownEnd}
                inStay={
                  start !== null &&
                  shownEnd != null &&
                  day > start &&
                  day < shownEnd
                }
                key={day}
                label={i + 1}
                money={money}
                night={nightOf(day)}
                onKeyDown={onKeyDown}
              />
            ))}
          </div>
        </motion.div>
      </AnimatePresence>

      <div aria-live="polite" className="relative mt-2 h-4 px-1 text-xs">
        <AnimatePresence initial={false} mode="popLayout">
          <motion.p
            animate={{ opacity: 1, y: 0 }}
            className={cn(
              note
                ? "text-orange-600 dark:text-orange-400"
                : "text-zinc-500 dark:text-zinc-400"
            )}
            exit={{ opacity: 0, y: -4 }}
            initial={{ opacity: 0, y: 4 }}
            key={note ?? summary}
            transition={fade}
          >
            {note ?? summary}
          </motion.p>
        </AnimatePresence>
      </div>

      <div className="mt-3 flex items-center justify-between gap-3 border-zinc-100 border-t px-1 pt-3 dark:border-zinc-900">
        <div className="min-w-0 leading-tight">
          <p className="text-xs text-zinc-500 dark:text-zinc-400">Total</p>
          <div className="relative h-6 overflow-hidden">
            <AnimatePresence initial={false} mode="popLayout">
              <motion.p
                animate={{ opacity: 1, y: 0 }}
                className="font-semibold text-lg text-zinc-900 tabular-nums tracking-tight dark:text-zinc-50"
                exit={{ opacity: 0, y: -10 }}
                initial={{ opacity: 0, y: 10 }}
                key={total}
                transition={fade}
              >
                {total ? money(total) : "—"}
              </motion.p>
            </AnimatePresence>
          </div>
        </div>
        <button
          aria-disabled={!total}
          className={cn(
            "h-10 shrink-0 rounded-full px-5 font-medium text-sm outline-none transition-colors duration-200 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 dark:focus-visible:ring-offset-zinc-950",
            reserved &&
              "bg-emerald-600 text-white dark:bg-emerald-500 dark:text-emerald-950",
            !reserved &&
              (total
                ? "bg-zinc-900 text-white hover:bg-zinc-800 dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-white"
                : "bg-zinc-100 text-zinc-400 dark:bg-zinc-900 dark:text-zinc-600")
          )}
          onClick={() => {
            if (start === null || end === null) {
              return;
            }
            onReserve?.({ checkIn: isoOf(start), checkOut: isoOf(end), total });
            setReserved(true);
          }}
          type="button"
        >
          {reserved ? "Reserved" : "Reserve"}
        </button>
      </div>
    </div>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Switch Button
 * @version: 2.0.0
 * @date: 2026-10-16
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 *
 * Works on its own: it toggles the `dark` class on <html>. If a theme provider
 * owns the theme (next-themes or your own), pass `theme` and `onThemeChange`.
 *
 * The new theme spreads from the button as a circle (View Transitions API).
 * Without that API, or with reduced motion, the theme switches instantly.
 */

import { useEffect, useId, useRef, useState } from "react";
import { flushSync } from "react-dom";
import { cn } from "@/lib/utils";

type Theme = "light" | "dark";

interface SwitchButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  size?: "sm" | "default" | "lg";
  showLabel?: boolean;
  /**
   * The applied theme, when a theme provider owns it (for next-themes, its
   * `resolvedTheme`). Pair it with `onThemeChange`. Without it the button
   * toggles the `dark` class on <html> itself.
   */
  theme?: Theme;
  /** Called with the theme to switch to. */
  onThemeChange?: (theme: Theme) => void;
  /** Spread the new theme from the button as a circle. */
  reveal?: boolean;
}

const SIZES = {
  sm: { button: "h-8 gap-1.5 px-2.5 text-[13px]", square: "w-8", icon: 14 },
  default: { button: "h-9 gap-2 px-3 text-sm", square: "w-9", icon: 16 },
  lg: { button: "h-10 gap-2 px-3.5 text-[15px]", square: "w-10", icon: 18 },
};

const EASE_OUT = "cubic-bezier(0.23, 1, 0.32, 1)";
const EASE_IN_OUT = "cubic-bezier(0.65, 0, 0.35, 1)";
const EASE_REVEAL = "cubic-bezier(0.4, 0, 0.2, 1)";
const REVEAL_ATTR = "data-theme-reveal";
const REVEAL_STYLE_ID = "kokonut-theme-reveal";
const REVEAL_CSS = `html[${REVEAL_ATTR}]::view-transition-old(root),html[${REVEAL_ATTR}]::view-transition-new(root){animation:none;mix-blend-mode:normal}`;

const RAY_ANGLES = [0, 45, 90, 135, 180, 225, 270, 315];
const RAYS = RAY_ANGLES.map((deg) => {
  const rad = (deg * Math.PI) / 180;
  const at = (r: number) => ({
    x: Number((12 + r * Math.cos(rad)).toFixed(2)),
    y: Number((12 + r * Math.sin(rad)).toFixed(2)),
  });
  return { deg, from: at(7.5), to: at(10) };
});

// Each part's light look is its base class and its dark look a `dark:` class,
// so the server render (theme unknown) matches the client. Clicking animates
// from the old computed values to the new ones with WAAPI, which keeps
// working when a provider disables CSS transitions while it swaps themes.
const ANIMATED_PROPS = ["opacity", "scale", "translate", "filter"] as const;

type Snapshot = Map<Element, Keyframe>;

function snapshot(elements: Element[]): Snapshot {
  const map: Snapshot = new Map();
  for (const el of elements) {
    const style = getComputedStyle(el);
    const frame: Keyframe = { offset: 0 };
    for (const prop of ANIMATED_PROPS) {
      frame[prop] = style.getPropertyValue(prop);
    }
    map.set(el, frame);
    for (const animation of el.getAnimations()) {
      animation.cancel();
    }
  }
  return map;
}

function prefersReducedMotion() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function ensureRevealStyle() {
  if (document.getElementById(REVEAL_STYLE_ID)) {
    return;
  }
  const style = document.createElement("style");
  style.id = REVEAL_STYLE_ID;
  style.textContent = REVEAL_CSS;
  document.head.appendChild(style);
}

function timing(el: Element, toDark: boolean): KeyframeAnimationOptions {
  const { part, index = "0" } = (el as HTMLElement | SVGElement).dataset;
  const i = Number(index);
  switch (part) {
    case "ray":
      // Rays retract one after another; on the way back they wait for the
      // bite to clear first.
      return {
        delay: toDark ? i * 18 : 140 + i * 22,
        duration: 260,
        easing: EASE_OUT,
      };
    case "bite":
      return { delay: toDark ? 60 : 0, duration: 380, easing: EASE_IN_OUT };
    case "disc":
      return { delay: toDark ? 40 : 0, duration: 380, easing: EASE_OUT };
    default:
      return { duration: 240, easing: EASE_OUT };
  }
}

function morph(from: Snapshot, toDark: boolean) {
  if (prefersReducedMotion()) {
    return;
  }
  for (const [el, frame] of from) {
    el.animate([frame, {}], { ...timing(el, toDark), fill: "backwards" });
  }
}

let revealRunning = false;

function revealFrom(button: HTMLElement, apply: () => void) {
  const doc = document as Document & { activeViewTransition?: unknown };
  if (
    typeof doc.startViewTransition !== "function" ||
    prefersReducedMotion() ||
    revealRunning ||
    doc.activeViewTransition
  ) {
    apply();
    return;
  }

  const rect = button.getBoundingClientRect();
  const x = rect.left + rect.width / 2;
  const y = rect.top + rect.height / 2;
  const radius = Math.hypot(
    Math.max(x, window.innerWidth - x),
    Math.max(y, window.innerHeight - y)
  );
  const root = document.documentElement;

  ensureRevealStyle();
  root.setAttribute(REVEAL_ATTR, "");
  revealRunning = true;

  let transition: ViewTransition;
  try {
    transition = doc.startViewTransition(() => flushSync(apply));
  } catch {
    root.removeAttribute(REVEAL_ATTR);
    revealRunning = false;
    apply();
    return;
  }

  transition.ready
    .then(() => {
      root.animate(
        {
          clipPath: [
            `circle(0px at ${x}px ${y}px)`,
            `circle(${radius}px at ${x}px ${y}px)`,
          ],
        },
        {
          duration: 500,
          easing: EASE_REVEAL,
          pseudoElement: "::view-transition-new(root)",
        }
      );
    })
    .catch(() => {
      // Skipped or aborted (e.g. a page navigation started a transition).
    });

  transition.finished
    .catch(() => {
      // The theme is already applied by the time a transition can fail.
    })
    .finally(() => {
      root.removeAttribute(REVEAL_ATTR);
      revealRunning = false;
    });
}

export default function SwitchButton({
  className,
  size = "default",
  showLabel = true,
  theme,
  onThemeChange,
  reveal = true,
  onClick,
  ...props
}: SwitchButtonProps) {
  const maskId = `${useId()}-moon`;
  const iconRef = useRef<SVGSVGElement>(null);
  const labelRef = useRef<HTMLSpanElement>(null);
  const [observed, setObserved] = useState<Theme | null>(null);

  // Only for aria-pressed: read the applied theme after mount, so the first
  // client render matches the server.
  useEffect(() => {
    const root = document.documentElement;
    const read = () =>
      setObserved(root.classList.contains("dark") ? "dark" : "light");
    read();
    const observer = new MutationObserver(read);
    observer.observe(root, { attributes: true, attributeFilter: ["class"] });
    return () => observer.disconnect();
  }, []);

  const current = observed && (theme ?? observed);
  const sizing = SIZES[size];

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    onClick?.(e);
    if (e.defaultPrevented) {
      return;
    }
    const root = document.documentElement;
    const from = theme ?? (root.classList.contains("dark") ? "dark" : "light");
    const next: Theme = from === "dark" ? "light" : "dark";
    const button = e.currentTarget;

    const apply = () => {
      const parts = [
        ...(iconRef.current?.querySelectorAll("[data-part]") ?? []),
        ...(labelRef.current?.querySelectorAll("[data-part]") ?? []),
      ];
      const before = snapshot(parts);
      // With a provider the class is also set here, because next-themes
      // applies it in an effect: the reveal's snapshot needs it now. The
      // provider then sets the same value.
      root.classList.toggle("dark", next === "dark");
      root.style.colorScheme = next;
      onThemeChange?.(next);
      morph(before, next === "dark");
    };

    if (reveal) {
      revealFrom(button, apply);
    } else {
      apply();
    }
  };

  return (
    <button
      aria-label="Dark theme"
      aria-pressed={current ? current === "dark" : undefined}
      className={cn(
        "group/switch relative inline-flex shrink-0 cursor-pointer select-none items-center justify-center rounded-lg font-medium",
        "border border-zinc-200 bg-white text-zinc-900 shadow-xs",
        "dark:border-zinc-800 dark:bg-zinc-900 dark:text-zinc-100",
        "hover:border-zinc-300 hover:bg-zinc-50 dark:hover:border-zinc-700 dark:hover:bg-zinc-800/70",
        "active:bg-zinc-100 dark:active:bg-zinc-800",
        "transition-[background-color,border-color] duration-150 ease-out",
        "outline-none focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 focus-visible:ring-offset-white dark:focus-visible:ring-zinc-500 dark:focus-visible:ring-offset-zinc-950",
        "disabled:pointer-events-none disabled:opacity-50",
        sizing.button,
        !showLabel && cn(sizing.square, "px-0"),
        className
      )}
      type="button"
      {...props}
      onClick={handleClick}
    >
      <svg
        aria-hidden="true"
        className="pointer-events-none shrink-0 overflow-visible"
        fill="none"
        height={sizing.icon}
        ref={iconRef}
        viewBox="0 0 24 24"
        width={sizing.icon}
      >
        <mask id={maskId}>
          <rect fill="white" height="32" width="32" x="-4" y="-4" />
          <circle
            className="translate-x-[10px] -translate-y-[10px] dark:translate-x-0 dark:translate-y-0"
            cx="17"
            cy="7"
            data-part="bite"
            fill="black"
            r="7.5"
          />
        </mask>
        <g mask={`url(#${maskId})`}>
          <circle
            className="origin-[12px_12px] [transform-box:view-box] dark:scale-[1.8]"
            cx="12"
            cy="12"
            data-part="disc"
            fill="currentColor"
            r="4.75"
          />
        </g>
        <g stroke="currentColor" strokeLinecap="round" strokeWidth="2">
          {RAYS.map((ray, index) => (
            <line
              className="origin-[12px_12px] [transform-box:view-box] dark:scale-50 dark:opacity-0"
              data-index={index}
              data-part="ray"
              key={ray.deg}
              x1={ray.from.x}
              x2={ray.to.x}
              y1={ray.from.y}
              y2={ray.to.y}
            />
          ))}
        </g>
      </svg>
      {showLabel && (
        <span aria-hidden="true" className="grid leading-none" ref={labelRef}>
          <span
            className="col-start-1 row-start-1 dark:opacity-0 dark:blur-[3px]"
            data-part="label"
          >
            Light
          </span>
          <span
            className="col-start-1 row-start-1 opacity-0 blur-[3px] dark:opacity-100 dark:blur-none"
            data-part="label"
          >
            Dark
          </span>
        </span>
      )}
    </button>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Extruded Text
 * @version: 2.0.0
 * @date: 2026-10-14
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import { type HTMLAttributes, type RefObject, useEffect, useRef } from "react";
import { cn } from "@/lib/utils";

interface SwooshTextProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  text?: string;
  /** Element to render, e.g. "h1" for a heading. */
  as?: "div" | "span" | "p" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6";
  /** Stacked layers behind each letter (clamped to 6-16). */
  depth?: number;
  /** Total extrusion length, in em. */
  length?: number;
  /** Optional color for the deepest layer only, e.g. "#f97316". */
  accent?: string;
}

// Spring for the light direction. Under-damped on purpose: a fast flick
// swings the extrusion past its target before it settles.
const LIGHT_STIFFNESS = 170;
const LIGHT_DAMPING = 13;
// How much of the pointer's velocity is carried into the spring.
const LIGHT_KICK = 9;
const LIGHT_MAX_SPEED = 30;
const LIGHT_MAX_LENGTH = 1.35;
// Spring for each keycap, close to critical so letters sink without wobble.
const KEY_STIFFNESS = 420;
const KEY_DAMPING = 34;
// How far a fully pressed key sinks into its extrusion (fraction of depth).
const MAX_SINK = 0.72;
// Falloff radius of the press wave, in multiples of the font size.
const PRESS_RADIUS = 0.75;
// Rest: light from the top-left, extrusion toward the bottom-right (45°).
const REST = Math.SQRT1_2;
const EPSILON = 0.0008;
const WHITESPACE = /\s+/;

const segmenter =
  typeof Intl !== "undefined" && "Segmenter" in Intl
    ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
    : null;

/** Splits into user-perceived characters, so emoji and accents stay whole. */
function splitGraphemes(value: string): string[] {
  return segmenter
    ? Array.from(segmenter.segment(value), (s) => s.segment)
    : Array.from(value);
}

interface Key {
  x: number;
  y: number;
  p: number;
  v: number;
  // Layers deepest first, then the face (index 0) last.
  layers: HTMLSpanElement[];
  // Last value written, so unchanged keys are skipped.
  drawn: string;
}

interface Sim {
  lx: number;
  ly: number;
  vx: number;
  vy: number;
  tx: number;
  ty: number;
  // Pointer in client coordinates, or null when it is away.
  px: number | null;
  py: number | null;
  pressed: number;
  fontSize: number;
  depth: number;
  step: number;
  keys: Key[];
}

function round(value: number) {
  return Math.round(value * 10_000) / 10_000;
}

function clamp(value: number, max: number) {
  return Math.max(-max, Math.min(max, value));
}

function lightTarget(sim: Sim, rect: DOMRect): [number, number] {
  if (sim.px === null || sim.py === null) {
    return [REST, REST];
  }
  // The extrusion points away from the light (the pointer). Near the centre
  // the light is overhead, so the extrusion shortens instead of flipping.
  const dx = rect.left + rect.width / 2 - sim.px;
  const dy = rect.top + rect.height / 2 - sim.py;
  const reach = Math.max(Math.hypot(dx, dy), sim.fontSize * 0.9);
  return [dx / reach, dy / reach];
}

function stepLight(sim: Sim, dt: number) {
  sim.vx += ((sim.tx - sim.lx) * LIGHT_STIFFNESS - sim.vx * LIGHT_DAMPING) * dt;
  sim.vy += ((sim.ty - sim.ly) * LIGHT_STIFFNESS - sim.vy * LIGHT_DAMPING) * dt;
  sim.lx += sim.vx * dt;
  sim.ly += sim.vy * dt;
  // Keep a wild flick from stretching the extrusion too far.
  const length = Math.hypot(sim.lx, sim.ly);
  if (length > LIGHT_MAX_LENGTH) {
    sim.lx = (sim.lx / length) * LIGHT_MAX_LENGTH;
    sim.ly = (sim.ly / length) * LIGHT_MAX_LENGTH;
  }
  const moving =
    Math.abs(sim.tx - sim.lx) > EPSILON ||
    Math.abs(sim.ty - sim.ly) > EPSILON ||
    Math.hypot(sim.vx, sim.vy) > EPSILON;
  if (!moving) {
    sim.lx = sim.tx;
    sim.ly = sim.ty;
    sim.vx = 0;
    sim.vy = 0;
  }
  return moving;
}

function keyTarget(sim: Sim, index: number, dx: number, dy: number) {
  if (index === sim.pressed) {
    return 1;
  }
  if (sim.px === null) {
    return 0;
  }
  const distance = Math.hypot(dx, dy) / (sim.fontSize * PRESS_RADIUS);
  return distance > 2.5 ? 0 : Math.exp(-distance * distance);
}

function stepKeys(sim: Sim, dt: number, rect: DOMRect) {
  let moving = false;
  const x = (sim.px ?? 0) - rect.left;
  const y = (sim.py ?? 0) - rect.top;
  for (let i = 0; i < sim.keys.length; i++) {
    const key = sim.keys[i];
    const target = keyTarget(sim, i, x - key.x, y - key.y) * MAX_SINK;
    key.v += ((target - key.p) * KEY_STIFFNESS - key.v * KEY_DAMPING) * dt;
    key.p += key.v * dt;
    if (Math.abs(target - key.p) < EPSILON && Math.abs(key.v) < EPSILON) {
      key.p = target;
      key.v = 0;
    } else {
      moving = true;
    }
  }
  return moving;
}

// Layer `index` sits `index` steps deep. As the key sinks (p → 1) the
// column compresses toward the deepest layer, which never moves.
function layerTransform(
  index: number,
  depth: number,
  step: number,
  light: [number, number],
  p: number
) {
  const offset = (index + (depth - index) * p) * step;
  return `translate3d(${round(light[0] * offset)}em, ${round(light[1] * offset)}em, 0)`;
}

// Writes transforms straight onto each layer. Changing a custom property on
// the root instead would restyle every descendant each frame (~10x slower).
function drawKeys(sim: Sim) {
  const light: [number, number] = [round(sim.lx), round(sim.ly)];
  for (const key of sim.keys) {
    const p = round(Math.max(0, key.p));
    const signature = `${light[0]},${light[1]},${p}`;
    if (signature === key.drawn) {
      continue;
    }
    key.drawn = signature;
    const count = key.layers.length;
    for (let j = 0; j < count; j++) {
      key.layers[j].style.transform = layerTransform(
        count - 1 - j,
        sim.depth,
        sim.step,
        light,
        p
      );
    }
  }
}

const REST_LIGHT: [number, number] = [REST, REST];

function layerColor(index: number, depth: number, accent?: string) {
  if (index === depth && accent) {
    return accent;
  }
  const t = Math.round(((index - 1) / Math.max(1, depth - 1)) * 100);
  return `color-mix(in oklab, var(--ex-far) ${t}%, var(--ex-near))`;
}

function Letter({
  char,
  depth,
  step,
  accent,
}: {
  char: string;
  depth: number;
  step: number;
  accent?: string;
}) {
  // Deepest layer first so the face paints on top.
  const layers = Array.from({ length: depth }, (_, i) => depth - i);
  return (
    <span className="relative inline-block" data-key="">
      {layers.map((i) => (
        <span
          className="absolute inset-0"
          key={i}
          style={{
            color: layerColor(i, depth, accent),
            transform: layerTransform(i, depth, step, REST_LIGHT, 0),
          }}
        >
          {char}
        </span>
      ))}
      <span
        className="relative inline-block text-[var(--ex-face)]"
        style={{ transform: layerTransform(0, depth, step, REST_LIGHT, 0) }}
      >
        {char}
      </span>
    </span>
  );
}

function measureKeys(root: HTMLElement, sim: Sim) {
  const rect = root.getBoundingClientRect();
  sim.fontSize = Number.parseFloat(getComputedStyle(root).fontSize) || 16;
  const els = root.querySelectorAll<HTMLSpanElement>("[data-key]");
  sim.keys = Array.from(els, (el, i) => {
    const r = el.getBoundingClientRect();
    const previous = sim.keys[i];
    return {
      layers: Array.from(el.children) as HTMLSpanElement[],
      drawn: "",
      x: r.left - rect.left + r.width / 2,
      y: r.top - rect.top + r.height / 2,
      p: previous?.p ?? 0,
      v: previous?.v ?? 0,
    };
  });
}

function nearestKey(sim: Sim, x: number, y: number) {
  let best = -1;
  let bestDistance = sim.fontSize * 0.8;
  for (let i = 0; i < sim.keys.length; i++) {
    const d = Math.hypot(sim.keys[i].x - x, sim.keys[i].y - y);
    if (d < bestDistance) {
      best = i;
      bestDistance = d;
    }
  }
  return best;
}

function createSim(depth: number, step: number): Sim {
  return {
    lx: REST,
    ly: REST,
    vx: 0,
    vy: 0,
    tx: REST,
    ty: REST,
    px: null,
    py: null,
    pressed: -1,
    fontSize: 16,
    depth,
    step,
    keys: [],
  };
}

function useExtrusion(
  rootRef: RefObject<HTMLElement | null>,
  text: string,
  depth: number,
  step: number
) {
  useEffect(() => {
    const root = rootRef.current;
    // `text` is read so the effect re-runs (and re-measures) when it changes.
    if (!root || text === "") {
      return;
    }
    // Reduced motion keeps the fixed 45° extrusion from the first render.
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      return;
    }

    const sim = createSim(depth, step);
    let frame = 0;
    let last = 0;
    let visible = true;
    let onScreen = true;

    const tick = (now: number) => {
      frame = 0;
      const dt = last ? Math.min((now - last) / 1000, 1 / 30) : 1 / 60;
      last = now;
      const rect = root.getBoundingClientRect();
      [sim.tx, sim.ty] = lightTarget(sim, rect);
      const lightMoving = stepLight(sim, dt);
      const keysMoving = stepKeys(sim, dt, rect);
      drawKeys(sim);
      // Sleep once everything has settled, or while offscreen.
      if ((lightMoving || keysMoving) && visible) {
        frame = requestAnimationFrame(tick);
      } else {
        last = 0;
      }
    };

    const wake = () => {
      if (!frame && visible) {
        frame = requestAnimationFrame(tick);
      }
    };

    const onMove = (event: PointerEvent) => {
      if (!visible) {
        return;
      }
      const rect = root.getBoundingClientRect();
      const [ax, ay] = lightTarget(sim, rect);
      sim.px = event.clientX;
      sim.py = event.clientY;
      const [bx, by] = lightTarget(sim, rect);
      // Carry the pointer's velocity into the spring so a flick swings it.
      sim.vx = clamp(sim.vx + (bx - ax) * LIGHT_KICK, LIGHT_MAX_SPEED);
      sim.vy = clamp(sim.vy + (by - ay) * LIGHT_KICK, LIGHT_MAX_SPEED);
      wake();
    };

    const onLeave = () => {
      sim.px = null;
      sim.py = null;
      sim.pressed = -1;
      wake();
    };

    const onDown = (event: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      sim.pressed = nearestKey(
        sim,
        event.clientX - rect.left,
        event.clientY - rect.top
      );
      sim.px = event.clientX;
      sim.py = event.clientY;
      wake();
    };

    const onUp = (event: PointerEvent) => {
      sim.pressed = -1;
      // Touch has no hover: once the finger lifts, the light goes home.
      if (event.pointerType !== "mouse") {
        sim.px = null;
        sim.py = null;
      }
      wake();
    };

    const onVisibility = () => {
      visible = onScreen && !document.hidden;
      wake();
    };

    const measure = () => measureKeys(root, sim);
    measure();
    const resize = new ResizeObserver(measure);
    resize.observe(root);
    document.fonts?.ready.then(measure).catch(() => undefined);

    const intersection = new IntersectionObserver(([entry]) => {
      onScreen = entry.isIntersecting;
      visible = onScreen && !document.hidden;
      wake();
    });
    intersection.observe(root);

    window.addEventListener("pointermove", onMove, { passive: true });
    document.documentElement.addEventListener("pointerleave", onLeave);
    root.addEventListener("pointerdown", onDown);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      cancelAnimationFrame(frame);
      resize.disconnect();
      intersection.disconnect();
      window.removeEventListener("pointermove", onMove);
      document.documentElement.removeEventListener("pointerleave", onLeave);
      root.removeEventListener("pointerdown", onDown);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [rootRef, text, depth, step]);
}

export default function SwooshText({
  text = "Extruded",
  as: Tag = "div",
  depth = 12,
  length = 0.2,
  accent,
  className,
  style,
  ...props
}: SwooshTextProps) {
  const rootRef = useRef<HTMLElement | null>(null);
  const layers = Math.round(Math.min(16, Math.max(6, depth)));
  const step = length / layers;
  useExtrusion(rootRef, text, layers, step);

  const words = text.split(WHITESPACE).filter(Boolean);

  return (
    <Tag
      className={cn(
        "relative touch-manipulation select-none font-bold text-5xl tracking-tight",
        "[--ex-face:var(--color-zinc-900)] [--ex-far:var(--color-zinc-600)] [--ex-near:var(--color-zinc-300)]",
        "dark:[--ex-face:var(--color-zinc-50)] dark:[--ex-far:var(--color-zinc-700)] dark:[--ex-near:var(--color-zinc-400)]",
        className
      )}
      ref={(node: HTMLElement | null) => {
        rootRef.current = node;
      }}
      style={style}
      {...props}
    >
      <span className="sr-only">{text}</span>
      <span aria-hidden="true">
        {words.map((word, w) => (
          // biome-ignore lint/suspicious/noArrayIndexKey: words can repeat
          <span key={w}>
            {w > 0 ? " " : null}
            <span className="inline-block whitespace-nowrap">
              {splitGraphemes(word).map((char, c) => (
                <Letter
                  accent={accent}
                  char={char}
                  depth={layers}
                  // biome-ignore lint/suspicious/noArrayIndexKey: letters repeat
                  key={c}
                  step={step}
                />
              ))}
            </span>
          </span>
        ))}
      </span>
    </Tag>
  );
}

"use client";

/**
 * @author: @dorianbaffier
 * @description: Synced Transcript
 * @version: 1.0.0
 * @date: 2026-10-16
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import { ArrowDown, ArrowUp, Pause, Play } from "lucide-react";
import {
  type KeyboardEvent,
  type MouseEvent,
  memo,
  type PointerEvent,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";

const SPEEDS = [1, 1.5, 2];
const WHITESPACE = /\s+/;

export interface TranscriptSegment {
  speaker: string;
  /** Seconds from the start. */
  start: number;
  end: number;
  text: string;
}

export interface SyncedTranscriptProps {
  title?: string;
  segments?: TranscriptSegment[];
  /** Seconds. Defaults to the end of the last segment. Playback is simulated; drive it from your own audio with `onTimeChange`. */
  duration?: number;
  onTimeChange?: (seconds: number) => void;
  className?: string;
}

interface Word {
  text: string;
  start: number;
  /** Index across the whole transcript. */
  index: number;
}

// Times each segment from its word count, with a breath between speakers.
function timed(lines: [string, string][]): TranscriptSegment[] {
  const out: TranscriptSegment[] = [];
  let t = 0.6;
  for (const [speaker, text] of lines) {
    const words = text.split(WHITESPACE).length;
    const end = t + words / 2.7;
    out.push({ speaker, start: t, end, text });
    t = end + 0.7;
  }
  return out;
}

const DEFAULT_SEGMENTS = timed([
  [
    "Maya",
    "Welcome back. Today we're talking about the small details in interfaces, the ones nobody notices until they're missing.",
  ],
  [
    "Theo",
    "Right. Like a menu that opens in a hundred and fifty milliseconds instead of four hundred. You never think about it, but the slow one feels broken.",
  ],
  ["Maya", "So where do you start when something feels off?"],
  [
    "Theo",
    "I slow it down. I record the screen and step through it frame by frame. Most of the time the easing is wrong, or two things move that should move as one.",
  ],
  ["Maya", "And when it finally feels right?"],
  [
    "Theo",
    "Then I stop touching it. The best motion is the kind you only miss when it's gone.",
  ],
]);

const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v));

function formatTime(seconds: number) {
  const s = Math.max(0, Math.floor(seconds));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

// Spreads a segment's time over its words by length, so long words last longer.
function splitWords(segments: TranscriptSegment[]) {
  let index = 0;
  return segments.map((segment) => {
    const parts = segment.text.split(WHITESPACE).filter(Boolean);
    const total = parts.reduce((sum, w) => sum + w.length + 1, 0);
    let t = segment.start;
    return parts.map((text) => {
      const word = { text, start: t, index };
      t += ((text.length + 1) / total) * (segment.end - segment.start);
      index += 1;
      return word;
    });
  });
}

// What each paragraph needs to know: all spoken, none yet, or which word.
// Past and future paragraphs get a constant, so they skip re-rendering.
function paragraphActive(segment: number, current: number, active: number) {
  if (segment < current) {
    return Number.MAX_SAFE_INTEGER;
  }
  return segment === current ? active : -1;
}

// Only the paragraph holding the spoken word re-renders as time moves.
const Paragraph = memo(function Paragraph({
  words,
  active,
}: {
  words: Word[];
  /** The spoken word's global index. */
  active: number;
}) {
  return (
    <>
      {words.map((word) => (
        <span
          className={cn(
            "transition-colors duration-150 ease-out",
            word.index <= active
              ? "text-zinc-900 dark:text-zinc-100"
              : "text-zinc-400 dark:text-zinc-500"
          )}
          data-index={word.index}
          key={word.index}
        >
          {word.text}{" "}
        </span>
      ))}
    </>
  );
});

export default function SyncedTranscript({
  title = "Frame Rate · Episode 48",
  segments = DEFAULT_SEGMENTS,
  duration: durationProp,
  onTimeChange,
  className,
}: SyncedTranscriptProps) {
  const duration = durationProp ?? Math.ceil((segments.at(-1)?.end ?? 0) + 0.6);
  const words = useMemo(() => splitWords(segments), [segments]);
  const flat = useMemo(() => words.flat(), [words]);

  const [time, setTime] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [speedIndex, setSpeedIndex] = useState(0);
  const [following, setFollowing] = useState(true);
  // Where the spoken word is when the reader has scrolled away from it.
  const [away, setAway] = useState<"up" | "down" | null>(null);
  const timeRef = useRef(0);
  const scrollRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const markRef = useRef<HTMLDivElement>(null);
  const lastTop = useRef<number | null>(null);
  const rate = SPEEDS[speedIndex];

  useEffect(() => {
    if (!playing) {
      return;
    }
    let frame = 0;
    let last = performance.now();
    const tick = (now: number) => {
      const next = Math.min(
        duration,
        timeRef.current + ((now - last) / 1000) * rate
      );
      last = now;
      timeRef.current = next;
      setTime(next);
      if (next >= duration) {
        setPlaying(false);
        return;
      }
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [playing, duration, rate]);

  useEffect(() => {
    onTimeChange?.(time);
  }, [time, onTimeChange]);

  const seek = useCallback(
    (seconds: number) => {
      const next = clamp(seconds, 0, duration);
      timeRef.current = next;
      setTime(next);
    },
    [duration]
  );

  // The last word that has started, or -1 before the first.
  let active = -1;
  for (const word of flat) {
    if (word.start <= time) {
      active = word.index;
    } else {
      break;
    }
  }
  const activeSegment = words.findIndex((ws) =>
    ws.some((w) => w.index === active)
  );

  const scrollToWord = useCallback((el: HTMLElement, smooth: boolean) => {
    const box = scrollRef.current;
    if (!box) {
      return;
    }
    // Keep the spoken line a third of the way down, like lyrics.
    const top =
      box.scrollTop +
      el.getBoundingClientRect().top -
      box.getBoundingClientRect().top -
      box.clientHeight / 3;
    const reduce = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    box.scrollTo({ top, behavior: smooth && !reduce ? "smooth" : "auto" });
  }, []);

  // One highlight slides from word to word; it jumps, unanimated, to a new line.
  useLayoutEffect(() => {
    const mark = markRef.current;
    const el = contentRef.current?.querySelector<HTMLElement>(
      `[data-index="${active}"]`
    );
    if (!(mark && el)) {
      if (mark) {
        mark.style.opacity = "0";
      }
      lastTop.current = null;
      return;
    }
    const sameLine = lastTop.current === el.offsetTop;
    mark.style.transition = sameLine
      ? "transform 140ms cubic-bezier(0.23, 1, 0.32, 1), width 140ms cubic-bezier(0.23, 1, 0.32, 1), opacity 150ms ease-out"
      : "opacity 150ms ease-out";
    // The trailing space is part of the span; leave it out of the mark.
    const space = Number.parseFloat(getComputedStyle(el).fontSize) * 0.28;
    mark.style.transform = `translate(${el.offsetLeft - 3}px, ${el.offsetTop}px)`;
    mark.style.width = `${el.offsetWidth - space + 6}px`;
    mark.style.height = `${el.offsetHeight}px`;
    mark.style.opacity = "1";
    if (!sameLine && following) {
      scrollToWord(el, lastTop.current !== null);
    }
    lastTop.current = el.offsetTop;
  }, [active, following, scrollToWord]);

  // When the reader scrolls away, note which way the spoken word went.
  const checkAway = useCallback(() => {
    const box = scrollRef.current;
    const el = contentRef.current?.querySelector<HTMLElement>(
      `[data-index="${active}"]`
    );
    if (!(box && el) || following) {
      setAway(null);
      return;
    }
    const word = el.getBoundingClientRect();
    const view = box.getBoundingClientRect();
    if (word.bottom < view.top) {
      setAway("up");
    } else if (word.top > view.bottom) {
      setAway("down");
    } else {
      setAway(null);
    }
  }, [active, following]);

  useEffect(() => {
    checkAway();
  }, [checkAway]);

  const takeOver = () => setFollowing(false);

  const follow = () => {
    setFollowing(true);
    setAway(null);
    const el = contentRef.current?.querySelector<HTMLElement>(
      `[data-index="${active}"]`
    );
    if (el) {
      scrollToWord(el, true);
    }
  };

  const handleWordClick =
    (segment: TranscriptSegment) => (event: MouseEvent<HTMLButtonElement>) => {
      const target = (event.target as HTMLElement).closest("[data-index]");
      const index = Number(target?.getAttribute("data-index") ?? -1);
      // Keyboard presses have no word under them; start the paragraph.
      seek(index >= 0 ? (flat[index]?.start ?? segment.start) : segment.start);
      setFollowing(true);
    };

  const handleProgress = (event: PointerEvent<HTMLDivElement>) => {
    if (event.type === "pointerdown") {
      event.currentTarget.setPointerCapture(event.pointerId);
    } else if (!event.currentTarget.hasPointerCapture(event.pointerId)) {
      return;
    }
    const rect = event.currentTarget.getBoundingClientRect();
    seek(((event.clientX - rect.left) / rect.width) * duration);
    setFollowing(true);
  };

  const handleProgressKey = (event: KeyboardEvent<HTMLDivElement>) => {
    const moves: Record<string, number> = {
      ArrowLeft: -5,
      ArrowDown: -5,
      ArrowRight: 5,
      ArrowUp: 5,
      Home: -duration,
      End: duration,
    };
    if (event.key === " ") {
      event.preventDefault();
      setPlaying((p) => !p);
      return;
    }
    const move = moves[event.key];
    if (move !== undefined) {
      event.preventDefault();
      seek(time + move);
      setFollowing(true);
    }
  };

  const togglePlay = () => {
    if (!playing && timeRef.current >= duration) {
      seek(0);
    }
    setPlaying((p) => !p);
  };

  return (
    <div
      className={cn(
        "w-full max-w-md select-none rounded-3xl border border-zinc-200 bg-white text-zinc-900 dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-100",
        className
      )}
    >
      <div className="flex items-center justify-between gap-3 px-5 pt-5">
        <div className="min-w-0">
          <p className="text-xs text-zinc-500 dark:text-zinc-400">Transcript</p>
          <p className="truncate font-medium text-sm">{title}</p>
        </div>
        <button
          aria-label={`Playback speed ${rate}x`}
          className="h-7 shrink-0 rounded-full border border-zinc-200 px-2.5 font-medium text-xs tabular-nums outline-none transition-colors duration-150 ease-out hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-zinc-400 dark:border-zinc-800 dark:hover:bg-zinc-900"
          onClick={() => setSpeedIndex((i) => (i + 1) % SPEEDS.length)}
          type="button"
        >
          {rate}×
        </button>
      </div>

      <div className="relative">
        <section
          aria-label="Transcript"
          className="h-72 overflow-y-auto px-5 py-6 outline-none [mask-image:linear-gradient(to_bottom,transparent,black_24px,black_calc(100%-24px),transparent)] focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-inset"
          onScroll={checkAway}
          onTouchMove={takeOver}
          onWheel={takeOver}
          ref={scrollRef}
        >
          <div className="relative isolate" ref={contentRef}>
            <div
              aria-hidden
              className="pointer-events-none absolute top-0 left-0 -z-10 rounded-md bg-zinc-100 opacity-0 dark:bg-zinc-800/80"
              ref={markRef}
            />
            {segments.map((segment, i) => (
              <div
                className={cn(i > 0 && "mt-5")}
                key={`${segment.start}-${segment.speaker}`}
              >
                <div className="mb-1 flex items-center gap-2 text-xs">
                  <span
                    aria-hidden
                    className="flex size-5 items-center justify-center rounded-full bg-zinc-100 font-medium text-[10px] text-zinc-600 dark:bg-zinc-800 dark:text-zinc-300"
                  >
                    {segment.speaker.charAt(0)}
                  </span>
                  <span className="font-medium">{segment.speaker}</span>
                  <button
                    aria-label={`Play from ${formatTime(segment.start)}`}
                    className="rounded text-zinc-400 tabular-nums outline-none transition-colors duration-150 ease-out hover:text-zinc-900 focus-visible:ring-2 focus-visible:ring-zinc-400 dark:text-zinc-500 dark:hover:text-zinc-100"
                    onClick={() => {
                      seek(segment.start);
                      setFollowing(true);
                    }}
                    type="button"
                  >
                    {formatTime(segment.start)}
                  </button>
                </div>
                <button
                  className="block cursor-pointer rounded-sm text-left text-[15px] leading-7 outline-none focus-visible:ring-2 focus-visible:ring-zinc-400"
                  onClick={handleWordClick(segment)}
                  tabIndex={-1}
                  type="button"
                >
                  <Paragraph
                    active={paragraphActive(i, activeSegment, active)}
                    words={words[i]}
                  />
                </button>
              </div>
            ))}
          </div>
        </section>

        {/* Back to the spoken word after scrolling away. */}
        <button
          className={cn(
            "absolute bottom-3 left-1/2 flex -translate-x-1/2 items-center gap-1.5 rounded-full bg-zinc-900 px-3 py-1.5 font-medium text-white text-xs shadow-sm outline-none transition-[opacity,translate] duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] focus-visible:ring-2 focus-visible:ring-zinc-400 dark:bg-zinc-100 dark:text-zinc-900",
            away
              ? "translate-y-0 opacity-100"
              : "pointer-events-none translate-y-2 opacity-0"
          )}
          onClick={follow}
          tabIndex={away ? 0 : -1}
          type="button"
        >
          {away === "up" ? (
            <ArrowUp aria-hidden className="size-3.5" />
          ) : (
            <ArrowDown aria-hidden className="size-3.5" />
          )}
          Back to now
        </button>
      </div>

      <div className="flex items-center gap-3 border-zinc-200 border-t px-5 py-3 dark:border-zinc-800">
        <button
          aria-label={playing ? "Pause" : "Play"}
          className="flex size-9 shrink-0 items-center justify-center rounded-full bg-zinc-900 text-white outline-none transition-colors duration-150 ease-out hover:bg-zinc-700 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 dark:bg-zinc-100 dark:text-zinc-900 dark:focus-visible:ring-offset-zinc-950 dark:hover:bg-zinc-300"
          onClick={togglePlay}
          type="button"
        >
          {playing ? (
            <Pause aria-hidden className="size-4" fill="currentColor" />
          ) : (
            <Play
              aria-hidden
              className="size-4 translate-x-px"
              fill="currentColor"
            />
          )}
        </button>
        <span className="w-9 text-xs text-zinc-500 tabular-nums dark:text-zinc-400">
          {formatTime(time)}
        </span>
        <div
          aria-label="Seek"
          aria-valuemax={Math.round(duration)}
          aria-valuemin={0}
          aria-valuenow={Math.round(time)}
          aria-valuetext={`${formatTime(time)} of ${formatTime(duration)}`}
          className="group relative flex h-6 flex-1 cursor-pointer touch-none items-center rounded outline-none focus-visible:ring-2 focus-visible:ring-zinc-400"
          onKeyDown={handleProgressKey}
          onPointerDown={handleProgress}
          onPointerMove={handleProgress}
          role="slider"
          tabIndex={0}
        >
          <div className="h-1 w-full overflow-hidden rounded-full bg-zinc-200 dark:bg-zinc-800">
            <div
              className="h-full w-full origin-left rounded-full bg-zinc-900 dark:bg-zinc-100"
              style={{ transform: `scaleX(${time / duration})` }}
            />
          </div>
        </div>
        <span className="w-9 text-right text-xs text-zinc-500 tabular-nums dark:text-zinc-400">
          {formatTime(duration)}
        </span>
      </div>
    </div>
  );
}

"use client";

